    [Fact]
    public async Task HandlerLegacyWorldLoginUsesKeyToStartLegacySessionWithoutInternalSnapshotResponse()
    {
        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(1293600, uid: 1293600);
        using var log = new StringWriter();
        var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot), log);
        var sent = new List<byte[]>();
        var connection = CreateSendingConnection(sent);

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new LegacyMsgLoginGamePacket(1293600).ToFrameBytes()));
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new MsgTeamPacket(MsgTeamType.InviteRequest, 400_001).ToFrameBytes()));

        Assert.Equal(62, sent.Count);
        Assert.NotEqual(WorldPacketOpcodes.InternalSnapshotResponse, ReadFrame(sent[0]).Header.Opcode);
        Assert.True(LegacyMsgMessagePacket.TryParse(ReadFrame(sent[0]), out var answerOk));
        Assert.Equal("ANSWER_OK", answerOk.Content[3]);
        AssertLegacyWorldEntryStartupFrames(sent, startIndex: 1);
        var delayedIndex = FindSingleUpdateIndex(
            sent,
            1_293_600,
            LegacyMsgUpdateDataType.Money,
            98_602_439_956);
        Assert.True(delayedIndex > 1);
        AssertLegacyWorldLoginDelayedStartupReviews(sent, delayedIndex);

        var output = log.ToString();
        Assert.Contains("WorldServer legacy MsgLoginGame Success key=1293600", output);
        Assert.Contains("WorldServer handled MsgTeam", output);
        Assert.Contains("session=accountId=1293600 username=HeroOne characterUid=1293600 characterName=HeroOne", output);
    }

