    [Fact]
    public async Task HandlerLegacyWorldLoginLogsPeerDisconnectBeforeLoaderHero()
    {
        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(1293600, uid: 1293600);
        using var log = new StringWriter();
        var handler = CreateWorldEntryStartupProbeHandler(
            LegacyWorldEntryStartupPrefixProbeMode.SkipTimer,
            log);
        var sent = new List<byte[]>();
        var connection = CreateSendingConnection(
            sent,
            (frame, _) =>
            {
                if (PacketHeader.TryRead(frame.Span, out var header) &&
                    header.Opcode == WorldPacketOpcodes.LegacyLoaderHeroInfo)
                {
                    throw new IOException(
                        "simulated client close",
                        new SocketException((int)SocketError.ConnectionReset));
                }

                return ValueTask.CompletedTask;
            });

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new LegacyMsgLoginGamePacket(1293600).ToFrameBytes()));

        Assert.DoesNotContain(sent, frame => ReadFrame(frame).Header.Opcode == WorldPacketOpcodes.LegacyLoaderHeroInfo);
        var output = log.ToString();
        Assert.Contains("WorldServer legacy startup prefix complete uid=1293600 mode=SkipTimer.", output);
        Assert.Contains("WorldServer legacy startup send attempt stage=loader-hero uid=1293600 opcode=22210", output);
        Assert.Contains("WorldServer legacy startup send peer-disconnect stage=loader-hero", output);
        Assert.DoesNotContain("WorldServer legacy startup send returned stage=loader-hero", output);
        Assert.DoesNotContain("WorldServer legacy MsgLoginGame Success key=1293600", output);
    }

