    [Fact]
    public async Task HandlerRuntimeLoopSendsLegacyXpAndStaminaAfterStartupWhenEnabled()
    {
        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(1293600, uid: 1293600);
        using var cancel = new CancellationTokenSource();
        var handler = new WorldServerFrameHandler(
            new CharacterSnapshotLoader(_usersRoot),
            handoffService: null,
            worldData: null,
            new LegacyRuntimeUpdateLoopOptions(
                Enabled: true,
                TimeSpan.FromMilliseconds(5),
                TimeProvider.System));
        var sent = new RuntimeThreadSafeFrameCapture();
        var connection = CreateSendingConnection(sent);

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new LegacyMsgLoginGamePacket(1293600).ToFrameBytes()),
            cancel.Token);
        await WaitUntilAsync(
            () => sent.Count >= 64,
            TimeSpan.FromSeconds(2));
        await cancel.CancelAsync();

        AssertSingleUpdate(sent[^2], 1_293_600, LegacyMsgUpdateDataType.XPCircle, 1);
        AssertSingleUpdate(sent[^1], 1_293_600, LegacyMsgUpdateDataType.Stamina, 5);
    }

    [Fact]
    public async Task HandlerRuntimeLoopSuppressesNewerClientOverwhelmStatusVectorByDefault()
    {
        var updates = await CaptureLegacyOverwhelmRuntimeMsgUpdatesAsync(
            clientCompatibility: null,
            updates => HasSingleLegacyMsgUpdate(updates, LegacyMsgUpdateDataType.Stamina, 5));

        Assert.Contains(updates, update => IsSingleLegacyMsgUpdate(update, LegacyMsgUpdateDataType.XPCircle, 1));
        Assert.Contains(updates, update => IsSingleLegacyMsgUpdate(update, LegacyMsgUpdateDataType.Stamina, 5));
        Assert.DoesNotContain(updates, HasLegacyOverwhelmRuntimeStatusVector);
    }

    [Fact]
    public async Task HandlerRuntimeLoopSendsNewerClientOverwhelmStatusVectorWhenEnabled()
    {
        var updates = await CaptureLegacyOverwhelmRuntimeMsgUpdatesAsync(
            LegacyClientCompatibilityOptions.NewerClient,
            updates => updates.Any(HasLegacyOverwhelmRuntimeStatusVector));

        var status = Assert.Single(updates, HasLegacyOverwhelmRuntimeStatusVector);
        var entry = Assert.Single(status.Updates);
        Assert.Equal(LegacyMsgUpdateDataType.StatusFlag, entry.Type);
        Assert.NotNull(entry.Values);
        Assert.True(HasLegacyStatusFlag(entry.Values!, LegacyRuntimeUpdateTicker.OverwhelmFlag));
        Assert.False(HasLegacyStatusFlag(entry.Values!, LegacyRuntimeUpdateTicker.RevelatorFlag));
    }

    [Fact]
    public async Task HandlerRuntimeLoopExpiresLegacyXpSkillFlagsWhenTimerElapsed()
    {
        Directory.CreateDirectory(_usersRoot);
        var expiredAt = DateTimeOffset.UtcNow.AddSeconds(-1).ToString("O", CultureInfo.InvariantCulture);
        WriteSnapshot(
            1293600,
            uid: 1293600,
            statusFlags: BuildStatusFlags(
                LegacyCycloneFlag,
                LegacySupermanFlag,
                LegacyFatalStrikeFlag,
                LegacyChainBoltFlag,
                LegacyBladeFlurryFlag,
                LegacyCannonBarrageFlag,
                LegacyBlackbeardsRageFlag,
                LegacyDragonCycloneFlag,
                LegacyOmnipotenceFlag,
                LegacyThunderRampageFlag),
            extraCharacterLines:
                $"LegacyCycloneExpiresAtUtc={expiredAt}\r\n" +
                $"LegacySupermanExpiresAtUtc={expiredAt}\r\n" +
                $"LegacyFatalStrikeExpiresAtUtc={expiredAt}\r\n" +
                $"LegacyChainBoltExpiresAtUtc={expiredAt}\r\n" +
                $"LegacyBladeFlurryExpiresAtUtc={expiredAt}\r\n" +
                $"LegacyCannonBarrageExpiresAtUtc={expiredAt}\r\n" +
                $"LegacyBlackbeardsRageExpiresAtUtc={expiredAt}\r\n" +
                $"LegacyDragonCycloneExpiresAtUtc={expiredAt}\r\n" +
                $"LegacyOmnipotenceExpiresAtUtc={expiredAt}\r\n" +
                $"LegacyThunderRampageExpiresAtUtc={expiredAt}");
        using var cancel = new CancellationTokenSource();
        using var log = new RuntimeThreadSafeStringWriter();
        var handler = new WorldServerFrameHandler(
            new CharacterSnapshotLoader(_usersRoot),
            handoffService: null,
            worldData: null,
            runtimeUpdateLoop: new LegacyRuntimeUpdateLoopOptions(
                Enabled: true,
                TimeSpan.FromMilliseconds(5),
                TimeProvider.System),
            log: log);
        var sent = new RuntimeThreadSafeFrameCapture();
        var connection = CreateSendingConnection(sent);

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new LegacyMsgLoginGamePacket(1293600).ToFrameBytes()),
            cancel.Token);
        var startupCount = sent.Count;
        await WaitUntilAsync(
            () => TryGetExpiredLegacyXpSkillStatusUpdate(sent.Skip(startupCount), out _),
            TimeSpan.FromSeconds(2));
        await cancel.CancelAsync();

        Assert.True(TryGetExpiredLegacyXpSkillStatusUpdate(sent.Skip(startupCount), out var statusUpdate));
        var statusEntry = Assert.Single(statusUpdate.Updates);
        Assert.NotNull(statusEntry.Values);
        Assert.False(HasLegacyStatusFlag(statusEntry.Values!, LegacyCycloneFlag));
        Assert.False(HasLegacyStatusFlag(statusEntry.Values!, LegacySupermanFlag));
        Assert.False(HasLegacyStatusFlag(statusEntry.Values!, LegacyFatalStrikeFlag));
        Assert.False(HasLegacyStatusFlag(statusEntry.Values!, LegacyChainBoltFlag));
        Assert.False(HasLegacyStatusFlag(statusEntry.Values!, LegacyBladeFlurryFlag));
        Assert.False(HasLegacyStatusFlag(statusEntry.Values!, LegacyCannonBarrageFlag));
        Assert.False(HasLegacyStatusFlag(statusEntry.Values!, LegacyBlackbeardsRageFlag));
        Assert.False(HasLegacyStatusFlag(statusEntry.Values!, LegacyDragonCycloneFlag));
        Assert.False(HasLegacyStatusFlag(statusEntry.Values!, LegacyOmnipotenceFlag));
        Assert.False(HasLegacyStatusFlag(statusEntry.Values!, LegacyThunderRampageFlag));
        Assert.Contains("WorldServer expired legacy XP skill flags playerCount=1", log.ToString());

        static bool TryGetExpiredLegacyXpSkillStatusUpdate(
            IEnumerable<byte[]> frames,
            out LegacyMsgUpdatePacket update)
        {
            foreach (var bytes in frames)
            {
                if (!LegacyMsgUpdatePacket.TryParse(ReadFrame(bytes), out update) ||
                    update.Uid != 1_293_600 ||
                    update.Updates.Count != 1 ||
                    update.Updates[0].Type != LegacyMsgUpdateDataType.StatusFlag ||
                    update.Updates[0].Values is not { } values ||
                    HasLegacyStatusFlag(values, LegacyCycloneFlag) ||
                    HasLegacyStatusFlag(values, LegacySupermanFlag) ||
                    HasLegacyStatusFlag(values, LegacyFatalStrikeFlag) ||
                    HasLegacyStatusFlag(values, LegacyChainBoltFlag) ||
                    HasLegacyStatusFlag(values, LegacyBladeFlurryFlag) ||
                    HasLegacyStatusFlag(values, LegacyCannonBarrageFlag) ||
                    HasLegacyStatusFlag(values, LegacyBlackbeardsRageFlag) ||
                    HasLegacyStatusFlag(values, LegacyDragonCycloneFlag) ||
                    HasLegacyStatusFlag(values, LegacyOmnipotenceFlag) ||
                    HasLegacyStatusFlag(values, LegacyThunderRampageFlag))
                {
                    continue;
                }

                return true;
            }

            update = null!;
            return false;
        }
    }

    [Fact]
    public async Task HandlerLegacyWorldLoginSendsDailyResetQuestReviewsAfterSourceCompatibleStartupWhenSavedDayIsStale()
    {
        Directory.CreateDirectory(_usersRoot);
        var staleDay = DateTime.Now.DayOfYear == 1 ? 365 : DateTime.Now.DayOfYear - 1;
        WriteSnapshot(1293600, uid: 1293600, day: staleDay, enilghten: 200);
        using var log = new StringWriter();
        var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot), log);
        var sent = new List<byte[]>();

        await handler.HandleFrameAsync(
            CreateSendingConnection(sent),
            ReadFrame(new LegacyMsgLoginGamePacket(1293600).ToFrameBytes()));

        Assert.Equal(77, sent.Count);
        Assert.True(LegacyMsgMessagePacket.TryParse(ReadFrame(sent[0]), out var answerOk));
        Assert.Equal("ANSWER_OK", answerOk.Content[3]);
        AssertLegacyWorldEntryStartupFrames(sent, startIndex: 1);

        var dailyResetIndex = FindSingleUpdateIndex(
            sent,
            1_293_600,
            LegacyMsgUpdateDataType.Money,
            98_602_439_956);
        Assert.True(dailyResetIndex > 1);
        AssertLegacyWorldLoginDelayedStartupReviews(sent, dailyResetIndex);
        AssertQuestReview(sent[dailyResetIndex + 5], 6_126);
        AssertSingleUpdate(sent[dailyResetIndex + 6], 1_293_600, LegacyMsgUpdateDataType.EnlightPoints, 200);
        Assert.Equal(
            [
                35_024U,
                35_007U,
                35_025U,
                35_028U,
                35_034U,
                6_390U,
                6_329U,
                6_245U,
                6_049U,
                6_366U,
                6_014U,
                2_375U,
                6_126U,
            ],
            sent.Skip(dailyResetIndex + 7).Take(13).Select(bytes =>
            {
                Assert.True(LegacyQuestListPacket.TryParse(ReadFrame(bytes), out var packet));
                return packet.QuestId;
            }));
    }

    [Fact]
    public async Task HandlerLegacyWorldLoginMissingSnapshotSendsNewRoleWithoutSession()
    {
        Directory.CreateDirectory(_usersRoot);
        using var log = new StringWriter();
        var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot), log);
        var sent = new List<byte[]>();
        var connection = CreateSendingConnection(sent);

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new LegacyMsgLoginGamePacket(1293600).ToFrameBytes()));
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new MsgTeamPacket(MsgTeamType.InviteRequest, 400_001).ToFrameBytes()));

        Assert.Single(sent);
        Assert.True(LegacyMsgMessagePacket.TryParse(ReadFrame(sent[0]), out var newRole));
        Assert.Equal("NEW_ROLE", newRole.Content[3]);
        var output = log.ToString();
        Assert.Contains("WorldServer legacy MsgLoginGame snapshot missing", output);
        Assert.Contains("accountId=1293600", output);
        Assert.Contains("file=1293600.ini", output);
        Assert.Contains("reason=snapshotMissing", output);
        Assert.Contains("status=MissingSnapshot", output);
        Assert.Contains("WorldServer legacy MsgLoginGame pending NEW_ROLE key=1293600", output);
        Assert.Contains("WorldServer handled MsgTeam", output);
        Assert.Contains("session=none", output);
        Assert.DoesNotContain("session=accountId=1293600", output);
    }

