    [Fact]
    public async Task HandlerLegacyNewRoleCreatesFirstSnapshotAndStartsLegacyWorldSession()
    {
        Directory.CreateDirectory(_usersRoot);
        using var log = new StringWriter();
        var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot), log);
        var sent = new List<byte[]>();
        var connection = CreateSendingConnection(sent);

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new LegacyMsgLoginGamePacket(1293600).ToFrameBytes()));
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new LegacyNewRolePacket("FirstRole", 1008, 12).ToFrameBytes()));

        Assert.True(sent.Count > 2);
        Assert.True(LegacyMsgMessagePacket.TryParse(ReadFrame(sent[0]), out var newRole));
        Assert.Equal("NEW_ROLE", newRole.Content[3]);
        Assert.True(LegacyMsgMessagePacket.TryParse(ReadFrame(sent[1]), out var createOk));
        Assert.Equal("ANSWER_OK", createOk.Content[3]);
        Assert.True(LegacyServerVersionPacket.TryParse(ReadFrame(sent[2]), out _));
        Assert.True(LegacyServerTimerPacket.TryParse(ReadFrame(sent[3]), out _));
        Assert.True(LegacyServerConfigPacket.TryParse(ReadFrame(sent[4]), out _));
        Assert.True(LegacyLoaderHeroInfoPacket.TryParse(ReadFrame(sent[5]), out _));
        Assert.True(LegacyProtoHeroInfoPacket.TryParse(ReadFrame(sent[6]), out _));
        Assert.True(LegacyChiInfoPacket.TryParse(ReadFrame(sent[7]), out _));

        var snapshotPath = Path.Combine(_usersRoot, "1293600.ini");
        Assert.True(File.Exists(snapshotPath));
        var snapshot = CharacterSnapshotParser.ParseText(File.ReadAllText(snapshotPath));
        Assert.Equal(1293600, snapshot.Uid);
        Assert.Equal("FirstRole", snapshot.Name);
        Assert.Equal(1008, snapshot.Body);
        Assert.Equal(7000, snapshot.Class);
        Assert.Equal(1, snapshot.Level);
        Assert.Equal(1002, snapshot.MapId);
        Assert.Equal(410, snapshot.X);
        Assert.Equal(350, snapshot.Y);

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new MsgTeamPacket(MsgTeamType.InviteRequest, 400_001).ToFrameBytes()));

        var output = log.ToString();
        Assert.Contains("WorldServer legacy NewRole Success uid=1293600 name=FirstRole class=7000 body=1008", output);
        Assert.Contains("WorldServer handled MsgTeam", output);
        Assert.Contains("session=accountId=1293600 username=FirstRole characterUid=1293600 characterName=FirstRole", output);
    }

    [Fact]
    public async Task HandlerLegacyNewRoleCreatesTunedSourceStarterState()
    {
        var usersRoot = Path.Combine(_usersRoot, "Users");
        using var log = new StringWriter();
        var loader = new CharacterSnapshotLoader(usersRoot);
        var handler = new WorldServerFrameHandler(loader, log);
        var sent = new List<byte[]>();
        var connection = CreateSendingConnection(sent);

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new LegacyMsgLoginGamePacket(1293600).ToFrameBytes()));
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new LegacyNewRolePacket("Demon", 1008, 2).ToFrameBytes()));

        var snapshot = loader.LoadByAccountId(1293600);
        Assert.NotNull(snapshot);
        Assert.Equal("Demon", snapshot.Name);
        Assert.Equal(1000, snapshot.Class);
        Assert.Equal(1, snapshot.Level);
        Assert.Equal(5, snapshot.Strength);
        Assert.Equal(2, snapshot.Agility);
        Assert.Equal(3, snapshot.Vitality);
        Assert.Equal(0, snapshot.Spirit);
        Assert.Equal(0, snapshot.MinMana);
        Assert.Equal(0, snapshot.MaxMana);
        Assert.Equal(100_000, snapshot.Money);
        Assert.Equal(0, snapshot.ConquerPoints);
        Assert.Equal(93, snapshot.MinHitPoints);

        var playerItemsPath = Path.Combine(_usersRoot, "PlayersItems", "1293600.bin");
        Assert.True(File.Exists(playerItemsPath));
        var playerItems = loader.LoadPlayerItemsByCharacterUid(1293600);
        Assert.Empty(playerItems.InventoryItems);
        Assert.Equal(
            new[] { 132_009U, 420_301U, 420_301U, 150_003U },
            playerItems.EquipmentItems.Select(item => item.ItemId).ToArray());
        Assert.Equal(
            new ushort[] { 3, 4, 5, 6 },
            playerItems.EquipmentItems.Select(item => item.Position).ToArray());
        Assert.All(playerItems.EquipmentItems, item =>
        {
            Assert.Equal(1, item.Durability);
            Assert.Equal(1, item.MaximumDurability);
            Assert.Equal(0, item.Bound);
            Assert.InRange(item.Color, 3U, 8U);
        });
