    [Fact]
    public void LegacyThunderStrikerStarterSourceSpellsExcludeRebirthOnlySpell()
    {
        var method = typeof(WorldServerFrameHandler).GetMethod(
            "TryGetLegacyFirstCharacterStarterSpellProfile",
            BindingFlags.Static | BindingFlags.NonPublic);
        Assert.NotNull(method);
        object?[] args = [9_000L, null];

        Assert.True((bool)method.Invoke(null, args)!);

        Assert.NotNull(args[1]);
        var sourceProperty = args[1]!.GetType().GetProperty("SourceSpellIds");
        Assert.NotNull(sourceProperty);
        var sourceSpellIds = Assert.IsAssignableFrom<IReadOnlyList<ushort>>(sourceProperty.GetValue(args[1]));
        Assert.Equal(
            new ushort[] { 15_800, 15_700, 15_770, 15_670, 15_680, 15_690 },
            sourceSpellIds.ToArray());
        Assert.DoesNotContain((ushort)15_720, sourceSpellIds);
    }

