        File.WriteAllBytes(
            Path.Combine(playerSpellsRoot, "1293600.bin"),
            PlayerSpellSnapshotLoaderTests.BuildPlayerSpellRecords(
                [PlayerSpellSnapshotLoaderTests.Entry(1110, level: 3, experience: 9876)]));
