    [Fact]
    public async Task HandlerLegacyNobilityConquerPointsDonateDoesNotTreatOrphanTradeRequestAsOpenTrade()
    {
        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(
            1293600,
            uid: 1293600,
            money: 0,
            conquerPoints: 500_000,
            boundConquerPoints: 0);
        using var log = new StringWriter();
        var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot), log);
        var sent = new List<byte[]>();
        var connection = CreateSendingConnection(sent);

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new LegacyMsgLoginGamePacket(1293600).ToFrameBytes()));

        var startupCount = sent.Count;
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new LegacyTradePacket(Type: 0).ToFrameBytes()));
        Assert.False(GetSession(handler, connection).LegacyTradeActive);

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new LegacyNobilityRequestPacket(
                LegacyNobilityAction.Donate,
                Value: 250_000_000,
                DonationType: (byte)LegacyNobilityDonationType.ConquerPoints).ToFrameBytes()));

        Assert.Equal(startupCount + 3, sent.Count);
        var updated = GetSession(handler, connection);
        Assert.False(updated.LegacyTradeActive);
        Assert.Equal(0, updated.Character.ConquerPoints);
        Assert.Equal("250000000", updated.Character.Attributes["DonationNobility"]);

        var output = log.ToString();
        Assert.DoesNotContain("reason=inTrade", output);
        Assert.Contains("WorldServer applied LegacyNobility donation", output);
        Assert.True(LegacyNobilityIconPacket.TryParse(ReadFrame(sent[startupCount]), out var icon));
        Assert.Equal(250_000_000UL, icon.Donation);
        AssertSingleUpdate(sent[startupCount + 1], 1_293_600, LegacyMsgUpdateDataType.ConquerPoints, 0);

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new LegacyTradePacket(Type: 2).ToFrameBytes()));
        Assert.False(GetSession(handler, connection).LegacyTradeActive);

        Assert.Equal(startupCount + 3, sent.Count);
    }

    [Fact]
    public async Task HandlerLegacyNobilityDonatePersistsAndReloadsSourceBackedKingRank()
    {
        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(
            1293600,
            uid: 1293600,
            money: 500_000_000,
            conquerPoints: 500_000,
            boundConquerPoints: 50);
        using var log = new StringWriter();
        var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot), log);
        var sent = new List<byte[]>();
        var connection = CreateSendingConnection(sent);

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new LegacyMsgLoginGamePacket(1293600).ToFrameBytes()));

        var startupCount = sent.Count;
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new LegacyNobilityRequestPacket(
                LegacyNobilityAction.Donate,
                Value: 250_000_000,
                DonationType: (byte)LegacyNobilityDonationType.ConquerPoints).ToFrameBytes()));

        Assert.True(LegacyNobilityIconPacket.TryParse(ReadFrame(sent[startupCount]), out var icon));
        Assert.Equal(250_000_000UL, icon.Donation);
        Assert.Equal((byte)12, icon.Rank);
        Assert.Equal(0, icon.Position);
        AssertSingleUpdate(sent[startupCount + 1], 1_293_600, LegacyMsgUpdateDataType.ConquerPoints, 0);

        var rankListenIndex = sent.Count;
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new LegacyNobilityRequestPacket(
                LegacyNobilityAction.RankListen,
                Value: 0,
                DonationType: 0).ToFrameBytes()));

        Assert.True(LegacyNobilityRankListPacket.TryParse(ReadFrame(sent[rankListenIndex]), out var rankList));
        var entry = Assert.Single(rankList.Entries);
        Assert.Equal(1_293_600U, entry.Uid);
        Assert.Equal(250_000_000UL, entry.Donation);
        Assert.Equal((byte)12, entry.Rank);
        Assert.Equal(0, entry.Position);

        var reloaded = new CharacterSnapshotLoader(_usersRoot).LoadByAccountId(1293600);
        Assert.NotNull(reloaded);
        Assert.Equal(500_000_000, reloaded.Money);
        Assert.Equal(0, reloaded.ConquerPoints);
        Assert.Equal("250000000", reloaded.Attributes["DonationNobility"]);
        Assert.Equal("250000000", reloaded.Attributes["LastNobilityDonation"]);
        Assert.Equal("12", reloaded.Attributes["NobilityRank"]);
        Assert.Equal("0", reloaded.Attributes["NobilityPosition"]);
        var reloadedIcon = LegacyNobilityIconPacket.FromSnapshot(reloaded, _usersRoot);
        Assert.Equal(250_000_000UL, reloadedIcon.Donation);
        Assert.Equal((byte)12, reloadedIcon.Rank);
        Assert.Equal(0, reloadedIcon.Position);

        using var reloadLog = new StringWriter();
        var reloadHandler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot), reloadLog);
        var reloadSent = new List<byte[]>();
        var reloadConnection = CreateSendingConnection(reloadSent);

        await reloadHandler.HandleFrameAsync(
            reloadConnection,
            ReadFrame(new LegacyMsgLoginGamePacket(1293600).ToFrameBytes()));

        LegacyNobilityIconPacket? startupIcon = null;
        foreach (var frameBytes in reloadSent)
        {
            if (LegacyNobilityIconPacket.TryParse(ReadFrame(frameBytes), out var parsed))
            {
                startupIcon = parsed;
                break;
            }
        }

        Assert.NotNull(startupIcon);
        Assert.Equal(250_000_000UL, startupIcon.Value.Donation);
        Assert.Equal((byte)12, startupIcon.Value.Rank);
        Assert.Equal(0, startupIcon.Value.Position);

        var output = log.ToString();
        Assert.Contains("WorldServer applied LegacyNobility donation", output);
        Assert.Contains("rank=12 position=0", output);
        Assert.Contains("spentCurrency=ConquerPoints", output);
        Assert.Contains("WorldServer persisted LegacyNobility", output);
        Assert.DoesNotContain("PARITY-GAP unmodeled LegacyNobility", output);
    }

    [Fact]
    public async Task HandlerLegacyNobilityDonateBroadcastsPromotionAndChangedIconToAffectedOnlineNoble()
    {
        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(10, uid: 10, name: "First", nobilityDonation: 400_000_000);
        WriteSnapshot(20, uid: 20, name: "Second", nobilityDonation: 390_000_000);
        WriteSnapshot(30, uid: 30, name: "Third", nobilityDonation: 380_000_000);
        WriteSnapshot(40, uid: 40, name: "Donor", money: 0, conquerPoints: 770_000, nobilityDonation: 0);
        using var log = new StringWriter();
        var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot), log);
        var donorSent = new List<byte[]>();
        var displacedSent = new List<byte[]>();
        var donorConnection = CreateSendingConnection(donorSent);
        var displacedConnection = CreateSendingConnection(displacedSent);

        await handler.HandleFrameAsync(
            displacedConnection,
            ReadFrame(new LegacyMsgLoginGamePacket(30).ToFrameBytes()));
        await handler.HandleFrameAsync(
            donorConnection,
            ReadFrame(new LegacyMsgLoginGamePacket(40).ToFrameBytes()));

        var donorStart = donorSent.Count;
        var displacedStart = displacedSent.Count;
        await handler.HandleFrameAsync(
            donorConnection,
            ReadFrame(new LegacyNobilityRequestPacket(
                LegacyNobilityAction.Donate,
                Value: 385_000_000,
                DonationType: (byte)LegacyNobilityDonationType.ConquerPoints).ToFrameBytes()));

        Assert.Equal(donorStart + 3, donorSent.Count);
        Assert.True(LegacyNobilityIconPacket.TryParse(ReadFrame(donorSent[donorStart]), out var donorIcon));
        Assert.Equal(40UL, donorIcon.Uid);
        Assert.Equal(385_000_000UL, donorIcon.Donation);
        Assert.Equal((byte)12, donorIcon.Rank);
        Assert.Equal(2, donorIcon.Position);
        AssertSingleUpdate(donorSent[donorStart + 1], 40, LegacyMsgUpdateDataType.ConquerPoints, 0);
        Assert.True(LegacyMsgMessagePacket.TryParse(ReadFrame(donorSent[donorStart + 2]), out var donorMessage));
        Assert.Equal(LegacyMsgMessagePacket.RedColor, donorMessage.Color);
        Assert.Equal(LegacyMsgMessagePacket.CenterChatType, donorMessage.ChatType);
        Assert.Equal("Donor has been promoted to King.", donorMessage.Content[3]);

        Assert.Equal(displacedStart + 2, displacedSent.Count);
        Assert.True(LegacyNobilityIconPacket.TryParse(ReadFrame(displacedSent[displacedStart]), out var displacedIcon));
        Assert.Equal(30UL, displacedIcon.Uid);
        Assert.Equal(380_000_000UL, displacedIcon.Donation);
        Assert.Equal((byte)9, displacedIcon.Rank);
        Assert.Equal(3, displacedIcon.Position);
        Assert.True(LegacyMsgMessagePacket.TryParse(ReadFrame(displacedSent[displacedStart + 1]), out var displacedMessage));
        Assert.Equal("Donor has been promoted to King.", displacedMessage.Content[3]);

        var displaced = GetSession(handler, displacedConnection).Character;
        Assert.Equal("9", displaced.Attributes["NobilityRank"]);
        Assert.Equal("3", displaced.Attributes["NobilityPosition"]);
        var donor = GetSession(handler, donorConnection).Character;
        Assert.Equal("12", donor.Attributes["NobilityRank"]);
        Assert.Equal("2", donor.Attributes["NobilityPosition"]);

        var output = log.ToString();
        Assert.Contains("WorldServer sent LegacyNobility changed icon fanout", output);
        Assert.Contains("WorldServer broadcast LegacyNobility promotion", output);
        Assert.DoesNotContain("PARITY-GAP unmodeled LegacyNobility", output);
    }

