        Assert.Equal("200000000", persisted.Attributes["DonationNobility"]);
        Assert.Equal("5", persisted.Attributes["NobilityRank"]);

        var output = log.ToString();
        Assert.Contains("WorldServer applied LegacyNobility donation", output);
        Assert.Contains("donationType=1", output);
        Assert.Contains("spentCurrency=BoundConquerPoints", output);
        Assert.DoesNotContain("PARITY-GAP unsupported LegacyNobility donation type", output);
        Assert.DoesNotContain("PARITY-GAP unmodeled LegacyNobility", output);
    }

