        var handler = new WorldServerFrameHandler(snapshotLoader: null, log);
        var sent = new List<byte[]>();
        var connection = CreateSendingConnection(sent);
        var writer = new PacketWriter(LegacyMsgLoginGamePacket.Opcode, LegacyMsgLoginGamePacket.PayloadLength - 1);

        await handler.HandleFrameAsync(connection, ReadFrame(writer.ToArray()));
        await handler.HandleFrameAsync(
