    [Fact]
    public async Task HandlerSkipsStartupItemsMissingOldClientCatalogByDefault()
    {
        var dbRoot = Path.Combine(Path.GetTempPath(), "wolf-world-handler-items-catalog-" + Guid.NewGuid());
        try
        {
            var usersRoot = Path.Combine(dbRoot, "Users");
            var itemsRoot = Path.Combine(dbRoot, "PlayersItems");
            Directory.CreateDirectory(usersRoot);
            Directory.CreateDirectory(itemsRoot);
            WriteSnapshot(usersRoot, 1293600, uid: 1293600);
            File.WriteAllBytes(
                Path.Combine(itemsRoot, "1293600.bin"),
                PlayerItemSnapshotLoaderTests.BuildPlayerItems(
                [
                    PlayerItemSnapshotLoaderTests.DbItem(uid: 1001, itemId: 3_324_226, position: 0),
                    PlayerItemSnapshotLoaderTests.DbItem(uid: 1002, itemId: 3_316_793, position: 0, stackSize: 12),
                    PlayerItemSnapshotLoaderTests.DbItem(uid: 1003, itemId: 729_464, position: 0),
                ],
                []));
            var worldData = CreateStaticVisibilityCatalog(
                items:
                [
                    new ItemType(3_324_226, "KnownItem", ["3324226", "KnownItem"]),
                    new ItemType(3_316_793, "PeachJade", ["3316793", "PeachJade"]),
                    new ItemType(729_464, "BoundCpsPack", ["729464", "2,999CPPack(B)"]),
                ]);
            using var log = new StringWriter();
            var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
            var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
            var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(usersRoot), handoff, worldData, log);
            var sent = new List<byte[]>();
            var connection = CreateSendingConnection(sent);

            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));

            var itemIds = ParseLegacyStartupItemIds(sent);
            Assert.Contains(3_324_226U, itemIds);
            Assert.DoesNotContain(3_316_793U, itemIds);
            Assert.DoesNotContain(729_464U, itemIds);
            Assert.Contains(
                GetSession(handler, connection).PlayerItems.InventoryItems,
                item => item.ItemId == 3_316_793U && item.StackSize == 12);
            Assert.Contains(
                GetSession(handler, connection).PlayerItems.InventoryItems,
                item => item.ItemId == 729_464U);
            var output = log.ToString();
            Assert.Contains("skipped old-client startup item incompatible with old-client itemtype catalog", output);
            Assert.Contains("itemId=3316793", output);
            Assert.Contains("itemId=729464", output);
            Assert.Contains("category=inventory", output);
        }
        finally
        {
            if (Directory.Exists(dbRoot))
            {
                Directory.Delete(dbRoot, recursive: true);
            }
        }
    }

