    [Fact]
    public async Task HandlerPersistsChangedPlayerSpellsWhenSessionIsUpdated()
    {
        var dbRoot = Path.Combine(Path.GetTempPath(), "wolf-world-handler-spells-" + Guid.NewGuid());
        try
        {
            var usersRoot = Path.Combine(dbRoot, "Users");
            var spellsRoot = Path.Combine(dbRoot, "PlayersSpells");
            Directory.CreateDirectory(usersRoot);
            Directory.CreateDirectory(spellsRoot);
            WriteSnapshot(usersRoot, 1293600, uid: 1293600);
            var existingSpell = PlayerSpellSnapshotLoaderTests.Entry(1000, level: 1, experience: 10);
            File.WriteAllBytes(
                Path.Combine(spellsRoot, "1293600.bin"),
                PlayerSpellSnapshotLoaderTests.BuildPlayerSpellRecords([existingSpell]));
            using var log = new StringWriter();
            var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
            var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
            var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(usersRoot), handoff, log);
            var sent = new List<byte[]>();
            var connection = CreateSendingConnection(sent);

            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));
            var session = GetSession(handler, connection);
            var learnedSpell = PlayerSpellSnapshotLoaderTests.Entry(12345, level: 2, experience: 250);
            Assert.DoesNotContain(session.PlayerSpells.Spells, spell => spell.Id == learnedSpell.Id);
            var expectedSpells = session.PlayerSpells.Spells.Concat([learnedSpell]).ToArray();
            SetSession(handler, connection, session with
            {
                PlayerSpells = new PlayerSpellSnapshot(expectedSpells),
            });

            var persisted = new PlayerSpellSnapshotLoader(spellsRoot).LoadByCharacterUid(1293600);
            Assert.Equal(expectedSpells, persisted.Spells);
            Assert.DoesNotContain("player spell persistence failed", log.ToString());
        }
        finally
        {
            if (Directory.Exists(dbRoot))
            {
                Directory.Delete(dbRoot, recursive: true);
            }
        }
    }

