    [Fact]
    public async Task HandlerSendsAssociationKnownPersonsAfterMailAndAnimaBeforeBeasts()
    {
        var dbRoot = Path.Combine(Path.GetTempPath(), "wolf-world-handler-association-startup-" + Guid.NewGuid());
        try
        {
            var usersRoot = Path.Combine(dbRoot, "Users");
            Directory.CreateDirectory(usersRoot);
            WriteSnapshot(
                usersRoot,
                900201,
                uid: 900201,
                tailedBeastActivated: true,
                tailedBeastTotalPoints: 2_448_000,
                tailedBeastFlag: 31);
            var values = new int[14];
            values[11] = 1003;
            values[12] = 42;
            values[13] = 1;
            SocialAssociationRecord Record(int relationType, int targetId, string targetName) => new(
                OwnerId: 900_201,
                RelationType: relationType,
                TargetId: targetId,
                TargetName: targetName,
                Values: values,
                Note: "Synthetic association",
                TailValue: 0,
                SourceFile: "synthetic-associations.txt",
                LineNumber: relationType,
                RawLine: string.Empty,
                Fields: []);
            var worldData = CreateStaticVisibilityCatalog(socialAssociations:
            [
                Record(1, 900_202, "SyntheticFriend"),
                Record(2, 900_203, "SyntheticEnemy"),
                Record(3, 900_202, "SyntheticFriend"),
            ]);
            var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
            var ticket = handoff.Issue(900201, "user02", ConquerRuntimeDefaults.WorldServer);
            var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(usersRoot), handoff, worldData);
            var sent = new List<byte[]>();

            await handler.HandleFrameAsync(
                CreateSendingConnection(sent),
                ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));

            var mailIndex = FindOpcodeIndex(sent, WorldPacketOpcodes.LegacyMailNotify, startIndex: 1);
            Assert.True(LegacyMailNotifyPacket.TryParse(ReadFrame(sent[mailIndex]), out _));
            Assert.True(LegacyDragonSkinPacket.TryParse(ReadFrame(sent[mailIndex + 1]), out _));
            Assert.True(LegacyKnownPersonPacket.TryParse(ReadFrame(sent[mailIndex + 2]), out var friend));
            Assert.True(LegacyKnownPersonPacket.TryParse(ReadFrame(sent[mailIndex + 3]), out var enemy));
            Assert.True(LegacyTradePartnerPacket.TryParse(ReadFrame(sent[mailIndex + 4]), out var tradePartner));
            Assert.True(LegacyBeastsInfoPacket.TryParse(ReadFrame(sent[mailIndex + 5]), out _));
            Assert.DoesNotContain(
                sent,
                bytes => ReadFrame(bytes).Header.Opcode == WorldPacketOpcodes.LegacyApprenticeInformation);

            Assert.Equal(LegacyKnownPersonAction.AddFriend, friend.Action);
            Assert.Equal(900_202U, friend.Uid);
            Assert.Equal("SyntheticFriend", friend.Name);
            Assert.False(friend.Online);
            Assert.Equal(0U, friend.NobilityRank);
            Assert.Equal(0U, friend.LookFace);
            Assert.Equal(0U, friend.Level);

            Assert.Equal(LegacyKnownPersonAction.AddEnemy, enemy.Action);
            Assert.Equal(900_203U, enemy.Uid);
            Assert.Equal("SyntheticEnemy", enemy.Name);
            Assert.False(enemy.Online);

            Assert.Equal(LegacyTradePartnerAction.AddPartner, tradePartner.Action);
            Assert.Equal(900_202U, tradePartner.Uid);
            Assert.Equal("SyntheticFriend", tradePartner.Name);
            Assert.False(tradePartner.Online);
            Assert.Equal(1003U, tradePartner.LookFace);
            Assert.Equal(42U, tradePartner.Level);
            Assert.Equal(1U, tradePartner.NobilityRank);

        }
        finally
        {
            if (Directory.Exists(dbRoot))
            {
                Directory.Delete(dbRoot, recursive: true);
            }
        }
    }

