    [Fact]
    public async Task HandlerSendsFlowerAndClanStartupAfterActiveness()
    {
        var dbRoot = Path.Combine(Path.GetTempPath(), "wolf-world-handler-flower-clan-" + Guid.NewGuid());
        try
        {
            var usersRoot = Path.Combine(dbRoot, "Users");
            var clansRoot = Path.Combine(dbRoot, "Clans");
            Directory.CreateDirectory(usersRoot);
            Directory.CreateDirectory(clansRoot);
            WriteSnapshot(
                usersRoot,
                1293600,
                uid: 1293600,
                flowers: "1/0/0/0/0/0/0/0/0/",
                clanId: 329,
                clanRank: 100,
                clanDonation: 500000,
                weatherType: 4);
            var snapshotPath = Path.Combine(usersRoot, "1293600.ini");
            File.WriteAllText(
                snapshotPath,
                File.ReadAllText(snapshotPath).Replace(
                    "PkPoints=0",
                    "SpecialTitles=3,6002,0,2002,0,9999,0,\r\nPkPoints=0"));
            File.WriteAllText(
                Path.Combine(clansRoot, "329.txt"),
                "Count=3\r\n329/01033671750/CoFreeDom3D[PM]/0/500000/None/0/0/0/0/\r\n0/\r\n0/\r\n");
            File.WriteAllText(
                Path.Combine(dbRoot, "InnerPower.txt"),
                "Count=1\r\nCoder[GM]/1293600/3000/0/\r\n");
            File.WriteAllText(
                Path.Combine(dbRoot, "title_type.txt"),
                string.Join(
                    "\r\n",
                    "6002@@21@@RadiantWings@@0@@0@@0@@0@@0@@",
                    "2002@@3@@Victor@@0@@0@@0@@0@@150@@",
                    "9999@@1@@Anchor@@0@@0@@0@@0@@59120@@"));
            var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
            var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
            var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(usersRoot), handoff);
            var sent = new List<byte[]>();

            await handler.HandleFrameAsync(
                CreateSendingConnection(sent),
                ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));

            var claimsIndex = FindOpcodeIndex(sent, WorldPacketOpcodes.LegacyActivityClaims);
            var flowerIndex = FindOpcodeIndex(sent, WorldPacketOpcodes.LegacyFlower);
            var clanIndex = FindOpcodeIndex(sent, WorldPacketOpcodes.LegacyClan);
            var jiangHuIndex = FindOpcodeIndex(sent, WorldPacketOpcodes.LegacyJiangHuInfo);
            var innerPowerIndex = FindSingleUpdateIndex(
                sent,
                LegacyMsgUpdateDataType.InnerPowerPotency,
                jiangHuIndex + 1);
            var vipLevelIndex = FindSingleUpdateIndex(
                sent,
                LegacyMsgUpdateDataType.VIPLevel,
                innerPowerIndex + 1);
            var vipStatusIndex = FindOpcodeIndex(
                sent,
                WorldPacketOpcodes.LegacyMsgVipStatus,
                vipLevelIndex + 1);
            var merchantIndex = FindSingleUpdateIndex(
                sent,
                LegacyMsgUpdateDataType.Merchant,
                vipStatusIndex + 1);
            var merchantActionIndex = FindOpcodeIndex(
                sent,
                WorldPacketOpcodes.MsgAction,
                merchantIndex + 1);
            var titleStorageIndex = FindOpcodeIndex(
                sent,
                WorldPacketOpcodes.LegacyMsgTitleStorage,
                merchantActionIndex + 1);
            var coatStorageIndex = FindOpcodeIndex(
                sent,
                WorldPacketOpcodes.LegacyCoatStorage,
                titleStorageIndex + 1);
            var fullLoadTitleIndex = FindOpcodeIndex(
                sent,
                WorldPacketOpcodes.LegacyMsgTitleStorage,
                coatStorageIndex + 1);
            var weatherIndex = FindOpcodeIndex(
                sent,
                WorldPacketOpcodes.LegacyWeather,
                fullLoadTitleIndex + 1);
            var welcomeTalkIndex = FindOpcodeIndex(
                sent,
                WorldPacketOpcodes.LegacyMsgMessage,
                weatherIndex + 1);
            var staticGuiIndex = FindOpcodeIndex(
                sent,
                WorldPacketOpcodes.LegacyNpcReply,
                welcomeTalkIndex + 1);
            var runeRankIndex = FindOpcodeIndex(
                sent,
                WorldPacketOpcodes.LegacyMsgMessage,
                staticGuiIndex + 1);
            var runeStorageIndex = FindOpcodeIndex(
                sent,
                WorldPacketOpcodes.LegacyRuneStorage,
                runeRankIndex + 1);

            Assert.Equal(claimsIndex + 1, flowerIndex);
            Assert.Equal(flowerIndex + 1, clanIndex);
            Assert.Equal(clanIndex + 1, jiangHuIndex);
            Assert.Equal(jiangHuIndex + 1, innerPowerIndex);
            Assert.Equal(innerPowerIndex + 1, vipLevelIndex);
            Assert.Equal(vipLevelIndex + 1, vipStatusIndex);
            Assert.Equal(vipStatusIndex + 1, merchantIndex);
            Assert.Equal(merchantIndex + 1, merchantActionIndex);
            Assert.Equal(merchantActionIndex + 1, titleStorageIndex);
            Assert.True(titleStorageIndex < coatStorageIndex);
            Assert.True(coatStorageIndex < fullLoadTitleIndex);
            Assert.True(fullLoadTitleIndex < weatherIndex);
            Assert.True(weatherIndex < welcomeTalkIndex);
            Assert.True(welcomeTalkIndex < staticGuiIndex);
            Assert.True(staticGuiIndex < runeRankIndex);
            Assert.True(runeRankIndex < runeStorageIndex);
            Assert.True(LegacyFlowerPacket.TryParse(ReadFrame(sent[flowerIndex]), out var flower));
            Assert.Equal(LegacyFlowerPacket.FlowerSenderAction, flower.Action);
            Assert.Equal(1U, flower.RedRoses);
            Assert.True(LegacyClanPacket.TryParse(ReadFrame(sent[clanIndex]), out var clan));
            Assert.Equal(329U, clan.ClanId);
            Assert.Equal("329 1 0 500000 0 100 0 0 0 0 0 500000", clan.Values[0]);
            Assert.True(LegacyJiangHuInfoPacket.TryParse(ReadFrame(sent[jiangHuIndex]), out var jiangHu));
            Assert.Equal(LegacyJiangHuInfoPacket.IconBarMode, jiangHu.Mode);
            Assert.Equal(["0"], jiangHu.Values);
            AssertSingleUpdate(sent[innerPowerIndex], 1_293_600, LegacyMsgUpdateDataType.InnerPowerPotency, 3000);
            AssertSingleUpdate(sent[vipLevelIndex], 1_293_600, LegacyMsgUpdateDataType.VIPLevel, 0);
            Assert.True(LegacyVipStatusPacket.TryParse(ReadFrame(sent[vipStatusIndex]), out var vipStatus));
            Assert.Equal(LegacyVipStatusFlags.None, vipStatus.Flags);
            AssertSingleUpdate(sent[merchantIndex], 1_293_600, LegacyMsgUpdateDataType.Merchant, 255);
            Assert.True(MsgActionPacket.TryParse(ReadFrame(sent[merchantActionIndex]), out var merchantAction));
            Assert.Equal(MsgActionType.LegacyMerchantStartup, merchantAction.Type);
            Assert.Equal(2U, merchantAction.DwParam);
            Assert.True(LegacyTitleStoragePacket.TryParse(ReadFrame(sent[titleStorageIndex]), out var titleStorage));
            Assert.Equal(LegacyTitleStorageAction.UnEquip, titleStorage.Action);
            Assert.Equal(6002U, titleStorage.DwParam2);
            Assert.Equal(21U, titleStorage.DwParam3);
            Assert.Equal(
                "0d0009090805100018f22e2015",
                Convert.ToHexString(sent[titleStorageIndex]).ToLowerInvariant());
            Assert.True(LegacyCoatStoragePacket.TryParse(ReadFrame(sent[coatStorageIndex]), out var coatStorage));
            Assert.Empty(coatStorage.Items);
            Assert.True(LegacyTitleStoragePacket.TryParse(ReadFrame(sent[fullLoadTitleIndex]), out var fullLoadTitle));
            Assert.Equal(LegacyTitleStorageAction.UpdateScore, fullLoadTitle.Action);
            Assert.Equal(59120U, fullLoadTitle.DwParam1);
            Assert.Equal(9999U, fullLoadTitle.DwParam2);
            Assert.Equal(1U, fullLoadTitle.DwParam3);
            Assert.True(LegacyWeatherPacket.TryParse(ReadFrame(sent[weatherIndex]), out var weather));
            Assert.Equal(LegacyWeatherType.RainWind, weather.Type);
            Assert.Equal(250U, weather.Intensity);
            Assert.True(LegacyMsgMessagePacket.TryParse(ReadFrame(sent[welcomeTalkIndex]), out var welcomeTalk));
            Assert.Equal(LegacyMsgMessagePacket.TalkChatType, welcomeTalk.ChatType);
            Assert.Equal("Welcome to WolfConquer.", welcomeTalk.Content[3]);
            Assert.True(LegacyNpcReplyPacket.TryParse(ReadFrame(sent[staticGuiIndex]), out var staticGui));
            Assert.Equal(LegacyNpcReplyInteractType.StaticGui, staticGui.InteractType);
            Assert.Equal("Welcome to WolfConquer.", staticGui.Text);
            Assert.True(LegacyMsgMessagePacket.TryParse(ReadFrame(sent[runeRankIndex]), out var runeRank));
            Assert.Equal("My ranking: Unranked; Current rune pack score: 0", runeRank.Content[3]);
        }
        finally
        {
            if (Directory.Exists(dbRoot))
            {
                Directory.Delete(dbRoot, recursive: true);
            }
        }
    }

