                ReadFrame(new LegacyClanPacket(LegacyClanPacket.MyClanMode, 0, 0, []).ToFrameBytes()));

            var responses = sent.Skip(countBeforeRequest).ToArray();
            Assert.Equal(2, responses.Length);
            Assert.True(LegacyClanPacket.TryParse(ReadFrame(responses[0]), out var clanInfo));
            Assert.Equal(LegacyClanPacket.InfoMode, clanInfo.Mode);
            Assert.Equal(329U, clanInfo.ClanId);
            Assert.Equal("329 1 0 500000 0 100 0 0 0 0 0 500000", clanInfo.Values[0]);
            Assert.True(LegacyClanPacket.TryParse(ReadFrame(responses[1]), out var cityWarStatus));
            Assert.Equal(LegacyClanPacket.MyClanMode, cityWarStatus.Mode);
            Assert.Equal(329U, cityWarStatus.ClanId);
            Assert.Equal(["0 0 0 0 0 0 0"], cityWarStatus.Values);

            var output = log.ToString();
            Assert.Contains("WorldServer handled LegacyClan", output);
            Assert.Contains("mode=29 clanId=329 responses=2", output);
            Assert.DoesNotContain("WorldServer deferred LegacyClan", output);
        }
        finally
        {
            if (Directory.Exists(dbRoot))
            {
                Directory.Delete(dbRoot, recursive: true);
            }
        }
    }

