    [Fact]
    public async Task HandlerSendsPrivilegedBroadcastAfterTitleStorageBeforeWeather()
    {
        var dbRoot = Path.Combine(Path.GetTempPath(), "wolf-world-handler-pm-broadcast-" + Guid.NewGuid());
        try
        {
            var usersRoot = Path.Combine(dbRoot, "Users");
            Directory.CreateDirectory(usersRoot);
            WriteSnapshot(
                usersRoot,
                1293600,
                uid: 1293600,
                weatherType: 4);
            var snapshotPath = Path.Combine(usersRoot, "1293600.ini");
            File.WriteAllText(
                snapshotPath,
                File.ReadAllText(snapshotPath)
                    .Replace("Name=HeroOne", "Name=Coder[PM]")
                    .Replace("PkPoints=0", "SpecialTitles=1,6023,1,\r\nPkPoints=0"));
            File.WriteAllText(
                Path.Combine(dbRoot, "title_type.txt"),
                "6023@@6023@@VioletWings@@0@@0@@0@@0@@100@@");
            var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
            var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
            var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(usersRoot), handoff);
            var sent = new List<byte[]>();

            await handler.HandleFrameAsync(
                CreateSendingConnection(sent),
                ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));

            var titleStorageIndex = FindOpcodeIndex(sent, WorldPacketOpcodes.LegacyMsgTitleStorage);
            var broadcastIndex = FindOpcodeIndex(
                sent,
                WorldPacketOpcodes.LegacyMsgMessage,
                titleStorageIndex + 1);
            var weatherIndex = FindOpcodeIndex(
                sent,
                WorldPacketOpcodes.LegacyWeather,
                broadcastIndex + 1);

            Assert.Equal(broadcastIndex + 1, weatherIndex);
            Assert.True(LegacyMsgMessagePacket.TryParse(ReadFrame(sent[broadcastIndex]), out var broadcast));
            Assert.Equal(LegacyMsgMessagePacket.BroadcastChatType, broadcast.ChatType);
            Assert.Equal(LegacyStartupWelcomePackets.PrivilegedBroadcastText, broadcast.Content[3]);
        }
        finally
        {
            if (Directory.Exists(dbRoot))
            {
                Directory.Delete(dbRoot, recursive: true);
            }
        }
    }

