        Assert.Equal(59, sent.Count);
        AssertLegacyWorldEntryStartupFrames(sent, startIndex: 1);
        Assert.True(PacketFrameDecoder.TryRead(new ReadOnlySequence<byte>(sent[^2]), out var actionFrame, out _, out _));
        Assert.True(MsgActionPacket.TryParse(actionFrame, out var action));
        Assert.Equal(1_293_600U, action.ObjId);
        Assert.Equal(1015U, action.DwParam);
        Assert.Equal(1234U, action.Timestamp);
        Assert.Equal(MsgActionType.SetLocation, action.Type);
        Assert.Equal(0, action.Facing);
        Assert.Equal(830U, action.PositionX);
        Assert.Equal(584U, action.PositionY);

        Assert.True(PacketFrameDecoder.TryRead(new ReadOnlySequence<byte>(sent[^1]), out var mapFrame, out _, out _));
        Assert.True(LegacyMapStatusPacket.TryParse(mapFrame, out var mapStatus));
        Assert.Equal(new LegacyMapStatusPacket(1015, 1015, Status: 0), mapStatus);
        Assert.Contains("WorldServer handled MsgAction", log.ToString());
        Assert.Contains("type=SetLocation", log.ToString());
        Assert.Contains("sent LegacyMapStatus", log.ToString());
    }

