    [Fact]
    public async Task HandlerChangeMapActionTeleportsThroughNearbyLegacyPortal()
    {
        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(1293600, uid: 1293600, mapId: 1000, x: 52, y: 50);
        using var log = new StringWriter();
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        var worldData = MsgTeamRuntimeTests.CreateTeamArenaRewardCatalog(
            portals: [new Portal(1000, 50, 50, 9999, 60, 60)],
            maps:
            [
                CreateMapMetadata(1000),
                CreateMapMetadata(9999),
            ]);
        var handler = new WorldServerFrameHandler(
            new CharacterSnapshotLoader(_usersRoot),
            handoff,
            ArenaStatisticsProvider.FromCatalog(worldData),
            TeamArenaStatisticsProvider.FromCatalog(worldData),
            worldData,
            LegacyRuntimeUpdateLoopOptions.Disabled,
            log,
            CreateSparseTerrain(mapId: 9999, width: 61, height: 61, blocked: []));
        var sent = new List<byte[]>();
        var connection = CreateSendingConnection(sent);

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));

        var countBeforeRequest = sent.Count;
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new MsgActionPacket
            {
                ObjId = 1_293_600,
                Timestamp = 4321,
                Type = MsgActionType.ChangeMap,
            }.ToFrameBytes()));

        Assert.Equal(countBeforeRequest + 6, sent.Count);
        Assert.True(MsgActionPacket.TryParse(ReadFrame(sent[countBeforeRequest]), out var teleport));
        Assert.Equal(MsgActionType.Teleport, teleport.Type);
        Assert.Equal(1_293_600U, teleport.ObjId);
        Assert.Equal(9999U, teleport.DwParam);
        Assert.Equal(9999, teleport.DwParam3);
        Assert.Equal(4321U, teleport.Timestamp);
        Assert.Equal(60U, teleport.PositionX);
        Assert.Equal(60U, teleport.PositionY);

        Assert.True(MsgActionPacket.TryParse(ReadFrame(sent[countBeforeRequest + 1]), out var merchantStartup));
        Assert.Equal(MsgActionType.LegacyMerchantStartup, merchantStartup.Type);
        Assert.Equal(2U, merchantStartup.DwParam);
        Assert.Equal(9999, merchantStartup.DwParam3);

        Assert.True(MsgActionPacket.TryParse(ReadFrame(sent[countBeforeRequest + 2]), out var stopVending));
        Assert.Equal(MsgActionType.StopVending, stopVending.Type);
        Assert.Equal(9999U, stopVending.DwParam);
        Assert.Equal(9999, stopVending.DwParam3);

        Assert.True(MsgActionPacket.TryParse(ReadFrame(sent[countBeforeRequest + 3]), out var color));
        Assert.Equal(MsgActionType.LegacyColor, color.Type);
        Assert.Equal(0U, color.DwParam);

        Assert.True(LegacyMapStatusPacket.TryParse(ReadFrame(sent[countBeforeRequest + 4]), out var mapStatus));
        Assert.Equal(new LegacyMapStatusPacket(9999, 9999, Status: 0), mapStatus);

        Assert.True(MsgActionPacket.TryParse(ReadFrame(sent[countBeforeRequest + 5]), out var changeMapAck));
        Assert.Equal(MsgActionType.ChangeMap, changeMapAck.Type);
        Assert.Equal(1_293_600U, changeMapAck.ObjId);

        var updated = GetSession(handler, connection);
        Assert.Equal(9999, updated.Character.MapId);
        Assert.Equal(60, updated.Character.X);
        Assert.Equal(60, updated.Character.Y);
        Assert.Equal(1000, updated.Character.PreviousMapId);
        Assert.Equal(52, updated.Character.PreviousMapX);
        Assert.Equal(50, updated.Character.PreviousMapY);

        var output = log.ToString();
        Assert.Contains("WorldServer handled MsgAction ChangeMap", output);
        Assert.Contains("source=MsgDataPacket.ChangeMap [Data(85)] -> GameClient.Teleport", output);
        Assert.DoesNotContain("PARITY-GAP unmodeled MsgAction", output);
    }

