        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var moverTicket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        var peerTicket = handoff.Issue(1293601, "demon3", ConquerRuntimeDefaults.WorldServer);
        var worldData = MsgTeamRuntimeTests.CreateTeamArenaRewardCatalog(
            portals: [new Portal(1000, 50, 50, 9999, 60, 60)],
            maps:
            [
                CreateMapMetadata(1000),
                CreateMapMetadata(9999),
            ]);
        var handler = new WorldServerFrameHandler(
            new CharacterSnapshotLoader(_usersRoot),
            handoff,
            ArenaStatisticsProvider.FromCatalog(worldData),
            TeamArenaStatisticsProvider.FromCatalog(worldData),
            worldData,
            LegacyRuntimeUpdateLoopOptions.Disabled,
            log,
            CreateSparseTerrain(mapId: 9999, width: 61, height: 61, blocked: []));
        var moverSent = new List<byte[]>();
        var peerSent = new List<byte[]>();
        var moverConnection = CreateSendingConnection(moverSent);
        var peerConnection = CreateSendingConnection(peerSent);

        await handler.HandleFrameAsync(
            moverConnection,
            ReadFrame(new InternalWorldEnterRequestPacket(moverTicket.Token).ToFrameBytes()));
        await handler.HandleFrameAsync(
            peerConnection,
            ReadFrame(new InternalWorldEnterRequestPacket(peerTicket.Token).ToFrameBytes()));

        var peerCountBeforeRequest = peerSent.Count;
        await handler.HandleFrameAsync(
            moverConnection,
            ReadFrame(new MsgActionPacket
            {
                ObjId = 1_293_600,
                Timestamp = 4321,
                Type = MsgActionType.ChangeMap,
            }.ToFrameBytes()));

        Assert.True(peerSent.Count > peerCountBeforeRequest);
        Assert.True(LegacyRemoveEntityPacket.TryParse(ReadFrame(peerSent[peerCountBeforeRequest]), out var remove));
        Assert.Equal(1_293_600U, remove.Uid);

        var output = log.ToString();
        Assert.Contains("WorldServer sent legacy teleport leave RemoveEntity", output);
        Assert.Contains("source=GameClient.Teleport -> Player.View.Clear(stream)", output);
    }

