    [Fact]
    public async Task HandlerSetPkModeActionStoresModeEchoesActionAndSendsLegacyTalk()
    {
        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(1293600, uid: 1293600);
        using var log = new StringWriter();
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot), handoff, log);
        var sent = new List<byte[]>();
        var connection = CreateSendingConnection(sent);

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));

        var countBeforeSetPkMode = sent.Count;
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new MsgActionPacket
            {
                ObjId = 1_293_600,
                DwParam = 3,
                Timestamp = 123_456,
                Type = MsgActionType.SetPkMode,
                PositionX = 830,
                PositionY = 584,
            }.ToFrameBytes()));

        Assert.Equal(countBeforeSetPkMode + 2, sent.Count);
        Assert.True(MsgActionPacket.TryParse(ReadFrame(sent[countBeforeSetPkMode]), out var echo));
        Assert.Equal(MsgActionType.SetPkMode, echo.Type);
        Assert.Equal(1_293_600U, echo.ObjId);
        Assert.Equal(3U, echo.DwParam);
        Assert.Equal(3, echo.DwParam3);
        Assert.Equal(123_456U, echo.Timestamp);
        Assert.True(LegacyMsgMessagePacket.TryParse(ReadFrame(sent[countBeforeSetPkMode + 1]), out var talk));
        Assert.Equal(LegacyMsgMessagePacket.TalkChatType, talk.ChatType);
        Assert.Equal("Capture PK mode. You can only attack monsters, black-name and blue-name players.", talk.Content[3]);
        Assert.Equal("3", GetSession(handler, connection).Character.Attributes["PkMode"]);

        var output = log.ToString();
        Assert.Contains("WorldServer handled MsgAction SetPkMode", output);
        Assert.Contains("source=MsgDataPacket.SetPkMode [Data(96)]", output);
        Assert.DoesNotContain("PARITY-GAP unmodeled MsgAction", output);
    }

    [Fact]
    public async Task HandlerAwayActionTogglesAwayStateEchoesActionAndRefreshesVisiblePeers()
    {
        const int AwayField = 37;
        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(
            1293600,
            uid: 1293600,
            mapId: 1015,
            x: 830,
            y: 584,
            extraCharacterLines: DisableLegacyWeaponProcLines);
        WriteSnapshot(1293601, uid: 1293601, mapId: 1015, x: 836, y: 584, name: "Peer");
        using var log = new StringWriter();
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        var peerTicket = handoff.Issue(1293601, "peer", ConquerRuntimeDefaults.WorldServer);
        var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot), handoff, log);
        var sent = new List<byte[]>();
        var peerSent = new List<byte[]>();
        var connection = CreateSendingConnection(sent);
        var peerConnection = CreateSendingConnection(peerSent);

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));
        await handler.HandleFrameAsync(
            peerConnection,
            ReadFrame(new InternalWorldEnterRequestPacket(peerTicket.Token).ToFrameBytes()));

        var sentBeforeAway = sent.Count;
        var peerSentBeforeAway = peerSent.Count;
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new MsgActionPacket
            {
                ObjId = 1_293_600,
                DwParam = 1,
                Type = MsgActionType.Away,
            }.ToFrameBytes()));

        Assert.Equal(sentBeforeAway + 1, sent.Count);
        Assert.True(MsgActionPacket.TryParse(ReadFrame(sent[sentBeforeAway]), out var awayEcho));
        Assert.Equal(MsgActionType.Away, awayEcho.Type);
        Assert.Equal(1_293_600U, awayEcho.ObjId);
        Assert.Equal(1U, awayEcho.DwParam);
        Assert.Equal(peerSentBeforeAway + 1, peerSent.Count);
        Assert.True(LegacyPlayerSpawnPacket.TryParse(ReadFrame(peerSent[peerSentBeforeAway]), out var awaySpawn));
        Assert.Equal(1UL, awaySpawn.GetNumericField(AwayField));
        Assert.Equal("1", GetSession(handler, connection).Character.Attributes["Away"]);

        sentBeforeAway = sent.Count;
        peerSentBeforeAway = peerSent.Count;
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new MsgActionPacket
            {
                ObjId = 1_293_600,
                DwParam = 0,
                Type = MsgActionType.Away,
            }.ToFrameBytes()));

        Assert.Equal(sentBeforeAway + 1, sent.Count);
        Assert.True(MsgActionPacket.TryParse(ReadFrame(sent[sentBeforeAway]), out var presentEcho));
        Assert.Equal(MsgActionType.Away, presentEcho.Type);
        Assert.Equal(1_293_600U, presentEcho.ObjId);
        Assert.Equal(0U, presentEcho.DwParam);
        Assert.Equal(peerSentBeforeAway + 1, peerSent.Count);
        Assert.True(LegacyPlayerSpawnPacket.TryParse(ReadFrame(peerSent[peerSentBeforeAway]), out var presentSpawn));
        Assert.Equal(0UL, presentSpawn.GetNumericField(AwayField));
        Assert.Equal("0", GetSession(handler, connection).Character.Attributes["Away"]);

        var output = log.ToString();
        Assert.Contains("WorldServer handled MsgAction Away", output);
        Assert.Contains("legacy MsgDataPacket.[Data(161)] toggles Player.Away", output);
        Assert.DoesNotContain("PARITY-GAP unmodeled MsgAction", output);
    }

