    [Theory]
    [InlineData(830, 584, 830, 584)]
    [InlineData(0, 0, 410, 354)]
    public async Task HandlerJumpActionWithDeadNeptuneCursePullsBackToLegacyDeadPosition(
        ushort recordedX,
        ushort recordedY,
        long expectedX,
        long expectedY)
    {
        const int DeadFlag = 0x05;
        const int NeptuneCurseFlag = 0xDE;
        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(
            1293600,
            uid: 1293600,
            mapId: 1015,
            x: 840,
            y: 590,
            minHitPoints: 0,
            statusFlags: BuildStatusFlags(DeadFlag, NeptuneCurseFlag),
            extraCharacterLines:
                $"Dead_X={recordedX}\r\n" +
                $"Dead_Y={recordedY}\r\n");
        WriteSnapshot(
            1293601,
            uid: 1293601,
            mapId: 1015,
            x: expectedX,
            y: expectedY,
            name: "Peer");
        using var log = new StringWriter();
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        var peerTicket = handoff.Issue(1293601, "peer", ConquerRuntimeDefaults.WorldServer);
        var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot), handoff, log);
        var sent = new List<byte[]>();
        var peerSent = new List<byte[]>();
        var connection = CreateSendingConnection(sent);
        var peerConnection = CreateSendingConnection(peerSent);

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));
        await handler.HandleFrameAsync(
            peerConnection,
            ReadFrame(new InternalWorldEnterRequestPacket(peerTicket.Token).ToFrameBytes()));

        var countBeforeJump = sent.Count;
        var peerCountBeforeJump = peerSent.Count;
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new MsgActionPacket
            {
                ObjId = 1_293_600,
                Timestamp = 987,
                Type = MsgActionType.Jump,
                Facing = 6,
                TargetPositionX = 845,
                TargetPositionY = 590,
            }.ToFrameBytes()));

        var updated = GetSession(handler, connection);
        Assert.Equal(expectedX, updated.Character.X);
        Assert.Equal(expectedY, updated.Character.Y);

        var pullbackIndex = FindFrameIndexAfter(
            sent,
            countBeforeJump,
            frame => MsgAttackPacket.TryParse(frame, out var packet) &&
                packet.Query.Uid == 0 &&
                packet.Query.OpponentUid == 1_293_600U &&
                packet.Query.AttackType == MsgAttackType.Death &&
                packet.Query.X == recordedX &&
                packet.Query.Y == recordedY);
        Assert.InRange(pullbackIndex, countBeforeJump, sent.Count - 1);

        var peerPullbackIndex = FindFrameIndexAfter(
            peerSent,
            peerCountBeforeJump,
            frame => MsgAttackPacket.TryParse(frame, out var packet) &&
                packet.Query.Uid == 0 &&
                packet.Query.OpponentUid == 1_293_600U &&
                packet.Query.AttackType == MsgAttackType.Death &&
                packet.Query.X == recordedX &&
                packet.Query.Y == recordedY);
        Assert.InRange(peerPullbackIndex, peerCountBeforeJump, peerSent.Count - 1);

        Assert.DoesNotContain(
            sent.Skip(countBeforeJump).Select(ReadFrame),
            frame => MsgActionPacket.TryParse(frame, out var action) && action.Type == MsgActionType.Jump);
        Assert.Contains("WorldServer handled MsgAction Jump NeptuneCurse dead-position pullback", log.ToString());
    }

    [Fact]
    public async Task HandlerReviveActionRestoresHitpointsStaminaAndClearsDeathFlags()
    {
        const int DeadFlag = 0x05;
        const int GhostFlag = 0x0A;
        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(
            1293600,
            uid: 1293600,
            mapId: 1015,
            minHitPoints: 0,
            statusFlags: BuildStatusFlags(DeadFlag, GhostFlag));
        using var log = new StringWriter();
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot), handoff, log);
        var sent = new List<byte[]>();
        var connection = CreateSendingConnection(sent);

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));

        var countBeforeRevive = sent.Count;
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new MsgActionPacket
            {
                ObjId = 1_293_600,
                Timestamp = 1234,
                Type = MsgActionType.Revive,
            }.ToFrameBytes()));

        Assert.Equal(countBeforeRevive + 6, sent.Count);
        Assert.True(LegacyMsgUpdatePacket.TryParse(ReadFrame(sent[countBeforeRevive]), out var maxHitpoints));
        var maxHitpointUpdate = Assert.Single(maxHitpoints.Updates);
        Assert.Equal(LegacyMsgUpdateDataType.MaxHitpoints, maxHitpointUpdate.Type);
        Assert.True(maxHitpointUpdate.Value > 0);

        Assert.True(LegacyMsgUpdatePacket.TryParse(ReadFrame(sent[countBeforeRevive + 1]), out var hitpoints));
        Assert.Equal(
            [
                new LegacyMsgUpdateEntry(LegacyMsgUpdateDataType.MaxHitpoints, maxHitpointUpdate.Value),
                new LegacyMsgUpdateEntry(LegacyMsgUpdateDataType.Hitpoints, maxHitpointUpdate.Value),
            ],
            hitpoints.Updates);
        AssertSingleUpdate(sent[countBeforeRevive + 2], 1_293_600, LegacyMsgUpdateDataType.Stamina, 100);

        Assert.True(LegacyMsgUpdatePacket.TryParse(ReadFrame(sent[countBeforeRevive + 3]), out var status));
        var statusUpdate = Assert.Single(status.Updates);
        Assert.Equal(LegacyMsgUpdateDataType.StatusFlag, statusUpdate.Type);
        Assert.NotNull(statusUpdate.Values);
        Assert.False(HasLegacyStatusFlag(statusUpdate.Values, DeadFlag));
        Assert.False(HasLegacyStatusFlag(statusUpdate.Values, GhostFlag));
        AssertSingleUpdate(sent[countBeforeRevive + 4], 1_293_600, LegacyMsgUpdateDataType.Mesh, 1_541_008);

        Assert.True(LegacyMapStatusPacket.TryParse(ReadFrame(sent[countBeforeRevive + 5]), out var mapStatus));
        Assert.Equal(new LegacyMapStatusPacket(1015, 1015, Status: 0), mapStatus);

        var updated = GetSession(handler, connection);
        Assert.Equal((long)maxHitpointUpdate.Value, updated.Character.MinHitPoints);
        Assert.False(HasLegacyStatusFlag(
            LegacyPlayerSpawnPacket.FromSnapshot(updated.Character).StatusFlags,
            DeadFlag));
        Assert.False(HasLegacyStatusFlag(
            LegacyPlayerSpawnPacket.FromSnapshot(updated.Character).StatusFlags,
            GhostFlag));
        Assert.Contains("WorldServer handled MsgAction revive", log.ToString());
    }

