    [Fact]
    public async Task HandlerRuntimeLoopAppliesLegacyGhostTransitionAfterGhostStamp()
    {
        const int DeadFlag = 0x05;
        const int GhostFlag = 0x0A;
        var deathAt = new DateTimeOffset(2026, 6, 11, 10, 15, 30, TimeSpan.Zero);
        var tickInterval = TimeSpan.FromMilliseconds(20);
        var timeProvider = new BossRuntimeManualTimeProvider(deathAt);
        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(
            1293600,
            uid: 1293600,
            mapId: 1015,
            x: 830,
            y: 584,
            body: 1007,
            minHitPoints: 0,
            statusFlags: BuildStatusFlags(DeadFlag),
            extraCharacterLines:
                $"DeadStamp={deathAt:O}\r\n" +
                $"GhostStamp={deathAt.AddSeconds(1):O}\r\n" +
                "Dead_X=830\r\n" +
                "Dead_Y=584");
        using var log = new RuntimeThreadSafeStringWriter();
        using var cancel = new CancellationTokenSource();
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        var handler = new WorldServerFrameHandler(
            new CharacterSnapshotLoader(_usersRoot),
            handoff,
            worldData: null,
            new LegacyRuntimeUpdateLoopOptions(
                Enabled: true,
                tickInterval,
                timeProvider),
            log);
        var sent = new RuntimeThreadSafeFrameCapture();
        var connection = CreateSendingConnection(sent);

        try
        {
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()),
                cancel.Token);

            await WaitForMonsterRuntimeTimerRegistrationAsync(timeProvider);
            // Drain initial player XP/stamina/status updates before GhostStamp so
            // its matching status vector cannot interleave the source Status/Mesh/Map triple.
            timeProvider.Advance(tickInterval);
            await WaitForMonsterRuntimeTimerRegistrationAsync(timeProvider);
            Assert.False(HasLegacyStatusFlag(
                LegacyPlayerSpawnPacket.FromSnapshot(GetSession(handler, connection).Character).StatusFlags,
                GhostFlag));
            Assert.Equal(1_007L, GetSession(handler, connection).Character.Body);
            Assert.Equal(154L, GetSession(handler, connection).Character.Face);

            var start = sent.Count;
            timeProvider.Advance(TimeSpan.FromSeconds(1));
            await WaitUntilAsync(
                () =>
                {
                    var firstStatusIndex = FindFrameIndexAfter(
                        sent,
                        start,
                        frame => LegacyMsgUpdatePacket.TryParse(frame, out var update) &&
                            update.Uid == 1_293_600U &&
                            update.Updates.Count == 1 &&
                            update.Updates[0].Type == LegacyMsgUpdateDataType.StatusFlag &&
                            update.Updates[0].Values is { } values &&
                            HasLegacyStatusFlag(values, DeadFlag) &&
                            HasLegacyStatusFlag(values, GhostFlag));
                    return firstStatusIndex >= start &&
                        sent.Count > firstStatusIndex + 2 &&
                        log.ToString().Contains("WorldServer sent player ghost transition", StringComparison.Ordinal);
                },
                TimeSpan.FromSeconds(2));

            var statusIndex = FindFrameIndexAfter(
                sent,
                start,
                frame => LegacyMsgUpdatePacket.TryParse(frame, out var update) &&
                    update.Uid == 1_293_600U &&
                    update.Updates.Count == 1 &&
                    update.Updates[0].Type == LegacyMsgUpdateDataType.StatusFlag &&
                    update.Updates[0].Values is { } values &&
                    HasLegacyStatusFlag(values, DeadFlag) &&
                    HasLegacyStatusFlag(values, GhostFlag));
            Assert.True(LegacyMsgUpdatePacket.TryParse(ReadFrame(sent[statusIndex]), out var status));
            var statusUpdate = Assert.Single(status.Updates);
            Assert.NotNull(statusUpdate.Values);
            Assert.True(HasLegacyStatusFlag(statusUpdate.Values, DeadFlag));
            Assert.True(HasLegacyStatusFlag(statusUpdate.Values, GhostFlag));
            Assert.True(LegacyMsgUpdatePacket.TryParse(ReadFrame(sent[statusIndex + 1]), out var mesh));
            Assert.Equal(1_293_600U, mesh.Uid);
            Assert.Equal(new LegacyMsgUpdateEntry(LegacyMsgUpdateDataType.Mesh, 991_541_007UL),
                Assert.Single(mesh.Updates)); //99*10_000_000 + Face154*10_000 + Body1007.
            Assert.True(LegacyMapStatusPacket.TryParse(ReadFrame(sent[statusIndex + 2]), out var mapStatus));
            Assert.Equal(new LegacyMapStatusPacket(1015, 1015, Status: 0), mapStatus);
            Assert.DoesNotContain(
                sent.Skip(statusIndex + 3),
                frame => LegacyMsgUpdatePacket.TryParse(ReadFrame(frame), out var update) &&
                    update.Uid == 1_293_600U &&
                    update.Updates.Any(entry => entry.Type == LegacyMsgUpdateDataType.Mesh));
            Assert.DoesNotContain(
                sent.Skip(statusIndex + 2),
                frame => LegacyStringPacket.TryParse(ReadFrame(frame), out var packet) &&
                    packet.Uid == 1_293_600U &&
                    packet.Id == LegacyStringId.Effect &&
                    packet.Strings.Contains("ghost", StringComparer.Ordinal));
            Assert.DoesNotContain(
                sent.Skip(statusIndex + 2),
                frame => MsgActionPacket.TryParse(ReadFrame(frame), out var action) &&
                    action.ObjId == 1_293_600U &&
                    action.Type == MsgActionType.Ghost);

            var updated = GetSession(handler, connection);
            Assert.Equal("99", updated.Character.Attributes["TransformationID"]);
            Assert.True(HasLegacyStatusFlag(
                LegacyPlayerSpawnPacket.FromSnapshot(updated.Character).StatusFlags,
                GhostFlag));
            Assert.Contains("WorldServer sent player ghost transition", log.ToString());
        }
        finally
        {
            await cancel.CancelAsync();
        }
    }

    [Fact]
    public async Task HandlerRuntimeLoopSendsDeathRevivePromptAfterLegacyDelay()
    {
        const int DeadFlag = 0x05;
        const int GhostFlag = 0x0A;
        var deathAt = new DateTimeOffset(2026, 6, 11, 10, 15, 30, TimeSpan.Zero);
        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(
            1293600,
            uid: 1293600,
            mapId: 1015,
            x: 830,
            y: 584,
            minHitPoints: 0,
            statusFlags: BuildStatusFlags(DeadFlag, GhostFlag),
            extraCharacterLines:
                $"DeadStamp={deathAt:O}\r\n" +
                $"GhostStamp={deathAt.AddSeconds(1):O}\r\n" +
                "Dead_X=830\r\n" +
                "Dead_Y=584");
        using var log = new RuntimeThreadSafeStringWriter();
        using var cancel = new CancellationTokenSource();
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        var handler = new WorldServerFrameHandler(
            new CharacterSnapshotLoader(_usersRoot),
            handoff,
            worldData: null,
            new LegacyRuntimeUpdateLoopOptions(
                Enabled: true,
                TimeSpan.FromMilliseconds(20),
                new AnchoredRuntimeTimeProvider(deathAt.AddSeconds(21))),
            log);
        var sent = new RuntimeThreadSafeFrameCapture();
        var connection = CreateSendingConnection(sent);

        try
        {
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()),
                cancel.Token);

            var start = sent.Count;
            await WaitUntilAsync(
                () => FindFrameIndexAfter(
                    sent,
                    start,
                    frame => LegacyNpcReplyPacket.TryParse(frame, out var reply) &&
                        reply.InteractType == LegacyNpcReplyInteractType.MessageBox &&
                        reply.Text == LegacyPlayerDeathState.RevivePromptText) >= start,
                TimeSpan.FromSeconds(2));

            var promptIndex = FindFrameIndexAfter(
                sent,
                start,
                frame => LegacyNpcReplyPacket.TryParse(frame, out var reply) &&
                    reply.InteractType == LegacyNpcReplyInteractType.MessageBox &&
                    reply.Text == LegacyPlayerDeathState.RevivePromptText);
            Assert.InRange(promptIndex, start, sent.Count - 1);

            var updated = GetSession(handler, connection);
            Assert.Equal("1", updated.Character.Attributes[LegacyPlayerDeathState.RevivePromptVisibleAttribute]);
            Assert.Equal(
                LegacyPlayerDeathState.RevivePromptPendingKey,
                updated.Character.Attributes[LegacyRuntimeMessageBoxPrompt.PendingAttribute]);
            Assert.Contains("WorldServer processed player death revive prompts prompted=1 cleared=0", log.ToString());
        }
        finally
        {
            await cancel.CancelAsync();
        }
    }

