            extraCharacterLines:
                $"DeadStamp={deathAt:O}\r\n" +
                $"GhostStamp={deathAt.AddSeconds(1):O}\r\n" +
                "Dead_X=830\r\n" +
                "Dead_Y=584\r\n" +
                $"{LegacyPlayerDeathState.RevivePromptVisibleAttribute}=1\r\n" +
                $"{LegacyRuntimeMessageBoxPrompt.PendingAttribute}={LegacyPlayerDeathState.RevivePromptPendingKey}\r\n");
        using var log = new StringWriter();
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
