        var sent = new List<byte[]>();
        var connection = CreateSendingConnection(sent);

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));

        var countBeforeReply = sent.Count;
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(BuildLegacyNpcDialogReply(optionId: 0, interactType: 6)));

        Assert.Equal(countBeforeReply + 6, sent.Count);
        var updated = GetSession(handler, connection);
        Assert.True(updated.Character.MinHitPoints > 0);
        Assert.False(updated.Character.Attributes.ContainsKey(LegacyPlayerDeathState.RevivePromptVisibleAttribute));
        Assert.False(updated.Character.Attributes.ContainsKey(LegacyRuntimeMessageBoxPrompt.PendingAttribute));
        Assert.False(HasLegacyStatusFlag(
            LegacyPlayerSpawnPacket.FromSnapshot(updated.Character).StatusFlags,
            DeadFlag));
        Assert.False(HasLegacyStatusFlag(
            LegacyPlayerSpawnPacket.FromSnapshot(updated.Character).StatusFlags,
            GhostFlag));
        Assert.Contains("WorldServer handled MsgAction revive", log.ToString());
    }

    [Theory]
    [InlineData(LegacyVipTeleportType.SelfTeleport, LegacyVipTeleportLocation.PhoenixCastle, 1011U, 184U, 275U)]
    [InlineData(LegacyVipTeleportType.TeamTeleport, LegacyVipTeleportLocation.DCSquare, 1000U, 502U, 655U)]
    [InlineData(LegacyVipTeleportType.TeammateTeleport, LegacyVipTeleportLocation.BIEast, 1015U, 572U, 370U)]
    public async Task HandlerLegacyVipHandlerTeleportsUsingLegacyDestinationTable(
        LegacyVipTeleportType teleportType,
        LegacyVipTeleportLocation location,
        uint expectedMap,
        uint expectedX,
        uint expectedY)
    {
        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(1293600, uid: 1293600, mapId: 1000, x: 192, y: 345);
        using var log = new StringWriter();
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot), handoff, log);
        var sent = new List<byte[]>();
        var connection = CreateSendingConnection(sent);

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));
        var beforeTeleport = sent.Count;
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new LegacyVipHandlerPacket(teleportType, location, Countdown: 0, Name: "").ToFrameBytes()));

        Assert.Equal(beforeTeleport + 5, sent.Count);
        Assert.True(MsgActionPacket.TryParse(ReadFrame(sent[beforeTeleport]), out var teleport));
        Assert.Equal(1_293_600U, teleport.ObjId);
        Assert.Equal(expectedMap, teleport.DwParam);
        Assert.Equal(expectedMap, teleport.DwParam3);
        Assert.Equal(MsgActionType.Teleport, teleport.Type);
        Assert.Equal(expectedX, teleport.PositionX);
        Assert.Equal(expectedY, teleport.PositionY);

        Assert.True(MsgActionPacket.TryParse(ReadFrame(sent[beforeTeleport + 1]), out var merchantStartup));
        Assert.Equal(MsgActionType.LegacyMerchantStartup, merchantStartup.Type);
        Assert.Equal(2U, merchantStartup.DwParam);
        Assert.Equal(expectedMap, merchantStartup.DwParam3);
        Assert.Equal(expectedX, merchantStartup.PositionX);
        Assert.Equal(expectedY, merchantStartup.PositionY);

        Assert.True(MsgActionPacket.TryParse(ReadFrame(sent[beforeTeleport + 2]), out var stopVending));
        Assert.Equal(MsgActionType.StopVending, stopVending.Type);
        Assert.Equal(expectedMap, stopVending.DwParam);
        Assert.Equal(expectedMap, stopVending.DwParam3);
        Assert.Equal(expectedX, stopVending.PositionX);
        Assert.Equal(expectedY, stopVending.PositionY);

        Assert.True(MsgActionPacket.TryParse(ReadFrame(sent[beforeTeleport + 3]), out var mapColor));
        Assert.Equal(MsgActionType.LegacyColor, mapColor.Type);
        Assert.Equal(0U, mapColor.DwParam);
        Assert.Equal(expectedX, mapColor.PositionX);
        Assert.Equal(expectedY, mapColor.PositionY);

        Assert.True(LegacyMapStatusPacket.TryParse(ReadFrame(sent[beforeTeleport + 4]), out var mapStatus));
        Assert.Equal(new LegacyMapStatusPacket(expectedMap, expectedMap, Status: 0), mapStatus);

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new MsgActionPacket
            {
                ObjId = 1_293_600,
                Timestamp = 1234,
                Type = MsgActionType.SetLocation,
            }.ToFrameBytes()));

        Assert.Equal(beforeTeleport + 7, sent.Count);
        Assert.True(MsgActionPacket.TryParse(ReadFrame(sent[^2]), out var followupAction));
        Assert.Equal(MsgActionType.SetLocation, followupAction.Type);
        Assert.Equal(expectedMap, followupAction.DwParam);
        Assert.Equal(expectedX, followupAction.PositionX);
        Assert.Equal(expectedY, followupAction.PositionY);
        Assert.Contains("WorldServer handled LegacyVipHandler", log.ToString());
        Assert.Contains("applied LegacyVipHandler teleport", log.ToString());
    }

