        Assert.Equal(1002U, firstTeleport.DwParam);
        Assert.Equal(410U, firstTeleport.PositionX);
        Assert.Equal(354U, firstTeleport.PositionY);
        Assert.True(MsgActionPacket.TryParse(ReadFrame(sent[beforeTeleport + 1]), out var firstMerchantStartup));
        Assert.Equal(MsgActionType.LegacyMerchantStartup, firstMerchantStartup.Type);
        Assert.True(MsgActionPacket.TryParse(ReadFrame(sent[beforeTeleport + 2]), out var firstStopVending));
