        Assert.Equal(new LegacyMapStatusPacket(1002, 1002, Status: 0), firstMapStatus);
        Assert.True(LegacyMsgMessagePacket.TryParse(ReadFrame(sent[beforeTeleport + 5]), out var cooldown));
        Assert.Equal(LegacyMsgMessagePacket.TalkChatType, cooldown.ChatType);
        Assert.Contains("more seconds to use the VIP Teleport.", cooldown.Content[3]);
