    [Fact]
    public async Task HandlerLegacySpellSoulSelectionUpdatesSessionPersistsAndSendsTypeThreeResponse()
    {
        var dbRoot = Path.Combine(Path.GetTempPath(), "wolf-world-spell-soul-" + Guid.NewGuid());
        try
        {
            var usersRoot = Path.Combine(dbRoot, "Users");
            var spellsRoot = Path.Combine(dbRoot, "PlayersSpells");
            Directory.CreateDirectory(usersRoot);
            Directory.CreateDirectory(spellsRoot);
            WriteSnapshot(usersRoot, 1293600, uid: 1293600, level: 109);
            var learnedSpell = PlayerSpellSnapshotLoaderTests.Entry(
                10_311,
                level: 3,
                experience: 123_456,
                previousLevel: 1,
                soulLevel: 4,
                useSpellSoul: 1);
            File.WriteAllBytes(
                Path.Combine(spellsRoot, "1293600.bin"),
                PlayerSpellSnapshotLoaderTests.BuildPlayerSpellRecords([learnedSpell]));
            using var log = new StringWriter();
            var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
            var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
            var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(usersRoot), handoff, log);
            var sent = new List<byte[]>();
            var connection = CreateSendingConnection(sent);

            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));

            var request = LegacySpellPacket.FromSnapshot(learnedSpell) with
            {
                UseSoul = LegacySpellPacket.MapUseSoul(3),
            };
            var countBeforeRequest = sent.Count;
            await handler.HandleFrameAsync(connection, ReadFrame(request.ToFrameBytes()));

            Assert.Equal(countBeforeRequest + 1, sent.Count);
            Assert.True(LegacySpellPacket.TryParse(ReadFrame(sent[countBeforeRequest]), out var response));
            Assert.Equal(request with { Type = 3 }, response);

            var session = GetSession(handler, connection);
            var updatedSpell = Assert.Single(session.PlayerSpells.Spells);
            Assert.Equal(3, updatedSpell.UseSpellSoul);

            var persisted = PlayerSpellSnapshotLoader.Parse(
                File.ReadAllBytes(Path.Combine(spellsRoot, "1293600.bin")),
                "1293600.bin");
            Assert.Equal(3, Assert.Single(persisted.Spells).UseSpellSoul);
            Assert.Contains("WorldServer handled LegacySpell soul selection", log.ToString());
            Assert.DoesNotContain("selected soul is session-only", log.ToString());
        }
        finally
        {
            if (Directory.Exists(dbRoot))
            {
                Directory.Delete(dbRoot, recursive: true);
            }
        }
    }

    [Fact]
    public async Task HandlerMovementWalkUpdatesSessionLocationAndEchoesMovement()
    {
        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(1293600, uid: 1293600, x: 830, y: 584);
        using var log = new StringWriter();
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot), handoff, log);
        var sent = new List<byte[]>();
        var connection = CreateSendingConnection(sent);

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));

        var countBeforeRequest = sent.Count;
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new MsgMovementPacket
            {
                Direction = 5,
                Uid = 0,
                Running = MsgMovementMode.Walk,
                Timestamp = 456,
            }.ToFrameBytes()));

        Assert.Equal(countBeforeRequest + 1, sent.Count);
        Assert.True(MsgMovementPacket.TryParse(ReadFrame(sent[countBeforeRequest]), out var movement));
        Assert.Equal(1_293_600U, movement.Uid);
        Assert.Equal(5U, movement.Direction);
        Assert.Equal(MsgMovementMode.Walk, movement.Running);
        Assert.Equal(456U, movement.Timestamp);
        Assert.Equal(1015U, movement.MapId);

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new MsgActionPacket
            {
                ObjId = 1_293_600,
                Timestamp = 789,
                Type = MsgActionType.SetLocation,
            }.ToFrameBytes()));

        Assert.True(MsgActionPacket.TryParse(ReadFrame(sent[countBeforeRequest + 1]), out var action));
        Assert.Equal(831U, action.PositionX);
        Assert.Equal(583U, action.PositionY);
        Assert.Equal(5, action.Facing);
        Assert.Contains("WorldServer updated MsgMovement", log.ToString());
        Assert.Contains("x=831 y=583 angle=5", log.ToString());
    }

