    [Fact]
    public async Task HandlerJumpActionWithInteractionPartnerMovesPairAndSendsLegacyJump()
    {
        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(1293600, uid: 1293600, mapId: 1015, x: 830, y: 584);
        WriteSnapshot(1293601, uid: 1293601, mapId: 1015, x: 830, y: 584, name: "Partner");
        WriteSnapshot(1293602, uid: 1293602, mapId: 1015, x: 835, y: 584, name: "Watcher");
        using var log = new StringWriter();
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var moverTicket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        var partnerTicket = handoff.Issue(1293601, "demon3", ConquerRuntimeDefaults.WorldServer);
        var watcherTicket = handoff.Issue(1293602, "watcher", ConquerRuntimeDefaults.WorldServer);
        var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot), handoff, log);
        var moverSent = new List<byte[]>();
        var partnerSent = new List<byte[]>();
        var watcherSent = new List<byte[]>();
        var moverConnection = CreateSendingConnection(moverSent);
        var partnerConnection = CreateSendingConnection(partnerSent);
        var watcherConnection = CreateSendingConnection(watcherSent);

        await handler.HandleFrameAsync(
            moverConnection,
            ReadFrame(new InternalWorldEnterRequestPacket(moverTicket.Token).ToFrameBytes()));
        await handler.HandleFrameAsync(
            partnerConnection,
            ReadFrame(new InternalWorldEnterRequestPacket(partnerTicket.Token).ToFrameBytes()));
        await handler.HandleFrameAsync(
            watcherConnection,
            ReadFrame(new InternalWorldEnterRequestPacket(watcherTicket.Token).ToFrameBytes()));
        await handler.HandleFrameAsync(
            moverConnection,
            ReadFrame(new MsgAttackPacket(new MsgAttackQuery(
                Uid: 1_293_600,
                OpponentUid: 1_293_601,
                X: 830,
                Y: 584,
                AttackType: MsgAttackType.InteractionRequest,
                Damage: 0,
                KilledMonster: 0,
                ResponseDamage: 7,
                Effect: MsgAttackEffect.None,
                Unknown: 0)).ToFrameBytes()));
        await handler.HandleFrameAsync(
            partnerConnection,
            ReadFrame(new MsgAttackPacket(new MsgAttackQuery(
                Uid: 1_293_601,
                OpponentUid: 1_293_600,
                X: 830,
                Y: 584,
                AttackType: MsgAttackType.InteractionAccept,
                Damage: 103,
                KilledMonster: 0,
                ResponseDamage: 0,
                Effect: MsgAttackEffect.None,
                Unknown: 0)).ToFrameBytes()));

        var moverBeforeJump = moverSent.Count;
        var partnerBeforeJump = partnerSent.Count;
        var watcherBeforeJump = watcherSent.Count;
        await handler.HandleFrameAsync(
            moverConnection,
            ReadFrame(new MsgActionPacket
            {
                ObjId = 1_293_600,
                Timestamp = 987,
                Type = MsgActionType.Jump,
                Facing = 6,
                TargetPositionX = 840,
                TargetPositionY = 590,
            }.ToFrameBytes()));

        Assert.Equal(moverBeforeJump + 1, moverSent.Count);
        Assert.Equal(partnerBeforeJump + 1, partnerSent.Count);
        Assert.Equal(watcherBeforeJump + 1, watcherSent.Count);
        Assert.True(LegacyInterActionWalkPacket.TryParse(ReadFrame(moverSent[moverBeforeJump]), out var moverJump));
        Assert.True(LegacyInterActionWalkPacket.TryParse(ReadFrame(partnerSent[partnerBeforeJump]), out var partnerJump));
        Assert.True(LegacyInterActionWalkPacket.TryParse(ReadFrame(watcherSent[watcherBeforeJump]), out var watcherJump));
        Assert.Equal(moverJump, partnerJump);
        Assert.Equal(moverJump, watcherJump);
        Assert.Equal(LegacyInterActionWalkMode.Jump, moverJump.Mode);
        Assert.Equal(840, moverJump.X);
        Assert.Equal(590, moverJump.Y);
        Assert.Equal(2U, moverJump.Count);
        Assert.Equal(1_293_600U, moverJump.Uid);
        Assert.Equal(1_293_601U, moverJump.OpponentUid);

        var mover = GetSession(handler, moverConnection);
        var partner = GetSession(handler, partnerConnection);
        var watcher = GetSession(handler, watcherConnection);
        Assert.Equal(840, mover.Character.X);
        Assert.Equal(590, mover.Character.Y);
        Assert.Equal(840, partner.Character.X);
        Assert.Equal(590, partner.Character.Y);
        Assert.Equal(835, watcher.Character.X);
        Assert.Equal(584, watcher.Character.Y);
        Assert.Equal("6", mover.Character.Attributes["Angle"]);
        Assert.Equal("6", partner.Character.Attributes["Angle"]);
        Assert.Contains("WorldServer sent MsgAction interaction jump", log.ToString());
        Assert.Contains("playerCount=2", log.ToString());
    }

