    [Fact]
    public async Task HandlerMovementSendsLegacyMovementToVisiblePeer()
    {
        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(1293600, uid: 1293600, mapId: 1015, x: 830, y: 584);
        WriteSnapshot(1293601, uid: 1293601, mapId: 1015, x: 840, y: 590);
        using var log = new StringWriter();
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        var otherTicket = handoff.Issue(1293601, "demon3", ConquerRuntimeDefaults.WorldServer);
        var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot), handoff, log);
        var sent = new List<byte[]>();
        var otherSent = new List<byte[]>();
        var connection = CreateSendingConnection(sent);
        var otherConnection = CreateSendingConnection(otherSent);

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));
        await handler.HandleFrameAsync(
            otherConnection,
            ReadFrame(new InternalWorldEnterRequestPacket(otherTicket.Token).ToFrameBytes()));

        var visiblePeerBefore = sent.Count;
        var ownerBefore = otherSent.Count;
        await handler.HandleFrameAsync(
            otherConnection,
            ReadFrame(new MsgMovementPacket
            {
                Direction = 5,
                Uid = 0,
                Running = MsgMovementMode.Walk,
                Timestamp = 456,
            }.ToFrameBytes()));

        Assert.Equal(ownerBefore + 1, otherSent.Count);
        Assert.Equal(visiblePeerBefore + 1, sent.Count);
        Assert.True(MsgMovementPacket.TryParse(ReadFrame(otherSent[ownerBefore]), out var ownerMovement));
        Assert.True(MsgMovementPacket.TryParse(ReadFrame(sent[visiblePeerBefore]), out var peerMovement));
        Assert.Equal(ownerMovement, peerMovement);
        Assert.Equal(1_293_601U, peerMovement.Uid);
        Assert.Equal(5U, peerMovement.Direction);
        Assert.Equal(MsgMovementMode.Walk, peerMovement.Running);
        Assert.Equal(456U, peerMovement.Timestamp);
        Assert.Equal(1015U, peerMovement.MapId);
        Assert.Contains("WorldServer sent MsgMovement visibility", log.ToString());
        Assert.Contains("playerCount=1", log.ToString());
    }

