    [Fact]
    public async Task HandlerMovementSendsInteractionWalkForAcceptedInteractionPartner()
    {
        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(1293600, uid: 1293600, mapId: 1015, x: 830, y: 584);
        WriteSnapshot(1293601, uid: 1293601, mapId: 1015, x: 830, y: 584);
        using var log = new StringWriter();
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var moverTicket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        var partnerTicket = handoff.Issue(1293601, "demon3", ConquerRuntimeDefaults.WorldServer);
        var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot), handoff, log);
        var moverSent = new List<byte[]>();
        var partnerSent = new List<byte[]>();
        var moverConnection = CreateSendingConnection(moverSent);
        var partnerConnection = CreateSendingConnection(partnerSent);

        await handler.HandleFrameAsync(
            moverConnection,
            ReadFrame(new InternalWorldEnterRequestPacket(moverTicket.Token).ToFrameBytes()));
        await handler.HandleFrameAsync(
            partnerConnection,
            ReadFrame(new InternalWorldEnterRequestPacket(partnerTicket.Token).ToFrameBytes()));

        var partnerBeforeRequest = partnerSent.Count;
        await handler.HandleFrameAsync(
            moverConnection,
            ReadFrame(new MsgAttackPacket(new MsgAttackQuery(
                Uid: 1_293_600,
                OpponentUid: 1_293_601,
                X: 830,
                Y: 584,
                AttackType: MsgAttackType.InteractionRequest,
                Damage: 0,
                KilledMonster: 0,
                ResponseDamage: 7,
                Effect: MsgAttackEffect.None,
                Unknown: 0)).ToFrameBytes()));

        Assert.Equal(partnerBeforeRequest + 2, partnerSent.Count);
        Assert.True(MsgAttackPacket.TryParse(ReadFrame(partnerSent[partnerBeforeRequest]), out var firstRequest));
        Assert.True(MsgAttackPacket.TryParse(ReadFrame(partnerSent[partnerBeforeRequest + 1]), out var secondRequest));
        Assert.Equal(MsgAttackType.InteractionRequest, firstRequest.Query.AttackType);
        Assert.Equal(7U, firstRequest.Query.ResponseDamage);
        Assert.Equal(firstRequest, secondRequest);

        var moverBeforeAccept = moverSent.Count;
        var partnerBeforeAccept = partnerSent.Count;
        await handler.HandleFrameAsync(
            partnerConnection,
            ReadFrame(new MsgAttackPacket(new MsgAttackQuery(
                Uid: 1_293_601,
                OpponentUid: 1_293_600,
                X: 830,
                Y: 584,
                AttackType: MsgAttackType.InteractionAccept,
                Damage: 103,
                KilledMonster: 0,
                ResponseDamage: 0,
                Effect: MsgAttackEffect.None,
                Unknown: 0)).ToFrameBytes()));

        Assert.Equal(moverBeforeAccept + 1, moverSent.Count);
        Assert.Equal(partnerBeforeAccept + 1, partnerSent.Count);
        Assert.True(MsgAttackPacket.TryParse(ReadFrame(moverSent[moverBeforeAccept]), out var moverAccept));
        Assert.True(MsgAttackPacket.TryParse(ReadFrame(partnerSent[partnerBeforeAccept]), out var partnerAccept));
        Assert.Equal(MsgAttackType.InteractionAccept, moverAccept.Query.AttackType);
        Assert.Equal(7U, moverAccept.Query.ResponseDamage);
        Assert.Equal(moverAccept, partnerAccept);

        var moverBeforeMove = moverSent.Count;
        var partnerBeforeMove = partnerSent.Count;
        await handler.HandleFrameAsync(
            moverConnection,
            ReadFrame(new MsgMovementPacket
            {
                Direction = 5,
                Uid = 0,
                Running = MsgMovementMode.Walk,
                Timestamp = 456,
            }.ToFrameBytes()));

        Assert.Equal(moverBeforeMove + 1, moverSent.Count);
        Assert.Equal(partnerBeforeMove + 1, partnerSent.Count);
        Assert.True(LegacyInterActionWalkPacket.TryParse(ReadFrame(moverSent[moverBeforeMove]), out var moverWalk));
        Assert.True(LegacyInterActionWalkPacket.TryParse(ReadFrame(partnerSent[partnerBeforeMove]), out var partnerWalk));
        Assert.Equal(moverWalk, partnerWalk);
        Assert.Equal(LegacyInterActionWalkMode.Walk, moverWalk.Mode);
        Assert.Equal(5, moverWalk.DirectionOne);
        Assert.Equal(1_293_600U, moverWalk.Uid);
        Assert.Equal(1_293_601U, moverWalk.OpponentUid);

        var partnerBeforeSetLocation = partnerSent.Count;
        await handler.HandleFrameAsync(
            partnerConnection,
            ReadFrame(new MsgActionPacket
            {
                ObjId = 1_293_601,
                Timestamp = 789,
                Type = MsgActionType.SetLocation,
            }.ToFrameBytes()));

        Assert.True(MsgActionPacket.TryParse(ReadFrame(partnerSent[partnerBeforeSetLocation]), out var partnerLocation));
        Assert.Equal(831U, partnerLocation.PositionX);
        Assert.Equal(583U, partnerLocation.PositionY);
        Assert.Equal(5, partnerLocation.Facing);
        Assert.Contains("WorldServer paired MsgAttack interaction", log.ToString());
        Assert.Contains("WorldServer sent MsgMovement interaction walk", log.ToString());
    }

