    [Fact]
    public async Task HandlerInteractionStopEffectClearsInteractionWalkPairing()
    {
        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(1293600, uid: 1293600, mapId: 1015, x: 830, y: 584);
        WriteSnapshot(1293601, uid: 1293601, mapId: 1015, x: 830, y: 584);
        using var log = new StringWriter();
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var moverTicket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        var partnerTicket = handoff.Issue(1293601, "demon3", ConquerRuntimeDefaults.WorldServer);
        var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot), handoff, log);
        var moverSent = new List<byte[]>();
        var partnerSent = new List<byte[]>();
        var moverConnection = CreateSendingConnection(moverSent);
        var partnerConnection = CreateSendingConnection(partnerSent);

        await handler.HandleFrameAsync(
            moverConnection,
            ReadFrame(new InternalWorldEnterRequestPacket(moverTicket.Token).ToFrameBytes()));
        await handler.HandleFrameAsync(
            partnerConnection,
            ReadFrame(new InternalWorldEnterRequestPacket(partnerTicket.Token).ToFrameBytes()));
        await handler.HandleFrameAsync(
            moverConnection,
            ReadFrame(new MsgAttackPacket(new MsgAttackQuery(
                Uid: 1_293_600,
                OpponentUid: 1_293_601,
                X: 830,
                Y: 584,
                AttackType: MsgAttackType.InteractionRequest,
                Damage: 0,
                KilledMonster: 0,
                ResponseDamage: 7,
                Effect: MsgAttackEffect.None,
                Unknown: 0)).ToFrameBytes()));
        await handler.HandleFrameAsync(
            partnerConnection,
            ReadFrame(new MsgAttackPacket(new MsgAttackQuery(
                Uid: 1_293_601,
                OpponentUid: 1_293_600,
                X: 830,
                Y: 584,
                AttackType: MsgAttackType.InteractionAccept,
                Damage: 103,
                KilledMonster: 0,
                ResponseDamage: 0,
                Effect: MsgAttackEffect.None,
                Unknown: 0)).ToFrameBytes()));

        var moverBeforeStop = moverSent.Count;
        var partnerBeforeStop = partnerSent.Count;
        await handler.HandleFrameAsync(
            moverConnection,
            ReadFrame(new MsgAttackPacket(new MsgAttackQuery(
                Uid: 1_293_600,
                OpponentUid: 1_293_601,
                X: 830,
                Y: 584,
                AttackType: MsgAttackType.InteractionStopEffect,
                Damage: 0,
                KilledMonster: 0,
                ResponseDamage: 0,
                Effect: MsgAttackEffect.None,
                Unknown: 0)).ToFrameBytes()));

        Assert.Equal(moverBeforeStop + 2, moverSent.Count);
        Assert.Equal(partnerBeforeStop + 2, partnerSent.Count);
        Assert.True(MsgAttackPacket.TryParse(ReadFrame(moverSent[moverBeforeStop]), out var moverStop));
        Assert.True(MsgAttackPacket.TryParse(ReadFrame(moverSent[moverBeforeStop + 1]), out var moverStopSwapped));
        Assert.Equal(MsgAttackType.InteractionStopEffect, moverStop.Query.AttackType);
        Assert.Equal(7U, moverStop.Query.ResponseDamage);
        Assert.Equal(1_293_600U, moverStop.Query.Uid);
        Assert.Equal(1_293_601U, moverStop.Query.OpponentUid);
        Assert.Equal(1_293_601U, moverStopSwapped.Query.Uid);
        Assert.Equal(1_293_600U, moverStopSwapped.Query.OpponentUid);

        var moverBeforeMove = moverSent.Count;
        var partnerBeforeMove = partnerSent.Count;
        await handler.HandleFrameAsync(
            moverConnection,
            ReadFrame(new MsgMovementPacket
            {
                Direction = 5,
                Uid = 0,
                Running = MsgMovementMode.Walk,
                Timestamp = 456,
            }.ToFrameBytes()));

        Assert.Equal(moverBeforeMove + 1, moverSent.Count);
        Assert.Equal(partnerBeforeMove + 1, partnerSent.Count);
        Assert.True(MsgMovementPacket.TryParse(ReadFrame(moverSent[moverBeforeMove]), out var selfMovement));
        Assert.True(MsgMovementPacket.TryParse(ReadFrame(partnerSent[partnerBeforeMove]), out var peerMovement));
        Assert.Equal(selfMovement, peerMovement);
        Assert.False(LegacyInterActionWalkPacket.TryParse(ReadFrame(moverSent[moverBeforeMove]), out _));

        var partnerBeforeSetLocation = partnerSent.Count;
        await handler.HandleFrameAsync(
            partnerConnection,
            ReadFrame(new MsgActionPacket
            {
                ObjId = 1_293_601,
                Timestamp = 789,
                Type = MsgActionType.SetLocation,
            }.ToFrameBytes()));

        Assert.True(MsgActionPacket.TryParse(ReadFrame(partnerSent[partnerBeforeSetLocation]), out var partnerLocation));
        Assert.Equal(830U, partnerLocation.PositionX);
        Assert.Equal(584U, partnerLocation.PositionY);
        Assert.Contains("WorldServer stopped MsgAttack interaction", log.ToString());
    }

    [Fact]
    public async Task HandlerMovementRemovesLegacyMovementCancelledStatusFlags()
    {
        const int PoisonedFlag = 1;
        const int FocusedFlag = 0x15;
        const int CastPrayFlag = 0x1E;
        const int PrayingFlag = 0x1F;
        const int MagicDefenderFlag = 0x80;
