        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var moverTicket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        var peerTicket = handoff.Issue(1293601, "demon3", ConquerRuntimeDefaults.WorldServer);
        var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot), handoff, log);
        var moverSent = new List<byte[]>();
        var peerSent = new List<byte[]>();
        var moverConnection = CreateSendingConnection(moverSent);
        var peerConnection = CreateSendingConnection(peerSent);

        await handler.HandleFrameAsync(
            moverConnection,
            ReadFrame(new InternalWorldEnterRequestPacket(moverTicket.Token).ToFrameBytes()));
        await handler.HandleFrameAsync(
            peerConnection,
            ReadFrame(new InternalWorldEnterRequestPacket(peerTicket.Token).ToFrameBytes()));
        await handler.HandleFrameAsync(
            moverConnection,
            ReadFrame(new MsgMovementPacket
            {
                Direction = 5,
                Uid = 0,
                Running = MsgMovementMode.Walk,
                Timestamp = 456,
            }.ToFrameBytes()));

        var peerBeforeSetLocation = peerSent.Count;
        await handler.HandleFrameAsync(
            peerConnection,
            ReadFrame(new MsgActionPacket
            {
                ObjId = 1_293_601,
                Timestamp = 789,
                Type = MsgActionType.SetLocation,
            }.ToFrameBytes()));

        Assert.True(LegacyPlayerSpawnPacket.TryParse(ReadFrame(peerSent[peerBeforeSetLocation + 1]), out var moverSpawn));
        Assert.Equal(1_293_600UL, moverSpawn.GetNumericField(UidField));
        Assert.True(HasLegacyStatusFlag(moverSpawn.StatusFlags, PoisonedFlag));
        Assert.False(HasLegacyStatusFlag(moverSpawn.StatusFlags, FocusedFlag));
        Assert.False(HasLegacyStatusFlag(moverSpawn.StatusFlags, CastPrayFlag));
        Assert.False(HasLegacyStatusFlag(moverSpawn.StatusFlags, PrayingFlag));
        Assert.False(HasLegacyStatusFlag(moverSpawn.StatusFlags, MagicDefenderFlag));
        Assert.Contains("WorldServer cleared MsgMovement status flags", log.ToString());
    }

