        Assert.DoesNotContain("PARITY-GAP unmodeled MsgAction", log.ToString());
        Assert.Contains("WorldServer handled MsgAction ChangeStance", log.ToString());
        Assert.Contains("source=MsgDataPacket.ChangeStance [Data(81)]", log.ToString());
    }

