    [Fact]
    public async Task HandlerLegacyNpcReplyAcceptsThrillingSpookAndTeleportsNearbyTeamMembers()
    {
        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(1293600, uid: 1293600, mapId: 1036, x: 247, y: 144);
        WriteSnapshot(400001, uid: 400001, name: "Target", mapId: 1036, x: 260, y: 144);
        WriteSnapshot(400002, uid: 400002, name: "FarTarget", mapId: 1036, x: 280, y: 144);
        using var log = new StringWriter();
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var leaderTicket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        var targetTicket = handoff.Issue(400001, "target", ConquerRuntimeDefaults.WorldServer);
        var farTicket = handoff.Issue(400002, "far", ConquerRuntimeDefaults.WorldServer);
        var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot), handoff, log);
        var leaderSent = new List<byte[]>();
        var targetSent = new List<byte[]>();
        var farSent = new List<byte[]>();
        var leader = CreateSendingConnection(leaderSent);
        var target = CreateSendingConnection(targetSent);
        var far = CreateSendingConnection(farSent);

        await handler.HandleFrameAsync(
            leader,
            ReadFrame(new InternalWorldEnterRequestPacket(leaderTicket.Token).ToFrameBytes()));
        await handler.HandleFrameAsync(
            target,
            ReadFrame(new InternalWorldEnterRequestPacket(targetTicket.Token).ToFrameBytes()));
        await handler.HandleFrameAsync(
            far,
            ReadFrame(new InternalWorldEnterRequestPacket(farTicket.Token).ToFrameBytes()));
        await handler.HandleFrameAsync(leader, ReadFrame(new MsgTeamPacket(MsgTeamType.Create, 0).ToFrameBytes()));
        await handler.HandleFrameAsync(leader, ReadFrame(new MsgTeamPacket(MsgTeamType.InviteRequest, 400001).ToFrameBytes()));
        await handler.HandleFrameAsync(target, ReadFrame(new MsgTeamPacket(MsgTeamType.AcceptInvitation, 1293600).ToFrameBytes()));
        await handler.HandleFrameAsync(leader, ReadFrame(new MsgTeamPacket(MsgTeamType.InviteRequest, 400002).ToFrameBytes()));
        await handler.HandleFrameAsync(far, ReadFrame(new MsgTeamPacket(MsgTeamType.AcceptInvitation, 1293600).ToFrameBytes()));
        await handler.HandleFrameAsync(leader, ReadFrame(BuildLegacyMapTrapsRequest()));
        var dynamicId = GetSession(handler, leader).Character.Attributes[LegacyRuntimeMessageBoxPrompt.DestinationDynamicIdAttribute];

        await handler.HandleFrameAsync(leader, ReadFrame(BuildLegacyNpcDialogReply(optionId: 0, interactType: 6)));

        var leaderSession = GetSession(handler, leader);
        var targetSession = GetSession(handler, target);
        var farSession = GetSession(handler, far);
        Assert.Equal(2090, leaderSession.Character.MapId);
        Assert.Equal(32, leaderSession.Character.X);
        Assert.Equal(30, leaderSession.Character.Y);
        Assert.Equal(dynamicId, leaderSession.Character.Attributes["DynamicID"]);
        Assert.Equal(2090, targetSession.Character.MapId);
        Assert.Equal(32, targetSession.Character.X);
        Assert.Equal(30, targetSession.Character.Y);
        Assert.Equal(dynamicId, targetSession.Character.Attributes["DynamicID"]);
        Assert.Equal(1036, farSession.Character.MapId);
        Assert.Equal(280, farSession.Character.X);
        Assert.Equal(144, farSession.Character.Y);
        Assert.Contains("count=2", log.ToString());
    }

