    [Fact]
    public async Task HandlerLegacyNpcReplyAcceptsAlienWorldLeaveAndTeleportsSession()
    {
        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(1293600, uid: 1293600, mapId: 10428, x: 60, y: 67);
        using var log = new StringWriter();
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot), handoff, log);
        var sent = new List<byte[]>();
        var connection = CreateSendingConnection(sent);

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new MsgMovementPacket
            {
                Direction = 5,
                Uid = 0,
                Running = MsgMovementMode.Walk,
                Timestamp = 456,
            }.ToFrameBytes()));

        var countBeforeReply = sent.Count;
        await handler.HandleFrameAsync(connection, ReadFrame(BuildLegacyNpcDialogReply(optionId: 0, interactType: 6)));

        var replyResponses = sent.Skip(countBeforeReply).ToArray();
        Assert.Collection(
            replyResponses,
            bytes => AssertLegacyTeleportAction(
                bytes,
                MsgActionType.Teleport,
                expectedUid: 1_293_600,
                expectedMapId: 1002,
                expectedX: 351,
                expectedY: 422),
            bytes => AssertLegacyTeleportAction(
                bytes,
                MsgActionType.LegacyMerchantStartup,
                expectedUid: 1_293_600,
                expectedMapId: 1002,
                expectedX: 351,
                expectedY: 422,
                expectedDwParam: 2),
            bytes => AssertLegacyTeleportAction(
                bytes,
                MsgActionType.StopVending,
                expectedUid: 1_293_600,
                expectedMapId: 1002,
                expectedX: 351,
                expectedY: 422),
            bytes => AssertLegacyTeleportAction(
                bytes,
                MsgActionType.LegacyColor,
                expectedUid: 1_293_600,
                expectedMapId: 1002,
                expectedX: 351,
                expectedY: 422,
                expectedDwParam: 0),
            bytes =>
            {
                Assert.True(LegacyMapStatusPacket.TryParse(ReadFrame(bytes), out var mapStatus));
                Assert.Equal(new LegacyMapStatusPacket(1002, 1002, Status: 0), mapStatus);
            });

        var countBeforeSetLocation = sent.Count;

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new MsgActionPacket
            {
                ObjId = 1_293_600,
                Timestamp = 789,
                Type = MsgActionType.SetLocation,
            }.ToFrameBytes()));

        var setLocationResponse = Assert.Single(
            sent.Skip(countBeforeSetLocation),
            bytes =>
                MsgActionPacket.TryParse(ReadFrame(bytes), out var packet) &&
                packet.Type == MsgActionType.SetLocation &&
                packet.ObjId == 1_293_600U &&
                packet.DwParam == 1002U &&
                packet.PositionX == 351U &&
                packet.PositionY == 422U);
        Assert.True(MsgActionPacket.TryParse(ReadFrame(setLocationResponse), out var action));
        Assert.Equal(MsgActionType.SetLocation, action.Type);
        Assert.Equal(1_293_600U, action.ObjId);
        Assert.Equal(1002U, action.DwParam);
        Assert.Equal(351U, action.PositionX);
        Assert.Equal(422U, action.PositionY);
        Assert.Contains("WorldServer accepted alien-world leave message box", log.ToString());
    }

