    [Fact]
    public async Task HandlerSetLocationActionSendsVisiblePlayerSpawnsBeforeMapStatus()
    {
        const int UidField = 2;
        const int RightWeaponField = 12;
        const int XField = 27;
        const int YField = 28;
        const int RightWeaponSoulField = 67;

        var itemsRoot = Path.Combine(Path.GetTempPath(), "wolf-world-player-items-" + Guid.NewGuid());
        try
        {
            Directory.CreateDirectory(_usersRoot);
            Directory.CreateDirectory(itemsRoot);
            WriteSnapshot(1293600, uid: 1293600, mapId: 1015, x: 830, y: 584);
            WriteSnapshot(1293601, uid: 1293601, mapId: 1015, x: 840, y: 590);
            File.WriteAllBytes(
                Path.Combine(itemsRoot, "1293601.bin"),
                PlayerItemSnapshotLoaderTests.BuildPlayerItems(
                    [
                        PlayerItemSnapshotLoaderTests.DbItem(
                            uid: 2001,
                            itemId: 500109,
                            position: 4,
                            purificationItemId: 800004)
                    ],
                    []));
            using var log = new StringWriter();
            var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
            var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
            var otherTicket = handoff.Issue(1293601, "demon3", ConquerRuntimeDefaults.WorldServer);
            var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot, itemsRoot), handoff, log);
            var sent = new List<byte[]>();
            var otherSent = new List<byte[]>();
            var connection = CreateSendingConnection(sent);
            var otherConnection = CreateSendingConnection(otherSent);

            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));
            await handler.HandleFrameAsync(
                otherConnection,
                ReadFrame(new InternalWorldEnterRequestPacket(otherTicket.Token).ToFrameBytes()));
            // Empty owner startup57; the peer's real query publishes one fresh spawn to it.
            Assert.Equal(58, sent.Count);
            AssertLegacyWorldEntryStartupFrames(sent, startIndex: 1);
            // Peer startup57 + weapon1008 + permanent purificationExtra =59, not old synthetic spells.
            Assert.Equal(59, otherSent.Count);
            var queryIndex = FindFrameIndexAfter(otherSent, 0,
                frame => LegacyShowEquipmentPacket.TryParse(frame, out var show) &&
                    show.Action == LegacyShowEquipmentPacket.ShowAction);
            Assert.InRange(queryIndex, 2, otherSent.Count - 10);
            Assert.True(LegacyGameItemPacket.TryParse(ReadFrame(otherSent[queryIndex - 2]), out var weapon));
            Assert.Equal(2001U, weapon.Uid);
            Assert.Equal(500_109U, weapon.ItemId);
            Assert.True(LegacyItemExtraPacket.TryParse(ReadFrame(otherSent[queryIndex - 1]), out var extra));
            Assert.Empty(extra.Refineries);
            Assert.Equal(new LegacyItemExtraPurification(2001, LegacyItemExtraPacket.StabilizationType,
                800_004, 0, 0, 0, 0), Assert.Single(extra.Purifications));
            LegacySelectedEquipmentQueryAssertions.NeutralQuery(otherSent, queryIndex, 1_293_601U);
            var ownerBeforeLocation = sent.Count;
            var peerBeforeLocation = otherSent.Count;

            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new MsgActionPacket
                {
                    ObjId = 1_293_600,
                    Timestamp = 1234,
                    Type = MsgActionType.SetLocation,
                }.ToFrameBytes()));

            Assert.Equal(ownerBeforeLocation + 3, sent.Count);
            Assert.Equal(peerBeforeLocation + 1, otherSent.Count);
            Assert.True(PacketFrameDecoder.TryRead(new ReadOnlySequence<byte>(sent[^3]), out var actionFrame, out _, out _));
            Assert.True(MsgActionPacket.TryParse(actionFrame, out _));

            Assert.True(PacketFrameDecoder.TryRead(new ReadOnlySequence<byte>(sent[^2]), out var otherSpawnFrame, out _, out _));
            Assert.True(LegacyPlayerSpawnPacket.TryParse(otherSpawnFrame, out var otherSpawn));
            Assert.Equal(1_293_601UL, otherSpawn.GetNumericField(UidField));
            Assert.Equal(500_109UL, otherSpawn.GetNumericField(RightWeaponField));
            Assert.Equal(840UL, otherSpawn.GetNumericField(XField));
            Assert.Equal(590UL, otherSpawn.GetNumericField(YField));
            Assert.Equal(800_004UL, otherSpawn.GetNumericField(RightWeaponSoulField));

            Assert.True(PacketFrameDecoder.TryRead(new ReadOnlySequence<byte>(sent[^1]), out var mapFrame, out _, out _));
            Assert.True(LegacyMapStatusPacket.TryParse(mapFrame, out var mapStatus));
            Assert.Equal(1015U, mapStatus.Id);

            Assert.True(PacketFrameDecoder.TryRead(new ReadOnlySequence<byte>(otherSent[^1]), out var reciprocalSpawnFrame, out _, out _));
            Assert.True(LegacyPlayerSpawnPacket.TryParse(reciprocalSpawnFrame, out var reciprocalSpawn));
            Assert.Equal(1_293_600UL, reciprocalSpawn.GetNumericField(UidField));
            Assert.Equal(830UL, reciprocalSpawn.GetNumericField(XField));
            Assert.Equal(584UL, reciprocalSpawn.GetNumericField(YField));
            Assert.Contains("sent LegacyPlayerSpawn", log.ToString());
            Assert.Contains("playerCount=1", log.ToString());
        }
        finally
        {
            if (Directory.Exists(itemsRoot))
            {
                Directory.Delete(itemsRoot, recursive: true);
            }
        }
    }

