                PlayerItemSnapshotLoaderTests.BuildPlayerItems(
                    [
                        PlayerItemSnapshotLoaderTests.DbItem(
                            uid: 2001,
                            itemId: 500109,
                            position: 4,
                            purificationItemId: 800004),
                        PlayerItemSnapshotLoaderTests.DbItem(
                            uid: 2002,
                            itemId: 601109,
                            position: 54,
                            purificationItemId: 810004),
                    ],
                    []));
            using var log = new StringWriter();
            var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
            var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
            var otherTicket = handoff.Issue(1293601, "demon3", ConquerRuntimeDefaults.WorldServer);
            var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot, itemsRoot), handoff, log);
            var sent = new List<byte[]>();
            var otherSent = new List<byte[]>();
            var connection = CreateSendingConnection(sent);
            var otherConnection = CreateSendingConnection(otherSent);

            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));
            await handler.HandleFrameAsync(
                otherConnection,
                ReadFrame(new InternalWorldEnterRequestPacket(otherTicket.Token).ToFrameBytes()));

            var activeBefore = sent.Count;
            await handler.HandleFrameAsync(
                otherConnection,
                ReadFrame(new MsgItemUsagePacket(
                    Id: 0,
                    DwParam: 0,
                    Action: MsgItemUsageAction.Alternante,
                    Timestamp: 1234,
                    DwParam2: 0,
                    DwParam3: 0,
                    DwParam4: 0).ToFrameBytes()));

            Assert.Equal(activeBefore + 1, sent.Count);
            Assert.True(PacketFrameDecoder.TryRead(new ReadOnlySequence<byte>(sent[^1]), out var activeFrame, out _, out _));
            Assert.True(LegacyPlayerSpawnPacket.TryParse(activeFrame, out var activeSpawn));
            Assert.Equal(1_293_601UL, activeSpawn.GetNumericField(UidField));
            Assert.Equal(601_109UL, activeSpawn.GetNumericField(RightWeaponField));
            Assert.Equal(810_004UL, activeSpawn.GetNumericField(RightWeaponSoulField));

            var inactiveBefore = sent.Count;
            await handler.HandleFrameAsync(
                otherConnection,
                ReadFrame(new MsgItemUsagePacket(
                    Id: 0,
                    DwParam: 0,
                    Action: MsgItemUsageAction.UnAlternante,
                    Timestamp: 1235,
                    DwParam2: 0,
                    DwParam3: 0,
                    DwParam4: 0).ToFrameBytes()));

            Assert.Equal(inactiveBefore + 1, sent.Count);
            Assert.True(PacketFrameDecoder.TryRead(new ReadOnlySequence<byte>(sent[^1]), out var inactiveFrame, out _, out _));
            Assert.True(LegacyPlayerSpawnPacket.TryParse(inactiveFrame, out var inactiveSpawn));
            Assert.Equal(1_293_601UL, inactiveSpawn.GetNumericField(UidField));
            Assert.Equal(500_109UL, inactiveSpawn.GetNumericField(RightWeaponField));
            Assert.Equal(800_004UL, inactiveSpawn.GetNumericField(RightWeaponSoulField));
            Assert.Contains("WorldServer handled MsgItemUsage", log.ToString());
            Assert.Contains("toggled alternate equipment", log.ToString());
        }
        finally
        {
            if (Directory.Exists(itemsRoot))
            {
                Directory.Delete(itemsRoot, recursive: true);
            }
        }
    }

