            var otherConnection = CreateSendingConnection(otherSent);

            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));
            await handler.HandleFrameAsync(
                otherConnection,
                ReadFrame(new InternalWorldEnterRequestPacket(otherTicket.Token).ToFrameBytes()));

            var peerCountBefore = sent.Count;
            var selfCountBefore = otherSent.Count;
            await handler.HandleFrameAsync(
                otherConnection,
                ReadFrame(new MsgItemUsagePacket(
                    Id: 0,
                    DwParam: 4,
                    Action: MsgItemUsageAction.Unequip,
                    Timestamp: 1234,
                    DwParam2: 0,
                    DwParam3: 0,
                    DwParam4: 0).ToFrameBytes()));

            Assert.Equal(selfCountBefore + 12, otherSent.Count);
            var sourceQuery = LegacySelectedEquipmentQueryAssertions.NeutralQuery(otherSent, selfCountBefore + 2, 1_293_601U);
            AssertItemUsage(
                otherSent[selfCountBefore],
                new MsgItemUsagePacket(
                    Id: 2001,
                    DwParam: 4,
                    Action: MsgItemUsageAction.Unequip,
                    Timestamp: 0,
                    DwParam2: 0,
                    DwParam3: 0,
                    DwParam4: 0));
