    [Fact]
    public async Task HandlerLegacyCoatStorageRetrieveSkipsWhenInventoryIsFull()
    {
        var itemsRoot = Path.Combine(Path.GetTempPath(), "wolf-world-coat-storage-retrieve-full-items-" + Guid.NewGuid());
        try
        {
            Directory.CreateDirectory(_usersRoot);
            Directory.CreateDirectory(itemsRoot);
            WriteSnapshot(1293600, uid: 1293600);
            File.WriteAllBytes(
                Path.Combine(itemsRoot, "1293600.bin"),
                PlayerItemSnapshotLoaderTests.BuildPlayerItems(
                    CreateFullInventoryItems()
                        .Concat(
                        [
                            PlayerItemSnapshotLoaderTests.DbItem(
                                uid: 2001,
                                itemId: 181325,
                                position: 0,
                                maximumDurability: 222,
                                warehouseId: 100),
                        ])
                        .ToArray(),
                    []));
            using var log = new StringWriter();
            var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
            var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
            var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot, itemsRoot), handoff, log);
            var sent = new List<byte[]>();
            var connection = CreateSendingConnection(sent);

            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));

            var countBeforeRequest = sent.Count;
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new LegacyCoatStoragePacket(
                    LegacyCoatStoragePacket.RetrieveActionId,
                    DwParam1: 2001,
                    DwParam2: 0,
                    DwParam3: 0,
                    []).ToFrameBytes()));

            var response = Assert.Single(sent.Skip(countBeforeRequest));
            Assert.True(LegacyMsgMessagePacket.TryParse(ReadFrame(response), out var message));
            Assert.Equal(LegacyMsgMessagePacket.TalkChatType, message.ChatType);
            Assert.Equal("Please make 1 more space in your inventory.", message.Content[3]);

            var updated = GetSession(handler, connection);
            Assert.Equal(40, updated.PlayerItems.InventoryItems.Count);
            var stored = Assert.Single(updated.PlayerItems.WardrobeItems);
            Assert.Equal(2001U, stored.Uid);
            Assert.Equal(100U, stored.WarehouseId);

            var output = log.ToString();
            Assert.Contains("skipped LegacyCoatStorage Retrieve", output);
            Assert.Contains("inventory is full", output);
            Assert.DoesNotContain("handled LegacyCoatStorage Retrieve", output);
        }
        finally
        {
            if (Directory.Exists(itemsRoot))
            {
                Directory.Delete(itemsRoot, recursive: true);
            }
        }
    }

