    [Fact]
    public async Task HandlerItemUsageEquipReplacesOccupiedSimpleEquipmentSlot()
    {
        const int UidField = 2;
        const int HeadField = 8;

        var itemsRoot = Path.Combine(Path.GetTempPath(), "wolf-world-equip-replace-items-" + Guid.NewGuid());
        try
        {
            Directory.CreateDirectory(_usersRoot);
            Directory.CreateDirectory(itemsRoot);
            WriteSnapshot(1293600, uid: 1293600, mapId: 1015, x: 830, y: 584);
            WriteSnapshot(1293601, uid: 1293601, mapId: 1015, x: 840, y: 590);
            File.WriteAllBytes(
                Path.Combine(itemsRoot, "1293601.bin"),
                PlayerItemSnapshotLoaderTests.BuildPlayerItems(
                    [
                        PlayerItemSnapshotLoaderTests.DbItem(uid: 2001, itemId: 111003, position: 0),
                        PlayerItemSnapshotLoaderTests.DbItem(uid: 3001, itemId: 112003, position: 1),
                    ],
                    []));
            using var log = new StringWriter();
            var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
            var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
            var otherTicket = handoff.Issue(1293601, "demon3", ConquerRuntimeDefaults.WorldServer);
            var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot, itemsRoot), handoff, log);
            var sent = new List<byte[]>();
            var otherSent = new List<byte[]>();
            var connection = CreateSendingConnection(sent);
            var otherConnection = CreateSendingConnection(otherSent);

            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));
            await handler.HandleFrameAsync(
                otherConnection,
                ReadFrame(new InternalWorldEnterRequestPacket(otherTicket.Token).ToFrameBytes()));

            var peerCountBefore = sent.Count;
            var selfCountBefore = otherSent.Count;
            await handler.HandleFrameAsync(
                otherConnection,
                ReadFrame(new MsgItemUsagePacket(
                    Id: 2001,
                    DwParam: 1,
                    Action: MsgItemUsageAction.Equip,
                    Timestamp: 1235,
                    DwParam2: 0,
                    DwParam3: 0,
                    DwParam4: 0).ToFrameBytes()));

            Assert.Equal(selfCountBefore + 14, otherSent.Count);
            LegacySelectedEquipmentQueryAssertions.NeutralQuery(otherSent, selfCountBefore + 4, 1_293_601U);
            AssertItemUsage(
                otherSent[selfCountBefore],
                new MsgItemUsagePacket(
                    Id: 2001,
                    DwParam: 0,
                    Action: MsgItemUsageAction.RemoveInventory,
                    Timestamp: 0,
                    DwParam2: 0,
                    DwParam3: 0,
                    DwParam4: 0));
            AssertItemUsage(
                otherSent[selfCountBefore + 1],
                new MsgItemUsagePacket(
                    Id: 3001,
                    DwParam: 1,
                    Action: MsgItemUsageAction.Unequip,
                    Timestamp: 0,
                    DwParam2: 0,
                    DwParam3: 0,
                    DwParam4: 0));

            Assert.True(LegacyGameItemPacket.TryParse(ReadFrame(otherSent[selfCountBefore + 2]), out var displacedItem));
            Assert.Equal(3001U, displacedItem.Uid);
            Assert.Equal(112_003U, displacedItem.ItemId);
            Assert.Equal(LegacyGameItemPacket.AddItemMode, displacedItem.Mode);
            Assert.Equal((byte)0, displacedItem.Position);

            Assert.True(LegacyGameItemPacket.TryParse(ReadFrame(otherSent[selfCountBefore + 3]), out var addedItem));
            Assert.Equal(2001U, addedItem.Uid);
            Assert.Equal(111_003U, addedItem.ItemId);
            Assert.Equal(LegacyGameItemPacket.AddItemMode, addedItem.Mode);
            Assert.Equal((byte)1, addedItem.Position);

            Assert.Equal(peerCountBefore + 1, sent.Count);
            Assert.True(PacketFrameDecoder.TryRead(new ReadOnlySequence<byte>(sent[^1]), out var refreshedFrame, out _, out _));
            Assert.True(LegacyPlayerSpawnPacket.TryParse(refreshedFrame, out var refreshedSpawn));
            Assert.Equal(1_293_601UL, refreshedSpawn.GetNumericField(UidField));
            Assert.Equal(111_003UL, refreshedSpawn.GetNumericField(HeadField));
            Assert.Contains("replacedItemUid=3001", log.ToString());
        }
        finally
        {
            if (Directory.Exists(itemsRoot))
            {
                Directory.Delete(itemsRoot, recursive: true);
            }
        }
    }

