    [Fact]
    public async Task HandlerItemUsageEquipMovesPistolToLeftHandWhenRapierRightHandIsEquipped()
    {
        var itemsRoot = Path.Combine(Path.GetTempPath(), "wolf-world-equip-pistol-rapier-items-" + Guid.NewGuid());
        try
        {
            Directory.CreateDirectory(_usersRoot);
            Directory.CreateDirectory(itemsRoot);
            WriteSnapshot(1293600, uid: 1293600, classCode: 7051);
            File.WriteAllBytes(
                Path.Combine(itemsRoot, "1293600.bin"),
                PlayerItemSnapshotLoaderTests.BuildPlayerItems(
                    [
                        PlayerItemSnapshotLoaderTests.DbItem(uid: 2001, itemId: 612000, position: 0),
                        PlayerItemSnapshotLoaderTests.DbItem(uid: 3001, itemId: 611000, position: 4),
                    ],
                    []));
            using var log = new StringWriter();
            var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
            var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
            var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot, itemsRoot), handoff, log);
            var sent = new List<byte[]>();
            var connection = CreateSendingConnection(sent);

            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));

            Assert.True(ItemType.IsLegacyPistol(612000));
            Assert.True(ItemType.IsLegacyRapier(611000));

            var countBeforeRequest = sent.Count;
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new MsgItemUsagePacket(
                    Id: 2001,
                    DwParam: 5,
                    Action: MsgItemUsageAction.Equip,
                    Timestamp: 1234,
                    DwParam2: 0,
                    DwParam3: 0,
                    DwParam4: 0).ToFrameBytes()));

            Assert.Equal(countBeforeRequest + 13, sent.Count);
            LegacySelectedEquipmentQueryAssertions.NeutralQuery(sent, countBeforeRequest + 3, 1_293_600U);
            AssertItemUsage(
                sent[countBeforeRequest],
                new MsgItemUsagePacket(
                    Id: 2001,
                    DwParam: 0,
                    Action: MsgItemUsageAction.RemoveInventory,
                    Timestamp: 0,
                    DwParam2: 0,
                    DwParam3: 0,
                    DwParam4: 0));

            var addedItem = ParseLegacyGameItem(sent[countBeforeRequest + 1]);
            Assert.Equal(2001U, addedItem.Uid);
            Assert.Equal(612_000U, addedItem.ItemId);
            Assert.Equal(LegacyGameItemPacket.AddItemMode, addedItem.Mode);
            Assert.Equal((byte)5, addedItem.Position);

            var updatedItem = ParseLegacyGameItem(sent[countBeforeRequest + 2]);
            Assert.Equal(2001U, updatedItem.Uid);
            Assert.Equal(612_000U, updatedItem.ItemId);
            Assert.Equal(LegacyGameItemPacket.UpdateItemMode, updatedItem.Mode);
            Assert.Equal((byte)5, updatedItem.Position);
            Assert.Contains("handled MsgItemUsage equip", log.ToString());
        }
        finally
        {
            if (Directory.Exists(itemsRoot))
            {
                Directory.Delete(itemsRoot, recursive: true);
            }
        }
    }

