    [Fact]
    public async Task HandlerItemUsageDropUnboundInventoryItemSendsVisibleFloorItemAndRemovesIt()
    {
        var itemsRoot = Path.Combine(Path.GetTempPath(), "wolf-world-drop-ground-items-" + Guid.NewGuid());
        try
        {
            Directory.CreateDirectory(_usersRoot);
            Directory.CreateDirectory(itemsRoot);
            WriteSnapshot(1293600, uid: 1293600, mapId: 1002, x: 577, y: 586);
            WriteSnapshot(1293601, uid: 1293601, mapId: 1002, x: 580, y: 590);
