                Path.Combine(itemsRoot, "1293600.bin"),
                PlayerItemSnapshotLoaderTests.BuildPlayerItems(
                    [
                        PlayerItemSnapshotLoaderTests.DbItem(
                            uid: 2001,
                            itemId: 111003,
                            position: 0,
                            plus: 3),
                    ],
                    []));
            using var log = new StringWriter();
            var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
            var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
            var otherTicket = handoff.Issue(1293601, "demon3", ConquerRuntimeDefaults.WorldServer);
            var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot, itemsRoot), handoff, log);
            var sent = new List<byte[]>();
            var otherSent = new List<byte[]>();
            var connection = CreateSendingConnection(sent);
            var otherConnection = CreateSendingConnection(otherSent);

            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));
            await handler.HandleFrameAsync(
                otherConnection,
                ReadFrame(new InternalWorldEnterRequestPacket(otherTicket.Token).ToFrameBytes()));

            var countBeforeDrop = sent.Count;
            var otherCountBeforeDrop = otherSent.Count;
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new MsgItemUsagePacket(
                    Id: 2001,
                    DwParam: 0,
                    Action: MsgItemUsageAction.DropItem,
                    Timestamp: 1245,
                    DwParam2: 0,
                    DwParam3: 0,
                    DwParam4: 0).ToFrameBytes()));

            Assert.Equal(countBeforeDrop + 2, sent.Count);
            Assert.Equal(otherCountBeforeDrop + 1, otherSent.Count);

            var floorItem = ParseLegacyFloorItem(sent[countBeforeDrop]);
            Assert.Equal(111_003U, floorItem.ItemId);
            Assert.Equal(577, floorItem.X);
            Assert.Equal(586, floorItem.Y);
            Assert.Equal(40, floorItem.MaxLife);
            Assert.Equal(LegacyFloorItemDropType.Visible, floorItem.DropType);
            Assert.Equal(3, floorItem.PlusOrColor);
            Assert.Equal(1_293_600U, floorItem.ItemOwnerUid);
            Assert.Equal(floorItem, ParseLegacyFloorItem(otherSent[otherCountBeforeDrop]));
            AssertItemUsage(
                sent[countBeforeDrop + 1],
                new MsgItemUsagePacket(
                    Id: 2001,
                    DwParam: 0,
                    Action: MsgItemUsageAction.RemoveInventory,
                    Timestamp: 0,
                    DwParam2: 0,
                    DwParam3: 0,
                    DwParam4: 0));

            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new MsgItemUsagePacket(
                    Id: 2001,
                    DwParam: 0,
                    Action: MsgItemUsageAction.DropItem,
                    Timestamp: 1246,
                    DwParam2: 0,
                    DwParam3: 0,
                    DwParam4: 0).ToFrameBytes()));

            Assert.Equal(countBeforeDrop + 2, sent.Count);
            Assert.Equal(otherCountBeforeDrop + 1, otherSent.Count);
            Assert.Contains("sent LegacyFloorItem", log.ToString());
            Assert.Contains("handled MsgItemUsage ground drop", log.ToString());
            Assert.Contains("inventory item was not found", log.ToString());
        }
        finally
        {
            if (Directory.Exists(itemsRoot))
            {
                Directory.Delete(itemsRoot, recursive: true);
            }
        }
    }

    [Fact]
    public async Task HandlerRuntimeLoopExpiresVisibleFloorItemForVisiblePeer()
    {
        var itemsRoot = Path.Combine(Path.GetTempPath(), "wolf-world-expire-ground-items-" + Guid.NewGuid());
        try
        {
            Directory.CreateDirectory(_usersRoot);
            Directory.CreateDirectory(itemsRoot);
            WriteSnapshot(1293600, uid: 1293600, mapId: 1002, x: 577, y: 586);
            WriteSnapshot(1293601, uid: 1293601, mapId: 1002, x: 580, y: 590);
            File.WriteAllBytes(
                Path.Combine(itemsRoot, "1293600.bin"),
                PlayerItemSnapshotLoaderTests.BuildPlayerItems(
                    [
                        PlayerItemSnapshotLoaderTests.DbItem(
                            uid: 2001,
                            itemId: 111003,
                            position: 0,
                            plus: 3),
                    ],
                    []));
            using var log = new RuntimeThreadSafeStringWriter();
            using var cancel = new CancellationTokenSource();
            var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
            var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
            var otherTicket = handoff.Issue(1293601, "demon3", ConquerRuntimeDefaults.WorldServer);
            var handler = new WorldServerFrameHandler(
                new CharacterSnapshotLoader(_usersRoot, itemsRoot),
                handoff,
                (WorldDataCatalog?)null,
                new LegacyRuntimeUpdateLoopOptions(
                    Enabled: true,
                    TimeSpan.FromMilliseconds(20),
                    new AnchoredRuntimeTimeProvider(DateTimeOffset.UtcNow.AddSeconds(45))),
                log);
            var sent = new RuntimeThreadSafeFrameCapture();
            var otherSent = new RuntimeThreadSafeFrameCapture();
            var connection = CreateSendingConnection(sent);
            var otherConnection = CreateSendingConnection(otherSent);

            try
            {
                await handler.HandleFrameAsync(
                    connection,
                    ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()),
                    cancel.Token);
                await handler.HandleFrameAsync(
                    otherConnection,
                    ReadFrame(new InternalWorldEnterRequestPacket(otherTicket.Token).ToFrameBytes()),
                    cancel.Token);

                var countBeforeDrop = sent.Count;
                var otherCountBeforeDrop = otherSent.Count;
                await handler.HandleFrameAsync(
                    connection,
                    ReadFrame(new MsgItemUsagePacket(
                        Id: 2001,
                        DwParam: 0,
                        Action: MsgItemUsageAction.DropItem,
                        Timestamp: 1245,
                        DwParam2: 0,
                        DwParam3: 0,
                        DwParam4: 0).ToFrameBytes()),
                    cancel.Token);

                var dropIndex = FindFrameIndexAfter(
                    sent,
                    countBeforeDrop,
                    frame => LegacyFloorItemPacket.TryParse(frame, out var floorItem) &&
                        floorItem.ItemId == 111_003U &&
                        floorItem.DropType == LegacyFloorItemDropType.Visible);
                var floorItem = ParseLegacyFloorItem(sent[dropIndex]);
                var peerVisibleIndex = FindFrameIndexAfter(
                    otherSent,
                    otherCountBeforeDrop,
                    frame => LegacyFloorItemPacket.TryParse(frame, out var peerFloorItem) &&
                        peerFloorItem.Uid == floorItem.Uid &&
                        peerFloorItem.DropType == LegacyFloorItemDropType.Visible);
                Assert.True(peerVisibleIndex >= otherCountBeforeDrop);

                await WaitUntilAsync(
                    () =>
                        FindFrameIndexAfter(
                            sent,
                            dropIndex + 1,
                            frame => LegacyFloorItemPacket.TryParse(frame, out var remove) &&
                                remove.Uid == floorItem.Uid &&
                                remove.DropType == LegacyFloorItemDropType.Remove) > dropIndex &&
                        FindFrameIndexAfter(
                            otherSent,
                            peerVisibleIndex + 1,
                            frame => LegacyFloorItemPacket.TryParse(frame, out var remove) &&
                                remove.Uid == floorItem.Uid &&
                                remove.DropType == LegacyFloorItemDropType.Remove) > peerVisibleIndex,
                    TimeSpan.FromSeconds(2));
                Assert.Contains("WorldServer sent floor item expire remove", log.ToString());
            }
            finally
            {
                await cancel.CancelAsync();
                var globalLoopStarted = typeof(WorldServerFrameHandler).GetField(
                    "_legacyRuntimeGlobalLoopStarted", BindingFlags.Instance | BindingFlags.NonPublic);
                Assert.NotNull(globalLoopStarted);
                await WaitUntilAsync(
                    () => Equals(0, globalLoopStarted.GetValue(handler)),
                    TimeSpan.FromSeconds(2));
                // Join the selected global owner before retiring these fixture registrations.
                // These store gates also wait any already-entered synchronous persistence;
                // pending ordinary player ticker CAS updates cannot restore missing sessions.
                GetSessions(handler).TryRemove(connection, out _);
                GetSessions(handler).TryRemove(otherConnection, out _);
            }
        }
        finally
        {
            if (Directory.Exists(itemsRoot))
            {
                Directory.Delete(itemsRoot, recursive: true);
            }
        }
    }

    [Fact(Skip = "Requires external game fixtures omitted from the public source snapshot.")]
    public async Task HandlerItemUsageRepairItemChargesMoneyAndUpdatesDurability()
    {
        var seedPath = Path.Combine(FindRepositoryRoot(), ".setup_work", "seed-json");
        if (!File.Exists(Path.Combine(seedPath, "manifest.json")))
        {
            return;
        }

        var itemsRoot = Path.Combine(Path.GetTempPath(), "wolf-world-repair-items-" + Guid.NewGuid());
        try
        {
            Directory.CreateDirectory(_usersRoot);
            Directory.CreateDirectory(itemsRoot);
            WriteSnapshot(1293600, uid: 1293600, money: 25);
            File.WriteAllBytes(
                Path.Combine(itemsRoot, "1293600.bin"),
                PlayerItemSnapshotLoaderTests.BuildPlayerItems(
                    [
                        PlayerItemSnapshotLoaderTests.DbItem(
                            uid: 2001,
                            itemId: 101000,
                            position: 0,
                            durability: 5,
                            maximumDurability: 10),
                    ],
                    []));
            using var log = new StringWriter();
            var worldData = await new JsonWorldDataLoader(new WorldDataOptions(seedPath)).LoadAsync();
            var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
            var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
            var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot, itemsRoot), handoff, worldData, log);
            var sent = new List<byte[]>();
            var connection = CreateSendingConnection(sent);

            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));

            var countBeforeRepair = sent.Count;
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new MsgItemUsagePacket(
                    Id: 2001,
                    DwParam: 0,
                    Action: MsgItemUsageAction.RepairItem,
                    Timestamp: 1240,
                    DwParam2: 0,
                    DwParam3: 0,
                    DwParam4: 0).ToFrameBytes()));

            Assert.Equal(countBeforeRepair + 3, sent.Count);
            AssertSingleUpdate(sent[countBeforeRepair], 1_293_600, LegacyMsgUpdateDataType.Money, 24);
            AssertSingleUpdate(sent[countBeforeRepair + 1], 1_293_600, LegacyMsgUpdateDataType.Money, 24);
            Assert.True(LegacyGameItemPacket.TryParse(ReadFrame(sent[countBeforeRepair + 2]), out var repairedItem));
            Assert.Equal(2001U, repairedItem.Uid);
            Assert.Equal(101_000U, repairedItem.ItemId);
            Assert.Equal(10, repairedItem.Durability);
            Assert.Equal(10, repairedItem.MaximumDurability);
            Assert.Equal(LegacyGameItemPacket.UpdateItemMode, repairedItem.Mode);

            var persistedAfterRepair = new CharacterSnapshotLoader(_usersRoot, itemsRoot);
            var persistedCharacter = persistedAfterRepair.LoadByAccountId(1293600);
            Assert.NotNull(persistedCharacter);
            Assert.Equal(24, persistedCharacter.Money);
            var persistedRepairedItem = Assert.Single(
                persistedAfterRepair.LoadPlayerItemsByCharacterUid(1293600).InventoryItems,
                item => item.Uid == repairedItem.Uid);
            Assert.Equal(repairedItem.ItemId, persistedRepairedItem.ItemId);
            Assert.Equal(repairedItem.Durability, persistedRepairedItem.Durability);
            Assert.Equal(repairedItem.MaximumDurability, persistedRepairedItem.MaximumDurability);

            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new MsgItemUsagePacket(
                    Id: 2001,
                    DwParam: 0,
                    Action: MsgItemUsageAction.RepairItem,
                    Timestamp: 1241,
                    DwParam2: 0,
                    DwParam3: 0,
                    DwParam4: 0).ToFrameBytes()));

            Assert.Equal(countBeforeRepair + 3, sent.Count);
            Assert.Contains("handled MsgItemUsage paid repair", log.ToString());
            Assert.Contains("item does not need paid repair", log.ToString());
        }
