    [Fact]
    public async Task HandlerItemUsageRepairItemConsumesFiveMeteorsForZeroDurability()
    {
        var itemsRoot = Path.Combine(Path.GetTempPath(), "wolf-world-zero-repair-items-" + Guid.NewGuid());
        try
        {
            Directory.CreateDirectory(_usersRoot);
            Directory.CreateDirectory(itemsRoot);
            WriteSnapshot(1293600, uid: 1293600, money: 25);
            File.WriteAllBytes(
                Path.Combine(itemsRoot, "1293600.bin"),
                PlayerItemSnapshotLoaderTests.BuildPlayerItems(
                    [
                        PlayerItemSnapshotLoaderTests.DbItem(
                            uid: 2001,
                            itemId: 101000,
                            position: 0,
                            durability: 0,
                            maximumDurability: 10),
                        PlayerItemSnapshotLoaderTests.DbItem(
                            uid: 2002,
                            itemId: 1_088_001,
                            position: 0,
                            stackSize: 6),
                    ],
                    []));
            using var log = new StringWriter();
            var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
            var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
            var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot, itemsRoot), handoff, log);
            var sent = new List<byte[]>();
            var connection = CreateSendingConnection(sent);

            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));

            var countBeforeRepair = sent.Count;
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new MsgItemUsagePacket(
                    Id: 2001,
                    DwParam: 0,
                    Action: MsgItemUsageAction.RepairItem,
                    Timestamp: 1242,
                    DwParam2: 0,
                    DwParam3: 0,
                    DwParam4: 0).ToFrameBytes()));

            Assert.Equal(countBeforeRepair + 6, sent.Count);
            var itemUpdates = sent.Skip(countBeforeRepair).Select(ParseLegacyGameItem).ToArray();
            Assert.All(itemUpdates, item => Assert.Equal(LegacyGameItemPacket.UpdateItemMode, item.Mode));

            var meteorUpdates = itemUpdates.Where(item => item.Uid == 2002).ToArray();
            Assert.Equal(new ushort[] { 5, 4, 3, 2, 1 }, meteorUpdates.Select(item => item.StackSize).ToArray());
            Assert.All(meteorUpdates, item => Assert.Equal(1_088_001U, item.ItemId));

            var repairedItem = Assert.Single(itemUpdates, item => item.Uid == 2001);
            Assert.Equal(101_000U, repairedItem.ItemId);
            Assert.Equal((ushort)10, repairedItem.Durability);
            Assert.Equal((ushort)10, repairedItem.MaximumDurability);

            var persistedAfterRepair = new CharacterSnapshotLoader(_usersRoot, itemsRoot);
            var persistedItems = persistedAfterRepair.LoadPlayerItemsByCharacterUid(1293600).InventoryItems;
            var persistedRepairedItem = Assert.Single(persistedItems, item => item.Uid == repairedItem.Uid);
            Assert.Equal(repairedItem.ItemId, persistedRepairedItem.ItemId);
            Assert.Equal(repairedItem.Durability, persistedRepairedItem.Durability);
            Assert.Equal(repairedItem.MaximumDurability, persistedRepairedItem.MaximumDurability);
            var persistedMeteor = Assert.Single(persistedItems, item => item.Uid == 2002);
            Assert.Equal(meteorUpdates[^1].ItemId, persistedMeteor.ItemId);
            Assert.Equal(meteorUpdates[^1].StackSize, persistedMeteor.StackSize);

            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new MsgItemUsagePacket(
                    Id: 2001,
                    DwParam: 0,
                    Action: MsgItemUsageAction.RepairItem,
                    Timestamp: 1243,
                    DwParam2: 0,
                    DwParam3: 0,
                    DwParam4: 0).ToFrameBytes()));

            Assert.Equal(countBeforeRepair + 6, sent.Count);
            Assert.DoesNotContain("zero-durability meteor repair is not currently modeled", log.ToString());
        }
        finally
        {
            if (Directory.Exists(itemsRoot))
            {
                Directory.Delete(itemsRoot, recursive: true);
            }
        }
    }

