        }

        var itemsRoot = Path.Combine(Path.GetTempPath(), "wolf-world-buy-items-" + Guid.NewGuid());
        try
        {
            Directory.CreateDirectory(_usersRoot);
            Directory.CreateDirectory(itemsRoot);
            WriteSnapshot(1293600, uid: 1293600, mapId: 1002, x: 435, y: 311, money: 20);
            File.WriteAllBytes(
                Path.Combine(itemsRoot, "1293600.bin"),
                PlayerItemSnapshotLoaderTests.BuildPlayerItems([], []));
            using var log = new StringWriter();
            var worldData = await new JsonWorldDataLoader(new WorldDataOptions(seedPath)).LoadAsync();
            var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
            var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
            var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot, itemsRoot), handoff, worldData, log);
            var sent = new List<byte[]>();
            var connection = CreateSendingConnection(sent);

            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));

            var countBeforeBuy = sent.Count;
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new MsgItemUsagePacket(
                    Id: 3,
                    DwParam: 1_000_000,
                    Action: MsgItemUsageAction.BuyItem,
                    Timestamp: 1244,
                    DwParam2: 1,
                    DwParam3: 0,
                    DwParam4: 0).ToFrameBytes()));

            Assert.Equal(countBeforeBuy + 2, sent.Count);
            var boughtItem = ParseLegacyGameItem(sent[countBeforeBuy]);
            Assert.Equal(1U, boughtItem.Uid);
            Assert.Equal(1_000_000U, boughtItem.ItemId);
            Assert.Equal(LegacyGameItemPacket.AddItemMode, boughtItem.Mode);
            Assert.Equal((byte)0, boughtItem.Position);
            Assert.Equal((ushort)1, boughtItem.Durability);
            Assert.Equal((ushort)1, boughtItem.MaximumDurability);
            AssertSingleUpdate(sent[countBeforeBuy + 1], 1_293_600, LegacyMsgUpdateDataType.Money, 15);

            var persistedAfterBuy = new CharacterSnapshotLoader(_usersRoot, itemsRoot);
            var persistedBuyer = persistedAfterBuy.LoadByAccountId(1293600);
            Assert.NotNull(persistedBuyer);
            Assert.Equal(15, persistedBuyer.Money);
            var persistedBoughtItem = Assert.Single(persistedAfterBuy.LoadPlayerItemsByCharacterUid(1293600).InventoryItems);
            Assert.Equal(boughtItem.Uid, persistedBoughtItem.Uid);
            Assert.Equal(boughtItem.ItemId, persistedBoughtItem.ItemId);
            Assert.Equal((ushort)boughtItem.Position, persistedBoughtItem.Position);
            Assert.Equal(boughtItem.Durability, persistedBoughtItem.Durability);
            Assert.Equal(boughtItem.MaximumDurability, persistedBoughtItem.MaximumDurability);

            var countBeforeDrop = sent.Count;
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new MsgItemUsagePacket(
                    Id: 1,
                    DwParam: 0,
                    Action: MsgItemUsageAction.DropItem,
                    Timestamp: 1245,
                    DwParam2: 0,
                    DwParam3: 0,
                    DwParam4: 0).ToFrameBytes()));

            Assert.Equal(countBeforeDrop + 2, sent.Count);
            Assert.Equal(1_000_000U, ParseLegacyFloorItem(sent[countBeforeDrop]).ItemId);
            AssertItemUsage(
                sent[countBeforeDrop + 1],
                new MsgItemUsagePacket(
                    Id: 1,
                    DwParam: 0,
                    Action: MsgItemUsageAction.RemoveInventory,
                    Timestamp: 0,
                    DwParam2: 0,
                    DwParam3: 0,
                    DwParam4: 0));
            Assert.Empty(new PlayerItemSnapshotLoader(itemsRoot).LoadByCharacterUid(1293600).InventoryItems);
            Assert.Contains("handled MsgItemUsage buy", log.ToString());
        }
        finally
        {
            if (Directory.Exists(itemsRoot))
            {
                Directory.Delete(itemsRoot, recursive: true);
            }
        }
    }

