                Assert.Equal((byte)0, boughtItem.Position);
            }

            Assert.Contains("handled MsgItemUsage buy", log.ToString());
            Assert.Contains("remoteMallFallback=True", log.ToString());
        }
        finally
        {
            if (Directory.Exists(itemsRoot))
            {
                Directory.Delete(itemsRoot, recursive: true);
            }
        }
    }

