    [Fact]
    public async Task HandlerItemUsageShowWarehouseMoneyEchoesSnapshotWarehouseMoney()
    {
        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(1293600, uid: 1293600, warehouseMoney: 987_654_321);
        using var log = new StringWriter();
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot), handoff, log);
        var sent = new List<byte[]>();
        var connection = CreateSendingConnection(sent);

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));

        var countBeforeRequest = sent.Count;
        var request = new MsgItemUsagePacket(
            Id: 12345,
            DwParam: 0,
            Action: MsgItemUsageAction.ShowWarehouseMoney,
            Timestamp: 112233,
            DwParam2: 44,
            DwParam3: 55,
            DwParam4: 66);

        await handler.HandleFrameAsync(connection, ReadFrame(request.ToFrameBytes()));

        Assert.Equal(countBeforeRequest + 1, sent.Count);
        Assert.True(PacketFrameDecoder.TryRead(new ReadOnlySequence<byte>(sent[^1]), out var frame, out _, out _));
        Assert.True(MsgItemUsagePacket.TryParse(frame, out var response));
        Assert.Equal(request with { DwParam = 987_654_321UL }, response);
        Assert.Contains("WorldServer handled MsgItemUsage", log.ToString());
        Assert.Contains("sent MsgItemUsage warehouse money", log.ToString());
    }

