    [Fact]
    public async Task HandlerLegacyNpcReplyNobilityDonorInputConfirmAppliesCpDonation()
    {
        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(1293600, uid: 1293600, conquerPoints: 500_000, boundConquerPoints: 0);
        using var log = new StringWriter();
        var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot), log);
        var sent = new List<byte[]>();
        var connection = CreateSendingConnection(sent);

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new LegacyMsgLoginGamePacket(1293600).ToFrameBytes()));
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(LegacyNpcServerRequestPacket.Script(2_541, optionId: 0, interactType: 1).ToFrameBytes()));

        var countBeforeInput = sent.Count;
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(BuildLegacyNpcDialogReply(
                optionId: 1,
                interactType: (byte)LegacyNpcReplyInteractType.Input,
                npcId: 2_541,
                input: "400000")));

        Assert.Equal(countBeforeInput + 5, sent.Count);
        Assert.Equal(400_000U, GetSession(handler, connection).PendingNobilityDonationConquerPoints);
        Assert.True(LegacyNpcReplyPacket.TryParse(ReadFrame(sent[countBeforeInput]), out var confirm));
        Assert.Equal(LegacyNpcReplyInteractType.Dialog, confirm.InteractType);
        Assert.Contains("400000 CPs", confirm.Text);
        Assert.Contains("200000000", confirm.Text);

        var countBeforeConfirm = sent.Count;
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(BuildLegacyNpcDialogReply(
                optionId: 2,
                interactType: (byte)LegacyNpcReplyInteractType.Option)));

        Assert.Equal(countBeforeConfirm + 2, sent.Count);
        Assert.True(LegacyNobilityIconPacket.TryParse(ReadFrame(sent[countBeforeConfirm]), out var icon));
        Assert.Equal(200_000_000UL, icon.Donation);
        Assert.Equal((byte)5, icon.Rank);
        AssertSingleUpdate(sent[countBeforeConfirm + 1], 1_293_600, LegacyMsgUpdateDataType.ConquerPoints, 100_000);
        var updated = GetSession(handler, connection);
        Assert.Null(updated.PendingNobilityDonationConquerPoints);
        Assert.Equal(100_000, updated.Character.ConquerPoints);
        Assert.Equal("200000000", updated.Character.Attributes["DonationNobility"]);

        var persisted = CharacterSnapshotParser.ParseText(File.ReadAllText(Path.Combine(_usersRoot, "1293600.ini")));
        Assert.Equal(100_000, persisted.ConquerPoints);
        Assert.Equal("200000000", persisted.Attributes["DonationNobility"]);
        var output = log.ToString();
        Assert.Contains("WorldServer routed LegacyNpc NobilityDonor donation", output);
        Assert.Contains("WorldServer applied LegacyNobility donation", output);
        Assert.Contains("source=NpcHandler.NobilityDonor option 2.", output);
        Assert.Contains("source=MsgNobility donation.", output);
        Assert.DoesNotContain("PARITY-GAP unmodeled LegacyNpcReply", output);
    }

    [Fact]
    public async Task HandlerLegacyNpcReplyNobilityDonorConfirmRechecksConquerPointsBeforeMutation()
    {
        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(1293600, uid: 1293600, conquerPoints: 500_000, boundConquerPoints: 0);
        using var log = new StringWriter();
        var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot), log);
        var sent = new List<byte[]>();
        var connection = CreateSendingConnection(sent);

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new LegacyMsgLoginGamePacket(1293600).ToFrameBytes()));
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(LegacyNpcServerRequestPacket.Script(2_541, optionId: 0, interactType: 1).ToFrameBytes()));
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(BuildLegacyNpcDialogReply(
                optionId: 1,
                interactType: (byte)LegacyNpcReplyInteractType.Input,
                npcId: 2_541,
                input: "400000")));

        var pending = GetSession(handler, connection);
        Assert.Equal(400_000U, pending.PendingNobilityDonationConquerPoints);
        SetSession(
            handler,
            connection,
            pending with { Character = pending.Character with { ConquerPoints = 100_000 } });

        var countBeforeConfirm = sent.Count;
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(BuildLegacyNpcDialogReply(
                optionId: 2,
                interactType: (byte)LegacyNpcReplyInteractType.Option)));

        Assert.Equal(countBeforeConfirm + 1, sent.Count);
        Assert.True(LegacyNpcReplyPacket.TryParse(ReadFrame(sent[countBeforeConfirm]), out var messageBox));
        Assert.Equal(LegacyNpcReplyInteractType.MessageBox, messageBox.InteractType);
        Assert.Contains("You do not have: 400000 CPs.", messageBox.Text);
        var updated = GetSession(handler, connection);
