    [Fact]
    public async Task HandlerLegacyNpcReplyAccountManagerPaidKingPersistsSourceBackedPaidNobility()
    {
        const uint accountManagerNpcId = 45_632;

        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(
            1293600,
            uid: 1293600,
            nobilityDonation: 123_456,
            donatePoints: 160);
        using var log = new StringWriter();
        var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot), log);
        var sent = new List<byte[]>();
        var connection = CreateSendingConnection(sent);

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new LegacyMsgLoginGamePacket(1293600).ToFrameBytes()));

        var countBeforeMenu = sent.Count;
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(LegacyNpcServerRequestPacket.Script(accountManagerNpcId, optionId: 1, interactType: 1).ToFrameBytes()));

        Assert.True(sent.Count > countBeforeMenu);
        Assert.True(LegacyNpcReplyPacket.TryParse(ReadFrame(sent[countBeforeMenu]), out var menu));
        Assert.Equal(LegacyNpcReplyInteractType.Dialog, menu.InteractType);
        Assert.Contains("160", menu.Text);
        Assert.Contains(
            sent.Skip(countBeforeMenu)
                .Select(ReadFrame)
                .Where(frame => LegacyNpcReplyPacket.TryParse(frame, out _))
                .Select(frame =>
                {
                    LegacyNpcReplyPacket.TryParse(frame, out var reply);
                    return reply;
                }),
            reply => reply.InteractType == LegacyNpcReplyInteractType.Option && reply.OptionId == 10);

        var beforePurchase = DateTime.Now;
        var countBeforePurchase = sent.Count;
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(BuildLegacyNpcDialogReply(optionId: 10, interactType: 1)));

        Assert.Equal(countBeforePurchase, sent.Count);

        var persisted = CharacterSnapshotParser.ParseText(File.ReadAllText(Path.Combine(_usersRoot, "1293600.ini")));
        Assert.Equal("10", persisted.Attributes["DonatePoints"]);
        Assert.Equal("1293600", persisted.PaidNobility["Identifier"]);
        Assert.Equal("123456", persisted.PaidNobility["LastNobilityDonation"]);
        Assert.Equal("12", persisted.PaidNobility["PaidRank"]);
        Assert.True(bool.Parse(persisted.PaidNobility["IsActive"]));
        var periodTime = DateTime.FromBinary(long.Parse(persisted.PaidNobility["PeriodTime"], CultureInfo.InvariantCulture));
        Assert.InRange(
            periodTime,
            beforePurchase.AddDays(30).AddSeconds(-1),
            DateTime.Now.AddDays(30).AddSeconds(1));

        var reloaded = new CharacterSnapshotLoader(_usersRoot).LoadByAccountId(1293600);
        Assert.NotNull(reloaded);
        var icon = LegacyNobilityIconPacket.FromSnapshot(reloaded, _usersRoot);
        Assert.Equal(0UL, icon.Donation);
        Assert.Equal((byte)12, icon.Rank);
        Assert.Equal(0, icon.Position);
        Assert.Contains("source=NpcHandler.AccountManager", log.ToString());
        Assert.DoesNotContain("PARITY-GAP unmodeled LegacyNpcReply", log.ToString());
    }

