        Assert.Equal("50", persisted.Attributes["DonatePoints"]);
        Assert.Equal("7", persisted.Attributes["VipLevel"]);
        var persistedVipTime = DateTime.FromBinary(long.Parse(persisted.Attributes["VipTime"], CultureInfo.InvariantCulture));
        Assert.InRange(
            persistedVipTime,
            beforePurchase.AddDays(30).AddSeconds(-1),
            DateTime.Now.AddDays(30).AddSeconds(1));
        Assert.Contains("WorldServer applied LegacyNpc AccountManager VIP purchase", log.ToString());
        Assert.Contains("source=NpcHandler.AccountManager", log.ToString());
        Assert.DoesNotContain("PARITY-GAP unmodeled LegacyNpcReply", log.ToString());
    }

