    [Fact]
    public async Task HandlerLegacyNpcReplyAccountManagerItemPurchaseRejectsInsufficientDonatePoints()
    {
        const uint accountManagerNpcId = 45_632;
        var itemsRoot = Path.Combine(Path.GetTempPath(), "wolf-accountmanager-item-grants-" + Guid.NewGuid());

        try
        {
            Directory.CreateDirectory(_usersRoot);
            Directory.CreateDirectory(itemsRoot);
            WriteSnapshot(
                1293600,
                uid: 1293600,
                donatePoints: 19);
            using var log = new StringWriter();
            var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot, itemsRoot), log);
            var sent = new List<byte[]>();
            var connection = CreateSendingConnection(sent);

            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new LegacyMsgLoginGamePacket(1293600).ToFrameBytes()));
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(LegacyNpcServerRequestPacket.Script(accountManagerNpcId, optionId: 1, interactType: 1).ToFrameBytes()));

            var countBeforePurchase = sent.Count;
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(BuildLegacyNpcDialogReply(optionId: 4, interactType: 1)));

            Assert.True(sent.Count > countBeforePurchase);
            Assert.True(LegacyNpcReplyPacket.TryParse(ReadFrame(sent[countBeforePurchase]), out var insufficient));
            Assert.Contains("20", insufficient.Text);

            var updated = GetSession(handler, connection);
            Assert.Equal("19", updated.Character.Attributes["DonatePoints"]);
            Assert.Empty(updated.PlayerItems.InventoryItems);

            var persisted = CharacterSnapshotParser.ParseText(File.ReadAllText(Path.Combine(_usersRoot, "1293600.ini")));
            Assert.Equal("19", persisted.Attributes["DonatePoints"]);
            var persistedItems = new PlayerItemSnapshotLoader(itemsRoot).LoadByCharacterUid(1293600);
            Assert.Empty(persistedItems.InventoryItems);

            var output = log.ToString();
            Assert.Contains("WorldServer skipped LegacyNpc AccountManager item purchase", output);
            Assert.Contains("source=NpcHandler.AccountManager", output);
            Assert.DoesNotContain("WorldServer applied LegacyNpc AccountManager item purchase", output);
            Assert.DoesNotContain("PARITY-GAP", output);
        }
        finally
        {
            if (Directory.Exists(itemsRoot))
            {
                Directory.Delete(itemsRoot, recursive: true);
            }
        }
    }

    [Theory]
    [InlineData(12, "King", 150_000_000UL, 3, -1)]
    [InlineData(9, "Prince", 250_000_000UL, 5, -1)]
    public async Task HandlerLegacyWorldLoginExpiredActivePaidNobilityRestoresPreviousDonationAndSendsNormalIcon(
        int paidRank,
        string paidRankName,
        ulong previousDonation,
        int expectedRank,
        int expectedPosition)
    {
        Directory.CreateDirectory(_usersRoot);
        WriteAccountManagerPaidNobilitySnapshot(
            paidRank,
            paidRankName,
            previousDonation,
            DateTime.Now.AddDays(-1));
        using var log = new StringWriter();
        var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot), log);
        var sent = new List<byte[]>();
        var connection = CreateSendingConnection(sent);

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new LegacyMsgLoginGamePacket(1293600).ToFrameBytes()));

        var expectedDonation = previousDonation.ToString(CultureInfo.InvariantCulture);
        var expectedRankText = expectedRank.ToString(CultureInfo.InvariantCulture);
        var expectedPositionText = expectedPosition.ToString(CultureInfo.InvariantCulture);
        var session = GetSession(handler, connection);
        Assert.Equal(expectedDonation, session.Character.Attributes["DonationNobility"]);
        Assert.Equal(expectedDonation, session.Character.Attributes["LastNobilityDonation"]);
        Assert.Equal(expectedRankText, session.Character.Attributes["NobilityRank"]);
        Assert.Equal(expectedPositionText, session.Character.Attributes["NobilityPosition"]);
        Assert.False(IsPaidNobilityActive(session.Character.PaidNobility));

        var startupIcon = AssertSingleLegacyNobilityIcon(sent);
        Assert.Equal(1_293_600UL, startupIcon.Uid);
        Assert.Equal(previousDonation, startupIcon.Donation);
        Assert.Equal(checked((byte)expectedRank), startupIcon.Rank);
        Assert.Equal(expectedPosition, startupIcon.Position);

        var persisted = CharacterSnapshotParser.ParseText(File.ReadAllText(Path.Combine(_usersRoot, "1293600.ini")));
        Assert.Equal(expectedDonation, persisted.Attributes["DonationNobility"]);
        Assert.Equal(expectedDonation, persisted.Attributes["LastNobilityDonation"]);
        Assert.Equal(expectedRankText, persisted.Attributes["NobilityRank"]);
        Assert.Equal(expectedPositionText, persisted.Attributes["NobilityPosition"]);
        Assert.False(IsPaidNobilityActive(persisted.PaidNobility));
    }

