    [Fact]
    public async Task HandlerRuntimeLoopExpiresActivePaidNobilityRestoresRegularRankAndSendsUpdatedIcon()
    {
        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(10, uid: 10, name: "First", nobilityDonation: 400_000_000);
        WriteSnapshot(20, uid: 20, name: "Second", nobilityDonation: 380_000_000);
        WriteSnapshot(30, uid: 30, name: "OnlineOnly", nobilityDonation: 370_000_000);
        WriteAccountManagerPaidNobilitySnapshot(
            LegacyNobilityRanking.RankKing,
            "King",
            previousDonation: 390_000_000,
            DateTime.Now.AddSeconds(1));
        using var log = new RuntimeThreadSafeStringWriter();
        using var cancel = new CancellationTokenSource();
        var handler = new WorldServerFrameHandler(
            new CharacterSnapshotLoader(_usersRoot),
            handoffService: null,
            worldData: null,
            new LegacyRuntimeUpdateLoopOptions(
                Enabled: true,
                TimeSpan.FromMilliseconds(20),
                TimeProvider.System),
            log);
        var sent = new RuntimeThreadSafeFrameCapture();
        var onlineOnlySent = new RuntimeThreadSafeFrameCapture();
        var secondSent = new RuntimeThreadSafeFrameCapture();
        var connection = CreateSendingConnection(sent);
        var onlineOnlyConnection = CreateSendingConnection(onlineOnlySent);
        var secondConnection = CreateSendingConnection(secondSent);

        try
        {
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new LegacyMsgLoginGamePacket(1293600).ToFrameBytes()),
                cancel.Token);

            var startupIcon = AssertSingleLegacyNobilityIcon(sent);
            Assert.Equal(1_293_600UL, startupIcon.Uid);
            Assert.Equal(0UL, startupIcon.Donation);
            Assert.Equal((byte)LegacyNobilityRanking.RankKing, startupIcon.Rank);
            Assert.Equal(0, startupIcon.Position);

            await handler.HandleFrameAsync(
                onlineOnlyConnection,
                ReadFrame(new LegacyMsgLoginGamePacket(30).ToFrameBytes()),
                cancel.Token);
            var onlineOnlySession = GetSession(handler, onlineOnlyConnection);
            var onlineOnlyAttributes = new Dictionary<string, string>(
                onlineOnlySession.Character.Attributes,
                StringComparer.OrdinalIgnoreCase)
            {
                ["DonationNobility"] = "395000000",
                ["LastNobilityDonation"] = "395000000",
            };
            SetSession(handler, onlineOnlyConnection, onlineOnlySession with
            {
                Character = onlineOnlySession.Character with { Attributes = onlineOnlyAttributes },
            });

            await handler.HandleFrameAsync(
                secondConnection,
                ReadFrame(new LegacyMsgLoginGamePacket(20).ToFrameBytes()),
                cancel.Token);
            var secondStartupIcon = AssertSingleLegacyNobilityIcon(secondSent);
            Assert.Equal(20UL, secondStartupIcon.Uid);
            Assert.Equal(380_000_000UL, secondStartupIcon.Donation);
            Assert.Equal((byte)LegacyNobilityRanking.RankEarl, secondStartupIcon.Rank);
            Assert.Equal(LegacyNobilityRanking.DefaultPosition, secondStartupIcon.Position);

            var startupCount = sent.Count;
            var secondStartupCount = secondSent.Count;
            await WaitUntilAsync(
                () => FindFrameIndexAfter(
                    sent,
                    startupCount,
                    frame => LegacyNobilityIconPacket.TryParse(frame, out var icon) &&
                        icon.Uid == 1_293_600UL &&
                        icon.Donation == 390_000_000UL &&
                        icon.Rank == LegacyNobilityRanking.RankKing &&
                        icon.Position == 2) >= startupCount &&
                    FindFrameIndexAfter(
                        secondSent,
                        secondStartupCount,
                        frame => LegacyNobilityIconPacket.TryParse(frame, out var icon) &&
                            icon.Uid == 20UL &&
                            icon.Donation == 380_000_000UL &&
                            icon.Rank == LegacyNobilityRanking.RankPrince &&
                            icon.Position == 3) >= secondStartupCount,
                TimeSpan.FromSeconds(2));

            var expiredIconIndex = FindFrameIndexAfter(
                sent,
                startupCount,
                frame => LegacyNobilityIconPacket.TryParse(frame, out var icon) &&
                    icon.Uid == 1_293_600UL &&
                    icon.Donation == 390_000_000UL);
            Assert.True(LegacyNobilityIconPacket.TryParse(ReadFrame(sent[expiredIconIndex]), out var expiredIcon));
            Assert.Equal((byte)LegacyNobilityRanking.RankKing, expiredIcon.Rank);
            Assert.Equal(2, expiredIcon.Position);

            var secondFanoutIndex = FindFrameIndexAfter(
                secondSent,
                secondStartupCount,
                frame => LegacyNobilityIconPacket.TryParse(frame, out var icon) &&
                    icon.Uid == 20UL &&
                    icon.Donation == 380_000_000UL);
            Assert.True(LegacyNobilityIconPacket.TryParse(ReadFrame(secondSent[secondFanoutIndex]), out var secondFanout));
            Assert.Equal((byte)LegacyNobilityRanking.RankPrince, secondFanout.Rank);
            Assert.Equal(3, secondFanout.Position);

            var session = GetSession(handler, connection);
            Assert.Equal("390000000", session.Character.Attributes["DonationNobility"]);
            Assert.Equal("390000000", session.Character.Attributes["LastNobilityDonation"]);
            Assert.Equal("12", session.Character.Attributes["NobilityRank"]);
            Assert.Equal("2", session.Character.Attributes["NobilityPosition"]);
            Assert.False(IsPaidNobilityActive(session.Character.PaidNobility));

            var secondSession = GetSession(handler, secondConnection);
            Assert.Equal("380000000", secondSession.Character.Attributes["DonationNobility"]);
            Assert.Equal("9", secondSession.Character.Attributes["NobilityRank"]);
            Assert.Equal("3", secondSession.Character.Attributes["NobilityPosition"]);

            var persisted = CharacterSnapshotParser.ParseText(File.ReadAllText(Path.Combine(_usersRoot, "1293600.ini")));
            Assert.Equal("390000000", persisted.Attributes["DonationNobility"]);
            Assert.Equal("390000000", persisted.Attributes["LastNobilityDonation"]);
            Assert.Equal("12", persisted.Attributes["NobilityRank"]);
            Assert.Equal("2", persisted.Attributes["NobilityPosition"]);
            Assert.False(IsPaidNobilityActive(persisted.PaidNobility));
        }
        finally
        {
            await cancel.CancelAsync();
        }
    }

