    [Fact]
    public async Task HandlerLegacyNpcReplyAccountManagerPaidNobilityRejectsInsufficientDonatePoints()
    {
        const uint accountManagerNpcId = 45_632;

        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(
            1293600,
            uid: 1293600,
            donatePoints: 149);
        var before = CharacterSnapshotParser.ParseText(File.ReadAllText(Path.Combine(_usersRoot, "1293600.ini")));
        using var log = new StringWriter();
        var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot), log);
        var sent = new List<byte[]>();
        var connection = CreateSendingConnection(sent);

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new LegacyMsgLoginGamePacket(1293600).ToFrameBytes()));
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(LegacyNpcServerRequestPacket.Script(accountManagerNpcId, optionId: 1, interactType: 1).ToFrameBytes()));

        var countBeforePurchase = sent.Count;
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(BuildLegacyNpcDialogReply(optionId: 10, interactType: 1)));

        Assert.True(sent.Count > countBeforePurchase);
        Assert.True(LegacyNpcReplyPacket.TryParse(ReadFrame(sent[countBeforePurchase]), out var insufficient));
        Assert.Contains(
            insufficient.InteractType,
            new[] { LegacyNpcReplyInteractType.Dialog, LegacyNpcReplyInteractType.MessageBox });
        Assert.Contains("150", insufficient.Text);

        var persisted = CharacterSnapshotParser.ParseText(File.ReadAllText(Path.Combine(_usersRoot, "1293600.ini")));
        Assert.Equal("149", persisted.Attributes["DonatePoints"]);
        Assert.Equal(
            before.PaidNobility.OrderBy(pair => pair.Key, StringComparer.OrdinalIgnoreCase),
            persisted.PaidNobility.OrderBy(pair => pair.Key, StringComparer.OrdinalIgnoreCase));
        Assert.Contains("source=NpcHandler.AccountManager", log.ToString());
        Assert.DoesNotContain("PaidRank", persisted.PaidNobility.Keys);
        Assert.DoesNotContain("PeriodTime", persisted.PaidNobility.Keys);
        Assert.DoesNotContain("IsActive", persisted.PaidNobility.Keys);
    }

    [Fact(Skip = "Requires external game fixtures omitted from the public source snapshot.")]
    public async Task HandlerLegacyNpcReplyTeleportsVisibleLevelHuntExitNpcToTwinCity()
    {
        var seedPath = Path.Combine(FindRepositoryRoot(), ".setup_work", "seed-json");
        if (!File.Exists(Path.Combine(seedPath, "manifest.json")))
        {
            return;
        }

        using var log = new StringWriter();
        var worldData = await new JsonWorldDataLoader(new WorldDataOptions(seedPath)).LoadAsync();
        var levelHuntExit = worldData.NpcsById[20_201].Single(row => row.MapId == 10_342);
        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(
            1293600,
            uid: 1293600,
            mapId: levelHuntExit.MapId,
            x: levelHuntExit.X,
            y: levelHuntExit.Y);
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot), handoff, worldData, log);
        var sent = new List<byte[]>();
        var connection = CreateSendingConnection(sent);

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));

        var countBeforeClick = sent.Count;
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(LegacyNpcServerRequestPacket.Script(20_201, optionId: 0, interactType: 1).ToFrameBytes()));

        Assert.Equal(countBeforeClick + 5, sent.Count);
        Assert.True(LegacyNpcReplyPacket.TryParse(ReadFrame(sent[countBeforeClick]), out var dialog));
        Assert.Equal(LegacyNpcReplyInteractType.Dialog, dialog.InteractType);
        Assert.Equal("Hey Brothr HeroOne Do You Want Leve this map to Twin City", dialog.Text);
        Assert.True(LegacyNpcReplyPacket.TryParse(ReadFrame(sent[countBeforeClick + 1]), out var yesOption));
        Assert.Equal(1, yesOption.OptionId);
        Assert.Equal("Yes Plase", yesOption.Text);

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(BuildLegacyNpcDialogReply(optionId: 1, interactType: 1)));

        var teleportIndex = FindFrameIndexAfter(
            sent,
            countBeforeClick,
            frame => MsgActionPacket.TryParse(frame, out var action) &&
                action.Type == MsgActionType.Teleport &&
                action.DwParam == 1_002U &&
                action.PositionX == 410U &&
                action.PositionY == 355U);
        Assert.True(teleportIndex >= countBeforeClick);
        Assert.True(MsgActionPacket.TryParse(ReadFrame(sent[teleportIndex]), out var teleport));
        Assert.Equal(1_002U, teleport.DwParam);
        Assert.Equal(MsgActionType.Teleport, teleport.Type);
        Assert.Equal(410U, teleport.PositionX);
        Assert.Equal(355U, teleport.PositionY);
        Assert.Equal(1_002, teleport.DwParam3);

        Assert.True(MsgActionPacket.TryParse(ReadFrame(sent[teleportIndex + 1]), out var merchantStartup));
        Assert.Equal(MsgActionType.LegacyMerchantStartup, merchantStartup.Type);
        Assert.Equal(2U, merchantStartup.DwParam);
        Assert.True(MsgActionPacket.TryParse(ReadFrame(sent[teleportIndex + 2]), out var stopVending));
        Assert.Equal(MsgActionType.StopVending, stopVending.Type);
        Assert.True(MsgActionPacket.TryParse(ReadFrame(sent[teleportIndex + 3]), out var color));
        Assert.Equal(MsgActionType.LegacyColor, color.Type);
        Assert.True(LegacyMapStatusPacket.TryParse(ReadFrame(sent[teleportIndex + 4]), out var mapStatus));
        Assert.Equal(LegacyMapStatusPacket.FromMap(1_002, worldData.MapsById), mapStatus);

        var updatedSession = GetSession(handler, connection);
        Assert.Equal(1_002, updatedSession.Character.MapId);
        Assert.Equal(410, updatedSession.Character.X);
        Assert.Equal(355, updatedSession.Character.Y);
        Assert.Equal(levelHuntExit.MapId, updatedSession.Character.PreviousMapId);
        Assert.Equal(levelHuntExit.X, updatedSession.Character.PreviousMapX);
        Assert.Equal(levelHuntExit.Y, updatedSession.Character.PreviousMapY);
        Assert.Contains("source=NpcHandler.leveHuntMap1", log.ToString());
    }

