    [Fact(Skip = "Requires external game fixtures omitted from the public source snapshot.")]
    public async Task HandlerSetLocationActionLogsNearestNpcDiagnosticsForEmptyMap1015SpawnWindow()
    {
        var seedPath = Path.Combine(FindRepositoryRoot(), ".setup_work", "seed-json");
        if (!File.Exists(Path.Combine(seedPath, "manifest.json")))
        {
            return;
        }

        const int spawnX = 828;
        const int spawnY = 590;

        using var log = new StringWriter();
        var worldData = await new JsonWorldDataLoader(new WorldDataOptions(seedPath)).LoadAsync();
        var nearestNpc = worldData.NpcsByMapId[1015]
            .OrderBy(npc => LegacyTestDistance(spawnX, spawnY, npc.X, npc.Y))
            .First();
        var nearestNpcDistance = LegacyTestDistance(spawnX, spawnY, nearestNpc.X, nearestNpc.Y);
        var nearestSobNpc = worldData.SobNpcsByMapId[1015]
            .OrderBy(sobNpc => LegacyTestDistance(spawnX, spawnY, sobNpc.X, sobNpc.Y))
            .First();
        var nearestSobNpcDistance = LegacyTestDistance(spawnX, spawnY, nearestSobNpc.X, nearestSobNpc.Y);
        if (nearestNpcDistance <= 18 || nearestSobNpcDistance <= 18)
        {
            return;
        }

        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(1293600, uid: 1293600, mapId: 1015, x: spawnX, y: spawnY);
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot), handoff, worldData, log);
        var sent = new List<byte[]>();
        var connection = CreateSendingConnection(sent);

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new MsgActionPacket
            {
                ObjId = 1_293_600,
                Timestamp = 1234,
                Type = MsgActionType.SetLocation,
            }.ToFrameBytes()));

        var output = log.ToString();
        Assert.Contains("WorldServer found no visible LegacyNpcSpawn", output);
        Assert.DoesNotContain("PARITY-GAP no visible LegacyNpcSpawn", output);
        Assert.Contains($"nearestNpcId={nearestNpc.Id}", output);
        Assert.Contains($"nearestNpcX={nearestNpc.X}", output);
        Assert.Contains($"nearestNpcY={nearestNpc.Y}", output);
        Assert.Contains($"nearestNpcDistance={nearestNpcDistance}", output);
        Assert.Contains("visibilityThreshold=18", output);
        Assert.Contains("WorldServer found no visible LegacySobNpcSpawn", output);
        Assert.DoesNotContain("PARITY-GAP no visible LegacySobNpcSpawn", output);
        Assert.Contains($"nearestSobNpcId={nearestSobNpc.Id}", output);
        Assert.Contains($"nearestSobNpcName={nearestSobNpc.Name}", output);
        Assert.Contains($"nearestSobNpcDistance={nearestSobNpcDistance}", output);
        Assert.Contains("visibilityThreshold=18", output);
    }

