    public async Task HandlerSetLocationActionSendsVisibleMonstersBeforeMapStatus()
    {
        var seedPath = Path.Combine(FindRepositoryRoot(), ".setup_work", "seed-json");
        if (!File.Exists(Path.Combine(seedPath, "manifest.json")))
        {
            return;
        }

        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(1293600, uid: 1293600, mapId: 1000, x: 192, y: 345);
        using var log = new StringWriter();
        var worldData = await new JsonWorldDataLoader(new WorldDataOptions(seedPath)).LoadAsync();
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot), handoff, worldData, log);
        var sent = new List<byte[]>();
        var connection = CreateSendingConnection(sent);

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new MsgActionPacket
            {
                ObjId = 1_293_600,
                Timestamp = 1234,
                Type = MsgActionType.SetLocation,
            }.ToFrameBytes()));

        var actionIndex = FindFrameIndexAfter(
            sent,
            startIndex: 0,
            frame => MsgActionPacket.TryParse(frame, out var action) &&
                action.Type == MsgActionType.SetLocation);
        Assert.True(actionIndex >= 0);
        Assert.True(PacketFrameDecoder.TryRead(new ReadOnlySequence<byte>(sent[actionIndex]), out var actionFrame, out _, out _));
        Assert.True(MsgActionPacket.TryParse(actionFrame, out _));

        var mapStatusIndex = FindFrameIndexAfter(
            sent,
            actionIndex + 1,
            frame => LegacyMapStatusPacket.TryParse(frame, out _));
        Assert.True(mapStatusIndex > actionIndex);
        var monsters = new List<LegacyMonsterSpawnPacket>();
        for (var index = actionIndex + 1; index < mapStatusIndex; index++)
        {
            Assert.True(PacketFrameDecoder.TryRead(new ReadOnlySequence<byte>(sent[index]), out var monsterFrame, out _, out _));
            Assert.True(LegacyMonsterSpawnPacket.TryParse(monsterFrame, out var monster));
            monsters.Add(monster);
        }

        Assert.NotEmpty(monsters);
        Assert.All(monsters, monster =>
        {
            Assert.NotEmpty(monster.Names);
            Assert.True(monster.Hitpoints > 0);
            Assert.True(monster.X > 0);
            Assert.True(monster.Y > 0);
        });

        Assert.True(PacketFrameDecoder.TryRead(new ReadOnlySequence<byte>(sent[mapStatusIndex]), out var mapFrame, out _, out _));
        Assert.True(LegacyMapStatusPacket.TryParse(mapFrame, out var mapStatus));
        Assert.Equal(1000U, mapStatus.Id);
        Assert.Contains("sent LegacyMonsterSpawn", log.ToString());
        Assert.Contains($"monsterCount={monsters.Count}", log.ToString());
    }

