    public async Task HandlerSetLocationActionSendsBossMonsterHitpointUpdatesAfterSpawn()
    {
        var seedPath = Path.Combine(FindRepositoryRoot(), ".setup_work", "seed-json");
        if (!File.Exists(Path.Combine(seedPath, "manifest.json")))
        {
            return;
        }

        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(1293600, uid: 1293600, mapId: 1015, x: 758, y: 722);
        using var log = new StringWriter();
        var worldData = await new JsonWorldDataLoader(new WorldDataOptions(seedPath)).LoadAsync();
        var bossInstance = FindVisibleMonster(worldData, mapId: 1015, name: "BirdKing", x: 758, y: 722);
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot), handoff, worldData, log);
        var sent = new List<byte[]>();
        var connection = CreateSendingConnection(sent);

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new MsgActionPacket
            {
                ObjId = 1_293_600,
                Timestamp = 1234,
                Type = MsgActionType.SetLocation,
            }.ToFrameBytes()));

        var frames = sent.Select(ReadFrame).ToList();
        var monsterIndex = frames.FindIndex(frame =>
            LegacyMonsterSpawnPacket.TryParse(frame, out var monster) &&
            monster.Uid == bossInstance.Uid);

        Assert.True(monsterIndex >= 0);
        Assert.True(LegacyMonsterSpawnPacket.TryParse(frames[monsterIndex], out var bossMonster));
        Assert.True(LegacyMsgUpdatePacket.TryParse(frames[monsterIndex + 1], out var maxHitpoints));
        Assert.Equal(bossMonster.Uid, maxHitpoints.Uid);
        Assert.Equal(
        [
            new LegacyMsgUpdateEntry(LegacyMsgUpdateDataType.MaxHitpoints, bossInstance.MaxLife),
        ], maxHitpoints.Updates);

        Assert.True(LegacyMsgUpdatePacket.TryParse(frames[monsterIndex + 2], out var hitpoints));
        Assert.Equal(bossMonster.Uid, hitpoints.Uid);
        Assert.Equal(
        [
            new LegacyMsgUpdateEntry(LegacyMsgUpdateDataType.MaxHitpoints, bossInstance.MaxLife),
            new LegacyMsgUpdateEntry(LegacyMsgUpdateDataType.Hitpoints, bossInstance.Hitpoints),
        ], hitpoints.Updates);

        Assert.True(LegacyMapStatusPacket.TryParse(frames[^1], out var mapStatus));
        Assert.Equal(1015U, mapStatus.Id);
    }

