    [Fact]
    public async Task HandlerSendsArenaSignupCreateAndArenaInfoAfterSuccessfulWorldEnter()
    {
        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(1293600, uid: 1293600);
        using var log = new StringWriter();
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        var arenaStatistics = new ArenaStatisticsProvider(
        [
            ArenaRecord(400001, "Higher", points: 6000),
            ArenaRecord(1293600, "HeroOne", points: 4500, currentHonor: 500, historyHonor: 600, todayBattles: 5, todayWin: 4, totalLose: 3, totalWin: 12),
        ]);
        var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot), handoff, arenaStatistics, log);
        var sent = new List<byte[]>();
        var connection = CreateSendingConnection(sent);

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new MsgArenaSignupPacket(MsgArenaSignupDialogType.ArenaIconOn, MsgArenaSignupDialogButton.SignUp).ToFrameBytes()));

        Assert.Equal(59, sent.Count);
        AssertLegacyWorldEntryStartupFrames(sent, startIndex: 1);
        Assert.True(PacketFrameDecoder.TryRead(new ReadOnlySequence<byte>(sent[^2]), out var frame, out _, out _));
        Assert.True(MsgArenaSignupResponsePacket.TryParse(frame, out var response));
        Assert.Equal(MsgArenaSignupDialogType.ArenaIconOn, response.DialogType);
        Assert.Equal(MsgArenaSignupDialogButton.SignUp, response.DialogButton);
        Assert.Equal(1_293_600U, response.CharacterUid);
        Assert.Equal("HeroOne", response.CharacterName);
        Assert.Equal(2U, response.TodayRank);
        Assert.Equal(7051U, response.Class);
        Assert.Equal(4500U, response.ArenaPoints);
        Assert.Equal(140U, response.Level);
        Assert.True(PacketFrameDecoder.TryRead(new ReadOnlySequence<byte>(sent[^1]), out var infoFrame, out _, out _));
        Assert.True(MsgArenaInfoPacket.TryParse(infoFrame, out var arenaInfo));
        Assert.Equal(MsgArenaInfoStatus.WaitingForOpponent, arenaInfo.Status);
        Assert.Equal(2U, arenaInfo.TodayRank);
        Assert.Equal(4500U, arenaInfo.ArenaPoints);
        Assert.Equal(12U, arenaInfo.TotalWin);
        Assert.Equal(3U, arenaInfo.TotalLose);
        Assert.Equal(4U, arenaInfo.TodayWin);
        Assert.Equal(5U, arenaInfo.TodayBattles);
        Assert.Equal(600U, arenaInfo.HistoryHonor);
        Assert.Equal(500U, arenaInfo.CurrentHonor);
        Assert.Contains("WorldServer sent MsgArenaSignup response", log.ToString());
        Assert.Contains("WorldServer sent MsgArenaInfo", log.ToString());
        Assert.Contains("status=WaitingForOpponent", log.ToString());
        Assert.Contains("todayRank=2 arenaPoints=4500", log.ToString());
    }

    [Fact]
    public async Task HandlerArenaSignupPairsTwoWaitingPlayersAndSendsCountdown()
    {
        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(1293600, uid: 1293600, x: 830, y: 584);
        WriteSnapshot(400001, uid: 400001, x: 831, y: 584, name: "Target");
        using var log = new StringWriter();
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var firstTicket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        var secondTicket = handoff.Issue(400001, "target", ConquerRuntimeDefaults.WorldServer);
        var handler = new WorldServerFrameHandler(
            new CharacterSnapshotLoader(_usersRoot),
            handoff,
            new ArenaStatisticsProvider(
            [
                ArenaRecord(1293600, "HeroOne", points: 4300),
                ArenaRecord(400001, "Target", points: 4500),
            ]),
            log);
        var firstSent = new List<byte[]>();
        var secondSent = new List<byte[]>();
        var first = CreateSendingConnection(firstSent);
        var second = CreateSendingConnection(secondSent);

        await handler.HandleFrameAsync(
            first,
            ReadFrame(new InternalWorldEnterRequestPacket(firstTicket.Token).ToFrameBytes()));
        await handler.HandleFrameAsync(
            second,
            ReadFrame(new InternalWorldEnterRequestPacket(secondTicket.Token).ToFrameBytes()));
        await handler.HandleFrameAsync(
            first,
            ReadFrame(new MsgArenaSignupPacket(
                MsgArenaSignupDialogType.ArenaIconOn,
                MsgArenaSignupDialogButton.SignUp).ToFrameBytes()));
        var firstBeforePair = firstSent.Count;
        var secondBeforeSignup = secondSent.Count;

        await handler.HandleFrameAsync(
            second,
            ReadFrame(new MsgArenaSignupPacket(
                MsgArenaSignupDialogType.ArenaIconOn,
                MsgArenaSignupDialogButton.SignUp).ToFrameBytes()));

        Assert.Equal(firstBeforePair + 2, firstSent.Count);
        Assert.Equal(secondBeforeSignup + 4, secondSent.Count);
        AssertArenaInfoStatus(firstSent[firstBeforePair], MsgArenaInfoStatus.WaitingForOpponent);
        AssertArenaSignupResponse(
            firstSent[firstBeforePair + 1],
            MsgArenaSignupDialogType.StartCountDown,
            MsgArenaSignupDialogButton.SignUp,
            expectedUid: 1293600);
        AssertArenaSignupResponse(
            secondSent[secondBeforeSignup],
            MsgArenaSignupDialogType.ArenaIconOn,
            MsgArenaSignupDialogButton.SignUp,
            expectedUid: 400001);
        AssertArenaInfoStatus(secondSent[secondBeforeSignup + 1], MsgArenaInfoStatus.WaitingForOpponent);
        AssertArenaInfoStatus(secondSent[secondBeforeSignup + 2], MsgArenaInfoStatus.WaitingForOpponent);
        AssertArenaSignupResponse(
            secondSent[secondBeforeSignup + 3],
            MsgArenaSignupDialogType.StartCountDown,
            MsgArenaSignupDialogButton.SignUp,
            expectedUid: 400001);
        Assert.Contains("WorldServer sent Arena match countdown", log.ToString());
    }

    [Fact]
    public async Task HandlerArenaPendingCountdownGiveUpCompletesOnOpponentAcceptWithoutActiveFlow()
    {
        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(1293600, uid: 1293600, x: 830, y: 584);
        WriteSnapshot(400001, uid: 400001, x: 831, y: 584, name: "Target");
        WriteSnapshot(400002, uid: 400002, x: 832, y: 584, name: "Watcher");
        using var log = new StringWriter();
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var firstTicket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        var secondTicket = handoff.Issue(400001, "target", ConquerRuntimeDefaults.WorldServer);
        var watcherTicket = handoff.Issue(400002, "watcher", ConquerRuntimeDefaults.WorldServer);
        var handler = new WorldServerFrameHandler(
            new CharacterSnapshotLoader(_usersRoot),
            handoff,
            new ArenaStatisticsProvider(
            [
                ArenaRecord(1293600, "HeroOne", points: 4300),
                ArenaRecord(400001, "Target", points: 4500),
                ArenaRecord(400002, "Watcher", points: 4200),
            ]),
            log);
        var firstSent = new List<byte[]>();
        var secondSent = new List<byte[]>();
        var watcherSent = new List<byte[]>();
        var first = CreateSendingConnection(firstSent);
        var second = CreateSendingConnection(secondSent);
        var watcher = CreateSendingConnection(watcherSent);
        var signup = new MsgArenaSignupPacket(
            MsgArenaSignupDialogType.ArenaIconOn,
            MsgArenaSignupDialogButton.SignUp);

        await handler.HandleFrameAsync(first, ReadFrame(new InternalWorldEnterRequestPacket(firstTicket.Token).ToFrameBytes()));
        await handler.HandleFrameAsync(second, ReadFrame(new InternalWorldEnterRequestPacket(secondTicket.Token).ToFrameBytes()));
        await handler.HandleFrameAsync(watcher, ReadFrame(new InternalWorldEnterRequestPacket(watcherTicket.Token).ToFrameBytes()));
        await handler.HandleFrameAsync(first, ReadFrame(signup.ToFrameBytes()));
        await handler.HandleFrameAsync(second, ReadFrame(signup.ToFrameBytes()));
        var firstBeforeGiveUp = firstSent.Count;
        var secondBeforeGiveUp = secondSent.Count;
        var watcherBeforeGiveUp = watcherSent.Count;

        await handler.HandleFrameAsync(
            first,
            ReadFrame(new MsgArenaSignupPacket(
                MsgArenaSignupDialogType.ArenaGui,
                MsgArenaSignupDialogButton.DoGiveUp).ToFrameBytes()));

        Assert.Equal(firstBeforeGiveUp, firstSent.Count);
        Assert.Equal(secondBeforeGiveUp, secondSent.Count);

        await handler.HandleFrameAsync(
            second,
            ReadFrame(new MsgArenaSignupPacket(
                MsgArenaSignupDialogType.ArenaGui,
                MsgArenaSignupDialogButton.Accept).ToFrameBytes()));

        Assert.Equal(firstBeforeGiveUp + 4, firstSent.Count);
        Assert.Equal(secondBeforeGiveUp + 4, secondSent.Count);
        Assert.Equal(watcherBeforeGiveUp + 1, watcherSent.Count);
        AssertArenaInfoStatus(firstSent[firstBeforeGiveUp], MsgArenaInfoStatus.NotSignedUp);
        AssertArenaQualifierMessage(
            firstSent[firstBeforeGiveUp + 1],
            "Target has defeated HeroOne in the Qualifier, and is currently ranked No. 1.");
        AssertArenaSignupResponse(
            firstSent[firstBeforeGiveUp + 2],
            MsgArenaSignupDialogType.Dialog2,
            MsgArenaSignupDialogButton.SignUp,
            expectedUid: 1293600);
        AssertArenaResultInfo(
            firstSent[firstBeforeGiveUp + 3],
            minArenaPoints: 4251,
            maxArenaPoints: 4270,
            expectedTodayWin: 0,
            expectedTotalWin: 0,
            expectedTodayBattles: 1,
            expectedTotalLose: 1,
            expectedStatus: MsgArenaInfoStatus.NotSignedUp);
        AssertArenaInfoStatus(secondSent[secondBeforeGiveUp], MsgArenaInfoStatus.NotSignedUp);
        AssertArenaQualifierMessage(
            secondSent[secondBeforeGiveUp + 1],
            "Target has defeated HeroOne in the Qualifier, and is currently ranked No. 1.");
        AssertArenaSignupResponse(
            secondSent[secondBeforeGiveUp + 2],
            MsgArenaSignupDialogType.Dialog2,
            MsgArenaSignupDialogButton.Win,
            expectedUid: 400001);
        AssertArenaResultInfo(
            secondSent[secondBeforeGiveUp + 3],
            minArenaPoints: 4530,
            maxArenaPoints: 4549,
            expectedTodayWin: 1,
            expectedTotalWin: 1,
            expectedTodayBattles: 0,
            expectedTotalLose: 0,
            expectedStatus: MsgArenaInfoStatus.NotSignedUp);
        AssertArenaQualifierMessage(
            watcherSent[watcherBeforeGiveUp],
            "Target has defeated HeroOne in the Qualifier, and is currently ranked No. 1.");

        var firstBeforeQuery = firstSent.Count;
        await handler.HandleFrameAsync(
            first,
            ReadFrame(LegacyArenaMatchesPacket.Query(
                WorldPacketOpcodes.LegacyArenaMatches,
                page: 1).ToFrameBytes()));

        Assert.Equal(firstBeforeQuery + 1, firstSent.Count);
        Assert.True(LegacyArenaMatchesPacket.TryParse(ReadFrame(firstSent[firstBeforeQuery]), out var matches));
        Assert.Empty(matches.RegularEntries);
        Assert.Contains("declined pending Arena countdown", log.ToString());
    }

    [Fact]
    public async Task HandlerArenaAcceptImportsMatchedPlayersAndSendsOpponentFrames()
    {
        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(1293600, uid: 1293600, x: 830, y: 584);
        WriteSnapshot(400001, uid: 400001, x: 831, y: 584, name: "Target");
