        var firstTicket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        var secondTicket = handoff.Issue(400001, "target", ConquerRuntimeDefaults.WorldServer);
        var handler = new WorldServerFrameHandler(
            new CharacterSnapshotLoader(_usersRoot),
            handoff,
            new ArenaStatisticsProvider(
            [
                ArenaRecord(1293600, "HeroOne", points: 4300),
                ArenaRecord(400001, "Target", points: 4500),
            ]),
            log);
        var firstSent = new List<byte[]>();
        var secondSent = new List<byte[]>();
        var first = CreateSendingConnection(firstSent);
        var second = CreateSendingConnection(secondSent);
        var signup = new MsgArenaSignupPacket(
            MsgArenaSignupDialogType.ArenaIconOn,
            MsgArenaSignupDialogButton.SignUp);
        var accept = new MsgArenaSignupPacket(
            MsgArenaSignupDialogType.ArenaGui,
            MsgArenaSignupDialogButton.Accept);

        await handler.HandleFrameAsync(first, ReadFrame(new InternalWorldEnterRequestPacket(firstTicket.Token).ToFrameBytes()));
        await handler.HandleFrameAsync(second, ReadFrame(new InternalWorldEnterRequestPacket(secondTicket.Token).ToFrameBytes()));
        await handler.HandleFrameAsync(first, ReadFrame(signup.ToFrameBytes()));
        await handler.HandleFrameAsync(second, ReadFrame(signup.ToFrameBytes()));
        var firstBeforeAccept = firstSent.Count;
        var secondBeforeAccept = secondSent.Count;

        await handler.HandleFrameAsync(first, ReadFrame(accept.ToFrameBytes()));

        Assert.Equal(firstBeforeAccept, firstSent.Count);
        Assert.Equal(secondBeforeAccept, secondSent.Count);

        await handler.HandleFrameAsync(second, ReadFrame(accept.ToFrameBytes()));

        var firstResponses = firstSent.Skip(firstBeforeAccept).ToArray();
        var secondResponses = secondSent.Skip(secondBeforeAccept).ToArray();
        AssertArenaLocation(
