                firstResponses,
                MsgArenaSignupDialogType.StartTheFight,
                MsgArenaSignupDialogButton.SignUp,
                expectedUid: 400001),
            MsgArenaSignupDialogType.StartTheFight,
            MsgArenaSignupDialogButton.SignUp,
            expectedUid: 400001);
        AssertArenaSignupResponse(
            FindArenaSignupResponseFrame(
                firstResponses,
                MsgArenaSignupDialogType.Match,
                MsgArenaSignupDialogButton.MatchOn,
                expectedUid: 400001),
            MsgArenaSignupDialogType.Match,
            MsgArenaSignupDialogButton.MatchOn,
            expectedUid: 400001);
        AssertArenaMatchScore(FindArenaMatchScoreFrame(firstResponses));
        AssertArenaLocation(
            FindArenaLocationFrame(
                secondResponses,
                MsgActionType.Teleport,
                expectedUid: 400001,
                expectedMapId: 700,
                expectedX: 45,
                expectedY: 45),
            expectedUid: 400001,
            expectedMapId: 700,
            expectedX: 45,
            expectedY: 45,
            expectedType: MsgActionType.Teleport);
        AssertArenaSignupResponse(
            FindArenaSignupResponseFrame(
                secondResponses,
                MsgArenaSignupDialogType.StartTheFight,
                MsgArenaSignupDialogButton.SignUp,
                expectedUid: 1293600),
            MsgArenaSignupDialogType.StartTheFight,
            MsgArenaSignupDialogButton.SignUp,
            expectedUid: 1293600);
        AssertArenaSignupResponse(
            FindArenaSignupResponseFrame(
                secondResponses,
                MsgArenaSignupDialogType.Match,
                MsgArenaSignupDialogButton.MatchOn,
                expectedUid: 1293600),
            MsgArenaSignupDialogType.Match,
            MsgArenaSignupDialogButton.MatchOn,
            expectedUid: 1293600);
        AssertArenaMatchScore(FindArenaMatchScoreFrame(secondResponses));
        Assert.Contains("WorldServer sent Arena import frames", log.ToString());
    }

