    [Fact]
    public async Task HandlerArenaLethalCombatDamageUsesReturnedItemsForRegularArenaRewardWhenWinnerInventoryIsFull()
    {
        Directory.CreateDirectory(_usersRoot);
        var itemsRoot = Path.Combine(_usersRoot, "PlayersItems");
        Directory.CreateDirectory(itemsRoot);
        WriteSnapshot(1293600, uid: 1293600, x: 830, y: 584);
        WriteSnapshot(400001, uid: 400001, x: 831, y: 584, name: "Target");
        File.WriteAllBytes(
            Path.Combine(itemsRoot, "1293600.bin"),
            PlayerItemSnapshotLoaderTests.BuildPlayerItems(CreateFullInventoryItems(), []));
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var firstTicket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        var secondTicket = handoff.Issue(400001, "target", ConquerRuntimeDefaults.WorldServer);
        var worldData = MsgTeamRuntimeTests.CreateTeamArenaRewardCatalog();
        var handler = CreateArenaHandlerWithTerrain(
            new CharacterSnapshotLoader(_usersRoot, itemsRoot),
            handoff,
            new ArenaStatisticsProvider(
            [
                ArenaRecord(1293600, "HeroOne", points: 4300, todayWin: 9),
                ArenaRecord(400001, "Target", points: 4500),
            ]),
            worldData);
        var winnerSent = new List<byte[]>();
        var loserSent = new List<byte[]>();
        var winner = CreateSendingConnection(winnerSent);
        var loser = CreateSendingConnection(loserSent);
        var signup = new MsgArenaSignupPacket(
            MsgArenaSignupDialogType.ArenaIconOn,
            MsgArenaSignupDialogButton.SignUp);
        var accept = new MsgArenaSignupPacket(
            MsgArenaSignupDialogType.ArenaGui,
            MsgArenaSignupDialogButton.Accept);

        await handler.HandleFrameAsync(winner, ReadFrame(new InternalWorldEnterRequestPacket(firstTicket.Token).ToFrameBytes()));
        await handler.HandleFrameAsync(loser, ReadFrame(new InternalWorldEnterRequestPacket(secondTicket.Token).ToFrameBytes()));
        await handler.HandleFrameAsync(winner, ReadFrame(signup.ToFrameBytes()));
        await handler.HandleFrameAsync(loser, ReadFrame(signup.ToFrameBytes()));
        await handler.HandleFrameAsync(winner, ReadFrame(accept.ToFrameBytes()));
        await handler.HandleFrameAsync(loser, ReadFrame(accept.ToFrameBytes()));
        var winnerBeforeAttack = winnerSent.Count;

        await handler.HandleFrameAsync(
            winner,
            ReadFrame(new MsgAttackPacket(new MsgAttackQuery(
                Uid: 1293600,
                OpponentUid: 400001,
                X: 831,
                Y: 584,
                AttackType: MsgAttackType.Physical,
                Damage: 70_000,
                KilledMonster: 0,
                ResponseDamage: 0,
                Effect: MsgAttackEffect.None,
                Unknown: 0)).ToFrameBytes()));

        var attackResponses = winnerSent.Skip(winnerBeforeAttack).ToArray();
        AssertArenaRewardItem(
            FindArenaRewardItemFrame(attackResponses, LegacyGameItemPacket.AddItemReturnedMode),
            LegacyGameItemPacket.AddItemReturnedMode);

        var winnerBeforeWarehouseShow = winnerSent.Count;
        await handler.HandleFrameAsync(
            winner,
            ReadFrame(new LegacyWarehousePacket(
                65_535,
                LegacyWarehouseAction.Show,
                ItemUid: 0,
                Capacity: 0,
                Items: []).ToFrameBytes()));

        var warehouseResponses = winnerSent.Skip(winnerBeforeWarehouseShow).ToArray();
        var returnedItemsFrame = Assert.Single(
            warehouseResponses,
            bytes =>
                LegacyWarehousePacket.TryParse(ReadFrame(bytes), out var packet) &&
                packet.NpcId == 65_535U &&
                packet.Action == LegacyWarehouseAction.Show);
        Assert.True(LegacyWarehousePacket.TryParse(ReadFrame(returnedItemsFrame), out var returnedItems));
        Assert.Equal(65_535U, returnedItems.NpcId);
        Assert.Equal(LegacyWarehouseAction.Show, returnedItems.Action);
        var returnedItem = Assert.Single(returnedItems.Items);
        Assert.Equal(723_912U, returnedItem.ItemId);
    }

    [Fact]
    public async Task HandlerArenaWatcherRequestCheerAndQuitUsesRegularArenaMatch()
    {
        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(1293600, uid: 1293600, x: 830, y: 584);
        WriteSnapshot(400001, uid: 400001, x: 831, y: 584, name: "Target");
        WriteSnapshot(400002, uid: 400002, x: 832, y: 584, name: "Watcher");
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var firstTicket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        var secondTicket = handoff.Issue(400001, "target", ConquerRuntimeDefaults.WorldServer);
        var watcherTicket = handoff.Issue(400002, "watcher", ConquerRuntimeDefaults.WorldServer);
        var handler = new WorldServerFrameHandler(
            new CharacterSnapshotLoader(_usersRoot),
            handoff,
            new ArenaStatisticsProvider(
            [
                ArenaRecord(1293600, "HeroOne", points: 4300),
                ArenaRecord(400001, "Target", points: 4500),
                ArenaRecord(400002, "Watcher", points: 4200),
            ]));
        var firstSent = new List<byte[]>();
        var secondSent = new List<byte[]>();
        var watcherSent = new List<byte[]>();
        var first = CreateSendingConnection(firstSent);
        var second = CreateSendingConnection(secondSent);
        var watcher = CreateSendingConnection(watcherSent);
        var signup = new MsgArenaSignupPacket(
            MsgArenaSignupDialogType.ArenaIconOn,
            MsgArenaSignupDialogButton.SignUp);
        var accept = new MsgArenaSignupPacket(
            MsgArenaSignupDialogType.ArenaGui,
            MsgArenaSignupDialogButton.Accept);

        await handler.HandleFrameAsync(first, ReadFrame(new InternalWorldEnterRequestPacket(firstTicket.Token).ToFrameBytes()));
        await handler.HandleFrameAsync(second, ReadFrame(new InternalWorldEnterRequestPacket(secondTicket.Token).ToFrameBytes()));
        await handler.HandleFrameAsync(watcher, ReadFrame(new InternalWorldEnterRequestPacket(watcherTicket.Token).ToFrameBytes()));
        await handler.HandleFrameAsync(first, ReadFrame(signup.ToFrameBytes()));
        await handler.HandleFrameAsync(second, ReadFrame(signup.ToFrameBytes()));
        await handler.HandleFrameAsync(first, ReadFrame(accept.ToFrameBytes()));
        await handler.HandleFrameAsync(second, ReadFrame(accept.ToFrameBytes()));
        var firstBeforeBlockedWatch = firstSent.Count;
        var secondBeforeBlockedWatch = secondSent.Count;

        await handler.HandleFrameAsync(
            first,
            ReadFrame(LegacyArenaWatchersPacket.Query(
                LegacyArenaWatcherMode.RequestView,
                uid: 400001).ToFrameBytes()));

        Assert.Empty(firstSent.Skip(firstBeforeBlockedWatch));
        Assert.Empty(secondSent.Skip(secondBeforeBlockedWatch));
        var firstBeforeWatch = firstSent.Count;
        var secondBeforeWatch = secondSent.Count;
        var watcherBeforeWatch = watcherSent.Count;

        await handler.HandleFrameAsync(
            watcher,
            ReadFrame(LegacyArenaWatchersPacket.Query(
                LegacyArenaWatcherMode.RequestView,
                uid: 1293600).ToFrameBytes()));

        var firstWatchResponses = firstSent.Skip(firstBeforeWatch).ToArray();
        var secondWatchResponses = secondSent.Skip(secondBeforeWatch).ToArray();
        var watcherWatchResponses = watcherSent.Skip(watcherBeforeWatch).ToArray();
        AssertArenaLocationInRange(
            FindArenaLocationInRangeFrame(
                watcherWatchResponses,
                MsgActionType.Teleport,
                expectedUid: 400002,
                expectedMapId: 700,
                minX: 35,
                maxX: 69,
                minY: 35,
                maxY: 69),
            expectedUid: 400002,
            expectedMapId: 700,
            minX: 35,
            maxX: 69,
            minY: 35,
            maxY: 69,
            expectedType: MsgActionType.Teleport);
        AssertArenaWatcherHeader(
            FindArenaWatcherFrame(
                watcherWatchResponses,
                packet => packet.Mode == LegacyArenaWatcherMode.RequestView &&
                    packet.Count == 0 &&
                    packet.Entries.Count == 0),
            LegacyArenaWatcherMode.RequestView,
            expectedCount: 0);
        AssertArenaWatcherList(
            FindArenaWatcherFrame(
                watcherWatchResponses,
                packet => packet.Mode == LegacyArenaWatcherMode.Watchers &&
                    packet.Entries.Count == 1 &&
                    packet.Entries[0].Uid == 400002),
            expectedName: "Watcher",
            expectedUid: 400002);
        AssertArenaMatchScore(FindArenaMatchScoreFrame(watcherWatchResponses));
        AssertArenaWatcherList(
            FindArenaWatcherFrame(
                firstWatchResponses,
                packet => packet.Mode == LegacyArenaWatcherMode.Watchers &&
                    packet.Entries.Count == 1 &&
                    packet.Entries[0].Uid == 400002),
            expectedName: "Watcher",
            expectedUid: 400002);
        AssertArenaMatchScore(FindArenaMatchScoreFrame(firstWatchResponses));
        AssertArenaWatcherList(
            FindArenaWatcherFrame(
                secondWatchResponses,
                packet => packet.Mode == LegacyArenaWatcherMode.Watchers &&
                    packet.Entries.Count == 1 &&
                    packet.Entries[0].Uid == 400002),
            expectedName: "Watcher",
            expectedUid: 400002);
        AssertArenaMatchScore(FindArenaMatchScoreFrame(secondWatchResponses));
        var firstBeforeDuplicateWatch = firstSent.Count;
        var secondBeforeDuplicateWatch = secondSent.Count;
        var watcherBeforeDuplicateWatch = watcherSent.Count;

        await handler.HandleFrameAsync(
            watcher,
            ReadFrame(LegacyArenaWatchersPacket.Query(
                LegacyArenaWatcherMode.RequestView,
                uid: 1293600).ToFrameBytes()));

        Assert.Empty(firstSent.Skip(firstBeforeDuplicateWatch));
        Assert.Empty(secondSent.Skip(secondBeforeDuplicateWatch));
        Assert.Empty(watcherSent.Skip(watcherBeforeDuplicateWatch));
        var firstBeforeCheer = firstSent.Count;
        var secondBeforeCheer = secondSent.Count;
        var watcherBeforeCheer = watcherSent.Count;

        await handler.HandleFrameAsync(
            watcher,
            ReadFrame(LegacyArenaWatchersPacket.Query(
                LegacyArenaWatcherMode.Fighters,
                uid: 400001).ToFrameBytes()));

        var firstCheerResponses = firstSent.Skip(firstBeforeCheer).ToArray();
        var secondCheerResponses = secondSent.Skip(secondBeforeCheer).ToArray();
        var watcherCheerResponses = watcherSent.Skip(watcherBeforeCheer).ToArray();
        AssertArenaWatcherList(
            FindArenaWatcherFrame(
                watcherCheerResponses,
                packet => packet.Mode == LegacyArenaWatcherMode.Watchers &&
                    packet.Player1Cheers == 1 &&
                    packet.Entries.Count == 1 &&
                    packet.Entries[0].Uid == 400002),
            expectedName: "Watcher",
            expectedUid: 400002,
            expectedPlayer1Cheers: 1);
        AssertArenaMatchScore(FindArenaMatchScoreFrame(watcherCheerResponses));
        AssertArenaWatcherList(
            FindArenaWatcherFrame(
                firstCheerResponses,
                packet => packet.Mode == LegacyArenaWatcherMode.Watchers &&
                    packet.Player1Cheers == 1 &&
                    packet.Entries.Count == 1 &&
                    packet.Entries[0].Uid == 400002),
            expectedName: "Watcher",
            expectedUid: 400002,
            expectedPlayer1Cheers: 1);
        AssertArenaMatchScore(FindArenaMatchScoreFrame(firstCheerResponses));
        AssertArenaWatcherList(
            FindArenaWatcherFrame(
                secondCheerResponses,
                packet => packet.Mode == LegacyArenaWatcherMode.Watchers &&
                    packet.Player1Cheers == 1 &&
                    packet.Entries.Count == 1 &&
                    packet.Entries[0].Uid == 400002),
            expectedName: "Watcher",
            expectedUid: 400002,
            expectedPlayer1Cheers: 1);
        AssertArenaMatchScore(FindArenaMatchScoreFrame(secondCheerResponses));
        var watcherBeforeDuplicateCheer = watcherSent.Count;

        await handler.HandleFrameAsync(
            watcher,
            ReadFrame(LegacyArenaWatchersPacket.Query(
                LegacyArenaWatcherMode.Fighters,
                uid: 400001).ToFrameBytes()));

        Assert.Empty(watcherSent.Skip(watcherBeforeDuplicateCheer));
        var firstBeforeQuit = firstSent.Count;
        var secondBeforeQuit = secondSent.Count;
        var watcherBeforeQuit = watcherSent.Count;

        await handler.HandleFrameAsync(
            watcher,
            ReadFrame(LegacyArenaWatchersPacket.Query(
                LegacyArenaWatcherMode.QuitButton,
                uid: 0).ToFrameBytes()));

        var firstQuitResponses = firstSent.Skip(firstBeforeQuit).ToArray();
        var secondQuitResponses = secondSent.Skip(secondBeforeQuit).ToArray();
        var watcherQuitResponses = watcherSent.Skip(watcherBeforeQuit).ToArray();
        AssertArenaWatcherHeader(
            FindArenaWatcherFrame(
                firstQuitResponses,
                packet => packet.Mode == LegacyArenaWatcherMode.Watchers &&
                    packet.Count == 0 &&
                    packet.Entries.Count == 0),
            LegacyArenaWatcherMode.Watchers,
            expectedCount: 0);
        AssertArenaWatcherHeader(
            FindArenaWatcherFrame(
                secondQuitResponses,
                packet => packet.Mode == LegacyArenaWatcherMode.Watchers &&
                    packet.Count == 0 &&
                    packet.Entries.Count == 0),
            LegacyArenaWatcherMode.Watchers,
            expectedCount: 0);
        AssertArenaMatchScore(FindArenaMatchScoreFrame(firstQuitResponses));
        AssertArenaMatchScore(FindArenaMatchScoreFrame(secondQuitResponses));
        var leaveFrames = watcherQuitResponses
            .Where(bytes =>
                LegacyArenaWatchersPacket.TryParse(ReadFrame(bytes), out var packet) &&
                packet.Mode == LegacyArenaWatcherMode.Leave &&
                packet.Count == 0 &&
                packet.Entries.Count == 0)
            .ToArray();
        Assert.Equal(2, leaveFrames.Length);
        foreach (var leaveFrame in leaveFrames)
        {
            AssertArenaWatcherHeader(leaveFrame, LegacyArenaWatcherMode.Leave, expectedCount: 0);
        }
        AssertArenaLocation(
            FindArenaLocationFrame(
                watcherQuitResponses,
                MsgActionType.SetLocation,
                expectedUid: 400002,
                expectedMapId: 1015,
                expectedX: 832,
                expectedY: 584),
            expectedUid: 400002,
            expectedMapId: 1015,
            expectedX: 832,
            expectedY: 584);
    }

