    [Theory]
    [InlineData(WorldSnapshotWireStatus.UnknownTicket)]
    [InlineData(WorldSnapshotWireStatus.ExpiredTicket)]
    [InlineData(WorldSnapshotWireStatus.AlreadyRedeemedTicket)]
    [InlineData(WorldSnapshotWireStatus.MissingSnapshot)]
    [InlineData(WorldSnapshotWireStatus.SnapshotError)]
    [InlineData(WorldSnapshotWireStatus.SnapshotsUnavailable)]
    public async Task HandlerDoesNotCreateSessionAfterFailedWorldEnter(WorldSnapshotWireStatus failedStatus)
    {
        Directory.CreateDirectory(_usersRoot);
        using var log = new StringWriter();
        var sent = new List<byte[]>();
        var connection = CreateSendingConnection(sent);
        var frame = CreateFailedWorldEnterFrame(failedStatus, out var handler);

        await handler.HandleFrameAsync(connection, frame);
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new MsgTeamPacket(MsgTeamType.InviteRequest, 400_001).ToFrameBytes()));

        AssertResponse(sent.Single(), failedStatus, failedStatus == WorldSnapshotWireStatus.UnknownTicket ? 0 : 1293600);
        var output = log.ToString();
        Assert.Contains("WorldServer handled MsgTeam", output);
        Assert.Contains("session=none", output);
        Assert.DoesNotContain("session=accountId=1293600", output);

        PacketFrame CreateFailedWorldEnterFrame(
            WorldSnapshotWireStatus status,
            out WorldServerFrameHandler failedHandler)
        {
            var now = new DateTimeOffset(2026, 6, 2, 12, 0, 0, TimeSpan.Zero);
            var store = new InMemoryAccountHandoffTicketStore();
            var handoff = new AccountHandoffService(store, () => now, TimeSpan.FromSeconds(1));
            var loader = new CharacterSnapshotLoader(_usersRoot);
            var ticketToken = "missing-ticket";

            if (status != WorldSnapshotWireStatus.UnknownTicket)
            {
                if (status is not WorldSnapshotWireStatus.MissingSnapshot and not WorldSnapshotWireStatus.SnapshotsUnavailable)
                {
                    WriteSnapshot(1293600, status == WorldSnapshotWireStatus.SnapshotError ? 999 : 1293600);
                }

                var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
                ticketToken = ticket.Token;

                if (status == WorldSnapshotWireStatus.ExpiredTicket)
                {
                    now = now.AddSeconds(2);
                }
                else if (status == WorldSnapshotWireStatus.AlreadyRedeemedTicket)
                {
                    _ = handoff.Redeem(ticket.Token);
                }
            }

            failedHandler = new WorldServerFrameHandler(
                status == WorldSnapshotWireStatus.SnapshotsUnavailable ? null : loader,
                handoff,
                log);
            return ReadFrame(new InternalWorldEnterRequestPacket(ticketToken).ToFrameBytes());
        }
    }

