                SkinType: 0,
                OK: false).ToFrameBytes()));

        var firstResponses = sent.Skip(firstRequestStart).ToArray();
        Assert.Equal(4, firstResponses.Length);
        for (var index = 0; index < 3; index++)
        {
            Assert.True(LegacyDragonSkinPacket.TryParse(ReadFrame(firstResponses[index]), out var unlock));
            Assert.Equal(LegacyDragonSkinType.Unlock, unlock.Type);
            Assert.Equal(1_293_600U, unlock.UserID);
            Assert.Equal((uint)(index + 1), unlock.SkinType);
            Assert.True(unlock.OK);
        }

        Assert.True(LegacyDragonSkinPacket.TryParse(ReadFrame(firstResponses[3]), out var myShow));
        Assert.Equal(LegacyDragonSkinType.MyShow, myShow.Type);
        Assert.Equal(1_293_600U, myShow.UserID);
        Assert.Equal(3U, myShow.SkinType);
        Assert.False(myShow.OK);

        var repeatStart = sent.Count;
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new LegacyDragonSkinPacket(
                LegacyDragonSkinType.MyShow,
                UserID: 1_293_600,
                SkinType: 0,
                OK: false).ToFrameBytes()));

        var repeatResponse = Assert.Single(sent.Skip(repeatStart));
        Assert.True(LegacyDragonSkinPacket.TryParse(ReadFrame(repeatResponse), out var repeatShow));
        Assert.Equal(LegacyDragonSkinType.MyShow, repeatShow.Type);
        Assert.Equal(3U, repeatShow.SkinType);

        var viewStart = sent.Count;
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new LegacyDragonSkinPacket(
                LegacyDragonSkinType.PlayerView,
                UserID: 1_293_600,
                SkinType: 0,
                OK: false).ToFrameBytes()));

        var viewResponse = Assert.Single(sent.Skip(viewStart));
        Assert.True(LegacyDragonSkinPacket.TryParse(ReadFrame(viewResponse), out var playerView));
        Assert.Equal(LegacyDragonSkinType.PlayerView, playerView.Type);
        Assert.Equal(1_293_600U, playerView.UserID);
        Assert.Equal(3U, playerView.SkinType);

        var selfViewStart = sent.Count;
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new LegacyDragonSkinPacket(
                LegacyDragonSkinType.PlayerView,
                UserID: 0,
                SkinType: 0,
                OK: false).ToFrameBytes()));

        var selfViewResponse = Assert.Single(sent.Skip(selfViewStart));
        Assert.True(LegacyDragonSkinPacket.TryParse(ReadFrame(selfViewResponse), out var selfView));
        Assert.Equal(LegacyDragonSkinType.PlayerView, selfView.Type);
        Assert.Equal(1_293_600U, selfView.UserID);
        Assert.Equal(3U, selfView.SkinType);

        var output = log.ToString();
        Assert.Contains("WorldServer sent LegacyDragonSkin MyShow", output);
        Assert.Contains("unlocks=3", output);
        Assert.Contains("unlocks=0", output);
        Assert.DoesNotContain("WorldServer received opcode 2415", output);
    }

