        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));

        var effectStart = sent.Count;
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new LegacyDragonSkinPacket(
                LegacyDragonSkinType.Effect,
                UserID: 1_293_600,
                SkinType: 2,
                OK: true).ToFrameBytes()));

        Assert.Equal(effectStart, sent.Count);

