    [Fact]
    public async Task HandlerRespondsToLegacyGenericRankingQueryAfterWorldEnter()
    {
        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(1293600, uid: 1293600);
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        using var log = new StringWriter();
        var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot), handoff, log);
        var sent = new List<byte[]>();
        var connection = CreateSendingConnection(sent);

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));

        var queryStart = sent.Count;
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new LegacyGenericRankingPacket(
                LegacyGenericRankingAction.QueryCount,
                LegacyGenericRankingRankType.DragonChi,
                RegisteredCount: 0,
                Page: 0,
                Finish: 0,
                Count: 0,
                Reserved: 0,
                Entries: []).ToFrameBytes()));

        var responseBytes = Assert.Single(sent.Skip(queryStart));
        Assert.True(LegacyGenericRankingPacket.TryParse(ReadFrame(responseBytes), out var ranking));
        Assert.Equal(LegacyGenericRankingAction.QueryCount, ranking.Action);
        Assert.Equal(LegacyGenericRankingRankType.DragonChi, ranking.RankType);
        var entry = Assert.Single(ranking.Entries);
        Assert.Equal(400, entry.Amount);
        Assert.Equal(1_293_600U, entry.Uid);
        Assert.Equal("HeroOne", entry.Name);

        var noneStart = sent.Count;
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new LegacyGenericRankingPacket(
                LegacyGenericRankingAction.QueryCount,
                LegacyGenericRankingRankType.None,
                RegisteredCount: 0,
                Page: 0,
                Finish: 0,
                Count: 0,
                Reserved: 0,
                Entries: []).ToFrameBytes()));

        var noneBytes = Assert.Single(sent.Skip(noneStart));
        Assert.True(LegacyGenericRankingPacket.TryParse(ReadFrame(noneBytes), out var noneRanking));
        Assert.Equal(LegacyGenericRankingAction.QueryCount, noneRanking.Action);
        Assert.Equal(LegacyGenericRankingRankType.None, noneRanking.RankType);
        Assert.Equal(1, noneRanking.Finish);
        Assert.Equal(0, noneRanking.Count);
        Assert.Empty(noneRanking.Entries);

        var unknownRankType = (LegacyGenericRankingRankType)80_000_000u;
        var unknownStart = sent.Count;
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new LegacyGenericRankingPacket(
                LegacyGenericRankingAction.QueryCount,
                unknownRankType,
                RegisteredCount: 0,
                Page: 0,
                Finish: 0,
                Count: 0,
                Reserved: 0,
                Entries: []).ToFrameBytes()));

        var unknownBytes = Assert.Single(sent.Skip(unknownStart));
        Assert.True(LegacyGenericRankingPacket.TryParse(ReadFrame(unknownBytes), out var unknownRanking));
        Assert.Equal(LegacyGenericRankingAction.QueryCount, unknownRanking.Action);
        Assert.Equal(unknownRankType, unknownRanking.RankType);
        Assert.Equal(1, unknownRanking.Finish);
        Assert.Equal(0, unknownRanking.Count);
        Assert.Empty(unknownRanking.Entries);

        var prestigeRankType = (LegacyGenericRankingRankType)140_000_006u;
        var prestigeStart = sent.Count;
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new LegacyGenericRankingPacket(
                LegacyGenericRankingAction.PrestigeRanks,
                prestigeRankType,
                RegisteredCount: 0,
                Page: 0,
                Finish: 0,
                Count: 0,
                Reserved: 0,
                Entries: []).ToFrameBytes()));

        var prestigeBytes = Assert.Single(sent.Skip(prestigeStart));
        Assert.True(LegacyGenericRankingPacket.TryParse(ReadFrame(prestigeBytes), out var prestigeRanking));
        Assert.Equal(LegacyGenericRankingAction.PrestigeRanks, prestigeRanking.Action);
        Assert.Equal(prestigeRankType, prestigeRanking.RankType);
        Assert.Equal(1, prestigeRanking.Finish);
        Assert.Equal(0, prestigeRanking.Count);
        Assert.Empty(prestigeRanking.Entries);

        async Task AssertEmptyLegacyGenericRankingResponse(
            LegacyGenericRankingAction action,
            LegacyGenericRankingRankType rankType,
            byte page)
        {
            var start = sent.Count;
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new LegacyGenericRankingPacket(
                    action,
                    rankType,
                    RegisteredCount: 0,
                    Page: page,
                    Finish: 0,
                    Count: 0,
                    Reserved: 0,
                    Entries: []).ToFrameBytes()));

            var bytes = Assert.Single(sent.Skip(start));
            Assert.True(LegacyGenericRankingPacket.TryParse(ReadFrame(bytes), out var emptyRanking));
            Assert.Equal(action, emptyRanking.Action);
            Assert.Equal(rankType, emptyRanking.RankType);
            Assert.Equal(0, emptyRanking.RegisteredCount);
            Assert.Equal(page, emptyRanking.Page);
            Assert.Equal(1, emptyRanking.Finish);
            Assert.Equal(0, emptyRanking.Count);
            Assert.Empty(emptyRanking.Entries);
        }

        foreach (var (action, rankType, page) in new (LegacyGenericRankingAction, LegacyGenericRankingRankType, byte)[]
        {
            (LegacyGenericRankingAction.QueryCount, (LegacyGenericRankingRankType)180_000_000u, 0),
            (LegacyGenericRankingAction.Ranking, (LegacyGenericRankingRankType)180_000_000u, 1),
            (LegacyGenericRankingAction.PrestigeRanks, LegacyGenericRankingRankType.None, 0),
            (LegacyGenericRankingAction.Ranking, (LegacyGenericRankingRankType)70_000_000u, 2),
            (LegacyGenericRankingAction.QueryCount, (LegacyGenericRankingRankType)70_000_000u, 0),
            (LegacyGenericRankingAction.QueryCount, (LegacyGenericRankingRankType)140_000_006u, 0),
        })
        {
            await AssertEmptyLegacyGenericRankingResponse(action, rankType, page);
        }

        foreach (var action in new[]
        {
            LegacyGenericRankingAction.UpdateScreen,
            LegacyGenericRankingAction.InformationRequest,
        })
        {
            var silentStart = sent.Count;
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new LegacyGenericRankingPacket(
                    action,
                    (LegacyGenericRankingRankType)70_000_000u,
                    RegisteredCount: 0,
                    Page: 0,
                    Finish: 0,
                    Count: 0,
                    Reserved: 0,
                    Entries: []).ToFrameBytes()));

            Assert.Empty(sent.Skip(silentStart));
        }

        var output = log.ToString();
        Assert.Contains("WorldServer handled LegacyGenericRanking", output);
        Assert.Contains("rankType=DragonChi", output);
        Assert.Contains("entries=0", output);
        Assert.Contains("action=UpdateScreen rankType=70000000; source has no inbound response.", output);
        Assert.Contains("action=InformationRequest rankType=70000000; source has no inbound response.", output);
        Assert.DoesNotContain("action is not modeled", output);
        Assert.DoesNotContain("Chi power is not modeled", output);
        Assert.DoesNotContain("WorldServer received opcode 2165", output);
    }

