            var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(usersRoot), handoff, log);
            var sent = new List<byte[]>();
            var connection = CreateSendingConnection(sent);

            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));

            var queryStart = sent.Count;
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(LegacyGuildProcessPacket.Create(
                    LegacyGuildProcessAction.Requirements,
                    uid: 1370,
                    args: [0, 123_456, 6_543, 1 + 0x100]).ToFrameBytes()));

            Assert.Empty(sent.Skip(queryStart));

            queryStart = sent.Count;
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(LegacyGuildProcessPacket.Create(LegacyGuildProcessAction.Show, uid: 1370).ToFrameBytes()));

            var responses = sent.Skip(queryStart).ToArray();
            Assert.Equal(2, responses.Length);
            var info = Assert.Single(responses, response => LegacyGuildInformationPacket.TryParse(ReadFrame(response), out _));
            Assert.True(LegacyGuildInformationPacket.TryParse(ReadFrame(info), out var parsed));
            Assert.Equal(123_456U, parsed.RecruitmentBattlePower);
            Assert.Equal(6_543U, parsed.RecruitmentFlag);
            Assert.True(parsed.RecruitmentOn);
            Assert.True(parsed.RecruitmentOff);

            var reloaded = new CharacterSnapshotLoader(usersRoot).LoadByAccountId(1293600);
            Assert.NotNull(reloaded);
            Assert.Equal("123456", reloaded.Attributes["GuildRecruitmentBattlePower"]);
            Assert.Equal("6543", reloaded.Attributes["GuildRecruitmentFlag"]);
            Assert.Equal("1", reloaded.Attributes["GuildRecruitmentON"]);
            Assert.Equal("1", reloaded.Attributes["GuildRecruitmentOFF"]);
            var guildFile = File.ReadAllText(guildPath);
            Assert.Contains("/6543/123456/1/1/", guildFile);

            var output = log.ToString();
            Assert.Contains("WorldServer handled LegacyGuildProcess Requirements", output);
            Assert.Contains("action=Requirements", output);
            Assert.Contains("WorldServer persisted LegacyGuildProcess Requirements character", output);
            Assert.Contains("WorldServer persisted LegacyGuildProcess Requirements guild", output);
            Assert.Contains("WorldServer handled LegacyGuildProcess Show", output);
            Assert.DoesNotContain("WorldServer deferred LegacyGuildProcess action", output);
            Assert.DoesNotContain("WorldServer received opcode 2167", output);
        }
        finally
        {
            if (Directory.Exists(dbRoot))
            {
                Directory.Delete(dbRoot, recursive: true);
            }
        }
    }

    [Theory]
    [InlineData(LegacyGuildProcessAction.Create)]
    [InlineData(LegacyGuildProcessAction.Accept)]
    [InlineData(LegacyGuildProcessAction.Invite)]
    [InlineData(LegacyGuildProcessAction.Join)]
    [InlineData(LegacyGuildProcessAction.Quit)]
    [InlineData(LegacyGuildProcessAction.Disband)]
    [InlineData(LegacyGuildProcessAction.Promote)]
    [InlineData(LegacyGuildProcessAction.Appoint)]
    [InlineData(LegacyGuildProcessAction.Resign)]
    [InlineData(LegacyGuildProcessAction.Allied)]
    [InlineData(LegacyGuildProcessAction.RemoveAlly)]
    [InlineData(LegacyGuildProcessAction.Enemy)]
    [InlineData(LegacyGuildProcessAction.RemoveEnemy)]
    [InlineData(LegacyGuildProcessAction.RequestPromote)]
    [InlineData(LegacyGuildProcessAction.RequestAllied)]
    [InlineData(LegacyGuildProcessAction.Retire)]
    public async Task HandlerSkipsLegacyGuildProcessMutatingActionsAfterWorldEnter(
        LegacyGuildProcessAction action)
    {
        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(1293600, uid: 1293600, guildId: 1370);
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        using var log = new StringWriter();
        var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot), handoff, log);
        var sent = new List<byte[]>();
        var connection = CreateSendingConnection(sent);

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));

        var queryStart = sent.Count;
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(LegacyGuildProcessPacket.Create(
                action,
                uid: 1370,
                strings: action == LegacyGuildProcessAction.Create
                    ? ["QueuedGuild"]
                    : []).ToFrameBytes()));

        Assert.Empty(sent.Skip(queryStart));
        var output = log.ToString();
        Assert.Contains("WorldServer skipped LegacyGuildProcess", output);
        Assert.Contains($"action={action}", output);
        Assert.DoesNotContain("WorldServer deferred LegacyGuildProcess action", output);
        Assert.Contains("uid=1370", output);
        Assert.DoesNotContain("WorldServer received opcode 2167", output);
    }

