    [Fact(Skip = "Requires external game fixtures omitted from the public source snapshot.")]
    public async Task HandlerAppliesMonsterCombatDamageAfterWorldEnter()
    {
        var seedPath = Path.Combine(FindRepositoryRoot(), ".setup_work", "seed-json");
        if (!File.Exists(Path.Combine(seedPath, "manifest.json")))
        {
            return;
        }

        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(1293600, uid: 1293600, mapId: 1015, x: 830, y: 584);
        var worldData = await new JsonWorldDataLoader(new WorldDataOptions(seedPath)).LoadAsync();
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        using var log = new StringWriter();
        var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot), handoff, worldData, log);
        var sent = new List<byte[]>();
        var connection = CreateSendingConnection(sent);

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new MsgActionPacket
            {
                ObjId = 1_293_600,
                Timestamp = 1234,
                Type = MsgActionType.SetLocation,
            }.ToFrameBytes()));

        var monster = sent.ToArray()
            .Select(bytes => LegacyMonsterSpawnPacket.TryParse(ReadFrame(bytes), out var parsed) ? parsed : null)
            .FirstOrDefault(packet => packet is not null);
        Assert.NotNull(monster);

        var attackStart = sent.Count;
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new MsgAttackPacket(new MsgAttackQuery(
                Uid: 1_293_600,
                OpponentUid: monster.Uid,
                X: monster.X,
                Y: monster.Y,
                AttackType: MsgAttackType.Physical,
                Damage: checked((int)monster.MaxLife),
                KilledMonster: 0,
                ResponseDamage: 0,
                Effect: MsgAttackEffect.None,
                Unknown: 0)).ToFrameBytes()));

        Assert.True(MsgAttackPacket.TryParse(ReadFrame(sent[attackStart]), out var response));
        Assert.Equal(monster.Uid, response.Query.OpponentUid);
        Assert.Equal(monster.X, response.Query.X);
        Assert.Equal(monster.Y, response.Query.Y);
        Assert.Equal(MsgAttackType.Physical, response.Query.AttackType);
        Assert.Equal(0, response.Query.KilledMonster);
        Assert.Equal(0U, response.Query.ResponseDamage);

        Assert.True(MsgAttackPacket.TryParse(ReadFrame(sent[attackStart + 1]), out var death));
        Assert.Equal(1_293_600U, death.Query.Uid);
        Assert.Equal(monster.Uid, death.Query.OpponentUid);
        Assert.Equal(monster.X, death.Query.X);
        Assert.Equal(monster.Y, death.Query.Y);
        Assert.Equal(MsgAttackType.Death, death.Query.AttackType);
        Assert.Equal(0, death.Query.Damage);
        Assert.Equal(1, death.Query.KilledMonster);
        Assert.Equal(0U, death.Query.ResponseDamage);

        var deadAttackStart = sent.Count;
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new MsgAttackPacket(new MsgAttackQuery(
                Uid: 1_293_600,
                OpponentUid: monster.Uid,
                X: monster.X,
                Y: monster.Y,
                AttackType: MsgAttackType.Physical,
                Damage: 1,
                KilledMonster: 0,
                ResponseDamage: 0,
                Effect: MsgAttackEffect.None,
                Unknown: 0)).ToFrameBytes()));

        Assert.DoesNotContain(
            sent.Skip(deadAttackStart),
            frame => MsgAttackPacket.TryParse(ReadFrame(frame), out var packet) &&
                packet.Query.OpponentUid == monster.Uid);
        var output = log.ToString();
        Assert.Contains("WorldServer handled monster combat", output);
        Assert.Contains($"monsterUid={monster.Uid}", output);
        Assert.Contains("killed=True", output);
    }

    [Fact(Skip = "Requires external game fixtures omitted from the public source snapshot.")]
    public async Task HandlerMonsterPhysicalCombatUsesRuntimeVisibleMonsterPosition()
    {
        var seedPath = Path.Combine(FindRepositoryRoot(), ".setup_work", "seed-json");
        if (!File.Exists(Path.Combine(seedPath, "manifest.json")))
        {
            return;
        }

        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(
            1293600,
            uid: 1293600,
            mapId: 1015,
            x: 839,
            y: 573,
            extraCharacterLines: DisableLegacyWeaponProcLines);
        var worldData = await new JsonWorldDataLoader(new WorldDataOptions(seedPath)).LoadAsync();
        var monsterInstance = FindVisibleMonster(worldData, mapId: 1015, name: "Birdman", x: 837, y: 573);
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        using var log = new StringWriter();
        var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot), handoff, worldData, log);
        var sent = new List<byte[]>();
        var connection = CreateSendingConnection(sent);

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new MsgActionPacket
            {
                ObjId = 1_293_600,
                Timestamp = 1234,
                Type = MsgActionType.SetLocation,
            }.ToFrameBytes()));

        var monsterStates = GetMonsterStates(handler);
        Assert.True(monsterStates.TryMoveTowardTarget(
            monsterInstance,
            targetX: 839,
            targetY: 573,
            DateTimeOffset.UtcNow,
            TimeSpan.Zero,
            out var movedMonster,
            out _));
        Assert.Equal(838, movedMonster.X);
        Assert.Equal(573, movedMonster.Y);

        var attackStart = sent.Count;
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new MsgAttackPacket(new MsgAttackQuery(
                Uid: 1_293_600,
                OpponentUid: monsterInstance.Uid,
                X: movedMonster.X,
                Y: movedMonster.Y,
                AttackType: MsgAttackType.Physical,
                Damage: 1,
                KilledMonster: 0,
                ResponseDamage: 0,
                Effect: MsgAttackEffect.None,
                Unknown: 0)).ToFrameBytes()));

        await WaitUntilAsync(
            () => sent.Count > attackStart + 1 &&
                MsgAttackPacket.TryParse(ReadFrame(sent[attackStart]), out _) &&
                MsgAttackPacket.TryParse(ReadFrame(sent[attackStart + 1]), out _),
            TimeSpan.FromSeconds(10));
        Assert.True(MsgAttackPacket.TryParse(ReadFrame(sent[attackStart]), out var response));
        Assert.Equal(monsterInstance.Uid, response.Query.OpponentUid);
        Assert.Equal(movedMonster.X, response.Query.X);
        Assert.Equal(movedMonster.Y, response.Query.Y);
        Assert.Equal(MsgAttackType.Physical, response.Query.AttackType);
        Assert.Contains("WorldServer handled monster combat", log.ToString());
    }

    [Fact]
    public async Task HandlerMonsterPhysicalCombatAllowsNormalHighHitpointMonsterInPeaceMode()
    {
        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(
            1293600,
            uid: 1293600,
            mapId: 1015,
            x: 197,
            y: 230,
            extraCharacterLines: "PkMode=1");
        var monsterFamily = new Monster(
            901,
            "TrainingMonster",
            new Dictionary<string, string>
            {
                ["life"] = "70000",
                ["lookface"] = "901",
                ["level"] = "80",
                ["defense"] = "0",
                ["defense2"] = "10000",
                ["attack_range"] = "3",
            },
            []);
        var spawn = new MonsterSpawn(
            GeneratorId: 3,
            MapId: 1015,
            MonsterTypeId: 901,
            BoundX: 197,
            BoundY: 230,
            BoundWidth: 1,
            BoundHeight: 1,
            MaxNpc: 1,
            RestSeconds: 10,
            MaxPerGenerator: 1,
            TimerBegin: 0,
            TimerEnd: 0,
            BornX: 0,
            BornY: 0,
            SourceMapFolderId: 1015,
            SourceMonsterName: "TrainingMonster",
            SourceRelativePath: Path.Combine("1015", "TrainingMonster", "1.ini"),
            Attributes: new Dictionary<string, string>
            {
                ["id"] = "3",
                ["mapid"] = "1015",
                ["npctype"] = "901",
            });
        var worldData = MsgTeamRuntimeTests.CreateTeamArenaRewardCatalog(
            monsters: [monsterFamily],
            monsterSpawns: [spawn]);
        var monster = Assert.Single(LegacyMonsterInstance.FromGenerator(
            spawn,
            monsterFamily,
            worldData.GetLegacyMonsterRuntimeUidBase(spawn)));
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        using var log = new StringWriter();
        var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot), handoff, worldData, log);
        var sent = new List<byte[]>();
        var connection = CreateSendingConnection(sent);

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));
        var setLocationStart = sent.Count;
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new MsgActionPacket
            {
                ObjId = 1_293_600,
                Timestamp = 1234,
                Type = MsgActionType.SetLocation,
            }.ToFrameBytes()));

        var spawnIndex = FindFrameIndexAfter(
            sent,
            setLocationStart,
            frame =>
                LegacyMonsterSpawnPacket.TryParse(frame, out var parsed) &&
                parsed.Uid == monster.Uid);
        Assert.True(spawnIndex >= 0, $"Expected high-hitpoint normal monster spawn. Log={log}");
        Assert.True(LegacyMonsterSpawnPacket.TryParse(ReadFrame(sent[spawnIndex]), out var spawnPacket));
        Assert.False(spawnPacket.Boss);
        Assert.Equal(70_000U, spawnPacket.MaxLife);

        Assert.True(LegacyMsgUpdatePacket.TryParse(ReadFrame(sent[spawnIndex + 1]), out var maxHitpointsOnly));
        Assert.Equal(monster.Uid, maxHitpointsOnly.Uid);
        Assert.Equal(
            [new LegacyMsgUpdateEntry(LegacyMsgUpdateDataType.MaxHitpoints, 70_000)],
            maxHitpointsOnly.Updates);
        Assert.True(LegacyMsgUpdatePacket.TryParse(ReadFrame(sent[spawnIndex + 2]), out var hitpointPair));
        Assert.Equal(monster.Uid, hitpointPair.Uid);
        Assert.Equal(
            [
                new LegacyMsgUpdateEntry(LegacyMsgUpdateDataType.MaxHitpoints, 70_000),
                new LegacyMsgUpdateEntry(LegacyMsgUpdateDataType.Hitpoints, 70_000),
            ],
            hitpointPair.Updates);

        var attackStart = sent.Count;
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new MsgAttackPacket(new MsgAttackQuery(
                Uid: 1_293_600,
                OpponentUid: monster.Uid,
                X: monster.X,
                Y: monster.Y,
                AttackType: MsgAttackType.Physical,
                Damage: 500,
                KilledMonster: 0,
                ResponseDamage: 0,
                Effect: MsgAttackEffect.None,
                Unknown: 0)).ToFrameBytes()));

        Assert.True(MsgAttackPacket.TryParse(ReadFrame(sent[attackStart]), out var response));
        Assert.Equal(monster.Uid, response.Query.OpponentUid);
        Assert.Equal(monster.X, response.Query.X);
        Assert.Equal(monster.Y, response.Query.Y);
        Assert.Equal(MsgAttackType.Physical, response.Query.AttackType);
        Assert.True(response.Query.Damage > 0);
        var output = log.ToString();
        Assert.Contains("WorldServer handled monster combat", output);
        Assert.DoesNotContain("CanAttackMonster.Verified rejected Guard monster family", output);
        Assert.DoesNotContain("WorldServer applied legacy guard attack flashing-name", output);
    }

