        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new MsgActionPacket
            {
                ObjId = 1_293_600,
                Timestamp = 1234,
                Type = MsgActionType.SetLocation,
            }.ToFrameBytes()));

        var blockedStart = sent.Count;
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new MsgAttackPacket(new MsgAttackQuery(
                Uid: 1_293_600,
                OpponentUid: guard.Uid,
                X: guard.X,
                Y: guard.Y,
                AttackType: MsgAttackType.Physical,
                Damage: 500,
                KilledMonster: 0,
                ResponseDamage: 0,
                Effect: MsgAttackEffect.None,
                Unknown: 0)).ToFrameBytes()));

        Assert.Equal(blockedStart, sent.Count);
        Assert.Contains("CanAttackMonster.Verified rejected Guard monster family because pkMode=1", log.ToString());

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new MsgActionPacket
            {
                ObjId = 1_293_600,
                Timestamp = 5678,
                Type = MsgActionType.SetPkMode,
                DwParam = 0,
            }.ToFrameBytes()));

        var acceptedStart = sent.Count;
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new MsgAttackPacket(new MsgAttackQuery(
                Uid: 1_293_600,
                OpponentUid: guard.Uid,
                X: guard.X,
                Y: guard.Y,
                AttackType: MsgAttackType.Physical,
                Damage: 500,
                KilledMonster: 0,
                ResponseDamage: 0,
                Effect: MsgAttackEffect.None,
                Unknown: 0)).ToFrameBytes()));

        Assert.Contains(
            sent.Skip(acceptedStart),
            bytes =>
                MsgAttackPacket.TryParse(ReadFrame(bytes), out var response) &&
                response.Query.OpponentUid == guard.Uid &&
                response.Query.AttackType == MsgAttackType.Physical &&
                response.Query.Damage > 0);
        var updated = GetSession(handler, connection);
        Assert.True(HasLegacyStatusFlag(updated.Character.Attributes["StatusFlags"], FlashingNameFlag));
        Assert.Contains(
            sent.Skip(acceptedStart),
            bytes =>
                LegacyMsgUpdatePacket.TryParse(ReadFrame(bytes), out var update) &&
                update.Uid == 1_293_600U &&
                update.Updates.Any(entry =>
                    entry.Type == LegacyMsgUpdateDataType.StatusFlag &&
                    entry.Values is not null &&
                    HasLegacyStatusFlag(entry.Values, FlashingNameFlag)));
        Assert.Contains("WorldServer applied legacy guard attack flashing-name", log.ToString());
        Assert.Contains("WorldServer handled monster combat", log.ToString());
    }

