    [Fact(Skip = "Requires external game fixtures omitted from the public source snapshot.")]
    public async Task HandlerUsesLoadedGearToRaiseMonsterCombatDamage()
    {
        var seedPath = Path.Combine(FindRepositoryRoot(), ".setup_work", "seed-json");
        var playerItemsRoot = @"data/DBServer\PlayersItems";
        if (!File.Exists(Path.Combine(seedPath, "manifest.json")) ||
            !File.Exists(Path.Combine(playerItemsRoot, "1293600.bin")))
        {
            return;
        }

        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(
            1293600,
            uid: 1293600,
            mapId: 1015,
            x: 837,
            y: 573,
            extraCharacterLines:
                "LegacyMonsterDodgeRoll=149\r\n" +
                "LegacyMonsterDodgeSecondaryRoll=149\r\n" +
                DisableLegacyWeaponProcLines);
        var worldData = await new JsonWorldDataLoader(new WorldDataOptions(seedPath)).LoadAsync();
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        using var log = new StringWriter();
        var loader = new CharacterSnapshotLoader(
            _usersRoot,
            playerItemsRoot,
            playerSpellsRoot: null,
            playerProficienciesRoot: null,
            playersCombatGearRoot: null);
        var handler = new WorldServerFrameHandler(loader, handoff, worldData, log);
        var sent = new List<byte[]>();
        var connection = CreateSendingConnection(sent);

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new MsgActionPacket
            {
                ObjId = 1_293_600,
                Timestamp = 1234,
                Type = MsgActionType.SetLocation,
            }.ToFrameBytes()));

        var monster = sent.ToArray()
            .Select(bytes => LegacyMonsterSpawnPacket.TryParse(ReadFrame(bytes), out var parsed) ? parsed : null)
            .FirstOrDefault(packet => packet is not null &&
                packet.Names[0] == "Birdman" &&
                packet.X == 837 &&
                packet.Y == 573);
        Assert.NotNull(monster);

        var attackStart = sent.Count;
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new MsgAttackPacket(new MsgAttackQuery(
                Uid: 1_293_600,
                OpponentUid: monster.Uid,
                X: monster.X,
                Y: monster.Y,
                AttackType: MsgAttackType.Physical,
                Damage: 1,
                KilledMonster: 0,
                ResponseDamage: 0,
                Effect: MsgAttackEffect.None,
                Unknown: 0)).ToFrameBytes()));

        await WaitUntilAsync(
            () => FindFrameIndexAfter(
                sent,
                attackStart,
                frame => MsgAttackPacket.TryParse(frame, out var packet) &&
                    packet.Query.Uid == 1_293_600U &&
                    packet.Query.OpponentUid == monster.Uid &&
                    packet.Query.AttackType == MsgAttackType.Physical) >= attackStart,
            TimeSpan.FromSeconds(3));
        var playerHitIndex = FindFrameIndexAfter(
            sent,
            attackStart,
            frame => MsgAttackPacket.TryParse(frame, out var packet) &&
                packet.Query.Uid == 1_293_600U &&
                packet.Query.OpponentUid == monster.Uid &&
                packet.Query.AttackType == MsgAttackType.Physical);
        Assert.True(playerHitIndex >= attackStart, log.ToString());
        Assert.True(MsgAttackPacket.TryParse(ReadFrame(sent[playerHitIndex]), out var playerHit));
        Assert.Equal(monster.Uid, playerHit.Query.OpponentUid);
        var loadedSession = GetSession(handler, connection);
        var refineLevel = LegacyUserTotalRefineLevPacket.FromEquipmentPerfection(
            1_293_600,
            loadedSession.PlayerItems);
        var fields = LegacyPlayerStatusCalculator.CalculateFields(
            loadedSession.Character,
            loadedSession.PlayerItems,
            worldData,
            checked((uint)loadedSession.Character.MinHitPoints),
            refineLevel.Level,
            loadedSession.CombatGear);
        Assert.True(
            fields[LegacyPlayerStatusPacket.MaxAttackIndex] > fields[LegacyPlayerStatusPacket.MinAttackIndex],
            "Expected loaded gear to contribute physical attack fields.");
        Assert.True(worldData.MonstersById.TryGetValue((int)monster.MonsterId, out var monsterFamily));
        var minimumRolledDamage = LegacyPlayerMonsterPhysicalDamageCalculator.Calculate(
            fields[LegacyPlayerStatusPacket.MinAttackIndex],
            fields[LegacyPlayerStatusPacket.MaxAttackIndex],
            ReadUIntAttribute(monsterFamily.Attributes, "defense", "defence", "Defense", "Defence"),
            ReadUIntAttribute(monsterFamily.Attributes, "defense2", "defence2", "Defense2", "Defence2"),
            checked((int)loadedSession.Character.Level),
            monster.MonsterLevel,
            fields[LegacyPlayerStatusPacket.PhysicalPercentIndex],
            deterministicRoll: 0);

        Assert.True(minimumRolledDamage > monster.MaxLife, "Expected loaded gear to overkill the low-HP Birdman target.");
        Assert.True(
            playerHit.Query.Damage > monster.MaxLife,
            $"Expected visible hit damage to preserve the rolled overkill damage, not clamp to MaxLife={monster.MaxLife}.");
        Assert.Contains("WorldServer handled monster combat", log.ToString());
    }

    [Fact(Skip = "Requires external game fixtures omitted from the public source snapshot.")]
    public async Task HandlerUsesLoadedGearToReduceMonsterPhysicalDamageToOne()
    {
        var seedPath = Path.Combine(FindRepositoryRoot(), ".setup_work", "seed-json");
        var playerItemsRoot = @"data/DBServer\PlayersItems";
        var combatGearRoot = @"data/DBServer\PlayersCombatGear";
        if (!File.Exists(Path.Combine(seedPath, "manifest.json")) ||
            !File.Exists(Path.Combine(playerItemsRoot, "1293600.bin")) ||
            !File.Exists(Path.Combine(combatGearRoot, "1293600.ini")))
        {
            return;
        }

        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(
            1293600,
            uid: 1293600,
            mapId: 1015,
            x: 837,
            y: 573,
            extraCharacterLines: "LegacyMonsterDodgeRoll=149\r\nLegacyMonsterDodgeSecondaryRoll=149");
        var worldData = await new JsonWorldDataLoader(new WorldDataOptions(seedPath)).LoadAsync();
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        using var log = new RuntimeThreadSafeStringWriter();
        using var cancel = new CancellationTokenSource();
        var loader = new CharacterSnapshotLoader(
            _usersRoot,
            playerItemsRoot,
            playerSpellsRoot: null,
            playerProficienciesRoot: null,
            playersCombatGearRoot: combatGearRoot);
        var handler = new WorldServerFrameHandler(
            loader,
            handoff,
            worldData,
            new LegacyRuntimeUpdateLoopOptions(
                Enabled: true,
                TimeSpan.FromMilliseconds(20),
                new AnchoredRuntimeTimeProvider(DateTimeOffset.UtcNow.AddSeconds(20))),
            log);
        var sent = new RuntimeThreadSafeFrameCapture();
        var connection = CreateSendingConnection(sent);

        try
        {
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()),
                cancel.Token);
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new MsgActionPacket
                {
                    ObjId = 1_293_600,
                    Timestamp = 1234,
                    Type = MsgActionType.SetLocation,
                }.ToFrameBytes()),
                cancel.Token);

            var monster = sent.ToArray()
                .Select(bytes => LegacyMonsterSpawnPacket.TryParse(ReadFrame(bytes), out var parsed) ? parsed : null)
                .FirstOrDefault(packet => packet is not null &&
                    packet.Names[0] == "Birdman" &&
                    packet.X == 837 &&
                    packet.Y == 573);
            Assert.NotNull(monster);

            var attackStart = sent.Count;
            await WaitUntilAsync(
                () => FindFrameIndexAfter(
                    sent,
                    attackStart,
                    frame => MsgAttackPacket.TryParse(frame, out var packet) &&
                        packet.Query.Uid == monster.Uid &&
                        packet.Query.OpponentUid == 1_293_600U &&
                        packet.Query.AttackType == MsgAttackType.Physical) >= attackStart,
                TimeSpan.FromSeconds(3));

            var attackIndex = FindFrameIndexAfter(
                sent,
                attackStart,
                frame => MsgAttackPacket.TryParse(frame, out var packet) &&
                    packet.Query.Uid == monster.Uid &&
                    packet.Query.OpponentUid == 1_293_600U &&
                    packet.Query.AttackType == MsgAttackType.Physical);
            Assert.True(MsgAttackPacket.TryParse(ReadFrame(sent[attackIndex]), out var attack));
            Assert.Equal(1, attack.Query.Damage);

            var updated = GetSession(handler, connection);
            Assert.Equal(61_257, updated.Character.MinHitPoints);
            await WaitUntilAsync(
                () => log.ToString().Contains("WorldServer sent proactive monster attacks", StringComparison.Ordinal),
                TimeSpan.FromSeconds(5));
            Assert.Contains("WorldServer sent proactive monster attacks", log.ToString());
        }
        finally
        {
            await cancel.CancelAsync();
        }
    }

    [Fact(Skip = "Requires external game fixtures omitted from the public source snapshot.")]
    public async Task HandlerSendsMonsterRetaliationAfterSurvivingPlayerHit()
    {
        var seedPath = Path.Combine(FindRepositoryRoot(), ".setup_work", "seed-json");
        if (!File.Exists(Path.Combine(seedPath, "manifest.json")))
        {
            return;
        }

        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(
            1293600,
            uid: 1293600,
            mapId: 1015,
            x: 837,
            y: 573,
            extraCharacterLines: DisableLegacyWeaponProcLines);
        var worldData = await new JsonWorldDataLoader(new WorldDataOptions(seedPath)).LoadAsync();
        RaiseSeedMonsterLifeForRetaliationFixture(worldData, "Birdman");
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        using var log = new StringWriter();
        var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot), handoff, worldData, log);
        var sent = new List<byte[]>();
        var connection = CreateSendingConnection(sent);

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new MsgActionPacket
            {
                ObjId = 1_293_600,
                Timestamp = 1234,
                Type = MsgActionType.SetLocation,
            }.ToFrameBytes()));

        var monster = sent.ToArray()
            .Select(bytes => LegacyMonsterSpawnPacket.TryParse(ReadFrame(bytes), out var parsed) ? parsed : null)
            .FirstOrDefault(packet => packet is not null &&
                packet.Names[0] == "Birdman" &&
                packet.X == 837 &&
                packet.Y == 573);
        Assert.NotNull(monster);
        Assert.Equal(837, monster.X);
        Assert.Equal(573, monster.Y);

        var attackStart = sent.Count;
        await SendPlayerHitThenScheduledMonsterRetaliationAsync(
            handler,
            connection,
            sent,
            ReadFrame(new MsgAttackPacket(new MsgAttackQuery(
                Uid: 1_293_600,
                OpponentUid: monster.Uid,
                X: monster.X,
                Y: monster.Y,
                AttackType: MsgAttackType.Physical,
                Damage: 1,
                KilledMonster: 0,
                ResponseDamage: 0,
                Effect: MsgAttackEffect.None,
                Unknown: 0)).ToFrameBytes()));

        Assert.True(MsgAttackPacket.TryParse(ReadFrame(sent[attackStart]), out var playerHit));
        AssertServerAppliedSurvivingMonsterPhysicalHit(playerHit, monster);

        var retaliationIndex = FindFrameIndexAfter(
            sent,
            attackStart + 1,
            frame => MsgAttackPacket.TryParse(frame, out var packet) &&
                packet.Query.Uid == monster.Uid &&
                packet.Query.OpponentUid == 1_293_600U &&
                packet.Query.AttackType == MsgAttackType.Physical);
        Assert.True(retaliationIndex > attackStart, $"Expected monster retaliation frame after player hit. Log={log}");
        Assert.True(MsgAttackPacket.TryParse(ReadFrame(sent[retaliationIndex]), out var retaliation));
        Assert.Equal(monster.Uid, retaliation.Query.Uid);
        Assert.Equal(1_293_600U, retaliation.Query.OpponentUid);
        Assert.Equal(837, retaliation.Query.X);
        Assert.Equal(573, retaliation.Query.Y);
        Assert.Equal(MsgAttackType.Physical, retaliation.Query.AttackType);
        Assert.Equal(1_462, retaliation.Query.Damage);
        Assert.Equal(0, retaliation.Query.KilledMonster);

        var updated = GetSession(handler, connection);
        Assert.Equal(33_174, updated.Character.MinHitPoints);
        Assert.Equal(monster.Uid.ToString(CultureInfo.InvariantCulture), updated.Character.Attributes["ThundercloudSight"]);
        Assert.Contains(
            sent.Skip(retaliationIndex + 1),
            bytes =>
            {
                if (!LegacyMsgUpdatePacket.TryParse(ReadFrame(bytes), out var update))
                {
                    return false;
                }

                return update.Uid == 1_293_600U &&
                    update.Updates.Any(entry =>
                        entry.Type == LegacyMsgUpdateDataType.Hitpoints &&
                        entry.Value == 33_174UL);
            });
        Assert.Contains("WorldServer sent legacy monster retaliation", log.ToString());
    }

