                runtimeUpdateLoop: new LegacyRuntimeUpdateLoopOptions(false, TimeSpan.FromSeconds(1),
                    new BossRuntimeManualTimeProvider(new DateTimeOffset(2026, 10, 16, 12, 0, 0, TimeSpan.Zero))),
                log: log);
            var sent = new List<byte[]>();
            var connection = CreateSendingConnection(sent);

            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new MsgActionPacket
                {
                    ObjId = 1_293_600,
                    Timestamp = 1234,
                    Type = MsgActionType.SetLocation,
                }.ToFrameBytes()));

            var monsterSpawnFrames = sent.ToArray();
            var monster = monsterSpawnFrames
                .Select(bytes => LegacyMonsterSpawnPacket.TryParse(ReadFrame(bytes), out var parsed) ? parsed : null)
                .FirstOrDefault(packet => packet is not null &&
                    packet.Names[0] == "Birdman" &&
                    packet.X == 837 &&
                    packet.Y == 573);
            Assert.NotNull(monster);

            var attackStart = sent.Count;
            await SendPlayerHitThenScheduledMonsterRetaliationAsync(
                handler,
                connection,
                sent,
                ReadFrame(new MsgAttackPacket(new MsgAttackQuery(
                    Uid: 1_293_600,
                    OpponentUid: monster.Uid,
                    X: monster.X,
                    Y: monster.Y,
                    AttackType: MsgAttackType.Physical,
                    Damage: 1,
                    KilledMonster: 0,
                    ResponseDamage: 0,
                    Effect: MsgAttackEffect.None,
                    Unknown: 0)).ToFrameBytes()));

            var (playerHitIndex, playerHit) = AssertServerAppliedSurvivingMonsterPhysicalHitAfter(
                sent,
                attackStart,
                1_293_600U,
                monster,
                log.ToString());
            Assert.Equal(monster.Uid, playerHit.Query.OpponentUid);

            var activationUpdateIndex = FindFrameIndexAfter(
                sent,
                playerHitIndex + 1,
                frame => LegacyMsgUpdatePacket.TryParse(frame, out var update) &&
                    update.Uid == 1_293_600U &&
                    update.Updates.Any(entry =>
                        entry.Type == LegacyMsgUpdateDataType.AzureShield &&
                        entry.Flag == LightningShieldActivatedFlag &&
                        entry.Time == 10 &&
                        entry.Damage == 20_000U &&
                        entry.SpellLevel == 3U));
            Assert.True(activationUpdateIndex > attackStart, log.ToString());

            var drainUpdateIndex = FindFrameIndexAfter(
                sent,
                activationUpdateIndex + 1,
                frame => LegacyMsgUpdatePacket.TryParse(frame, out var update) &&
                    update.Uid == 1_293_600U &&
                    update.Updates.Any(entry =>
                        entry.Type == LegacyMsgUpdateDataType.AzureShield &&
                        entry.Flag == LightningShieldActivatedFlag &&
                        entry.Time == 10 &&
                        entry.Damage == 18_538U &&
                        entry.SpellLevel == 3U));
            Assert.True(drainUpdateIndex > activationUpdateIndex, log.ToString());

            var retaliationIndex = FindFrameIndexAfter(
                sent,
                drainUpdateIndex + 1,
                frame => MsgAttackPacket.TryParse(frame, out var packet) &&
                    packet.Query.Uid == monster.Uid &&
                    packet.Query.OpponentUid == 1_293_600U &&
                    packet.Query.AttackType == MsgAttackType.Physical);
            Assert.True(retaliationIndex > drainUpdateIndex, log.ToString());
            Assert.True(MsgAttackPacket.TryParse(ReadFrame(sent[retaliationIndex]), out var retaliation));
            Assert.Equal(0, retaliation.Query.Damage);

            var updated = GetSession(handler, connection);
            Assert.Equal(34_636, updated.Character.MinHitPoints);
            Assert.True(HasLegacyStatusFlag(updated.Character.Attributes["StatusFlags"], LightningShieldActivatedFlag));
            Assert.Equal("18538", updated.Character.Attributes["LightningShieldLeft"]);
            Assert.Contains("WorldServer applied legacy LightningShield monster-hit absorption", log.ToString());
        }
        finally
        {
            if (Directory.Exists(dbRoot))
            {
                Directory.Delete(dbRoot, recursive: true);
            }
        }
    }

