            var updated = GetSession(handler, connection);
            Assert.Equal(32_166, updated.Character.MinHitPoints);
            Assert.True(HasLegacyStatusFlag(
                updated.Character.Attributes["StatusFlags"],
                LightningMagicShieldTop4WeeklyFlag));
            Assert.Contains(
                sent.Skip(attackStart + 1),
                bytes => LegacyMsgUpdatePacket.TryParse(ReadFrame(bytes), out var update) &&
                    update.Uid == 1_293_600U &&
                    update.Updates.Any(entry =>
                        entry.Type == LegacyMsgUpdateDataType.StatusFlag &&
                        entry.Values is not null &&
                        HasLegacyStatusFlag(entry.Values, LightningMagicShieldTop4WeeklyFlag)));
            Assert.Contains(
                sent.Skip(attackStart + 1),
                bytes => LegacyMsgUpdatePacket.TryParse(ReadFrame(bytes), out var update) &&
                    update.Uid == 1_293_600U &&
                    update.Updates.Any(entry =>
                        entry.Type == LegacyMsgUpdateDataType.ArchiveSkill &&
                        entry.Flag == LightningMagicShieldTop4WeeklyFlag &&
                        entry.Time == 2));
            Assert.Contains(
                sent.Skip(attackStart + 1),
                bytes => LegacySpellAnimationPacket.TryParse(ReadFrame(bytes), out var animation) &&
                    animation.AttackerUid == 1_293_600U &&
                    animation.SpellId == 17_580 &&
                    animation.Targets.Any(target => target.Uid == 1_293_600U));
            Assert.DoesNotContain(
                sent.Skip(attackStart + 1),
                bytes => MsgAttackPacket.TryParse(ReadFrame(bytes), out var packet) &&
                    packet.Query.Uid == monster.Uid &&
                    packet.Query.OpponentUid == 1_293_600U &&
                    packet.Query.AttackType == MsgAttackType.Physical);

            var output = log.ToString();
            Assert.Contains("WorldServer sent legacy CombatGear UpdateTarget passive status", output);
            Assert.Contains("spellId=17580", output);
            Assert.Contains("WorldServer applied legacy CombatGear UpdateTarget", output);
            Assert.Contains("WorldServer blocked legacy monster retaliation with CombatGear CheckDamage", output);
            Assert.DoesNotContain("WorldServer sent legacy monster retaliation", output);
        }
        finally
        {
            if (Directory.Exists(dbRoot))
            {
                Directory.Delete(dbRoot, recursive: true);
            }
        }
    }

