                        entry.Values is not null &&
                        HasLegacyStatusFlag(entry.Values, VenomMagicShieldFlag)));
            Assert.Contains(
                sent.Skip(attackStart + 1),
                bytes => LegacyMsgUpdatePacket.TryParse(ReadFrame(bytes), out var update) &&
                    update.Uid == 1_293_600U &&
                    update.Updates.Any(entry =>
                        entry.Type == LegacyMsgUpdateDataType.ArchiveSkill &&
                        entry.Flag == VenomMagicShieldFlag &&
                        entry.Time == 10));

            LegacySpellAnimationPacket? magneticLight = null;
            foreach (var bytes in sent.Skip(attackStart + 1))
            {
                if (LegacySpellAnimationPacket.TryParse(ReadFrame(bytes), out var animation) &&
                    animation.AttackerUid == 1_293_600U &&
                    animation.SpellId == 20_220)
                {
                    magneticLight = animation;
                    break;
                }
            }

            Assert.NotNull(magneticLight);
            Assert.Equal(1, magneticLight.BombFlag);
            var target = Assert.Single(magneticLight.Targets);
            Assert.Equal(monster.Uid, target.Uid);
            Assert.Equal(15_000U, target.Damage);
            Assert.True(target.Hit);
            Assert.Equal(839, target.NewX);
            Assert.Equal(573, target.NewY);

            var output = log.ToString();
            Assert.Contains("WorldServer sent legacy CombatGear UpdateTarget passive status", output);
            Assert.Contains("spellId=20220", output);
            Assert.Contains("WorldServer sent legacy CombatGear UpdateTarget MagneticLight monster pushback", output);
            Assert.Contains("WorldServer applied legacy CombatGear UpdateTarget", output);
        }
        finally
        {
            if (Directory.Exists(dbRoot))
            {
                Directory.Delete(dbRoot, recursive: true);
            }
        }
    }

