            var connection = CreateSendingConnection(sent);

            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new MsgActionPacket
                {
                    ObjId = 1_293_600,
                    Timestamp = 1234,
                    Type = MsgActionType.SetLocation,
                }.ToFrameBytes()));

            var monster = sent.ToArray()
                .Select(bytes => LegacyMonsterSpawnPacket.TryParse(ReadFrame(bytes), out var parsed) ? parsed : null)
                .FirstOrDefault(packet => packet is not null &&
                    packet.Names[0] == "Birdman" &&
                    packet.X == 837 &&
                    packet.Y == 573);
            Assert.NotNull(monster);

            var sessionBeforeAttack = GetSession(handler, connection);
            var attackStart = sent.Count;
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new MsgAttackPacket(new MsgAttackQuery(
                    Uid: 1_293_600,
                    OpponentUid: monster.Uid,
                    X: monster.X,
                    Y: monster.Y,
                    AttackType: MsgAttackType.Physical,
                    Damage: 1,
                    KilledMonster: 0,
                    ResponseDamage: 0,
                    Effect: MsgAttackEffect.None,
                    Unknown: 0)).ToFrameBytes()));

            Assert.DoesNotContain(
                sent.Skip(attackStart),
                frame => LegacySpellAnimationPacket.TryParse(ReadFrame(frame), out var spell) &&
                    spell.AttackerUid == 1_293_600U &&
                    spell.SpellId == 21_670);
            Assert.Contains(
                sent.Skip(attackStart),
                bytes => MsgAttackPacket.TryParse(ReadFrame(bytes), out var physical) &&
                    physical.Query.Uid == 1_293_600U &&
                    physical.Query.OpponentUid == monster.Uid &&
                    physical.Query.AttackType == MsgAttackType.Physical);
            var sessionAfterAttack = GetSession(handler, connection);
            Assert.Equal(sessionBeforeAttack.Character.MinMana, sessionAfterAttack.Character.MinMana);
            Assert.Equal(
                sessionBeforeAttack.Character.Attributes.GetValueOrDefault("Stamina"),
                sessionAfterAttack.Character.Attributes.GetValueOrDefault("Stamina"));
            Assert.Equal(sessionBeforeAttack.PlayerSpells.Spells, sessionAfterAttack.PlayerSpells.Spells);
            Assert.DoesNotContain("WorldServer replaced legacy monster physical attack with CombatGear spell", log.ToString());
            Assert.Contains("WorldServer skipped legacy CombatGear monster-hit passive replacement", log.ToString());
            Assert.Contains("spellId=21670", log.ToString());
        }
        finally
        {
            if (Directory.Exists(dbRoot))
            {
                Directory.Delete(dbRoot, recursive: true);
            }
        }
    }

