        var spellsRoot = Path.Combine(dbRoot, "PlayersSpells");
        try
        {
            Directory.CreateDirectory(usersRoot);
            Directory.CreateDirectory(spellsRoot);
            WriteSnapshot(usersRoot, 1293600, uid: 1293600, level: 109);
            File.WriteAllBytes(
                Path.Combine(spellsRoot, "1293600.bin"),
                PlayerSpellSnapshotLoaderTests.BuildPlayerSpellRecords(
                [
                    PlayerSpellSnapshotLoaderTests.Entry(6_003, level: 0),
                ]));

            var worldData = await new JsonWorldDataLoader(new WorldDataOptions(seedPath)).LoadAsync();
            RaiseSeedMonsterLifeForRetaliationFixture(worldData, "Birdman");
            var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
            var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
            using var log = new StringWriter();
            var loader = new CharacterSnapshotLoader(
                usersRoot,
                playerItemsRoot: null,
                playerSpellsRoot: spellsRoot,
                playerProficienciesRoot: null);
            var handler = new WorldServerFrameHandler(loader, handoff, worldData, log);
            var sent = new List<byte[]>();
            // Declared physical CLIENT MODEL prestate, not socket-born acquisition.
            var physicalClient = new LegacyNativeGameClientRuntime();
            var connection = new ConquerTcpConnection(
                null, new IPEndPoint(IPAddress.Loopback, 9958),
                (frame, _) =>
                {
                    sent.Add(frame.ToArray());
                    return ValueTask.CompletedTask;
                },
                nativeGameClient: physicalClient);

            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));

            var firstStart = sent.Count;
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new MsgAttackPacket(new MsgAttackQuery(
                    Uid: 1_293_600,
                    OpponentUid: 1_293_600,
                    X: 830,
                    Y: 584,
                    AttackType: MsgAttackType.CounterKillSwitch,
                    Damage: 0,
                    KilledMonster: 0,
                    ResponseDamage: 0,
                    Effect: MsgAttackEffect.None,
                    Unknown: 0)).ToFrameBytes()));

            Assert.Equal(firstStart + 1, sent.Count);
            Assert.True(MsgAttackPacket.TryParse(ReadFrame(sent[firstStart]), out var firstToggle));
            Assert.Equal(MsgAttackType.CounterKillSwitch, firstToggle.Query.AttackType);
            Assert.Equal(1, firstToggle.Query.Damage);
            Assert.Equal(6_003, firstToggle.Query.SpellId);
            Assert.Equal("1", GetSession(handler, connection).Character.Attributes["LegacyCounterKillActive"]);

            var secondStart = sent.Count;
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new MsgAttackPacket(new MsgAttackQuery(
                    Uid: 1_293_600,
                    OpponentUid: 1_293_600,
                    X: 830,
                    Y: 584,
                    AttackType: MsgAttackType.CounterKillSwitch,
                    Damage: 0,
                    KilledMonster: 0,
                    ResponseDamage: 0,
                    Effect: MsgAttackEffect.None,
                    Unknown: 0)).ToFrameBytes()));

            Assert.Equal(secondStart + 1, sent.Count);
            Assert.True(MsgAttackPacket.TryParse(ReadFrame(sent[secondStart]), out var secondToggle));
            Assert.Equal(MsgAttackType.CounterKillSwitch, secondToggle.Query.AttackType);
            Assert.Equal(0, secondToggle.Query.Damage);
            Assert.Equal(6_003, secondToggle.Query.SpellId);
            Assert.Equal("0", GetSession(handler, connection).Character.Attributes["LegacyCounterKillActive"]);
            Assert.Contains("WorldServer handled legacy CounterKill switch", log.ToString());
        }
        finally
        {
            if (Directory.Exists(dbRoot))
            {
                Directory.Delete(dbRoot, recursive: true);
            }
        }
    }

