                playerSpellsRoot: spellsRoot,
                playerProficienciesRoot: null);
            var handler = new WorldServerFrameHandler(loader, handoff, worldData, log);
            var sent = new List<byte[]>();
            var connection = CreateSendingConnection(sent);

            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new MsgActionPacket
                {
                    ObjId = 1_293_600,
                    Timestamp = 1234,
                    Type = MsgActionType.SetLocation,
                }.ToFrameBytes()));

            var monster = sent.ToArray()
                .Select(bytes => LegacyMonsterSpawnPacket.TryParse(ReadFrame(bytes), out var parsed) ? parsed : null)
                .FirstOrDefault(packet => packet is not null &&
                    packet.Names[0] == "Birdman" &&
                    packet.X == 837 &&
                    packet.Y == 573);
            Assert.NotNull(monster);

            var attackStart = sent.Count;
            await SendPlayerHitThenScheduledMonsterRetaliationAsync(
                handler,
                connection,
                sent,
                ReadFrame(new MsgAttackPacket(new MsgAttackQuery(
                    Uid: 1_293_600,
                    OpponentUid: monster.Uid,
                    X: monster.X,
                    Y: monster.Y,
                    AttackType: MsgAttackType.Physical,
                    Damage: 1,
                    KilledMonster: 0,
                    ResponseDamage: 0,
                    Effect: MsgAttackEffect.None,
                    Unknown: 0)).ToFrameBytes()));

            var eagleEyeIndex = FindFrameIndexAfter(
                sent,
                attackStart + 1,
                frame => LegacySpellAnimationPacket.TryParse(frame, out var packet) &&
                    packet.AttackerUid == 1_293_600U &&
                    packet.AttackedUid == 1_293_600U &&
                    packet.SpellId == 11_130);
            Assert.True(eagleEyeIndex > attackStart, $"Expected EagleEye self animation. Log={log}");
            Assert.True(LegacySpellAnimationPacket.TryParse(ReadFrame(sent[eagleEyeIndex]), out var eagleEye));
            Assert.Equal(0, eagleEye.X);
            Assert.Equal(0, eagleEye.Y);
            var eagleTarget = Assert.Single(eagleEye.Targets);
            Assert.Equal(1_293_600U, eagleTarget.Uid);
            Assert.Equal(11_130U, eagleTarget.Damage);
            Assert.False(eagleTarget.Hit);

            var coldTimeIndex = FindFrameIndexAfter(
                sent,
                eagleEyeIndex + 1,
                frame => LegacyMagicColdTimePacket.TryParse(frame, out var packet) &&
                    packet.Spells.SequenceEqual([new LegacyMagicColdTimeSpell(11_030, Time: 0)]));
            Assert.True(coldTimeIndex > eagleEyeIndex, $"Expected EagleEye cold-time clear. Log={log}");

            var retaliationIndex = FindFrameIndexAfter(
                sent,
                coldTimeIndex + 1,
                frame => MsgAttackPacket.TryParse(frame, out var packet) &&
                    packet.Query.Uid == monster.Uid &&
                    packet.Query.OpponentUid == 1_293_600U &&
                    packet.Query.AttackType == MsgAttackType.Physical);
            Assert.True(retaliationIndex > coldTimeIndex, $"Expected normal monster retaliation after EagleEye. Log={log}");
            Assert.True(MsgAttackPacket.TryParse(ReadFrame(sent[retaliationIndex]), out var retaliation));
            Assert.Equal(1_462, retaliation.Query.Damage);

            var updated = GetSession(handler, connection);
            Assert.Equal("0", updated.Character.Attributes["LegacyEagleEyeCountDown"]);
            Assert.Equal(33_174, updated.Character.MinHitPoints);
            Assert.Contains("WorldServer sent legacy monster EagleEye countdown response", log.ToString());
            Assert.Contains("WorldServer sent legacy monster retaliation", log.ToString());
        }
        finally
        {
            if (Directory.Exists(dbRoot))
            {
                Directory.Delete(dbRoot, recursive: true);
            }
        }
    }

