            connection,
            ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new MsgActionPacket
            {
                ObjId = 1_293_600,
                Timestamp = 1234,
                Type = MsgActionType.SetLocation,
            }.ToFrameBytes()));

        var monster = sent.ToArray()
            .Select(bytes => LegacyMonsterSpawnPacket.TryParse(ReadFrame(bytes), out var parsed) ? parsed : null)
            .FirstOrDefault(packet => packet is not null &&
                packet.Names[0] == "Birdman" &&
                packet.X == 837 &&
                packet.Y == 573);
        Assert.NotNull(monster);

        var attackStart = sent.Count;
        await SendPlayerHitThenScheduledMonsterRetaliationAsync(
            handler,
            connection,
            sent,
            ReadFrame(new MsgAttackPacket(new MsgAttackQuery(
                Uid: 1_293_600,
                OpponentUid: monster.Uid,
                X: monster.X,
                Y: monster.Y,
                AttackType: MsgAttackType.Physical,
                Damage: 1,
                KilledMonster: 0,
                ResponseDamage: 0,
                Effect: MsgAttackEffect.None,
                Unknown: 0)).ToFrameBytes()));

        var retaliationIndex = FindFrameIndexAfter(
            sent,
            attackStart + 1,
            frame => MsgAttackPacket.TryParse(frame, out var packet) &&
                packet.Query.Uid == monster.Uid &&
                packet.Query.OpponentUid == 1_293_600U &&
                packet.Query.AttackType == MsgAttackType.Physical);
        Assert.True(
            retaliationIndex > attackStart,
            $"Expected zero-damage monster retaliation frame after dodge miss. NewFrameCount={sent.Count - attackStart}. Log={log}");
        Assert.True(MsgAttackPacket.TryParse(ReadFrame(sent[retaliationIndex]), out var retaliation));
        Assert.Equal(monster.Uid, retaliation.Query.Uid);
        Assert.Equal(1_293_600U, retaliation.Query.OpponentUid);
        Assert.Equal(MsgAttackType.Physical, retaliation.Query.AttackType);
        Assert.Equal(0, retaliation.Query.Damage);

        var updated = GetSession(handler, connection);
        Assert.Equal(34_636, updated.Character.MinHitPoints);
        Assert.DoesNotContain(
            sent.Skip(retaliationIndex + 1),
            bytes =>
            {
                if (!LegacyMsgUpdatePacket.TryParse(ReadFrame(bytes), out var update) ||
                    update.Uid != 1_293_600U)
                {
                    return false;
                }

                return update.Updates.Any(entry =>
                    entry.Type == LegacyMsgUpdateDataType.Hitpoints &&
                    entry.Value < 34_636UL);
            });
        Assert.Contains("WorldServer sent legacy monster dodge retaliation", log.ToString());
    }

