            .FirstOrDefault(packet => packet is not null && packet.Names[0] == "HawkPhysicalTester");
        Assert.NotNull(monster);

        var attackStart = sent.Count;
        await SendPlayerHitThenScheduledMonsterRetaliationAsync(
            handler,
            connection,
