                death.Query.OpponentUid == monster.Uid &&
                death.Query.AttackType == MsgAttackType.Death);
        Assert.True(deathIndex >= attackStart, log.ToString());

        var expectedConquerPoints = checked((ulong)(StartingConquerPoints + RewardConquerPoints));
        var updateIndex = FindFrameIndexAfter(
            sent,
            deathIndex,
            frame => LegacyMsgUpdatePacket.TryParse(frame, out var update) &&
                update.Uid == 1_293_600U &&
                update.Updates.Count == 1 &&
                update.Updates[0].Type == LegacyMsgUpdateDataType.ConquerPoints &&
                update.Updates[0].Value == expectedConquerPoints);
        Assert.True(updateIndex >= deathIndex, log.ToString());

        Assert.DoesNotContain(
            sent.Skip(attackStart),
            frame => LegacyProtoHeroInfoPacket.TryParse(ReadFrame(frame), out _));

        var messageIndex = FindFrameIndexAfter(
            sent,
            updateIndex,
            frame => LegacyMsgMessagePacket.TryParse(frame, out var message) &&
                message.Content.Count > 3 &&
                message.Content[3] == "You`ve received 5 Conquer Points.");
        Assert.True(messageIndex >= updateIndex, log.ToString());

        var updated = GetSession(handler, connection);
        Assert.Equal(StartingConquerPoints + RewardConquerPoints, updated.Character.ConquerPoints);
        var reloaded = new CharacterSnapshotLoader(_usersRoot).LoadByAccountId(1293600);
        Assert.NotNull(reloaded);
        Assert.Equal(StartingConquerPoints + RewardConquerPoints, reloaded.ConquerPoints);
        Assert.Contains("WorldServer applied legacy monster-death random Conquer Point reward", log.ToString());
        Assert.Contains("branch=NonBossVipLadder points=5", log.ToString());
        Assert.Contains(
            "updatedConquerPoints=1005 walletUpdate=LegacyMsgUpdate.ConquerPoints",
            log.ToString());
        Assert.DoesNotContain("heroInfoRefresh", log.ToString());
        Assert.Contains("ratePercent=50 rateRoll=0", log.ToString());
    }

