            uid: 1293600,
            mapId: 1015,
            x: 837,
            y: 573,
            conquerPoints: StartingConquerPoints,
            boundConquerPoints: 0);
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        using var log = new StringWriter();
        var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot, Path.Combine(_usersRoot, "PlayersItems")), handoff, log);
        var sent = new List<byte[]>();
        var connection = CreateSendingConnection(sent);

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));

        var session = GetSession(handler, connection);
        var floorItem = LegacyFloorItemPacket.FromMonsterDrop(
            itemId: 1_091_020U,
            x: checked((ushort)session.Character.X),
            y: checked((ushort)session.Character.Y),
            session.Character,
            floorUid: 7_777_000U);
        var floorItems = GetFloorItems(handler);
        floorItems.AddVisible(
            FloorItemRuntimeEntry.ForConquerPoints(
                session.Character.MapId,
                floorItem,
                PickupConquerPoints));

        var pickupStart = sent.Count;
        await handler.HandleFrameAsync(connection, ReadFrame(BuildLegacyFloorItemPickupFrame(floorItem.Uid)));

        var expectedConquerPoints = checked((ulong)(StartingConquerPoints + PickupConquerPoints));
        var updateIndex = FindFrameIndexAfter(
            sent,
            pickupStart,
            frame => LegacyMsgUpdatePacket.TryParse(frame, out var update) &&
                update.Uid == 1_293_600U &&
                update.Updates.Count == 1 &&
                update.Updates[0].Type == LegacyMsgUpdateDataType.ConquerPoints &&
                update.Updates[0].Value == expectedConquerPoints);
        var removeIndex = FindFrameIndexAfter(
            sent,
            pickupStart,
            frame => LegacyFloorItemPacket.TryParse(frame, out var remove) &&
                remove.Uid == floorItem.Uid &&
                remove.DropType == LegacyFloorItemDropType.Remove);
        Assert.InRange(updateIndex, pickupStart, removeIndex);
        Assert.DoesNotContain(
            sent.Skip(pickupStart),
            frame => LegacyProtoHeroInfoPacket.TryParse(ReadFrame(frame), out _));

        var messageIndex = FindFrameIndexAfter(
            sent,
            removeIndex,
            frame => LegacyMsgMessagePacket.TryParse(frame, out var message) &&
                message.Content.Count > 3 &&
                message.Content[3] == "You have picked up a 45 ConquerPoints.");
        Assert.True(messageIndex >= removeIndex);

        var updated = GetSession(handler, connection);
        Assert.Equal(StartingConquerPoints + PickupConquerPoints, updated.Character.ConquerPoints);
        var reloaded = new CharacterSnapshotLoader(_usersRoot).LoadByAccountId(1293600);
        Assert.NotNull(reloaded);
        Assert.Equal(StartingConquerPoints + PickupConquerPoints, reloaded.ConquerPoints);
        Assert.False(floorItems.TryGetVisibleEntry(floorItem.Uid, out _));

        var output = log.ToString();
        Assert.Contains("WorldServer handled LegacyFloorItem Conquer Point pickup", output);
        Assert.Contains("amount=45", output);
        Assert.Contains("updatedConquerPoints=1045", output);
        Assert.Contains("walletUpdate=LegacyMsgUpdate.ConquerPoints", output);
        Assert.DoesNotContain("heroInfoRefresh", output);
    }

