            sent,
            attackStart,
            frame => LegacyFloorItemPacket.TryParse(frame, out var drop) &&
                drop.DropType == LegacyFloorItemDropType.Visible &&
                drop.ItemOwnerUid == 1_293_600U);
        var floorItem = ParseLegacyFloorItem(sent[dropIndex]);
        Assert.DoesNotContain(
            peerSent.Skip(peerBeforeDrop),
            bytes => LegacyFloorItemPacket.TryParse(ReadFrame(bytes), out var drop) &&
                drop.Uid == floorItem.Uid);

        var peerBeforeJump = peerSent.Count;
        await handler.HandleFrameAsync(
            peerConnection,
            ReadFrame(new MsgActionPacket
            {
                ObjId = 1_293_601,
                Timestamp = 987,
                Type = MsgActionType.Jump,
                Facing = 6,
                TargetPositionX = 824,
                TargetPositionY = 573,
            }.ToFrameBytes()));

        var peerDropIndex = FindFrameIndexAfter(
            peerSent,
            peerBeforeJump,
            frame => LegacyFloorItemPacket.TryParse(frame, out var drop) &&
                drop.Uid == floorItem.Uid &&
                drop.DropType == LegacyFloorItemDropType.Visible);
        Assert.Equal(floorItem, ParseLegacyFloorItem(peerSent[peerDropIndex]));
        Assert.Contains("WorldServer sent visible LegacyFloorItem refresh", log.ToString());
    }

