            teammatePickupStart,
            frame => LegacyFloorItemPacket.TryParse(frame, out var remove) &&
                remove.Uid == floorItem.Uid &&
                remove.DropType == LegacyFloorItemDropType.Remove);
        Assert.InRange(moneyIndex, teammatePickupStart, removeIndex);
        Assert.Equal(52_000, GetSession(handler, teammateConnection).Character.Money);
        Assert.Contains("WorldServer allowed LegacyFloorItem team owner-lock pickup", log.ToString());
        Assert.Contains("WorldServer handled LegacyFloorItem money pickup", log.ToString());
    }

    [Fact(Skip = "Requires external game fixtures omitted from the public source snapshot.")]
    public async Task HandlerRequiresLootItemsOnForTeammateMonsterItemPickupDuringLegacyOwnerWindow()
    {
        var seedPath = Path.Combine(FindRepositoryRoot(), ".setup_work", "seed-json");
        if (!File.Exists(Path.Combine(seedPath, "manifest.json")))
        {
            return;
        }

        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(
            1293600,
            uid: 1293600,
            mapId: 1015,
            x: 837,
            y: 573,
            legacyMonsterDropRoll: 701,
            legacyMonsterDropItemSort: 410,
            legacyMonsterDropItemLevel: 0,
            legacyMonsterDropItemQuality: 3);
        WriteSnapshot(1293601, uid: 1293601, mapId: 1015, x: 842, y: 573, name: "Teammate");
        var worldData = await new JsonWorldDataLoader(new WorldDataOptions(seedPath)).LoadAsync();
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        var teammateTicket = handoff.Issue(1293601, "teammate", ConquerRuntimeDefaults.WorldServer);
        using var log = new StringWriter();
        var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot, Path.Combine(_usersRoot, "PlayersItems")), handoff, worldData, log);
        var sent = new List<byte[]>();
        var teammateSent = new List<byte[]>();
        var connection = CreateSendingConnection(sent);
        var teammateConnection = CreateSendingConnection(teammateSent);

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));
        await handler.HandleFrameAsync(
            teammateConnection,
            ReadFrame(new InternalWorldEnterRequestPacket(teammateTicket.Token).ToFrameBytes()));
        await handler.HandleFrameAsync(connection, ReadFrame(new MsgTeamPacket(MsgTeamType.Create, 0).ToFrameBytes()));
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new MsgTeamPacket(MsgTeamType.InviteRequest, 1293601).ToFrameBytes()));
        await handler.HandleFrameAsync(
            teammateConnection,
            ReadFrame(new MsgTeamPacket(MsgTeamType.AcceptInvitation, 1293600).ToFrameBytes()));
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new MsgActionPacket
            {
                ObjId = 1_293_600,
                Timestamp = 1234,
                Type = MsgActionType.SetLocation,
            }.ToFrameBytes()));

        var monster = sent.ToArray()
            .Select(bytes => LegacyMonsterSpawnPacket.TryParse(ReadFrame(bytes), out var parsed) ? parsed : null)
            .FirstOrDefault(packet => packet is not null &&
                packet.Names[0] == "Birdman" &&
                packet.X == 837 &&
                packet.Y == 573);
        Assert.NotNull(monster);

        var attackStart = sent.Count;
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new MsgAttackPacket(new MsgAttackQuery(
                Uid: 1_293_600,
                OpponentUid: monster.Uid,
                X: monster.X,
                Y: monster.Y,
                AttackType: MsgAttackType.Physical,
                Damage: checked((int)monster.MaxLife),
                KilledMonster: 0,
                ResponseDamage: 0,
                Effect: MsgAttackEffect.None,
                Unknown: 0)).ToFrameBytes()));

        var dropIndex = FindFrameIndexAfter(
            sent,
            attackStart,
            frame => LegacyFloorItemPacket.TryParse(frame, out var drop) &&
                drop.DropType == LegacyFloorItemDropType.Visible &&
                drop.ItemId == 410_003U &&
                drop.ItemOwnerUid == 1_293_600U);
        var floorItem = ParseLegacyFloorItem(sent[dropIndex]);

        var blockedPickupStart = teammateSent.Count;
        await handler.HandleFrameAsync(teammateConnection, ReadFrame(BuildLegacyFloorItemPickupFrame(floorItem.Uid)));

        var warningIndex = FindFrameIndexAfter(
            teammateSent,
            blockedPickupStart,
            frame => LegacyMsgMessagePacket.TryParse(frame, out var message) &&
                message.Content[3].Contains("wait a little bit", StringComparison.Ordinal));
        Assert.True(warningIndex >= blockedPickupStart);
        Assert.DoesNotContain(
            teammateSent.Skip(blockedPickupStart),
            bytes => LegacyGameItemPacket.TryParse(ReadFrame(bytes), out var item) &&
                item.ItemId == 410_003U);
        Assert.DoesNotContain(
            teammateSent.Skip(blockedPickupStart),
            bytes => LegacyFloorItemPacket.TryParse(ReadFrame(bytes), out var remove) &&
                remove.Uid == floorItem.Uid &&
                remove.DropType == LegacyFloorItemDropType.Remove);

        await handler.HandleFrameAsync(connection, ReadFrame(new MsgTeamPacket(MsgTeamType.LootItemsOn, 0).ToFrameBytes()));

        var allowedPickupStart = teammateSent.Count;
        await handler.HandleFrameAsync(teammateConnection, ReadFrame(BuildLegacyFloorItemPickupFrame(floorItem.Uid)));

        var itemIndex = FindFrameIndexAfter(
            teammateSent,
            allowedPickupStart,
            frame => LegacyGameItemPacket.TryParse(frame, out var item) &&
                item.ItemId == 410_003U);
        var removeIndex = FindFrameIndexAfter(
            teammateSent,
            allowedPickupStart,
            frame => LegacyFloorItemPacket.TryParse(frame, out var remove) &&
                remove.Uid == floorItem.Uid &&
                remove.DropType == LegacyFloorItemDropType.Remove);
        Assert.InRange(itemIndex, allowedPickupStart, removeIndex);
        Assert.Contains(GetSession(handler, teammateConnection).PlayerItems.InventoryItems, item => item.ItemId == 410_003U);
        Assert.Contains("WorldServer allowed LegacyFloorItem team owner-lock pickup", log.ToString());
        Assert.Contains("WorldServer handled LegacyFloorItem item pickup", log.ToString());
    }

    [Fact(Skip = "Requires external game fixtures omitted from the public source snapshot.")]
    public async Task HandlerMagicLayTrapTwilightDanceCreatesSourceBackedFloorEffectsAndAnimation()
    {
        var seedPath = Path.Combine(FindRepositoryRoot(), ".setup_work", "seed-json");
        if (!File.Exists(Path.Combine(seedPath, "manifest.json")))
        {
            return;
        }

        var dbRoot = Path.Combine(Path.GetTempPath(), "wolf-world-magic-laytrap-" + Guid.NewGuid());
        var usersRoot = Path.Combine(dbRoot, "Users");
        var spellsRoot = Path.Combine(dbRoot, "PlayersSpells");
        try
        {
            Directory.CreateDirectory(usersRoot);
            Directory.CreateDirectory(spellsRoot);
            WriteSnapshot(
                usersRoot,
                1293600,
                uid: 1293600,
                mapId: 1015,
                x: 100,
                y: 200,
                classCode: 5055,
                guildId: 123);
            File.WriteAllBytes(
                Path.Combine(spellsRoot, "1293600.bin"),
                PlayerSpellSnapshotLoaderTests.BuildPlayerSpellRecords(
                [
                    PlayerSpellSnapshotLoaderTests.Entry(
                        LegacyLayTrap.TwilightDanceSpellId,
                        level: 4,
                        useSpellSoul: 2),
                ]));

            var worldData = await new JsonWorldDataLoader(new WorldDataOptions(seedPath)).LoadAsync();
            var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
            var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
            using var log = new StringWriter();
            var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(usersRoot), handoff, worldData, log);
            var sent = new List<byte[]>();
            var connection = CreateSendingConnection(sent);

            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));

            var attackStart = sent.Count;
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new MsgAttackPacket(new MsgAttackQuery(
                    Uid: 1_293_600,
                    OpponentUid: 1_293_600,
                    X: 110,
                    Y: 200,
                    AttackType: MsgAttackType.Magic,
                    Damage: 0,
                    KilledMonster: 0,
                    ResponseDamage: 0,
                    Effect: MsgAttackEffect.None,
                    Unknown: 0,
                    SpellId: LegacyLayTrap.TwilightDanceSpellId)).ToFrameBytes()));

            var selfIndex = FindFrameIndexAfter(
                sent,
                attackStart,
                frame => MsgAttackPacket.TryParse(frame, out var packet) &&
                    packet.Query.Uid == 1_293_600U &&
                    packet.Query.OpponentUid == 1_293_600U &&
                    packet.Query.X == 110 &&
                    packet.Query.Y == 200 &&
                    packet.Query.AttackType == MsgAttackType.None &&
                    packet.Query.Damage == 0);
            Assert.True(selfIndex >= attackStart);

            Assert.True(MsgAttackPacket.TryParse(ReadFrame(sent[selfIndex]), out var selfInteraction));
            Assert.Equal((uint)0, selfInteraction.Query.ResponseDamage);
            Assert.Equal(MsgAttackEffect.None, selfInteraction.Query.Effect);

            var expectedCoordinates = LegacyLayTrap
                .SelectTwilightDanceCoordinates(100, 200, 110, 200)
                .Select(coordinate => (coordinate.X, coordinate.Y))
                .ToArray();
            var floorItems = sent
                .Skip(attackStart)
                .Select(bytes =>
                    LegacyFloorItemPacket.TryParse(ReadFrame(bytes), out var packet)
                        ? packet
                        : null)
                .OfType<LegacyFloorItemPacket>()
                .Where(packet =>
                    packet.DropType == LegacyFloorItemDropType.Effect &&
                    packet.ItemId == LegacyLayTrap.TwilightDanceFloorItemId &&
                    packet.ItemOwnerUid == 1_293_600U)
                .ToArray();
            Assert.Equal(3, floorItems.Length);
            Assert.Equal(expectedCoordinates, floorItems.Select(packet => (packet.X, packet.Y)).ToArray());
            Assert.Equal(floorItems[0].Uid + 1, floorItems[1].Uid);
            Assert.Equal(floorItems[1].Uid + 1, floorItems[2].Uid);
            Assert.All(floorItems, packet =>
            {
                Assert.Equal((ushort)0, packet.MaxLife);
                Assert.Equal((uint)0, packet.Life);
                Assert.Equal((byte)0, packet.PlusOrColor);
                Assert.Equal((uint)123, packet.GuildId);
                Assert.Equal((byte)0, packet.FlowerType);
                Assert.Equal((ulong)0, packet.Timer);
                Assert.Equal((ushort)100, packet.OwnerX);
                Assert.Equal((ushort)200, packet.OwnerY);
                Assert.Equal(LegacyLayTrap.TwilightDanceFloorName, packet.Name);
            });

            var spellIndex = FindFrameIndexAfter(
                sent,
                attackStart,
                frame => LegacySpellAnimationPacket.TryParse(frame, out var spell) &&
                    spell.AttackerUid == 1_293_600U &&
                    spell.AttackedUid == 1_293_600U &&
                    spell.X == 110 &&
                    spell.Y == 200 &&
                    spell.SpellId == LegacyLayTrap.TwilightDanceSpellId &&
                    spell.SpellLevel == 4 &&
                    spell.LevelHu == 2 &&
                    spell.Targets.Count == 0);
            Assert.True(spellIndex > selfIndex);
            Assert.True(
                floorItems.All(packet =>
                    FindFrameIndexAfter(
                        sent,
                        selfIndex + 1,
                        frame => LegacyFloorItemPacket.TryParse(frame, out var candidate) &&
                            candidate.Uid == packet.Uid) < spellIndex));
            Assert.Contains("WorldServer handled legacy LayTrap magic", log.ToString());
        }
        finally
        {
            if (Directory.Exists(dbRoot))
            {
                Directory.Delete(dbRoot, recursive: true);
            }
        }
    }

