                    Uid: 1_293_600,
                    OpponentUid: 1_293_600,
                    X: 830,
                    Y: 584,
                    AttackType: MsgAttackType.Magic,
                    Damage: 0,
                    KilledMonster: 0,
                    ResponseDamage: 0,
                    Effect: MsgAttackEffect.None,
                    Unknown: 0,
                    SpellId: 12_280)).ToFrameBytes()));

            Assert.Equal("32", GetSession(handler, teammateConnection).Character.Attributes["Stamina"]);
            Assert.True(FindFrameIndexAfter(
                teammateSent,
                teammateAttackStart,
                frame => LegacyMsgUpdatePacket.TryParse(frame, out var update) &&
                    update.Uid == 1_293_601U &&
                    update.Updates.Any(entry =>
                        entry.Type == LegacyMsgUpdateDataType.Stamina &&
                        entry.Value == 32UL)) >= teammateAttackStart);

            var casterSpellIndex = FindFrameIndexAfter(
                casterSent,
                casterAttackStart,
                frame => LegacySpellAnimationPacket.TryParse(frame, out var spell) &&
                    spell.AttackerUid == 1_293_600U &&
                    spell.SpellId == 12_280 &&
                    spell.Targets.Count == 1 &&
                    spell.Targets[0].Uid == 1_293_601U &&
                    spell.Targets[0].Damage == 0U &&
                    spell.Targets[0].Hit);
            Assert.True(casterSpellIndex >= casterAttackStart);
            Assert.Contains("WorldServer handled legacy DispatchXp magic", log.ToString());
        }
        finally
        {
            if (Directory.Exists(dbRoot))
            {
                Directory.Delete(dbRoot, recursive: true);
            }
        }
    }

