        var spellsRoot = Path.Combine(dbRoot, "PlayersSpells");
        try
        {
            Directory.CreateDirectory(usersRoot);
            Directory.CreateDirectory(spellsRoot);
            WriteSnapshot(usersRoot, 1293600, uid: 1293600, mapId: 1015, x: 830, y: 584, classCode: 5005);
            WriteSnapshot(usersRoot, 1293601, uid: 1293601, mapId: 1015, x: 831, y: 584, name: "Watcher");
            File.WriteAllBytes(
                Path.Combine(spellsRoot, "1293600.bin"),
                PlayerSpellSnapshotLoaderTests.BuildPlayerSpells([12090]));

            var worldData = await new JsonWorldDataLoader(new WorldDataOptions(seedPath)).LoadAsync();
            var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
            var casterTicket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
            var watcherTicket = handoff.Issue(1293601, "watcher", ConquerRuntimeDefaults.WorldServer);
            using var log = new StringWriter();
            var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(usersRoot), handoff, worldData, log);
            var casterSent = new List<byte[]>();
            var watcherSent = new List<byte[]>();
            var casterConnection = CreateSendingConnection(casterSent);
            var watcherConnection = CreateSendingConnection(watcherSent);

            await handler.HandleFrameAsync(
                casterConnection,
                ReadFrame(new InternalWorldEnterRequestPacket(casterTicket.Token).ToFrameBytes()));
            await handler.HandleFrameAsync(
                watcherConnection,
                ReadFrame(new InternalWorldEnterRequestPacket(watcherTicket.Token).ToFrameBytes()));

            var casterAttackStart = casterSent.Count;
            var watcherAttackStart = watcherSent.Count;
            await handler.HandleFrameAsync(
                casterConnection,
                ReadFrame(new MsgAttackPacket(new MsgAttackQuery(
                    Uid: 1_293_600,
                    OpponentUid: 0,
                    X: 830,
                    Y: 584,
                    AttackType: MsgAttackType.Magic,
                    Damage: 0,
                    KilledMonster: 0,
                    ResponseDamage: 0,
                    Effect: MsgAttackEffect.None,
                    Unknown: 0,
                    SpellId: 12_090)).ToFrameBytes()));

            Assert.Equal("3/", GetSession(handler, casterConnection).Character.Attributes["ShadowCloneFlags"]);
            var cloneSpawnIndex = FindFrameIndexAfter(
                casterSent,
                casterAttackStart,
                frame => LegacyPlayerSpawnPacket.TryParse(frame, out var clone) &&
                    clone.GetNumericField(UidField) == 700_101UL &&
                    clone.GetNumericField(OwnerUidField) == 1_293_600UL &&
                    clone.GetNumericField(OwnerPetField) == 2UL &&
                    clone.GetNumericField(OwnerPet1Field) == 3UL);
            var actionIndex = FindFrameIndexAfter(
                casterSent,
                casterAttackStart,
                frame => MsgActionPacket.TryParse(frame, out var action) &&
                    action.ObjId == 700_101U &&
                    action.Type == MsgActionType.MonsterRespawnEffect &&
                    action.PositionX == 830U &&
                    action.PositionY == 584U);
            var spellIndex = FindFrameIndexAfter(
                casterSent,
                casterAttackStart,
                frame => LegacySpellAnimationPacket.TryParse(frame, out var spell) &&
                    spell.AttackerUid == 1_293_600U &&
                    spell.SpellId == 12_090 &&
                    spell.Targets.Count == 0);

            Assert.True(cloneSpawnIndex >= casterAttackStart, log.ToString());
            Assert.True(actionIndex > cloneSpawnIndex, log.ToString());
            Assert.True(spellIndex > actionIndex, log.ToString());
            Assert.True(FindFrameIndexAfter(
                watcherSent,
                watcherAttackStart,
                frame => LegacyPlayerSpawnPacket.TryParse(frame, out var clone) &&
                    clone.GetNumericField(UidField) == 700_101UL) >= watcherAttackStart);
            Assert.Contains("WorldServer handled legacy CallPet magic", log.ToString());
        }
        finally
        {
            if (Directory.Exists(dbRoot))
            {
                Directory.Delete(dbRoot, recursive: true);
            }
        }
    }

