                frame => LegacyMonsterSpawnPacket.TryParse(frame, out var pet) &&
                    pet.Uid == 700_201U) >= watcherAttackStart);
            Assert.DoesNotContain(
                watcherSent.Skip(watcherAttackStart),
                bytes => LegacyPetInfoPacket.TryParse(ReadFrame(bytes), out _));
            Assert.Contains("WorldServer handled legacy CallPet magic", log.ToString());
        }
        finally
        {
            if (Directory.Exists(dbRoot))
            {
                Directory.Delete(dbRoot, recursive: true);
            }
        }
    }

