    public async Task HandlerMagicThundercloudDoubleThunderCreatesNearbySecondProjection()
    {
        var seedPath = Path.Combine(FindRepositoryRoot(), ".setup_work", "seed-json");
        if (!File.Exists(Path.Combine(seedPath, "manifest.json")))
