            Directory.CreateDirectory(spellsRoot);
            WriteSnapshot(
                usersRoot,
                1293600,
                uid: 1293600,
                mapId: 1015,
                x: 830,
                y: 584,
                classCode: 16000,
                extraCharacterLines: "DoubleThunder=1");
            File.WriteAllBytes(
                Path.Combine(spellsRoot, "1293600.bin"),
                PlayerSpellSnapshotLoaderTests.BuildPlayerSpellRecords(
                    [PlayerSpellSnapshotLoaderTests.Entry(12_840, level: 5)]));

            var worldData = await new JsonWorldDataLoader(new WorldDataOptions(seedPath)).LoadAsync();
            var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
            var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
            using var log = new StringWriter();
            var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(usersRoot), handoff, worldData, log);
            var sent = new List<byte[]>();
            var connection = CreateSendingConnection(sent);

            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));

            var attackStart = sent.Count;
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new MsgAttackPacket(new MsgAttackQuery(
                    Uid: 1_293_600,
                    OpponentUid: 0,
                    X: 831,
                    Y: 585,
                    AttackType: MsgAttackType.Magic,
                    Damage: 0,
                    KilledMonster: 0,
                    ResponseDamage: 0,
                    Effect: MsgAttackEffect.None,
                    Unknown: 0,
                    SpellId: 12_840)).ToFrameBytes()));

            var livePets = GetSession(handler, connection).Character.Attributes["LivePets"];
            Assert.Contains(
                "700201,980,9,999996641,140,14,14,Thundercloud,831,585",
                livePets,
                StringComparison.Ordinal);
            var entries = livePets.Split(';', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
            Assert.Equal(2, entries.Length);
            var second = entries[1].Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
            Assert.Equal("700202", second[0]);
            Assert.Equal("Thundercloud", second[7]);
            var secondX = ushort.Parse(second[8], CultureInfo.InvariantCulture);
            var secondY = ushort.Parse(second[9], CultureInfo.InvariantCulture);
            Assert.NotEqual((831, 585), ((int)secondX, (int)secondY));
            Assert.InRange(Math.Abs(secondX - 831), 0, 5);
            Assert.InRange(Math.Abs(secondY - 585), 0, 5);

            var secondPetInfoIndex = FindFrameIndexAfter(
                sent,
                attackStart,
                frame => LegacyPetInfoPacket.TryParse(frame, out var pet) &&
                    pet.Uid == 700_202U &&
                    pet.PetType == 9U &&
                    pet.X == secondX &&
                    pet.Y == secondY &&
                    pet.Name == "Thundercloud");
            var secondSpawnIndex = FindFrameIndexAfter(
                sent,
                attackStart,
                frame => LegacyMonsterSpawnPacket.TryParse(frame, out var pet) &&
                    pet.Uid == 700_202U &&
                    pet.OwnerPet == 3U &&
                    pet.OwnerPet1 == 15U &&
                    pet.X == secondX &&
                    pet.Y == secondY);
            var secondActionIndex = FindFrameIndexAfter(
                sent,
                attackStart,
                frame => MsgActionPacket.TryParse(frame, out var action) &&
                    action.ObjId == 700_202U &&
                    action.Type == MsgActionType.MonsterRespawnEffect &&
                    action.PositionX == secondX &&
                    action.PositionY == secondY);

            Assert.True(secondPetInfoIndex >= attackStart, log.ToString());
            Assert.True(secondSpawnIndex > secondPetInfoIndex, log.ToString());
            Assert.True(secondActionIndex > secondSpawnIndex, log.ToString());
            Assert.Contains("summons=2", log.ToString());
        }
        finally
        {
            if (Directory.Exists(dbRoot))
            {
                Directory.Delete(dbRoot, recursive: true);
            }
        }
    }

    [Fact(Skip = "Requires external game fixtures omitted from the public source snapshot.")]
    public async Task HandlerMagicThundercloudRuntimeExpiresFloorProjectionAndLivePet()
    {
        var seedPath = Path.Combine(FindRepositoryRoot(), ".setup_work", "seed-json");
        if (!File.Exists(Path.Combine(seedPath, "manifest.json")))
        {
            return;
        }

        var dbRoot = Path.Combine(Path.GetTempPath(), "wolf-world-magic-thundercloud-expire-" + Guid.NewGuid());
        var usersRoot = Path.Combine(dbRoot, "Users");
        var spellsRoot = Path.Combine(dbRoot, "PlayersSpells");
        using var cancel = new CancellationTokenSource();
        try
        {
            Directory.CreateDirectory(usersRoot);
            Directory.CreateDirectory(spellsRoot);
            WriteSnapshot(usersRoot, 1293600, uid: 1293600, mapId: 1015, x: 830, y: 584, classCode: 16000);
            File.WriteAllBytes(
                Path.Combine(spellsRoot, "1293600.bin"),
                PlayerSpellSnapshotLoaderTests.BuildPlayerSpells([12840]));

            var worldData = await new JsonWorldDataLoader(new WorldDataOptions(seedPath)).LoadAsync();
            var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
            var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
            using var log = new RuntimeThreadSafeStringWriter();
            var handler = new WorldServerFrameHandler(
                new CharacterSnapshotLoader(usersRoot),
                handoff,
                worldData,
                new LegacyRuntimeUpdateLoopOptions(
                    Enabled: true,
                    TimeSpan.FromMilliseconds(10),
                    new AnchoredRuntimeTimeProvider(DateTimeOffset.UtcNow.AddSeconds(30))),
                log);
            var sent = new RuntimeThreadSafeFrameCapture();
            var connection = CreateSendingConnection(sent);

            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()),
                cancel.Token);

            var attackStart = sent.Count;
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new MsgAttackPacket(new MsgAttackQuery(
                    Uid: 1_293_600,
                    OpponentUid: 0,
                    X: 831,
                    Y: 585,
                    AttackType: MsgAttackType.Magic,
                    Damage: 0,
                    KilledMonster: 0,
                    ResponseDamage: 0,
                    Effect: MsgAttackEffect.None,
                    Unknown: 0,
                    SpellId: 12_840)).ToFrameBytes()),
                cancel.Token);

            await WaitUntilAsync(
                () =>
                {
                    var frames = sent.ToArray().Skip(attackStart).ToArray();
                    var removeSeen = frames.Any(frame =>
                        MsgActionPacket.TryParse(ReadFrame(frame), out var action) &&
                        action.ObjId == 700_201U &&
                        action.Type == MsgActionType.RemoveEntity);
                    return removeSeen &&
                        !GetSession(handler, connection).Character.Attributes.ContainsKey("LivePets");
                },
                TimeSpan.FromSeconds(1));

            Assert.DoesNotContain(
                sent.Skip(attackStart),
                frame => LegacyFloorItemPacket.TryParse(ReadFrame(frame), out var floorItem) &&
                    floorItem.Uid == 700_201U);
            Assert.DoesNotContain(
                sent.Skip(attackStart),
                frame => LegacySpellAnimationPacket.TryParse(ReadFrame(frame), out var spell) &&
                    spell.SpellId == 13_190);
            Assert.Contains("WorldServer handled legacy Thundercloud floor runtime", log.ToString());
        }
        finally
        {
            await cancel.CancelAsync();
            if (Directory.Exists(dbRoot))
            {
                Directory.Delete(dbRoot, recursive: true);
            }
        }
    }

