    [Fact(Skip = "Requires external game fixtures omitted from the public source snapshot.")]
    public async Task HandlerSendsMagicMonsterRetaliationAfterSurvivingPlayerHit()
    {
        var seedPath = Path.Combine(FindRepositoryRoot(), ".setup_work", "seed-json");
        if (!File.Exists(Path.Combine(seedPath, "manifest.json")))
        {
            return;
        }

        var worldData = await new JsonWorldDataLoader(new WorldDataOptions(seedPath)).LoadAsync();
        RaiseSeedMonsterLifeForRetaliationFixture(worldData, "BirdmanMsgr");
        var (magicMonster, monsterFamily) = FindVisibleMagicMonster(worldData, mapId: 1015, name: "BirdmanMsgr");
        var expectedSpellId = ReadTestAttributeUInt32(monsterFamily.Attributes, "magic_type");
        const uint expectedStatusReducedDamage = 180;

        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(1293600, uid: 1293600, mapId: 1015, x: magicMonster.X, y: magicMonster.Y, level: 109);
        WriteSnapshot(1293601, uid: 1293601, mapId: 1015, x: magicMonster.X + 1, y: magicMonster.Y, level: 109, name: "Watcher");
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        var peerTicket = handoff.Issue(1293601, "watcher", ConquerRuntimeDefaults.WorldServer);
        using var log = new StringWriter();
        var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot), handoff, worldData, log);
        var sent = new List<byte[]>();
        var peerSent = new List<byte[]>();
        var connection = CreateSendingConnection(sent);
        var peerConnection = CreateSendingConnection(peerSent);

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));
        await handler.HandleFrameAsync(
            peerConnection,
            ReadFrame(new InternalWorldEnterRequestPacket(peerTicket.Token).ToFrameBytes()));
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new MsgActionPacket
            {
                ObjId = 1_293_600,
                Timestamp = 1234,
                Type = MsgActionType.SetLocation,
            }.ToFrameBytes()));

        var monster = sent.ToArray()
            .Select(bytes => LegacyMonsterSpawnPacket.TryParse(ReadFrame(bytes), out var parsed) ? parsed : null)
            .FirstOrDefault(packet => packet is not null && packet.Uid == magicMonster.Uid);
        Assert.NotNull(monster);
        Assert.Equal("BirdmanMsgr", monster.Names[0]);
        Assert.Equal(magicMonster.X, monster.X);
        Assert.Equal(magicMonster.Y, monster.Y);

        var attackStart = sent.Count;
        var peerStart = peerSent.Count;
        await SendPlayerHitThenScheduledMonsterRetaliationAsync(
            handler,
            connection,
            sent,
            ReadFrame(new MsgAttackPacket(new MsgAttackQuery(
                Uid: 1_293_600,
                OpponentUid: monster.Uid,
                X: monster.X,
                Y: monster.Y,
                AttackType: MsgAttackType.Physical,
                Damage: 1,
                KilledMonster: 0,
                ResponseDamage: 0,
                Effect: MsgAttackEffect.None,
                Unknown: 0)).ToFrameBytes()));

        var (playerHitIndex, playerHit) = AssertServerAppliedSurvivingMonsterPhysicalHitAfter(
            sent,
            attackStart,
            1_293_600U,
            monster,
            log.ToString());

        var spellIndex = FindFrameIndexAfter(
            sent,
            playerHitIndex,
            frame => LegacySpellAnimationPacket.TryParse(frame, out var packet) &&
                packet.AttackerUid == monster.Uid &&
                packet.SpellId == expectedSpellId);
        Assert.True(spellIndex >= playerHitIndex, $"Expected magic monster retaliation frame after player hit. Log={log}");
        Assert.True(LegacySpellAnimationPacket.TryParse(ReadFrame(sent[spellIndex]), out var spell));
        Assert.Equal(monster.Uid, spell.AttackerUid);
        Assert.Equal(0U, spell.AttackedUid);
        Assert.Equal(magicMonster.X, spell.X);
        Assert.Equal(magicMonster.Y, spell.Y);
        Assert.Equal(expectedSpellId, spell.SpellId);
        var target = Assert.Single(spell.Targets);
        Assert.Equal(1_293_600U, target.Uid);
        Assert.Equal(expectedStatusReducedDamage, target.Damage);
        Assert.True(target.Hit);
        Assert.Equal(MsgAttackEffect.None, target.Effect);

        var peerSpellIndex = FindFrameIndexAfter(
            peerSent,
            peerStart,
            frame => LegacySpellAnimationPacket.TryParse(frame, out var packet) &&
                packet.AttackerUid == monster.Uid &&
                packet.Targets.Any(target => target.Uid == 1_293_600U));
        Assert.True(peerSpellIndex >= peerStart);

        var updated = GetSession(handler, connection);
        Assert.Equal(34_636L - expectedStatusReducedDamage, updated.Character.MinHitPoints);
        Assert.Contains(
            sent.Skip(spellIndex + 1),
            bytes =>
            {
                if (!LegacyMsgUpdatePacket.TryParse(ReadFrame(bytes), out var update))
                {
                    return false;
                }

                return update.Uid == 1_293_600U &&
                    update.Updates.Any(entry =>
                        entry.Type == LegacyMsgUpdateDataType.Hitpoints &&
                        entry.Value == (ulong)updated.Character.MinHitPoints);
            });
        Assert.Contains("WorldServer sent legacy magic monster retaliation", log.ToString());
    }

