    [Fact(Skip = "Requires external game fixtures omitted from the public source snapshot.")]
    public async Task HandlerUsesLoadedGearToReduceMagicMonsterRetaliationToOne()
    {
        var seedPath = Path.Combine(FindRepositoryRoot(), ".setup_work", "seed-json");
        var playerItemsRoot = @"data/DBServer\PlayersItems";
        if (!File.Exists(Path.Combine(seedPath, "manifest.json")) ||
            !File.Exists(Path.Combine(playerItemsRoot, "1293600.bin")))
        {
            return;
        }

        var worldData = await new JsonWorldDataLoader(new WorldDataOptions(seedPath)).LoadAsync();
        RaiseSeedMonsterLifeForRetaliationFixture(worldData, "BirdmanMsgr");
        var (magicMonster, monsterFamily) = FindVisibleMagicMonster(worldData, mapId: 1015, name: "BirdmanMsgr");
        var expectedSpellId = ReadTestAttributeUInt32(monsterFamily.Attributes, "magic_type");

        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(
            1293600,
            uid: 1293600,
            mapId: 1015,
            x: magicMonster.X,
            y: magicMonster.Y);
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        using var log = new RuntimeThreadSafeStringWriter();
        using var cancel = new CancellationTokenSource();
        var loader = new CharacterSnapshotLoader(
            _usersRoot,
            playerItemsRoot,
            playerSpellsRoot: null,
            playerProficienciesRoot: null,
            playersCombatGearRoot: null);
        var handler = new WorldServerFrameHandler(
            loader,
            handoff,
            worldData,
            new LegacyRuntimeUpdateLoopOptions(
                Enabled: true,
                TimeSpan.FromMilliseconds(20),
                new AnchoredRuntimeTimeProvider(DateTimeOffset.UtcNow.AddSeconds(20))),
            log);
        var sent = new RuntimeThreadSafeFrameCapture();
        var connection = CreateSendingConnection(sent);

        try
        {
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()),
                cancel.Token);
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new MsgActionPacket
                {
                    ObjId = 1_293_600,
                    Timestamp = 1234,
                    Type = MsgActionType.SetLocation,
                }.ToFrameBytes()),
                cancel.Token);

            var loadedSession = GetSession(handler, connection);
            var refineLevel = LegacyUserTotalRefineLevPacket.FromEquipmentPerfection(
                1_293_600,
                loadedSession.PlayerItems);
            var fields = LegacyPlayerStatusCalculator.CalculateFields(
                loadedSession.Character,
                loadedSession.PlayerItems,
                worldData,
                checked((uint)loadedSession.Character.MinHitPoints),
                refineLevel.Level,
                loadedSession.CombatGear);
            var rawDamage = ReadTestAttributeUInt32(monsterFamily.Attributes, "attack_max");
            var blessedDamage = LegacyCombatDamageCalculator.DecreaseLegacyBless(
                rawDamage,
                fields[LegacyPlayerStatusPacket.ItemBlessIndex]);
            var totalMagicReduction = checked((ulong)fields[LegacyPlayerStatusPacket.MagicDefenceIndex] +
                fields[LegacyPlayerStatusPacket.MagicDamageDecreaseIndex]);
            var expectedDamage = totalMagicReduction >= blessedDamage
                ? 1U
                : blessedDamage - checked((uint)totalMagicReduction);

            Assert.True(fields[LegacyPlayerStatusPacket.MagicDefenceIndex] > 0);
            Assert.Equal(1U, expectedDamage);

            var attackStart = sent.Count;
            await WaitUntilAsync(
                () => FindFrameIndexAfter(
                    sent,
                    attackStart,
                    frame => LegacySpellAnimationPacket.TryParse(frame, out var packet) &&
                        packet.AttackerUid == magicMonster.Uid &&
                        packet.SpellId == expectedSpellId) >= attackStart,
                TimeSpan.FromSeconds(3));

            var spellIndex = FindFrameIndexAfter(
                sent,
                attackStart,
                frame => LegacySpellAnimationPacket.TryParse(frame, out var packet) &&
                    packet.AttackerUid == magicMonster.Uid &&
                    packet.SpellId == expectedSpellId);
            Assert.True(LegacySpellAnimationPacket.TryParse(ReadFrame(sent[spellIndex]), out var spell));
            var target = Assert.Single(spell.Targets);
            Assert.Equal(1_293_600U, target.Uid);
            Assert.Equal(expectedDamage, target.Damage);
            Assert.True(target.Hit);

            var updated = GetSession(handler, connection);
            Assert.Equal(loadedSession.Character.MinHitPoints - expectedDamage, updated.Character.MinHitPoints);
            await WaitUntilAsync(
                () => log.ToString().Contains("WorldServer sent proactive monster attacks", StringComparison.Ordinal),
                TimeSpan.FromSeconds(1));
            var output = log.ToString();
            Assert.Contains("WorldServer sent proactive monster attacks", output);
            Assert.Contains("WorldServer sent legacy magic monster retaliation", output);
        }
        finally
        {
            await cancel.CancelAsync();
        }
    }

