            {
                ["life"] = "500000",
                ["lookface"] = "9401",
                ["level"] = "0100",
                ["attack_range"] = "0015",
                ["view_range"] = "0015",
                ["attack_speed"] = "1",
                ["move_speed"] = "1",
                ["attack_min"] = "1000",
                ["attack_max"] = "1000",
                ["magic_type"] = "0000",
            },
            []);
        var spawn = new MonsterSpawn(
            GeneratorId: 9401,
            MapId: 1015,
            MonsterTypeId: 9401,
            BoundX: 100,
            BoundY: 100,
            BoundWidth: 1,
            BoundHeight: 1,
            MaxNpc: 1,
            RestSeconds: 10,
            MaxPerGenerator: 1,
            TimerBegin: 0,
            TimerEnd: 0,
            BornX: 0,
            BornY: 0,
            SourceMapFolderId: 1015,
            SourceMonsterName: "NonBossExtra",
            SourceRelativePath: Path.Combine("1015", "NonBossExtra", "1.ini"),
            Attributes: new Dictionary<string, string>
            {
                ["id"] = "9401",
                ["mapid"] = "1015",
                ["npctype"] = "9401",
            });
        var worldData = MsgTeamRuntimeTests.CreateTeamArenaRewardCatalog(
            monsters: [monsterFamily],
            monsterSpawns: [spawn]);
        var monsterInstance = Assert.Single(LegacyMonsterInstance.FromGenerator(
            spawn,
            monsterFamily,
            worldData.GetLegacyMonsterRuntimeUidBase(spawn)));
        Assert.False(monsterInstance.Boss);
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        var tickInterval = TimeSpan.FromMilliseconds(100);
        var timeProvider = new BossRuntimeManualTimeProvider(DateTimeOffset.UtcNow.AddSeconds(20));
        using var log = new RuntimeThreadSafeStringWriter();
        using var cancel = new CancellationTokenSource();
        var handler = new WorldServerFrameHandler(
            new CharacterSnapshotLoader(_usersRoot),
            handoff,
            worldData,
            CreateDeterministicMonsterRuntimeLoopOptions(tickInterval, timeProvider),
            log);
        var sent = new RuntimeThreadSafeFrameCapture();
        var connection = CreateSendingConnection(sent);

        try
        {
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()),
                cancel.Token);
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new MsgActionPacket
                {
                    ObjId = 1_293_600,
                    Timestamp = 1234,
                    Type = MsgActionType.SetLocation,
                }.ToFrameBytes()),
                cancel.Token);
            await WaitForMonsterRuntimeTimerRegistrationAsync(timeProvider);

            var monster = sent.ToArray()
                .Select(bytes => LegacyMonsterSpawnPacket.TryParse(ReadFrame(bytes), out var parsed) ? parsed : null)
                .FirstOrDefault(packet => packet is not null && packet.Uid == monsterInstance.Uid);
            Assert.NotNull(monster);

            var attackStart = sent.Count;
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new MsgAttackPacket(new MsgAttackQuery(
                    Uid: 1_293_600,
                    OpponentUid: monster.Uid,
                    X: monster.X,
                    Y: monster.Y,
                    AttackType: MsgAttackType.Physical,
                    Damage: 1,
                    KilledMonster: 0,
                    ResponseDamage: 0,
                    Effect: MsgAttackEffect.None,
                    Unknown: 0)).ToFrameBytes()),
                cancel.Token);

            var (playerHitIndex, _) = AssertServerAppliedSurvivingMonsterPhysicalHitAfter(
                sent,
                attackStart,
                1_293_600U,
                monster,
                log.ToString());
            var scheduledAttackStart = playerHitIndex + 1;
            var hitpointsBeforeScheduledAttack = GetSession(handler, connection).Character.MinHitPoints;
            bool HasScheduledSpell()
            {
                return FindFrameIndexAfter(
                    sent,
                    scheduledAttackStart,
                    frame => LegacySpellAnimationPacket.TryParse(frame, out var spell) &&
                        spell.AttackerUid == monster.Uid &&
                        spell.SpellId == 9999) >= scheduledAttackStart;
            }

            Assert.False(
                HasScheduledSpell(),
                $"Player-hit handling sent an immediate ExtraBoss spell. Log={log}");
            timeProvider.Advance(tickInterval);
            await WaitForProactiveMonsterActionAsync(HasScheduledSpell, log);

            var spellIndex = FindFrameIndexAfter(
                sent,
                scheduledAttackStart,
                frame => LegacySpellAnimationPacket.TryParse(frame, out var spell) &&
                    spell.AttackerUid == monster.Uid &&
                    spell.SpellId == 9999);
            Assert.True(LegacySpellAnimationPacket.TryParse(ReadFrame(sent[spellIndex]), out var extraBossSpell));
            Assert.Equal(monster.Uid, extraBossSpell.AttackerUid);
            Assert.Equal(0U, extraBossSpell.AttackedUid);
            Assert.Equal(9999, extraBossSpell.SpellId);
            var spellTarget = Assert.Single(extraBossSpell.Targets);
            Assert.Equal(1_293_600U, spellTarget.Uid);
            Assert.True(spellTarget.Damage > 0);
            Assert.DoesNotContain(
                sent.ToArray().Skip(scheduledAttackStart),
                bytes => MsgAttackPacket.TryParse(ReadFrame(bytes), out var packet) &&
                    packet.Query.Uid == monster.Uid &&
                    packet.Query.OpponentUid == 1_293_600U &&
                    packet.Query.AttackType == MsgAttackType.Physical);
            var updated = GetSession(handler, connection);
            Assert.Equal(
                hitpointsBeforeScheduledAttack - spellTarget.Damage,
                updated.Character.MinHitPoints);
            Assert.Contains("WorldServer sent legacy magic monster retaliation", log.ToString());
        }
        finally
        {
            await cancel.CancelAsync();
        }
    }

    [Fact]
    public async Task HandlerRuntimeLoopSendsBossAreaDeathSideEffectsBeforeSharedSpellAnimation()
    {
        const int DeadFlag = 0x05;
        const int GhostFlag = 0x0A;
        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(
            1293600,
            uid: 1293600,
            mapId: 1002,
            x: 94,
            y: 354,
            minHitPoints: 10,
            extraCharacterLines:
                "PkMode=1\r\n" +
                "LegacyBossSpellIndex=0\r\n");
        var monsterFamily = new Monster(
            213883,
            "AreaBoss",
            new Dictionary<string, string>
            {
                ["life"] = "70000",
                ["lookface"] = "900",
                ["level"] = "120",
                ["defense"] = "0",
                ["defense2"] = "10000",
                ["attack_min"] = "50000",
                ["attack_max"] = "50000",
                ["attack_range"] = "18",
                ["Boss"] = "1",
            },
            []);
        var spawn = new MonsterSpawn(
            GeneratorId: 2,
            MapId: 1002,
            MonsterTypeId: 213883,
            BoundX: 94,
            BoundY: 354,
            BoundWidth: 1,
            BoundHeight: 1,
            MaxNpc: 1,
            RestSeconds: 10,
            MaxPerGenerator: 1,
            TimerBegin: 0,
            TimerEnd: 0,
            BornX: 0,
            BornY: 0,
            SourceMapFolderId: 1002,
            SourceMonsterName: "AreaBoss",
            SourceRelativePath: Path.Combine("1002", "AreaBoss", "1.ini"),
            Attributes: new Dictionary<string, string>
            {
                ["id"] = "2",
                ["mapid"] = "1002",
                ["npctype"] = "213883",
            });
        var worldData = MsgTeamRuntimeTests.CreateTeamArenaRewardCatalog(
            monsters: [monsterFamily],
            monsterSpawns: [spawn]);
        var monster = Assert.Single(LegacyMonsterInstance.FromGenerator(
            spawn,
            monsterFamily,
            worldData.GetLegacyMonsterRuntimeUidBase(spawn)));
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        var tickInterval = TimeSpan.FromMilliseconds(100);
        var timeProvider = new BossRuntimeManualTimeProvider(DateTimeOffset.UtcNow.AddSeconds(20));
        using var log = new RuntimeThreadSafeStringWriter();
        using var cancel = new CancellationTokenSource();
        var handler = new WorldServerFrameHandler(
            new CharacterSnapshotLoader(_usersRoot),
            handoff,
            worldData,
            CreateDeterministicMonsterRuntimeLoopOptions(tickInterval, timeProvider),
            log);
        var sent = new RuntimeThreadSafeFrameCapture();
        var connection = CreateSendingConnection(sent);

        try
        {
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()),
                cancel.Token);
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new MsgActionPacket
                {
                    ObjId = 1_293_600,
                    Timestamp = 1234,
                    Type = MsgActionType.SetLocation,
                }.ToFrameBytes()),
                cancel.Token);
            await WaitForMonsterRuntimeTimerRegistrationAsync(timeProvider);

            var attackStart = sent.Count;
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new MsgAttackPacket(new MsgAttackQuery(
                    Uid: 1_293_600,
                    OpponentUid: monster.Uid,
                    X: monster.X,
                    Y: monster.Y,
                    AttackType: MsgAttackType.Physical,
                    Damage: 1,
                    KilledMonster: 0,
                    ResponseDamage: 0,
                    Effect: MsgAttackEffect.None,
                    Unknown: 0)).ToFrameBytes()),
                cancel.Token);

            var monsterSpawn = sent.ToArray()
                .Select(bytes => LegacyMonsterSpawnPacket.TryParse(ReadFrame(bytes), out var parsed) ? parsed : null)
                .FirstOrDefault(packet => packet is not null && packet.Uid == monster.Uid);
            Assert.NotNull(monsterSpawn);
            var (playerHitIndex, _) = AssertServerAppliedSurvivingMonsterPhysicalHitAfter(
                sent,
                attackStart,
                1_293_600U,
                monsterSpawn,
                log.ToString());
            var scheduledAttackStart = playerHitIndex + 1;
            bool HasAreaSpell()
            {
                return FindFrameIndexAfter(
                    sent,
                    scheduledAttackStart,
                    frame => LegacySpellAnimationPacket.TryParse(frame, out var spell) &&
                        spell.AttackerUid == monster.Uid &&
                        spell.SpellId == 7_013 &&
                        spell.Targets.Any(target => target.Uid == 1_293_600U && target.Damage >= 10)) >= scheduledAttackStart;
            }

            Assert.False(
                HasAreaSpell(),
                $"Player-hit handling sent an immediate boss area spell. Log={log}");
            timeProvider.Advance(tickInterval);
            await WaitForProactiveMonsterActionAsync(HasAreaSpell, log);

            var hitpointsIndex = FindFrameIndexAfter(
                sent,
                scheduledAttackStart,
                frame => LegacyMsgUpdatePacket.TryParse(frame, out var update) &&
                    update.Uid == 1_293_600U &&
                    update.Updates.Any(entry =>
                        entry.Type == LegacyMsgUpdateDataType.Hitpoints &&
                        entry.Value == 0));
            Assert.True(
                hitpointsIndex >= scheduledAttackStart,
                $"Expected lethal hitpoints update from scheduled boss area attack. Log={log}");

            var deadTalkIndex = FindFrameIndexAfter(
                sent,
                hitpointsIndex + 1,
                frame => LegacyMsgMessagePacket.TryParse(frame, out var message) &&
                    message.ChatType == LegacyMsgMessagePacket.TalkChatType &&
                    message.Color == LegacyMsgMessagePacket.RedColor &&
                    message.Content.Count > 3 &&
                    message.Content[3] == LegacyPlayerDeathState.DeadTalkText);
            Assert.True(deadTalkIndex > hitpointsIndex, $"Expected dead talk after lethal hitpoints update. Log={log}");

            var statusIndex = FindFrameIndexAfter(
                sent,
                deadTalkIndex + 1,
                frame => LegacyMsgUpdatePacket.TryParse(frame, out var update) &&
                    update.Uid == 1_293_600U &&
                    update.Updates.Count == 1 &&
                    update.Updates[0].Type == LegacyMsgUpdateDataType.StatusFlag &&
                    update.Updates[0].Values is { } statusFlags &&
                    HasLegacyStatusFlag(statusFlags, DeadFlag) &&
                    !HasLegacyStatusFlag(statusFlags, GhostFlag));
            Assert.True(statusIndex > deadTalkIndex, $"Expected dead status after dead talk. Log={log}");

            var deathIndex = FindFrameIndexAfter(
                sent,
                statusIndex + 1,
                frame => MsgAttackPacket.TryParse(frame, out var packet) &&
                    packet.Query.Uid == monster.Uid &&
                    packet.Query.OpponentUid == 1_293_600U &&
                    packet.Query.AttackType == MsgAttackType.Death);
            Assert.True(deathIndex > statusIndex, $"Expected death attack after dead status. Log={log}");

            var spellIndex = FindFrameIndexAfter(
                sent,
                scheduledAttackStart,
                frame => LegacySpellAnimationPacket.TryParse(frame, out var spell) &&
                    spell.AttackerUid == monster.Uid &&
                    spell.SpellId == 7_013 &&
                    spell.Targets.Any(target => target.Uid == 1_293_600U && target.Damage >= 10));
            Assert.True(
                spellIndex > deathIndex,
                $"Expected shared boss area spell animation after per-target death side effects. " +
                $"hitpointsIndex={hitpointsIndex} deadTalkIndex={deadTalkIndex} statusIndex={statusIndex} " +
                $"deathIndex={deathIndex} spellIndex={spellIndex}. Log={log}");

            var updated = GetSession(handler, connection);
            Assert.Equal(0, updated.Character.MinHitPoints);
            Assert.True(HasLegacyStatusFlag(
                LegacyPlayerSpawnPacket.FromSnapshot(updated.Character).StatusFlags,
                DeadFlag));
            Assert.False(HasLegacyStatusFlag(
                LegacyPlayerSpawnPacket.FromSnapshot(updated.Character).StatusFlags,
                GhostFlag));
            Assert.True(updated.Character.Attributes.ContainsKey(LegacyPlayerDeathState.DeadStampAttribute));
            Assert.True(updated.Character.Attributes.ContainsKey(LegacyPlayerDeathState.GhostStampAttribute));
            Assert.Equal("94", updated.Character.Attributes[LegacyPlayerDeathState.DeadXAttribute]);
            Assert.Equal("354", updated.Character.Attributes[LegacyPlayerDeathState.DeadYAttribute]);
            Assert.Equal(monster.Uid.ToString(CultureInfo.InvariantCulture), updated.Character.Attributes[LegacyPlayerDeathState.DeadKillerUidAttribute]);
            Assert.Equal("AreaBoss", updated.Character.Attributes[LegacyPlayerDeathState.DeadKillerNameAttribute]);
            Assert.Contains("WorldServer sent legacy boss area physical spell retaliation", log.ToString());
        }
        finally
        {
            await cancel.CancelAsync();
        }
    }

    [Fact(Skip = "Requires external game fixtures omitted from the public source snapshot.")]
    public async Task HandlerAwardsSourceAdjustedMonsterExperienceAfterPlayerHit()
    {
        var seedPath = Path.Combine(FindRepositoryRoot(), ".setup_work", "seed-json");
        if (!File.Exists(Path.Combine(seedPath, "manifest.json")))
        {
            return;
        }

        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(1293600, uid: 1293600, mapId: 1015, x: 837, y: 573, level: 84);
        var worldData = await new JsonWorldDataLoader(new WorldDataOptions(seedPath)).LoadAsync();
        RaiseSeedMonsterLifeForRetaliationFixture(worldData, "Birdman");
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        using var log = new StringWriter();
        var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot), handoff, worldData, log);
        var sent = new List<byte[]>();
        var connection = CreateSendingConnection(sent);

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new MsgActionPacket
            {
                ObjId = 1_293_600,
                Timestamp = 1234,
                Type = MsgActionType.SetLocation,
            }.ToFrameBytes()));

        var monster = sent.ToArray()
            .Select(bytes => LegacyMonsterSpawnPacket.TryParse(ReadFrame(bytes), out var parsed) ? parsed : null)
            .FirstOrDefault(packet => packet is not null &&
                packet.Names[0] == "Birdman" &&
                packet.Level == 87 &&
                packet.X == 837 &&
                packet.Y == 573);
        Assert.NotNull(monster);

        var attackStart = sent.Count;
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new MsgAttackPacket(new MsgAttackQuery(
                Uid: 1_293_600,
                OpponentUid: monster.Uid,
                X: monster.X,
                Y: monster.Y,
                AttackType: MsgAttackType.Physical,
                Damage: 100,
                KilledMonster: 0,
                ResponseDamage: 0,
                Effect: MsgAttackEffect.None,
                Unknown: 0)).ToFrameBytes()));

        Assert.True(MsgAttackPacket.TryParse(ReadFrame(sent[attackStart]), out var playerHit));
        AssertServerAppliedSurvivingMonsterPhysicalHit(playerHit, monster);
        var expectedExperience = CalculateExpectedMonsterAttackExperience(
            playerHit.Query.Damage,
            attackerLevel: 84,
            monster.Level,
            mapId: 1015);

        var updated = GetSession(handler, connection);
        Assert.Equal(84, updated.Character.Level);
        Assert.Equal(checked((long)expectedExperience), updated.Character.Experience);
        Assert.Contains(
            sent.Skip(attackStart + 1),
            bytes =>
            {
                if (!LegacyMsgUpdatePacket.TryParse(ReadFrame(bytes), out var update))
                {
                    return false;
                }

                if (update.Updates.Count != 1)
                {
                    return false;
                }

                var entry = update.Updates[0];
                return update.Uid == 1_293_600U &&
                    entry.Type == LegacyMsgUpdateDataType.Experience &&
                    entry.Value == expectedExperience;
            });
        Assert.Contains("WorldServer sent legacy monster experience", log.ToString());
    }

    [Fact(Skip = "Requires external game fixtures omitted from the public source snapshot.")]
    public async Task HandlerSharesLegacyMonsterDeathExperienceWithNearbyTeammate()
    {
        var seedPath = Path.Combine(FindRepositoryRoot(), ".setup_work", "seed-json");
        if (!File.Exists(Path.Combine(seedPath, "manifest.json")))
        {
            return;
        }

        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(1293600, uid: 1293600, mapId: 1015, x: 837, y: 573, level: 84, strength: 20_000);
        WriteSnapshot(1293601, uid: 1293601, mapId: 1015, x: 842, y: 573, level: 84, name: "Teammate");
        var worldData = await new JsonWorldDataLoader(new WorldDataOptions(seedPath)).LoadAsync();
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        var teammateTicket = handoff.Issue(1293601, "teammate", ConquerRuntimeDefaults.WorldServer);
        using var log = new StringWriter();
        var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot), handoff, worldData, log);
        var sent = new List<byte[]>();
        var teammateSent = new List<byte[]>();
        var connection = CreateSendingConnection(sent);
        var teammateConnection = CreateSendingConnection(teammateSent);

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));
        await handler.HandleFrameAsync(
            teammateConnection,
            ReadFrame(new InternalWorldEnterRequestPacket(teammateTicket.Token).ToFrameBytes()));
        await handler.HandleFrameAsync(connection, ReadFrame(new MsgTeamPacket(MsgTeamType.Create, 0).ToFrameBytes()));
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new MsgTeamPacket(MsgTeamType.InviteRequest, 1293601).ToFrameBytes()));
        await handler.HandleFrameAsync(
            teammateConnection,
            ReadFrame(new MsgTeamPacket(MsgTeamType.AcceptInvitation, 1293600).ToFrameBytes()));
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new MsgActionPacket
            {
                ObjId = 1_293_600,
                Timestamp = 1234,
                Type = MsgActionType.SetLocation,
            }.ToFrameBytes()));

        var monster = FindVisibleMonster(worldData, mapId: 1015, name: "Birdman", x: 837, y: 573);
        var attackStart = sent.Count;
        var teammateAttackStart = teammateSent.Count;
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new MsgAttackPacket(new MsgAttackQuery(
                Uid: 1_293_600,
                OpponentUid: monster.Uid,
                X: monster.X,
                Y: monster.Y,
                AttackType: MsgAttackType.Physical,
                Damage: 9_000,
                KilledMonster: 0,
                ResponseDamage: 0,
                Effect: MsgAttackEffect.None,
                Unknown: 0)).ToFrameBytes()));

        var deathIndex = FindFrameIndexAfter(
            sent,
            attackStart,
            frame => MsgAttackPacket.TryParse(frame, out var death) &&
                death.Query.OpponentUid == monster.Uid &&
                death.Query.AttackType == MsgAttackType.Death);
        Assert.True(deathIndex >= attackStart, log.ToString());

        var expectedShare = LegacyMonsterTeamExperienceShare.CalculateBaseShare(checked((int)monster.MaxLife));
        var teammate = GetSession(handler, teammateConnection);
        Assert.Equal(84, teammate.Character.Level);
        Assert.Equal((long)expectedShare, teammate.Character.Experience);
        Assert.Contains(
            teammateSent.Skip(teammateAttackStart),
            bytes =>
            {
                if (!LegacyMsgUpdatePacket.TryParse(ReadFrame(bytes), out var update) ||
                    update.Uid != 1_293_601U ||
                    update.Updates.Count != 1)
                {
                    return false;
                }

                var entry = update.Updates[0];
                return entry.Type == LegacyMsgUpdateDataType.Experience &&
                    entry.Value == checked((ulong)expectedShare);
            });
        Assert.Contains("WorldServer sent legacy monster team experience", log.ToString());
    }

    [Fact(Skip = "Requires external game fixtures omitted from the public source snapshot.")]
    public async Task HandlerSendsPlayerDeathWhenMonsterRetaliationIsLethal()
    {
        const int DeadFlag = 0x05;
        const int GhostFlag = 0x0A;
        var seedPath = Path.Combine(FindRepositoryRoot(), ".setup_work", "seed-json");
        if (!File.Exists(Path.Combine(seedPath, "manifest.json")))
        {
            return;
        }

        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(1293600, uid: 1293600, mapId: 1015, x: 837, y: 573, minHitPoints: 500);
        WriteSnapshot(1293601, uid: 1293601, mapId: 1015, x: 842, y: 573, name: "Watcher");
        var worldData = await new JsonWorldDataLoader(new WorldDataOptions(seedPath)).LoadAsync();
        RaiseSeedMonsterLifeForRetaliationFixture(worldData, "Birdman");
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        var peerTicket = handoff.Issue(1293601, "watcher", ConquerRuntimeDefaults.WorldServer);
        using var log = new StringWriter();
        var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot), handoff, worldData, log);
        var sent = new List<byte[]>();
        var peerSent = new List<byte[]>();
        var connection = CreateSendingConnection(sent);
        var peerConnection = CreateSendingConnection(peerSent);

        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));
        await handler.HandleFrameAsync(
            peerConnection,
            ReadFrame(new InternalWorldEnterRequestPacket(peerTicket.Token).ToFrameBytes()));
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new MsgActionPacket
            {
                ObjId = 1_293_600,
                Timestamp = 1234,
                Type = MsgActionType.SetLocation,
            }.ToFrameBytes()));

        var monster = sent.ToArray()
            .Select(bytes => LegacyMonsterSpawnPacket.TryParse(ReadFrame(bytes), out var parsed) ? parsed : null)
            .FirstOrDefault(packet => packet is not null &&
                packet.Names[0] == "Birdman" &&
                packet.X == 837 &&
                packet.Y == 573);
        Assert.NotNull(monster);

        var attackStart = sent.Count;
        var peerStart = peerSent.Count;
        await SendPlayerHitThenScheduledMonsterRetaliationAsync(
            handler,
            connection,
            sent,
            ReadFrame(new MsgAttackPacket(new MsgAttackQuery(
                Uid: 1_293_600,
                OpponentUid: monster.Uid,
                X: monster.X,
                Y: monster.Y,
                AttackType: MsgAttackType.Physical,
                Damage: 1,
                KilledMonster: 0,
                ResponseDamage: 0,
                Effect: MsgAttackEffect.None,
                Unknown: 0)).ToFrameBytes()));

        var playerHitIndex = FindFrameIndexAfter(
            sent,
            attackStart,
            frame => MsgAttackPacket.TryParse(frame, out var packet) &&
                packet.Query.Uid == 1_293_600U &&
                packet.Query.OpponentUid == monster.Uid &&
                packet.Query.AttackType == MsgAttackType.Physical);
        Assert.True(playerHitIndex >= attackStart, $"Expected player monster hit. Log={log}");
        Assert.True(MsgAttackPacket.TryParse(ReadFrame(sent[playerHitIndex]), out var playerHit));
        AssertServerAppliedSurvivingMonsterPhysicalHit(playerHit, monster);

        var retaliationIndex = FindFrameIndexAfter(
            sent,
            playerHitIndex + 1,
            frame => MsgAttackPacket.TryParse(frame, out var packet) &&
                packet.Query.Uid == monster.Uid &&
                packet.Query.OpponentUid == 1_293_600U &&
                packet.Query.AttackType == MsgAttackType.Physical);
        Assert.True(retaliationIndex > attackStart, $"Expected monster retaliation frame after player hit. Log={log}");
        Assert.True(MsgAttackPacket.TryParse(ReadFrame(sent[retaliationIndex]), out var retaliation));
        Assert.Equal(monster.Uid, retaliation.Query.Uid);
        Assert.Equal(1_293_600U, retaliation.Query.OpponentUid);
        Assert.Equal(837, retaliation.Query.X);
        Assert.Equal(573, retaliation.Query.Y);
        Assert.Equal(MsgAttackType.Physical, retaliation.Query.AttackType);
        Assert.Equal(1_462, retaliation.Query.Damage);
        Assert.Equal(0, retaliation.Query.KilledMonster);

        var deadTalkIndex = FindFrameIndexAfter(
            sent,
            retaliationIndex + 1,
            frame => LegacyMsgMessagePacket.TryParse(frame, out var message) &&
                message.ChatType == LegacyMsgMessagePacket.TalkChatType &&
                message.Color == LegacyMsgMessagePacket.RedColor &&
                message.Content.Count > 3 &&
                message.Content[3] == LegacyPlayerDeathState.DeadTalkText);
        Assert.True(deadTalkIndex > retaliationIndex, $"Expected dead talk after retaliation. Log={log}");
        Assert.True(LegacyMsgMessagePacket.TryParse(ReadFrame(sent[deadTalkIndex]), out var deadTalk));
        Assert.Equal(LegacyMsgMessagePacket.TalkChatType, deadTalk.ChatType);
        Assert.Equal(LegacyMsgMessagePacket.RedColor, deadTalk.Color);
        Assert.Equal(LegacyPlayerDeathState.DeadTalkText, deadTalk.Content[3]);

        var maxHitpointsIndex = FindFrameIndexAfter(
            sent,
            retaliationIndex + 1,
            frame => LegacyMsgUpdatePacket.TryParse(frame, out var update) &&
                update.Uid == 1_293_600U &&
                update.Updates.Count == 1 &&
                update.Updates[0].Type == LegacyMsgUpdateDataType.MaxHitpoints);
        Assert.True(maxHitpointsIndex > deadTalkIndex, $"Expected first max hitpoints update after dead talk. Log={log}");
        Assert.True(LegacyMsgUpdatePacket.TryParse(ReadFrame(sent[maxHitpointsIndex]), out var maxHitpoints));
        Assert.Equal(1_293_600U, maxHitpoints.Uid);
        var maxHitpointUpdate = Assert.Single(maxHitpoints.Updates);
        Assert.Equal(LegacyMsgUpdateDataType.MaxHitpoints, maxHitpointUpdate.Type);
        Assert.True(maxHitpointUpdate.Value >= 500);

        var hitpointsIndex = FindFrameIndexAfter(
            sent,
            maxHitpointsIndex + 1,
            frame => LegacyMsgUpdatePacket.TryParse(frame, out var update) &&
                update.Uid == 1_293_600U &&
                update.Updates.Count == 2 &&
                update.Updates[0].Type == LegacyMsgUpdateDataType.MaxHitpoints &&
                update.Updates[0].Value == maxHitpointUpdate.Value &&
                update.Updates[1].Type == LegacyMsgUpdateDataType.Hitpoints &&
                update.Updates[1].Value == 0);
        Assert.True(hitpointsIndex > maxHitpointsIndex, $"Expected lethal hitpoints update after max hitpoints update. Log={log}");
        Assert.True(LegacyMsgUpdatePacket.TryParse(ReadFrame(sent[hitpointsIndex]), out var hitpoints));
        Assert.Equal(1_293_600U, hitpoints.Uid);
        Assert.Equal(
            [
                new LegacyMsgUpdateEntry(LegacyMsgUpdateDataType.MaxHitpoints, maxHitpointUpdate.Value),
                new LegacyMsgUpdateEntry(LegacyMsgUpdateDataType.Hitpoints, 0),
            ],
            hitpoints.Updates);

        var statusIndex = FindFrameIndexAfter(
            sent,
            hitpointsIndex + 1,
            frame => LegacyMsgUpdatePacket.TryParse(frame, out var update) &&
                update.Uid == 1_293_600U &&
                update.Updates.Count == 1 &&
                update.Updates[0].Type == LegacyMsgUpdateDataType.StatusFlag &&
                update.Updates[0].Values is { } statusFlags &&
                HasLegacyStatusFlag(statusFlags, DeadFlag) &&
                !HasLegacyStatusFlag(statusFlags, GhostFlag));
        Assert.True(statusIndex > hitpointsIndex, $"Expected dead status after lethal hitpoints update. Log={log}");
        Assert.True(LegacyMsgUpdatePacket.TryParse(ReadFrame(sent[statusIndex]), out var status));
        Assert.Equal(1_293_600U, status.Uid);
        var statusUpdate = Assert.Single(status.Updates);
        Assert.Equal(LegacyMsgUpdateDataType.StatusFlag, statusUpdate.Type);
        Assert.NotNull(statusUpdate.Values);
        Assert.True(HasLegacyStatusFlag(statusUpdate.Values, DeadFlag));
        Assert.False(HasLegacyStatusFlag(statusUpdate.Values, GhostFlag));

        var deathIndex = FindFrameIndexAfter(
            sent,
            statusIndex + 1,
            frame => MsgAttackPacket.TryParse(frame, out var packet) &&
                packet.Query.Uid == monster.Uid &&
                packet.Query.OpponentUid == 1_293_600U &&
                packet.Query.AttackType == MsgAttackType.Death);
        Assert.True(deathIndex > statusIndex, $"Expected death attack after dead status. Log={log}");
        Assert.True(MsgAttackPacket.TryParse(ReadFrame(sent[deathIndex]), out var death));
        Assert.Equal(monster.Uid, death.Query.Uid);
        Assert.Equal(1_293_600U, death.Query.OpponentUid);
        Assert.Equal(837, death.Query.X);
        Assert.Equal(573, death.Query.Y);
        Assert.Equal(MsgAttackType.Death, death.Query.AttackType);
        Assert.Equal(0, death.Query.Damage);
        Assert.Equal(0, death.Query.KilledMonster);

        var peerRetaliationIndex = FindFrameIndexAfter(
            peerSent,
            peerStart,
            frame => MsgAttackPacket.TryParse(frame, out var packet) &&
                packet.Query.Uid == monster.Uid &&
                packet.Query.OpponentUid == 1_293_600U &&
                packet.Query.AttackType == MsgAttackType.Physical);
        Assert.True(peerRetaliationIndex >= peerStart, $"Expected peer retaliation frame. Log={log}");
        Assert.True(MsgAttackPacket.TryParse(ReadFrame(peerSent[peerRetaliationIndex]), out var peerRetaliation));
        Assert.Equal(MsgAttackType.Physical, peerRetaliation.Query.AttackType);
        Assert.Equal(monster.Uid, peerRetaliation.Query.Uid);
        Assert.Equal(1_293_600U, peerRetaliation.Query.OpponentUid);

        var peerStatusIndex = FindFrameIndexAfter(
            peerSent,
            peerRetaliationIndex + 1,
            frame => LegacyMsgUpdatePacket.TryParse(frame, out var update) &&
                update.Uid == 1_293_600U &&
                update.Updates.Count == 1 &&
                update.Updates[0].Type == LegacyMsgUpdateDataType.StatusFlag &&
                update.Updates[0].Values is { } statusFlags &&
                HasLegacyStatusFlag(statusFlags, DeadFlag) &&
                !HasLegacyStatusFlag(statusFlags, GhostFlag));
        Assert.True(peerStatusIndex > peerRetaliationIndex, $"Expected peer dead status after peer retaliation. Log={log}");
        Assert.True(LegacyMsgUpdatePacket.TryParse(ReadFrame(peerSent[peerStatusIndex]), out var peerStatus));
        Assert.Equal(1_293_600U, peerStatus.Uid);
        var peerStatusUpdate = Assert.Single(peerStatus.Updates);
        Assert.Equal(LegacyMsgUpdateDataType.StatusFlag, peerStatusUpdate.Type);
        Assert.NotNull(peerStatusUpdate.Values);
        Assert.True(HasLegacyStatusFlag(peerStatusUpdate.Values, DeadFlag));
        Assert.False(HasLegacyStatusFlag(peerStatusUpdate.Values, GhostFlag));

        var peerDeathIndex = FindFrameIndexAfter(
            peerSent,
            peerStatusIndex + 1,
            frame => MsgAttackPacket.TryParse(frame, out var packet) &&
                packet.Query.Uid == monster.Uid &&
                packet.Query.OpponentUid == 1_293_600U &&
                packet.Query.AttackType == MsgAttackType.Death);
        Assert.True(peerDeathIndex > peerStatusIndex, $"Expected peer death attack after peer dead status. Log={log}");
        Assert.True(MsgAttackPacket.TryParse(ReadFrame(peerSent[peerDeathIndex]), out var peerDeath));
        Assert.Equal(monster.Uid, peerDeath.Query.Uid);
        Assert.Equal(1_293_600U, peerDeath.Query.OpponentUid);
        Assert.Equal(MsgAttackType.Death, peerDeath.Query.AttackType);

        var updated = GetSession(handler, connection);
        Assert.Equal(0, updated.Character.MinHitPoints);
        Assert.True(HasLegacyStatusFlag(
            LegacyPlayerSpawnPacket.FromSnapshot(updated.Character).StatusFlags,
            DeadFlag));
        Assert.False(HasLegacyStatusFlag(
            LegacyPlayerSpawnPacket.FromSnapshot(updated.Character).StatusFlags,
            GhostFlag));
        Assert.True(updated.Character.Attributes.ContainsKey(LegacyPlayerDeathState.DeadStampAttribute));
        Assert.True(updated.Character.Attributes.ContainsKey(LegacyPlayerDeathState.GhostStampAttribute));
        Assert.Equal("837", updated.Character.Attributes[LegacyPlayerDeathState.DeadXAttribute]);
        Assert.Equal("573", updated.Character.Attributes[LegacyPlayerDeathState.DeadYAttribute]);
        Assert.Equal(monster.Uid.ToString(CultureInfo.InvariantCulture), updated.Character.Attributes[LegacyPlayerDeathState.DeadKillerUidAttribute]);
        Assert.Equal("Birdman", updated.Character.Attributes[LegacyPlayerDeathState.DeadKillerNameAttribute]);

        var beforeImmediateRevive = sent.Count;
        await handler.HandleFrameAsync(
            connection,
            ReadFrame(new MsgActionPacket
            {
                ObjId = 1_293_600,
                Timestamp = 2234,
                Type = MsgActionType.Revive,
            }.ToFrameBytes()));
        Assert.Equal(beforeImmediateRevive, sent.Count);

        var output = log.ToString();
        Assert.Contains("WorldServer sent legacy monster player death", output);
        Assert.Contains("WorldServer skipped MsgAction revive", output);
        Assert.Contains($"monsterUid={monster.Uid}", output);
        Assert.Contains("remainingHitpoints=0", output);
    }

    [Fact(Skip = "Requires external game fixtures omitted from the public source snapshot.")]
    public async Task HandlerRuntimeLoopSendsProactiveMonsterRetaliationToNearbyPlayer()
    {
        var seedPath = Path.Combine(FindRepositoryRoot(), ".setup_work", "seed-json");
        if (!File.Exists(Path.Combine(seedPath, "manifest.json")))
        {
            return;
        }

        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(1293600, uid: 1293600, mapId: 1015, x: 837, y: 573);
        var worldData = await new JsonWorldDataLoader(new WorldDataOptions(seedPath)).LoadAsync();
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        using var log = new RuntimeThreadSafeStringWriter();
        using var cancel = new CancellationTokenSource();
        var handler = new WorldServerFrameHandler(
            new CharacterSnapshotLoader(_usersRoot),
            handoff,
            worldData,
            new LegacyRuntimeUpdateLoopOptions(
                Enabled: true,
                TimeSpan.FromMilliseconds(20),
                new AnchoredRuntimeTimeProvider(DateTimeOffset.UtcNow.AddSeconds(20))),
            log);
        var sent = new RuntimeThreadSafeFrameCapture();
        var connection = CreateSendingConnection(sent);

        try
        {
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()),
                cancel.Token);
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new MsgActionPacket
                {
                    ObjId = 1_293_600,
                    Timestamp = 1234,
                    Type = MsgActionType.SetLocation,
                }.ToFrameBytes()),
                cancel.Token);

            var monster = sent.ToArray()
                .Select(bytes => LegacyMonsterSpawnPacket.TryParse(ReadFrame(bytes), out var parsed) ? parsed : null)
                .FirstOrDefault(packet => packet is not null &&
                    packet.Names[0] == "Birdman" &&
                    packet.X == 837 &&
                    packet.Y == 573);
            Assert.NotNull(monster);

            var attackStart = sent.Count;
            await WaitUntilAsync(
                () => FindFrameIndexAfter(
                    sent,
                    attackStart,
                    frame => MsgAttackPacket.TryParse(frame, out var packet) &&
                        packet.Query.Uid == monster.Uid &&
                        packet.Query.OpponentUid == 1_293_600U &&
                        packet.Query.AttackType == MsgAttackType.Physical) >= attackStart,
                TimeSpan.FromSeconds(3));

            var attackIndex = FindFrameIndexAfter(
                sent,
                attackStart,
                frame => MsgAttackPacket.TryParse(frame, out var packet) &&
                    packet.Query.Uid == monster.Uid &&
                    packet.Query.OpponentUid == 1_293_600U &&
                    packet.Query.AttackType == MsgAttackType.Physical);
            Assert.True(MsgAttackPacket.TryParse(ReadFrame(sent[attackIndex]), out var attack));
            Assert.Equal(837, attack.Query.X);
            Assert.Equal(573, attack.Query.Y);
            Assert.Equal(1_462, attack.Query.Damage);
            Assert.Equal(0, attack.Query.KilledMonster);
            await WaitUntilAsync(
                () => log.ToString().Contains("WorldServer sent proactive monster attacks", StringComparison.Ordinal),
                TimeSpan.FromSeconds(1));
            Assert.Contains("WorldServer sent proactive monster attacks", log.ToString());
        }
        finally
        {
            await cancel.CancelAsync();
        }
    }

    [Fact(Skip = "Requires external game fixtures omitted from the public source snapshot.")]
    public async Task HandlerRuntimeLoopRetainsMonsterTargetLockUntilTargetInvalid()
    {
        var seedPath = Path.Combine(FindRepositoryRoot(), ".setup_work", "seed-json");
        if (!File.Exists(Path.Combine(seedPath, "manifest.json")))
        {
            return;
        }

        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(1293600, uid: 1293600, mapId: 1015, x: 837, y: 573, minHitPoints: 1_000_000);
        WriteSnapshot(1293601, uid: 1293601, mapId: 1015, x: 837, y: 573, name: "Watcher", minHitPoints: 1_000_000);
        var seedWorldData = await new JsonWorldDataLoader(new WorldDataOptions(seedPath)).LoadAsync();
        var seedMonsterInstance = FindVisibleMonster(seedWorldData, mapId: 1015, name: "Birdman", x: 837, y: 573);
        var monsterFamily = seedWorldData.MonstersById[checked((int)seedMonsterInstance.MonsterId)];
        var monsterSpawn = Assert.Single(seedWorldData.MonsterSpawnsByGeneratorId[seedMonsterInstance.GeneratorId]);
        // Keep the actual seeded family and its single-tile generator unchanged.
        // This tests target-lock retention/retargeted attack, not random fallback
        // movement through unrelated nearby seeded monster tile claims.
        var worldData = MsgTeamRuntimeTests.CreateTeamArenaRewardCatalog(
            maps: seedWorldData.Maps,
            monsters: [monsterFamily],
            monsterSpawns: [monsterSpawn]);
        var monsterInstance = FindVisibleMonster(worldData, mapId: 1015, name: "Birdman", x: 837, y: 573);
        Assert.Single(worldData.MonsterSpawns);
        Assert.Equal(seedMonsterInstance.GeneratorId, monsterInstance.GeneratorId);
        Assert.Equal(seedMonsterInstance.MonsterId, monsterInstance.MonsterId);
        Assert.Equal(seedMonsterInstance.X, monsterInstance.X);
        Assert.Equal(seedMonsterInstance.Y, monsterInstance.Y);
        // Runtime UIDs are catalog-relative: the supported one-generator
        // catalog rebases the UID, while every attack assertion below still
        // requires the exact selected instance's UID and intended target UID.
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        var peerTicket = handoff.Issue(1293601, "watcher", ConquerRuntimeDefaults.WorldServer);
        using var log = new RuntimeThreadSafeStringWriter();
        using var cancel = new CancellationTokenSource();
        var handler = new WorldServerFrameHandler(
            new CharacterSnapshotLoader(_usersRoot),
            handoff,
            ArenaStatisticsProvider.FromCatalog(worldData),
            TeamArenaStatisticsProvider.FromCatalog(worldData),
            worldData,
            new LegacyRuntimeUpdateLoopOptions(
                Enabled: true,
                TimeSpan.FromMilliseconds(20),
                new AnchoredRuntimeTimeProvider(DateTimeOffset.UtcNow.AddSeconds(20))),
            log);
        var sent = new RuntimeThreadSafeFrameCapture();
        var peerSent = new RuntimeThreadSafeFrameCapture();
        var connection = CreateSendingConnection(sent);
        var peerConnection = CreateSendingConnection(peerSent);

        try
        {
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()),
                cancel.Token);
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new MsgActionPacket
                {
                    ObjId = 1_293_600,
                    Timestamp = 1234,
                    Type = MsgActionType.SetLocation,
                }.ToFrameBytes()),
                cancel.Token);

            var monster = sent.ToArray()
                .Select(bytes => LegacyMonsterSpawnPacket.TryParse(ReadFrame(bytes), out var parsed) ? parsed : null)
                .FirstOrDefault(packet => packet is not null &&
                    packet.Names[0] == "Birdman" &&
                    packet.X == 837 &&
                    packet.Y == 573);
            Assert.NotNull(monster);

            var firstAttackStart = sent.Count;
            await WaitUntilAsync(
                () => ContainsMonsterPhysicalAttackAfter(sent, firstAttackStart, monster.Uid, 1_293_600U),
                TimeSpan.FromSeconds(3));
            Assert.True(GetMonsterStates(handler).TryGetLastAttackTargetUid(
                monsterInstance,
                DateTimeOffset.UtcNow.AddSeconds(20),
                out var lockedTargetUid));
            Assert.Equal(1_293_600U, lockedTargetUid);

            await handler.HandleFrameAsync(
                peerConnection,
                ReadFrame(new InternalWorldEnterRequestPacket(peerTicket.Token).ToFrameBytes()),
                cancel.Token);
            var lockedSession = GetSession(handler, connection);
            SetSession(handler, connection, lockedSession with
            {
                Character = lockedSession.Character with
                {
                    X = 843,
                    Y = 573,
                },
            });
            var peerSession = GetSession(handler, peerConnection);
            SetSession(handler, peerConnection, peerSession with
            {
                Character = peerSession.Character with
                {
                    X = 841,
                    Y = 573,
                },
            });

            var retainStart = sent.Count;
            var peerRetainStart = peerSent.Count;
            var retainDeadline = DateTimeOffset.UtcNow + TimeSpan.FromSeconds(3);
            while (DateTimeOffset.UtcNow < retainDeadline &&
                !ContainsMonsterPhysicalAttackAfter(sent, retainStart, monster.Uid, 1_293_600U) &&
                !ContainsMonsterPhysicalAttackAfter(peerSent, peerRetainStart, monster.Uid, 1_293_600U) &&
                !ContainsMonsterPhysicalAttackAfter(sent, retainStart, monster.Uid, 1_293_601U) &&
                !ContainsMonsterPhysicalAttackAfter(peerSent, peerRetainStart, monster.Uid, 1_293_601U))
            {
                await Task.Delay(10, cancel.Token);
            }

            Assert.False(
                ContainsMonsterPhysicalAttackAfter(sent, retainStart, monster.Uid, 1_293_601U) ||
                ContainsMonsterPhysicalAttackAfter(peerSent, peerRetainStart, monster.Uid, 1_293_601U),
                $"Monster {monster.Uid} retargeted to nearby peer 1293601 before locked target became invalid. Log={log}");
            Assert.True(GetMonsterStates(handler).TryGetLastAttackTargetUid(
                monsterInstance,
                DateTimeOffset.UtcNow.AddSeconds(20),
                out var retainedTargetUid));
            Assert.Equal(1_293_600U, retainedTargetUid);

            var invalidatedSession = GetSession(handler, connection);
            SetSession(handler, connection, invalidatedSession with
            {
                Character = invalidatedSession.Character with
                {
                    MinHitPoints = 0,
                },
            });

            var invalidStart = sent.Count;
            var peerInvalidStart = peerSent.Count;
            try
            {
                await WaitUntilAsync(
                    () =>
                        ContainsMonsterPhysicalAttackAfter(sent, invalidStart, monster.Uid, 1_293_601U) ||
                        ContainsMonsterPhysicalAttackAfter(peerSent, peerInvalidStart, monster.Uid, 1_293_601U),
                    TimeSpan.FromSeconds(20));
            }
            catch (TimeoutException exception)
            {
                var runtimeOptions = (LegacyRuntimeUpdateLoopOptions)typeof(WorldServerFrameHandler)
                    .GetField("_runtimeUpdateLoop", BindingFlags.NonPublic | BindingFlags.Instance)!
                    .GetValue(handler)!;
                var runtimeNow = (runtimeOptions.TimeProvider ?? TimeProvider.System).GetUtcNow();
                var failedSessions = GetSessions(handler);
                failedSessions.TryGet(connection, out var failedLockedSession);
                failedSessions.TryGet(peerConnection, out var failedPeerSession);
                var failedMonsterStates = GetMonsterStates(handler);
                var visibleAvailable = failedMonsterStates.TryGetVisibleInstance(
                    monsterInstance, runtimeNow, out var failedVisibleMonster);
                var lockAvailable = failedMonsterStates.TryGetTargetLockState(
                    monsterInstance, runtimeNow, out var failedLock);
                var visibleDescription = visibleAvailable
                    ? $"uid={failedVisibleMonster.Uid} hp={failedVisibleMonster.Hitpoints} " +
                        $"xy={failedVisibleMonster.X},{failedVisibleMonster.Y} " +
                        $"map={failedVisibleMonster.MapId} dynamic={failedVisibleMonster.DynamicId}"
                    : "not-visible";
                throw new TimeoutException(
                    "HandlerRuntimeLoopRetainsMonsterTargetLockUntilTargetInvalid retarget wait timed out; " +
                    $"wallNow={DateTimeOffset.UtcNow:O} runtimeNow={runtimeNow:O}; " +
                    $"locked={DescribeTargetLockDiagnosticSession(failedLockedSession)}; " +
                    $"peer={DescribeTargetLockDiagnosticSession(failedPeerSession)}; " +
                    $"monster={visibleDescription}; lockAvailable={lockAvailable} lock={failedLock}; " +
                    $"captureRanges={invalidStart}..{sent.Count},{peerInvalidStart}..{peerSent.Count}; " +
                    $"Log={log}", exception);

                static string DescribeTargetLockDiagnosticSession(WorldSession? current)
                {
                    return current is null
                        ? "missing"
                        : $"uid={current.Character.Uid} hp={current.Character.MinHitPoints} " +
                            $"xy={current.Character.X},{current.Character.Y} map={current.Character.MapId} " +
                            $"dead={LegacyPlayerDeathState.HasStatusFlag(current.Character.Attributes, LegacyPlayerDeathState.DeadStatusFlag)} " +
                            $"ghost={LegacyPlayerDeathState.HasStatusFlag(current.Character.Attributes, LegacyPlayerDeathState.GhostStatusFlag)}";
                }
            }
            Assert.False(
                ContainsMonsterPhysicalAttackAfter(sent, invalidStart, monster.Uid, 1_293_600U) ||
                ContainsMonsterPhysicalAttackAfter(peerSent, peerInvalidStart, monster.Uid, 1_293_600U),
                $"Monster {monster.Uid} kept attacking invalid locked target 1293600. Log={log}");
            Assert.True(GetMonsterStates(handler).TryGetLastAttackTargetUid(
                monsterInstance,
                DateTimeOffset.UtcNow.AddSeconds(20),
                out var resetTargetUid));
            Assert.Equal(1_293_601U, resetTargetUid);
        }
        finally
        {
            await cancel.CancelAsync();
            await WaitForTargetLockRuntimeGlobalStopAsync(handler);
            // Join both synchronous persistence gates; late player ticker CAS cannot republish them.
            GetSessions(handler).TryRemove(connection, out _);
            GetSessions(handler).TryRemove(peerConnection, out _);
        }
    }

    [Fact]
    public async Task HandlerRuntimeLoopSkipsGenericAggroForGuardFamilies()
    {
        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(1293600, uid: 1293600, mapId: 1011, x: 197, y: 230, minHitPoints: 1_000_000);
        var guardFamily = new Monster(
            900,
            "Guard1",
            new Dictionary<string, string>
            {
                ["life"] = "70000",
                ["lookface"] = "0900",
                ["level"] = "0200",
