    [Fact]
    public async Task HandlerRuntimeLoopGuardAttacksOnlyFlashingPlayersWithLegacySpell()
    {
        const int FlashingNameFlag = 0;
        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(
            1293600,
            uid: 1293600,
            mapId: 1011,
            x: 197,
            y: 230,
            minHitPoints: 1_000_000,
            statusFlags: BuildStatusFlags(FlashingNameFlag));
        var guardFamily = new Monster(
            900,
            "Guard1",
            new Dictionary<string, string>
            {
                ["life"] = "70000",
                ["lookface"] = "0900",
                ["level"] = "0200",
                ["attack_range"] = "0015",
                ["view_range"] = "0015",
                ["attack_speed"] = "1",
                ["move_speed"] = "1",
                ["magic_type"] = "1234",
                ["attack_min"] = "200",
                ["attack_max"] = "200",
            },
            []);
        var guardSpawn = new MonsterSpawn(
            GeneratorId: 108,
            MapId: 1011,
            MonsterTypeId: 900,
            BoundX: 197,
            BoundY: 230,
            BoundWidth: 1,
            BoundHeight: 1,
            MaxNpc: 1,
            RestSeconds: 10,
            MaxPerGenerator: 1,
            TimerBegin: 0,
            TimerEnd: 0,
            BornX: 0,
            BornY: 0,
            SourceMapFolderId: 1011,
            SourceMonsterName: "Guard1",
            SourceRelativePath: Path.Combine("1011", "Guard1", "1.ini"),
            Attributes: new Dictionary<string, string>
            {
                ["id"] = "0108",
                ["mapid"] = "1011",
                ["npctype"] = "0900",
            });
        var worldData = MsgTeamRuntimeTests.CreateTeamArenaRewardCatalog(
            monsters: [guardFamily],
            monsterSpawns: [guardSpawn]);
        var guardInstance = Assert.Single(LegacyMonsterInstance.FromGenerator(
            guardSpawn,
            guardFamily,
            worldData.GetLegacyMonsterRuntimeUidBase(guardSpawn)));
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        using var log = new RuntimeThreadSafeStringWriter();
        using var cancel = new CancellationTokenSource();
        var handler = new WorldServerFrameHandler(
            new CharacterSnapshotLoader(_usersRoot),
            handoff,
            worldData,
            new LegacyRuntimeUpdateLoopOptions(
                Enabled: true,
                TimeSpan.FromMilliseconds(20),
                new AnchoredRuntimeTimeProvider(DateTimeOffset.UtcNow.AddSeconds(20))),
            log);
        var sent = new RuntimeThreadSafeFrameCapture();
        var connection = CreateSendingConnection(sent);

        try
        {
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()),
                cancel.Token);
            var start = sent.Count;
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new MsgActionPacket
                {
                    ObjId = 1_293_600,
                    Timestamp = 1234,
                    Type = MsgActionType.SetLocation,
                }.ToFrameBytes()),
                cancel.Token);

            await WaitUntilAsync(
                () => FindFrameIndexAfter(
                    sent,
                    start,
                    frame => LegacySpellAnimationPacket.TryParse(frame, out var spell) &&
                        spell.AttackerUid == guardInstance.Uid &&
                        spell.SpellId == 1234 &&
                        spell.Targets.Count == 1 &&
                        spell.Targets[0].Uid == 1_293_600U) >= start,
                TimeSpan.FromSeconds(2));

            var spellIndex = FindFrameIndexAfter(
                sent,
                start,
                frame => LegacySpellAnimationPacket.TryParse(frame, out var spell) &&
                    spell.AttackerUid == guardInstance.Uid &&
                    spell.SpellId == 1234);
            Assert.True(LegacySpellAnimationPacket.TryParse(ReadFrame(sent[spellIndex]), out var guardSpell));
            Assert.Equal(197, guardSpell.X);
            Assert.Equal(230, guardSpell.Y);
            var target = Assert.Single(guardSpell.Targets);
            Assert.Equal(1_293_600U, target.Uid);
            Assert.True(target.Damage > 0);

            await WaitUntilAsync(
                () => log.ToString().Contains("WorldServer sent legacy guard attacks", StringComparison.Ordinal),
                TimeSpan.FromSeconds(2));
            Assert.Contains("WorldServer sent legacy guard attacks", log.ToString());
            Assert.DoesNotContain("WorldServer sent proactive monster attacks", log.ToString());
        }
        finally
        {
            await cancel.CancelAsync();
            var globalLoopStarted = typeof(WorldServerFrameHandler).GetField(
                "_legacyRuntimeGlobalLoopStarted", BindingFlags.Instance | BindingFlags.NonPublic);
            Assert.NotNull(globalLoopStarted);
            await WaitUntilAsync(
                () => Equals(0, globalLoopStarted.GetValue(handler)),
                TimeSpan.FromSeconds(2));
            // Join this fixture's in-flight persistence gate after guard work exits;
            // pending player ticker CAS updates cannot republish a removed session.
            GetSessions(handler).TryRemove(connection, out _);
        }
    }

    [Fact]
    public async Task HandlerRuntimeLoopGuardReturnsTowardRespawnPosition()
    {
        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(1293600, uid: 1293600, mapId: 1011, x: 197, y: 230, minHitPoints: 1_000_000);
        var guardFamily = new Monster(
            900,
            "Guard1",
            new Dictionary<string, string>
            {
                ["life"] = "70000",
                ["lookface"] = "0900",
                ["level"] = "0200",
                ["attack_range"] = "0015",
                ["view_range"] = "0015",
                ["attack_speed"] = "1",
                ["move_speed"] = "1",
                ["magic_type"] = "1234",
                ["attack_min"] = "200",
                ["attack_max"] = "200",
            },
            []);
        var guardSpawn = new MonsterSpawn(
            GeneratorId: 110,
            MapId: 1011,
            MonsterTypeId: 900,
            BoundX: 197,
            BoundY: 230,
            BoundWidth: 1,
            BoundHeight: 1,
            MaxNpc: 1,
            RestSeconds: 10,
            MaxPerGenerator: 1,
            TimerBegin: 0,
            TimerEnd: 0,
            BornX: 0,
            BornY: 0,
            SourceMapFolderId: 1011,
            SourceMonsterName: "Guard1",
            SourceRelativePath: Path.Combine("1011", "Guard1", "1.ini"),
            Attributes: new Dictionary<string, string>
            {
                ["id"] = "0110",
                ["mapid"] = "1011",
                ["npctype"] = "0900",
            });
        var worldData = MsgTeamRuntimeTests.CreateTeamArenaRewardCatalog(
            monsters: [guardFamily],
            monsterSpawns: [guardSpawn]);
        var guardInstance = Assert.Single(LegacyMonsterInstance.FromGenerator(
            guardSpawn,
            guardFamily,
            worldData.GetLegacyMonsterRuntimeUidBase(guardSpawn)));
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        var anchor = DateTimeOffset.UtcNow.AddSeconds(20);
        using var log = new RuntimeThreadSafeStringWriter();
        using var cancel = new CancellationTokenSource();
        var handler = new WorldServerFrameHandler(
            new CharacterSnapshotLoader(_usersRoot),
            handoff,
            worldData,
            new LegacyRuntimeUpdateLoopOptions(
                Enabled: true,
                TimeSpan.FromMilliseconds(20),
                new AnchoredRuntimeTimeProvider(anchor)),
            log);
        var monsterStates = GetMonsterStates(handler);
        Assert.True(monsterStates.TryMoveTowardTarget(
            guardInstance,
            targetX: 199,
            targetY: 230,
            anchor.AddSeconds(-2),
            TimeSpan.Zero,
            out var shiftedOnce,
            out _));
        Assert.True(monsterStates.TryMoveTowardTarget(
            shiftedOnce,
            targetX: 199,
            targetY: 230,
            anchor.AddSeconds(-2).AddMilliseconds(1),
            TimeSpan.Zero,
            out var shiftedGuard,
            out _));
        Assert.Equal(199, shiftedGuard.X);

        var sent = new RuntimeThreadSafeFrameCapture();
        var connection = CreateSendingConnection(sent);

        try
        {
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()),
                cancel.Token);
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new MsgActionPacket
                {
                    ObjId = 1_293_600,
                    Timestamp = 1234,
                    Type = MsgActionType.SetLocation,
                }.ToFrameBytes()),
                cancel.Token);

            var movementStart = sent.Count;
            await WaitUntilAsync(
                () => FindFrameIndexAfter(
                    sent,
                    movementStart,
                    frame => MsgMovementPacket.TryParse(frame, out var movement) &&
                        movement.Uid == guardInstance.Uid) >= movementStart,
                TimeSpan.FromSeconds(2));

            var movementIndex = FindFrameIndexAfter(
                sent,
                movementStart,
                frame => MsgMovementPacket.TryParse(frame, out var movement) &&
                    movement.Uid == guardInstance.Uid);
            Assert.True(MsgMovementPacket.TryParse(ReadFrame(sent[movementIndex]), out var guardMovement));
            Assert.Equal(guardInstance.Uid, guardMovement.Uid);
            Assert.Equal(MsgMovementMode.Run, guardMovement.Running);
            Assert.True(monsterStates.TryGetVisibleInstance(
                guardInstance,
                anchor.AddSeconds(2),
                out var returnedGuard));
            Assert.True(returnedGuard.X < shiftedGuard.X);
            Assert.Contains("WorldServer sent legacy guard return movement", log.ToString());
        }
        finally
        {
            await cancel.CancelAsync();
        }
    }

