        var blockingGuardSpawn = returningGuardSpawn with
        {
            GeneratorId = 111,
            BoundX = 198,
            SourceRelativePath = Path.Combine("1011", "Guard1", "2.ini"),
            Attributes = new Dictionary<string, string>
            {
                ["id"] = "0111",
                ["mapid"] = "1011",
                ["npctype"] = "0900",
            },
        };
        var worldData = MsgTeamRuntimeTests.CreateTeamArenaRewardCatalog(
            monsters: [guardFamily],
            monsterSpawns: [returningGuardSpawn, blockingGuardSpawn]);
        var returningGuard = Assert.Single(LegacyMonsterInstance.FromGenerator(
            returningGuardSpawn,
            guardFamily,
            worldData.GetLegacyMonsterRuntimeUidBase(returningGuardSpawn)));
        var blockingGuard = Assert.Single(LegacyMonsterInstance.FromGenerator(
            blockingGuardSpawn,
