            new CharacterSnapshotLoader(_usersRoot),
            handoff,
            worldData,
            new LegacyRuntimeUpdateLoopOptions(
                Enabled: true,
                TimeSpan.FromMilliseconds(20),
                new AnchoredRuntimeTimeProvider(anchor)),
            log);
        var monsterStates = GetMonsterStates(handler);
        Assert.True(monsterStates.TryMoveTo(
            returningGuard,
            targetX: 199,
            targetY: 230,
            anchor.AddSeconds(-2),
            out var shiftedGuard));
        Assert.True(monsterStates.TryGetVisibleInstance(blockingGuard, anchor.AddSeconds(-2), out var blockingVisible));
        Assert.Equal(198, blockingVisible.X);

        var sent = new RuntimeThreadSafeFrameCapture();
        var connection = CreateSendingConnection(sent);

        try
        {
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()),
                cancel.Token);
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new MsgActionPacket
                {
                    ObjId = 1_293_600,
                    Timestamp = 1234,
                    Type = MsgActionType.SetLocation,
                }.ToFrameBytes()),
                cancel.Token);

            var movementStart = sent.Count;
            await Task.Delay(750, cancel.Token);

            var movementIndex = FindFrameIndexAfter(
                sent,
                movementStart,
                frame => MsgMovementPacket.TryParse(frame, out var movement) &&
                    movement.Uid == returningGuard.Uid);
            Assert.Equal(-1, movementIndex);
            Assert.True(monsterStates.TryGetVisibleInstance(
                returningGuard,
                anchor.AddSeconds(2),
                out var visibleGuard));
            Assert.Equal(shiftedGuard.X, visibleGuard.X);
            Assert.Equal(shiftedGuard.Y, visibleGuard.Y);
        }
        finally
        {
            await cancel.CancelAsync();
        }
    }

