            var target = Assert.Single(guardSpell.Targets);
            Assert.Equal(targetInstance.Uid, target.Uid);
            Assert.Equal(175U, target.Damage);
            Assert.True(GetMonsterStates(handler).TryGetVisibleInstance(
                targetInstance,
                DateTimeOffset.UtcNow.AddSeconds(20),
                out var damagedTarget));
            Assert.Equal(825U, damagedTarget.Hitpoints);
            Assert.DoesNotContain(
                sent.Skip(start),
                bytes => MsgAttackPacket.TryParse(ReadFrame(bytes), out var death) &&
                    death.Query.Uid == guardInstance.Uid &&
                    death.Query.OpponentUid == targetInstance.Uid &&
                    death.Query.AttackType == MsgAttackType.Death);
            Assert.False(
                ContainsMonsterPhysicalAttackAfter(sent, start, guardInstance.Uid, 1_293_600U),
                $"Guard monster-protection branch attacked the normal player. Log={log}");
            Assert.Contains("WorldServer sent legacy guard monster-protection attacks", log.ToString());
            Assert.DoesNotContain("WorldServer sent proactive monster attacks", log.ToString());
        }
        finally
        {
            await cancel.CancelAsync();
        }
    }

    [Fact]
    public async Task HandlerRuntimeLoopGuardLethalMonsterProtectionSendsSpellThenDeathWithoutDrop()
    {
        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(1293600, uid: 1293600, mapId: 1011, x: 197, y: 230, minHitPoints: 1_000_000);
        var guardFamily = new Monster(
            900,
            "Guard1",
            new Dictionary<string, string>
            {
                ["life"] = "70000",
                ["lookface"] = "0900",
                ["level"] = "0200",
                ["attack_range"] = "0015",
                ["view_range"] = "0015",
                ["attack_speed"] = "1",
                ["move_speed"] = "1",
                ["magic_type"] = "1234",
                ["attack_min"] = "200",
                ["attack_max"] = "200",
            },
            []);
        var targetFamily = new Monster(
            901,
            "Birdman",
            new Dictionary<string, string>
            {
                ["life"] = "100",
                ["lookface"] = "0205",
                ["level"] = "0087",
                ["attack_range"] = "0",
                ["view_range"] = "0015",
                ["attack_speed"] = "1",
                ["move_speed"] = "1",
                ["defense"] = "25",
            },
            []);
        var guardSpawn = new MonsterSpawn(
            GeneratorId: 115,
            MapId: 1011,
            MonsterTypeId: 900,
            BoundX: 197,
            BoundY: 230,
            BoundWidth: 1,
            BoundHeight: 1,
            MaxNpc: 1,
            RestSeconds: 10,
            MaxPerGenerator: 1,
            TimerBegin: 0,
            TimerEnd: 0,
            BornX: 0,
            BornY: 0,
            SourceMapFolderId: 1011,
            SourceMonsterName: "Guard1",
            SourceRelativePath: Path.Combine("1011", "Guard1", "1.ini"),
            Attributes: new Dictionary<string, string>
            {
                ["id"] = "0115",
                ["mapid"] = "1011",
                ["npctype"] = "0900",
            });
        var targetSpawn = new MonsterSpawn(
            GeneratorId: 116,
            MapId: 1011,
            MonsterTypeId: 901,
            BoundX: 198,
            BoundY: 230,
            BoundWidth: 1,
            BoundHeight: 1,
            MaxNpc: 1,
            RestSeconds: 10,
            MaxPerGenerator: 1,
            TimerBegin: 0,
            TimerEnd: 0,
            BornX: 0,
            BornY: 0,
            SourceMapFolderId: 1011,
            SourceMonsterName: "Birdman",
            SourceRelativePath: Path.Combine("1011", "Birdman", "1.ini"),
            Attributes: new Dictionary<string, string>
            {
                ["id"] = "0116",
                ["mapid"] = "1011",
                ["npctype"] = "0901",
            });
        var worldData = MsgTeamRuntimeTests.CreateTeamArenaRewardCatalog(
            monsters: [guardFamily, targetFamily],
            monsterSpawns: [guardSpawn, targetSpawn]);
        var guardInstance = Assert.Single(LegacyMonsterInstance.FromGenerator(
            guardSpawn,
            guardFamily,
            worldData.GetLegacyMonsterRuntimeUidBase(guardSpawn)));
        var targetInstance = Assert.Single(LegacyMonsterInstance.FromGenerator(
            targetSpawn,
            targetFamily,
            worldData.GetLegacyMonsterRuntimeUidBase(targetSpawn)));
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        var anchor = DateTimeOffset.UtcNow.AddSeconds(20);
        using var log = new RuntimeThreadSafeStringWriter();
        using var cancel = new CancellationTokenSource();
        var handler = new WorldServerFrameHandler(
            new CharacterSnapshotLoader(_usersRoot),
            handoff,
            worldData,
            new LegacyRuntimeUpdateLoopOptions(
                Enabled: true,
                TimeSpan.FromMilliseconds(20),
                new AnchoredRuntimeTimeProvider(anchor)),
            log);
        var sent = new RuntimeThreadSafeFrameCapture();
        var connection = CreateSendingConnection(sent);

        try
        {
            var start = sent.Count;
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()),
                cancel.Token);
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new MsgActionPacket
                {
                    ObjId = 1_293_600,
                    Timestamp = 1234,
                    Type = MsgActionType.SetLocation,
                }.ToFrameBytes()),
                cancel.Token);

            await WaitUntilAsync(
                () => FindFrameIndexAfter(
                    sent,
                    start,
                    frame => MsgAttackPacket.TryParse(frame, out var death) &&
                        death.Query.Uid == guardInstance.Uid &&
                        death.Query.OpponentUid == targetInstance.Uid &&
                        death.Query.AttackType == MsgAttackType.Death) >= start,
                TimeSpan.FromSeconds(2));

            var spellIndex = FindFrameIndexAfter(
                sent,
                start,
                frame => LegacySpellAnimationPacket.TryParse(frame, out var spell) &&
                    spell.AttackerUid == guardInstance.Uid &&
                    spell.SpellId == 1234 &&
                    spell.Targets.Count == 1 &&
                    spell.Targets[0].Uid == targetInstance.Uid);
            var deathIndexes = Enumerable
                .Range(start, sent.Count - start)
                .Where(index => MsgAttackPacket.TryParse(ReadFrame(sent[index]), out var death) &&
                    death.Query.Uid == guardInstance.Uid &&
                    death.Query.OpponentUid == targetInstance.Uid &&
                    death.Query.AttackType == MsgAttackType.Death)
                .ToArray();
            var deathIndex = Assert.Single(deathIndexes);
            Assert.Equal(spellIndex + 1, deathIndex);
            Assert.Equal(WorldPacketOpcodes.LegacySpellUse, ReadFrame(sent[spellIndex]).Header.Opcode);
            Assert.Equal(WorldPacketOpcodes.MsgAttack, ReadFrame(sent[deathIndex]).Header.Opcode);

            Assert.True(LegacySpellAnimationPacket.TryParse(ReadFrame(sent[spellIndex]), out var guardSpell));
            Assert.Equal(198, guardSpell.X);
            Assert.Equal(230, guardSpell.Y);
            var target = Assert.Single(guardSpell.Targets);
            Assert.Equal(targetInstance.Uid, target.Uid);
            Assert.Equal(175U, target.Damage);

            Assert.True(MsgAttackPacket.TryParse(ReadFrame(sent[deathIndex]), out var death));
            Assert.Equal(guardInstance.Uid, death.Query.Uid);
            Assert.Equal(targetInstance.Uid, death.Query.OpponentUid);
            Assert.Equal(targetInstance.X, death.Query.X);
            Assert.Equal(targetInstance.Y, death.Query.Y);
            Assert.Equal(MsgAttackType.Death, death.Query.AttackType);
            Assert.Equal(0, death.Query.Damage);
            Assert.Equal(1, death.Query.KilledMonster);
            Assert.Equal(0U, death.Query.ResponseDamage);
            Assert.Equal(MsgAttackEffect.None, death.Query.Effect);
            Assert.Equal(0U, death.Query.Unknown);
            Assert.False(GetMonsterStates(handler).TryGetVisibleInstance(
                targetInstance,
                anchor.AddSeconds(1),
                out _));
            Assert.DoesNotContain(
                sent.Skip(start),
                bytes => ReadFrame(bytes).Header.Opcode == WorldPacketOpcodes.LegacyFloorItem);
        }
        finally
        {
            await cancel.CancelAsync();
        }
    }

