    [Fact]
    public async Task HandlerRuntimeLoopReviverRevivesDeadPlayersAndSendsLegacySpellAnimation()
    {
        const int DeadFlag = 0x05;
        const int GhostFlag = 0x0A;
        var deathAt = new DateTimeOffset(2026, 6, 13, 15, 10, 0, TimeSpan.Zero);
        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(
            1293600,
            uid: 1293600,
            mapId: 1015,
            x: 197,
            y: 230,
            minHitPoints: 0,
            statusFlags: BuildStatusFlags(DeadFlag, GhostFlag),
            extraCharacterLines:
                $"DeadStamp={deathAt:O}\r\n" +
                $"GhostStamp={deathAt.AddSeconds(1):O}\r\n" +
                "Dead_X=197\r\n" +
                "Dead_Y=230");
        var reviverFamily = new Monster(
            10000,
            "Reviver",
            new Dictionary<string, string>
            {
                ["life"] = "70000",
                ["lookface"] = "10000",
                ["level"] = "0200",
                ["attack_range"] = "0015",
                ["view_range"] = "0015",
                ["attack_speed"] = "1",
                ["move_speed"] = "1",
            },
            []);
        var reviverSpawn = new MonsterSpawn(
            GeneratorId: 110,
            MapId: 1015,
            MonsterTypeId: 10000,
            BoundX: 199,
            BoundY: 230,
            BoundWidth: 1,
            BoundHeight: 1,
            MaxNpc: 1,
            RestSeconds: 10,
            MaxPerGenerator: 1,
            TimerBegin: 0,
            TimerEnd: 0,
            BornX: 0,
            BornY: 0,
            SourceMapFolderId: 1015,
            SourceMonsterName: "Reviver",
            SourceRelativePath: Path.Combine("1015", "Reviver", "1.ini"),
            Attributes: new Dictionary<string, string>
            {
                ["id"] = "0110",
                ["mapid"] = "1015",
                ["npctype"] = "10000",
            });
        var worldData = MsgTeamRuntimeTests.CreateTeamArenaRewardCatalog(
            monsters: [reviverFamily],
            monsterSpawns: [reviverSpawn]);
        var reviverInstance = Assert.Single(LegacyMonsterInstance.FromGenerator(
            reviverSpawn,
            reviverFamily,
            worldData.GetLegacyMonsterRuntimeUidBase(reviverSpawn)));
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        using var log = new RuntimeThreadSafeStringWriter();
        using var cancel = new CancellationTokenSource();
        var handler = new WorldServerFrameHandler(
            new CharacterSnapshotLoader(_usersRoot),
            handoff,
            worldData,
            new LegacyRuntimeUpdateLoopOptions(
                Enabled: true,
                TimeSpan.FromMilliseconds(20),
                new AnchoredRuntimeTimeProvider(deathAt.AddSeconds(2))),
            log);
        var sent = new RuntimeThreadSafeFrameCapture();
        var connection = CreateSendingConnection(sent);

        try
        {
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()),
                cancel.Token);
            var start = sent.Count;
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new MsgActionPacket
                {
                    ObjId = 1_293_600,
                    Timestamp = 1234,
                    Type = MsgActionType.SetLocation,
                }.ToFrameBytes()),
                cancel.Token);

            Assert.Contains(
                sent.ToArray(),
                frame => LegacyMonsterSpawnPacket.TryParse(ReadFrame(frame), out var spawn) &&
                    spawn.Uid == reviverInstance.Uid);

            await WaitUntilAsync(
                () => FindFrameIndexAfter(
                    sent,
                    start,
                    frame => LegacySpellAnimationPacket.TryParse(frame, out var packet) &&
                        packet.AttackerUid == reviverInstance.Uid &&
                        packet.SpellId == 1100 &&
                        packet.Targets.Count == 1 &&
                        packet.Targets[0].Uid == 1_293_600U &&
                        packet.Targets[0].Damage == 0) >= start,
                TimeSpan.FromSeconds(2));

            var reviveIndex = FindFrameIndexAfter(
                sent,
                start,
                frame => LegacyMsgUpdatePacket.TryParse(frame, out var update) &&
                    update.Uid == 1_293_600U &&
                    update.Updates.Count == 1 &&
                    update.Updates[0].Type == LegacyMsgUpdateDataType.MaxHitpoints);
            Assert.InRange(reviveIndex, start, sent.Count - 1);

            Assert.True(LegacyMsgUpdatePacket.TryParse(ReadFrame(sent[reviveIndex]), out var maxHitpoints));
            var maxHitpointUpdate = Assert.Single(maxHitpoints.Updates);
            Assert.Equal(LegacyMsgUpdateDataType.MaxHitpoints, maxHitpointUpdate.Type);
            Assert.True(maxHitpointUpdate.Value > 0);

            Assert.True(LegacyMsgUpdatePacket.TryParse(ReadFrame(sent[reviveIndex + 1]), out var hitpoints));
            Assert.Equal(
                [
                    new LegacyMsgUpdateEntry(LegacyMsgUpdateDataType.MaxHitpoints, maxHitpointUpdate.Value),
                    new LegacyMsgUpdateEntry(LegacyMsgUpdateDataType.Hitpoints, maxHitpointUpdate.Value),
                ],
                hitpoints.Updates);
            AssertSingleUpdate(sent[reviveIndex + 2], 1_293_600, LegacyMsgUpdateDataType.Stamina, 100);

            Assert.True(LegacyMsgUpdatePacket.TryParse(ReadFrame(sent[reviveIndex + 3]), out var status));
            var statusUpdate = Assert.Single(status.Updates);
            Assert.Equal(LegacyMsgUpdateDataType.StatusFlag, statusUpdate.Type);
            Assert.NotNull(statusUpdate.Values);
            Assert.False(HasLegacyStatusFlag(statusUpdate.Values, DeadFlag));
            Assert.False(HasLegacyStatusFlag(statusUpdate.Values, GhostFlag));
            AssertSingleUpdate(sent[reviveIndex + 4], 1_293_600, LegacyMsgUpdateDataType.Mesh, 1_541_008);
            Assert.True(LegacyMapStatusPacket.TryParse(ReadFrame(sent[reviveIndex + 5]), out var mapStatus));
            Assert.Equal(new LegacyMapStatusPacket(1015, 1015, Status: 0), mapStatus);

            var spellIndex = FindFrameIndexAfter(
                sent,
                reviveIndex,
                frame => LegacySpellAnimationPacket.TryParse(frame, out var packet) &&
                    packet.AttackerUid == reviverInstance.Uid &&
                    packet.SpellId == 1100);
            Assert.True(LegacySpellAnimationPacket.TryParse(ReadFrame(sent[spellIndex]), out var spell));
            Assert.Equal(199, spell.X);
            Assert.Equal(230, spell.Y);
            var target = Assert.Single(spell.Targets);
            Assert.Equal(1_293_600U, target.Uid);
            Assert.Equal(0U, target.Damage);
            Assert.Equal(MsgAttackEffect.None, target.Effect);

            var updated = GetSession(handler, connection);
            Assert.Equal((long)maxHitpointUpdate.Value, updated.Character.MinHitPoints);
            Assert.False(HasLegacyStatusFlag(
                LegacyPlayerSpawnPacket.FromSnapshot(updated.Character).StatusFlags,
                DeadFlag));
            Assert.False(HasLegacyStatusFlag(
                LegacyPlayerSpawnPacket.FromSnapshot(updated.Character).StatusFlags,
                GhostFlag));
            Assert.False(
                ContainsMonsterPhysicalAttackAfter(sent, start, reviverInstance.Uid, 1_293_600U),
                $"Reviver family attacked after its source ReviversCallback revive. Log={log}");
            Assert.Contains("WorldServer sent legacy Reviver revive", log.ToString());
        }
        finally
        {
            await cancel.CancelAsync();
        }
    }

