    {
        Directory.CreateDirectory(_usersRoot);
        WriteSnapshot(1293600, uid: 1293600, mapId: 1015, x: 833, y: 574);
        var monsterFamily = new Monster(
            901,
            "Birdman",
            new Dictionary<string, string>
            {
                ["life"] = "8925",
                ["lookface"] = "0205",
                ["level"] = "0087",
                ["attack_range"] = "0001",
                ["view_range"] = "0030",
                ["attack_speed"] = "1",
                ["move_speed"] = "1",
            },
            []);
        var spawn = new MonsterSpawn(
            GeneratorId: 108,
            MapId: 1015,
            MonsterTypeId: 901,
            BoundX: 852,
            BoundY: 574,
            BoundWidth: 1,
            BoundHeight: 1,
            MaxNpc: 1,
            RestSeconds: 10,
            MaxPerGenerator: 1,
            TimerBegin: 0,
            TimerEnd: 0,
            BornX: 0,
            BornY: 0,
            SourceMapFolderId: 1015,
            SourceMonsterName: "Birdman",
            SourceRelativePath: Path.Combine("1015", "Birdman", "1.ini"),
            Attributes: new Dictionary<string, string>
            {
                ["id"] = "0108",
                ["mapid"] = "1015",
                ["npctype"] = "0901",
            });
        var worldData = MsgTeamRuntimeTests.CreateTeamArenaRewardCatalog(
            monsters: [monsterFamily],
            monsterSpawns: [spawn]);
        var monsterInstance = Assert.Single(LegacyMonsterInstance.FromGenerator(
            spawn,
            monsterFamily,
            worldData.GetLegacyMonsterRuntimeUidBase(spawn)));
        Assert.Equal(852, monsterInstance.X);
        Assert.Equal(574, monsterInstance.Y);
        var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
        var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
        using var log = new RuntimeThreadSafeStringWriter();
        using var cancel = new CancellationTokenSource();
        var handler = new WorldServerFrameHandler(
            new CharacterSnapshotLoader(_usersRoot),
            handoff,
            worldData,
            new LegacyRuntimeUpdateLoopOptions(
                Enabled: true,
                TimeSpan.FromMilliseconds(20),
                new AnchoredRuntimeTimeProvider(DateTimeOffset.UtcNow.AddSeconds(20))),
            log);
        var sent = new RuntimeThreadSafeFrameCapture();
        var connection = CreateSendingConnection(sent);

        try
        {
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()),
                cancel.Token);
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new MsgActionPacket
                {
                    ObjId = 1_293_600,
                    Timestamp = 1234,
                    Type = MsgActionType.SetLocation,
                }.ToFrameBytes()),
                cancel.Token);

            Assert.DoesNotContain(
                sent,
                frame => LegacyMonsterSpawnPacket.TryParse(ReadFrame(frame), out var spawnPacket) &&
                    spawnPacket.Uid == monsterInstance.Uid);

            var runtimeStart = sent.Count;
            await WaitUntilAsync(
                () => FindFrameIndexAfter(
                    sent,
                    runtimeStart,
                    frame => LegacyMonsterSpawnPacket.TryParse(frame, out var spawnPacket) &&
                        spawnPacket.Uid == monsterInstance.Uid) >= runtimeStart ||
                    FindFrameIndexAfter(
                        sent,
                        runtimeStart,
                        frame => MsgMovementPacket.TryParse(frame, out var movement) &&
                            movement.Uid == monsterInstance.Uid) >= runtimeStart,
                TimeSpan.FromSeconds(2));

            var spawnIndex = FindFrameIndexAfter(
                sent,
                runtimeStart,
                frame => LegacyMonsterSpawnPacket.TryParse(frame, out var spawnPacket) &&
                    spawnPacket.Uid == monsterInstance.Uid);
            var movementIndex = FindFrameIndexAfter(
                sent,
                runtimeStart,
                frame => MsgMovementPacket.TryParse(frame, out var movement) &&
                    movement.Uid == monsterInstance.Uid);

            Assert.True(spawnIndex >= runtimeStart, $"Expected spawn before movement-only ghost. Log={log}");
            if (movementIndex >= runtimeStart)
            {
                Assert.True(spawnIndex < movementIndex);
            }

            Assert.True(LegacyMonsterSpawnPacket.TryParse(ReadFrame(sent[spawnIndex]), out var enteredSpawn));
            Assert.Equal(851, enteredSpawn.X);
            Assert.Equal(574, enteredSpawn.Y);
        }
        finally
        {
            await cancel.CancelAsync();
        }
    }

