    private static ConquerTcpConnection CreateSendingConnection(
        Action<byte[]> record,
        Func<ReadOnlyMemory<byte>, CancellationToken, ValueTask>? beforeSendAsync)
    {
        return new ConquerTcpConnection(null, new IPEndPoint(IPAddress.Loopback, 9958), (frame, _) =>
        {
            if (beforeSendAsync is not null)
            {
                var beforeSendTask = beforeSendAsync(frame, _);
                if (!beforeSendTask.IsCompletedSuccessfully)
                {
                    return AwaitAndRecordAsync(beforeSendTask, record, frame);
                }
            }

            record(frame.ToArray());
            return ValueTask.CompletedTask;
        });
    }

    private static async ValueTask AwaitAndRecordAsync(
        ValueTask beforeSendTask,
        Action<byte[]> record,
        ReadOnlyMemory<byte> frame)
    {
        await beforeSendTask.ConfigureAwait(false);
        record(frame.ToArray());
    }

