    private static void AssertServerAppliedSurvivingMonsterPhysicalHit(
        MsgAttackPacket hit,
        LegacyMonsterSpawnPacket monster)
    {
        Assert.Equal(monster.Uid, hit.Query.OpponentUid);
        Assert.Equal(MsgAttackType.Physical, hit.Query.AttackType);
        Assert.InRange(hit.Query.Damage, 1, checked((int)monster.MaxLife - 1));
    }

    private static (int Index, MsgAttackPacket Packet) AssertServerAppliedSurvivingMonsterPhysicalHitAfter(
        IReadOnlyList<byte[]> sent,
        int startIndex,
        uint playerUid,
        LegacyMonsterSpawnPacket monster,
        string failureMessage)
    {
        var hitIndex = FindFrameIndexAfter(
            sent,
            startIndex,
            frame => MsgAttackPacket.TryParse(frame, out var hit) &&
                hit.Query.Uid == playerUid &&
                hit.Query.OpponentUid == monster.Uid &&
                hit.Query.AttackType == MsgAttackType.Physical &&
                hit.Query.Damage >= 1 &&
                hit.Query.Damage < monster.MaxLife);
        Assert.True(hitIndex >= startIndex, failureMessage);
        Assert.True(MsgAttackPacket.TryParse(ReadFrame(sent[hitIndex]), out var playerHit));
        AssertServerAppliedSurvivingMonsterPhysicalHit(playerHit, monster);
        return (hitIndex, playerHit);
    }

    private static void RaiseSeedMonsterLifeForRetaliationFixture(
        WorldDataCatalog worldData,
        string monsterName,
        uint life = 100_000)
    {
        var matched = false;
        foreach (var monster in worldData.Monsters)
        {
            if (!string.Equals(monster.Name, monsterName, StringComparison.OrdinalIgnoreCase))
            {
                continue;
            }

            var attributes = Assert.IsAssignableFrom<IDictionary<string, string>>(monster.Attributes);
            attributes["life"] = life.ToString(CultureInfo.InvariantCulture);
            matched = true;
        }

        Assert.True(matched, $"Expected seed monster family '{monsterName}' to exist.");
    }

    private static ulong CalculateExpectedMonsterAttackExperience(
        int damage,
        int attackerLevel,
        int monsterLevel,
        int mapId)
    {
        var adjustedExperience = AdjustLegacyMonsterExperienceForTest(damage, attackerLevel, monsterLevel);
        var result = LegacyExperienceGainPolicy.CalculateAttackUpdate(
            new LegacyExperienceGainInputs(
                adjustedExperience,
                attackerLevel,
                CursedTimer: 0,
                SoulChantEquipped: false,
                SoulChantItemLevel: 0,
                ServerExperienceRate: 1.0,
                RainbowGemPercent: 0,
                DoubleExperienceTime: 0,
                DoubleExperienceRate: 1.0,
                MapId: mapId,
                HasOblivion: false,
                HasHeavenBlessing: false));
        return result.AppliedExperienceGain;
    }

    private static int AdjustLegacyMonsterExperienceForTest(int damage, int attackerLevel, int monsterLevel)
    {
        var adjusted = damage;
        var levelDelta = attackerLevel - monsterLevel;
        if (levelDelta >= 3 && levelDelta <= 5)
        {
            adjusted = adjusted * 70 / 100;
        }
        else if (levelDelta > 5 && levelDelta <= 10)
        {
            adjusted = adjusted * 20 / 100;
        }
        else if (levelDelta > 10 && levelDelta <= 20)
        {
            adjusted = adjusted * 10 / 100;
        }
        else if (levelDelta > 20)
        {
            adjusted = adjusted * 5 / 100;
        }
        else if (levelDelta < 0 && levelDelta >= -5)
        {
            adjusted = (int)(adjusted * 1.3);
        }
        else if (levelDelta >= -10 && levelDelta < -5)
        {
            adjusted = (int)(adjusted * 1.5);
        }
        else if (levelDelta >= -20 && levelDelta < -10)
        {
            adjusted = (int)(adjusted * 1.8);
        }
        else if (levelDelta < -20)
        {
            adjusted = (int)(adjusted * 2.3);
        }

        return Math.Max(10, adjusted);
    }

