    private static LegacyMonsterInstance FindVisibleMonster(
        WorldDataCatalog worldData,
        int mapId,
        string name,
        ushort x,
        ushort y)
    {
        Assert.True(worldData.MonsterSpawnsByMapId.TryGetValue(mapId, out var spawns));
        foreach (var spawn in spawns)
        {
            if (!worldData.MonstersById.TryGetValue(spawn.MonsterTypeId, out var monster) ||
                !string.Equals(monster.Name, name, StringComparison.OrdinalIgnoreCase))
            {
                continue;
            }

            var uidBase = worldData.GetLegacyMonsterRuntimeUidBase(spawn);
            foreach (var instance in LegacyMonsterInstance.FromGenerator(spawn, monster, uidBase))
            {
                if (instance.X == x && instance.Y == y)
                {
                    return instance;
                }
            }
        }

        throw new InvalidOperationException($"Could not find seed monster '{name}' on map {mapId} at {x},{y}.");
    }

    private static LegacyMonsterInstance FindVisibleRespawnMonster(
        WorldDataCatalog worldData,
        int mapId,
        long x,
        long y)
    {
        Assert.True(worldData.MonsterSpawnsByMapId.TryGetValue(mapId, out var spawns));
        LegacyMonsterInstance? best = null;
        foreach (var spawn in spawns)
        {
            if (!worldData.MonstersById.TryGetValue(spawn.MonsterTypeId, out var monster))
            {
                continue;
            }

            var uidBase = worldData.GetLegacyMonsterRuntimeUidBase(spawn);
            foreach (var instance in LegacyMonsterInstance.FromGenerator(spawn, monster, uidBase))
            {
                if (instance.MaxLife <= int.MaxValue &&
                    LegacyTestDistance(x, y, instance.X, instance.Y) <= 18)
                {
                    if (best is null || instance.RestSeconds < best.RestSeconds)
                    {
                        best = instance;
                    }
                }
            }
        }

        return best ?? throw new InvalidOperationException("Could not find a visible seed monster with a respawn timer.");
    }

    private static (LegacyMonsterInstance Instance, Monster Family) FindVisibleMagicMonster(
        WorldDataCatalog worldData,
        int mapId,
        string name)
    {
        Assert.True(worldData.MonsterSpawnsByMapId.TryGetValue(mapId, out var spawns));
        foreach (var spawn in spawns)
        {
            if (!worldData.MonstersById.TryGetValue(spawn.MonsterTypeId, out var monster) ||
                !string.Equals(monster.Name, name, StringComparison.OrdinalIgnoreCase) ||
                ReadTestAttributeUInt32(monster.Attributes, "magic_type") == 0)
            {
                continue;
            }

            var uidBase = worldData.GetLegacyMonsterRuntimeUidBase(spawn);
            return (LegacyMonsterInstance.FromGenerator(spawn, monster, uidBase).First(), monster);
        }

        throw new InvalidOperationException($"Could not find magic monster '{name}' on map {mapId}.");
    }

    private static uint ReadTestAttributeUInt32(IReadOnlyDictionary<string, string> attributes, string key)
    {
        Assert.True(attributes.TryGetValue(key, out var raw), $"Missing attribute '{key}'.");
        Assert.True(
            uint.TryParse(raw, NumberStyles.Integer, CultureInfo.InvariantCulture, out var parsed),
            $"Invalid UInt32 attribute '{key}' value '{raw}'.");
        return parsed;
    }

    private static uint ReadUIntAttribute(IReadOnlyDictionary<string, string> attributes, params string[] keys)
    {
        foreach (var key in keys)
        {
            if (!attributes.TryGetValue(key, out var raw))
            {
                continue;
            }

            Assert.True(
                uint.TryParse(raw, NumberStyles.Integer, CultureInfo.InvariantCulture, out var parsed),
                $"Invalid UInt32 attribute '{key}' value '{raw}'.");
            return parsed;
        }

        Assert.Fail($"Missing any attribute: {string.Join(", ", keys)}.");
        return 0;
    }

