    private sealed class RuntimeThreadSafeFrameCapture : IReadOnlyList<byte[]>
    {
        private readonly object _gate = new();
        private readonly List<byte[]> _frames = [];

        public int Count
        {
            get
            {
                lock (_gate)
                {
                    return _frames.Count;
                }
            }
        }

        public byte[] this[int index]
        {
            get
            {
                lock (_gate)
                {
                    return _frames[index];
                }
            }
        }

        public void Add(byte[] frame)
        {
            ArgumentNullException.ThrowIfNull(frame);
            lock (_gate)
            {
                _frames.Add(frame);
            }
        }

        public IEnumerator<byte[]> GetEnumerator()
        {
            byte[][] snapshot;
            lock (_gate)
            {
                snapshot = _frames.ToArray();
            }

            return ((IEnumerable<byte[]>)snapshot).GetEnumerator();
        }

        IEnumerator IEnumerable.GetEnumerator()
        {
            return GetEnumerator();
        }
    }

    private sealed class RuntimeThreadSafeStringWriter : StringWriter
    {
        private readonly object _gate = new();

        public override void Write(char value)
        {
            lock (_gate)
            {
                base.Write(value);
            }
        }

        public override void Write(string? value)
        {
            lock (_gate)
            {
                base.Write(value);
            }
        }

        public override void WriteLine(string? value)
        {
            lock (_gate)
            {
                base.WriteLine(value);
            }
        }

        public override Task WriteAsync(string? value)
        {
            lock (_gate)
            {
                base.Write(value);
            }

            return Task.CompletedTask;
        }

        public override Task WriteLineAsync(string? value)
        {
            lock (_gate)
            {
                base.WriteLine(value);
            }

            return Task.CompletedTask;
        }

        public override string ToString()
        {
            lock (_gate)
            {
                return base.ToString();
            }
        }
    }

    private static async Task WaitUntilAsync(Func<bool> predicate, TimeSpan timeout)
    {
        var deadline = DateTimeOffset.UtcNow + timeout;
        while (!predicate())
        {
            if (DateTimeOffset.UtcNow >= deadline)
            {
                throw new TimeoutException("Condition was not met before the timeout expired.");
            }

            await Task.Delay(10);
        }
    }

    private sealed class SparseTerrainCells : IReadOnlyList<LegacyDMapCell>
    {
        private readonly int _width;
        private readonly int _height;
        private readonly HashSet<(int X, int Y)> _blocked;

        public SparseTerrainCells(int width, int height, IEnumerable<(int X, int Y)> blocked)
        {
            _width = width;
            _height = height;
            _blocked = blocked.ToHashSet();
        }

        public int Count => checked(_width * _height);

        public LegacyDMapCell this[int index]
        {
            get
            {
                if ((uint)index >= (uint)Count)
                {
                    throw new ArgumentOutOfRangeException(nameof(index));
                }

                var x = index % _width;
                var y = index / _width;
                var terrainFlag = _blocked.Contains((x, y)) ? (short)1 : (short)0;
                return new LegacyDMapCell(x, y, terrainFlag, Surface: 0, Altitude: 0);
            }
        }

        public IEnumerator<LegacyDMapCell> GetEnumerator()
        {
            for (var index = 0; index < Count; index++)
            {
                yield return this[index];
            }
        }

        IEnumerator IEnumerable.GetEnumerator()
        {
            return GetEnumerator();
        }
    }

    private static string BuildStatusFlags(params int[] flags)
    {
        var wordCount = Math.Max(
            10,
            flags
                .Where(flag => flag >= 0)
                .Select(flag => flag / 32 + 1)
                .DefaultIfEmpty(10)
                .Max());
        var words = new ulong[wordCount];
        foreach (var flag in flags)
        {
            if (flag < 0)
            {
                continue;
            }

            var wordIndex = flag / 32;
            var bitIndex = flag % 32;
            words[wordIndex] |= 1UL << bitIndex;
        }

        return string.Join('/', words) + "/";
    }

    private static bool HasLegacyStatusFlag(IReadOnlyList<ulong> statusFlags, int flag)
    {
        var wordIndex = flag / 32;
        var bitIndex = flag % 32;
        return wordIndex < statusFlags.Count &&
            (statusFlags[wordIndex] & (1UL << bitIndex)) != 0;
    }

    private static bool HasLegacyStatusFlag(string statusFlags, int flag)
    {
        var wordIndex = flag / 32;
        var bitIndex = flag % 32;
        var parts = statusFlags.Split('/', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
        return wordIndex < parts.Length &&
            ulong.TryParse(parts[wordIndex], NumberStyles.Integer, CultureInfo.InvariantCulture, out var word) &&
            (word & (1UL << bitIndex)) != 0;
    }

    private static PacketFrame ReadFrame(byte[] bytes)
    {
        var sequence = new ReadOnlySequence<byte>(bytes);
        Assert.True(PacketFrameDecoder.TryRead(sequence, out var frame, out _, out _));
        return frame;
    }

