    private static async Task<IReadOnlyList<LegacyMsgUpdatePacket>> CaptureLegacyOverwhelmRuntimeMsgUpdatesAsync(
        LegacyClientCompatibilityOptions? clientCompatibility,
        Func<IReadOnlyList<LegacyMsgUpdatePacket>, bool> waitFor)
    {
        var dbRoot = Path.Combine(Path.GetTempPath(), "wolf-world-handler-overwhelm-runtime-" + Guid.NewGuid());
        using var cancel = new CancellationTokenSource();
        try
        {
            var usersRoot = Path.Combine(dbRoot, "Users");
            var itemsRoot = Path.Combine(dbRoot, "PlayersItems");
            Directory.CreateDirectory(usersRoot);
            Directory.CreateDirectory(itemsRoot);
            WriteSnapshot(usersRoot, 1293600, uid: 1293600);
            File.WriteAllBytes(Path.Combine(itemsRoot, "1293600.bin"), BuildRunePlayerItemsFile(101));
            var worldData = CreateStaticVisibilityCatalog(
                items: [new ItemType(4_010_501, "Overwhelm", ["4010501", "Overwhelm"])]);
            var handler = new WorldServerFrameHandler(
                new CharacterSnapshotLoader(usersRoot),
                handoffService: null,
                worldData,
                new LegacyRuntimeUpdateLoopOptions(
                    Enabled: true,
                    TimeSpan.FromMilliseconds(5),
                    TimeProvider.System),
                log: null,
                clientCompatibility);
            var sent = new List<byte[]>();

            await handler.HandleFrameAsync(
                CreateSendingConnection(sent),
                ReadFrame(new LegacyMsgLoginGamePacket(1293600).ToFrameBytes()),
                cancel.Token);
            await WaitUntilAsync(
                () => waitFor(ParseLegacyMsgUpdates(sent.ToArray())),
                TimeSpan.FromSeconds(2));

            return ParseLegacyMsgUpdates(sent.ToArray());
        }
        finally
        {
            await cancel.CancelAsync();
            if (Directory.Exists(dbRoot))
            {
                Directory.Delete(dbRoot, recursive: true);
            }
        }
    }

    private static bool HasSingleLegacyMsgUpdate(
        IReadOnlyList<LegacyMsgUpdatePacket> updates,
        LegacyMsgUpdateDataType type,
        ulong value)
    {
        return updates.Any(update => IsSingleLegacyMsgUpdate(update, type, value));
    }

    private static bool IsSingleLegacyMsgUpdate(
        LegacyMsgUpdatePacket packet,
        LegacyMsgUpdateDataType type,
        ulong value)
    {
        return packet.Uid == 1_293_600 &&
            packet.Updates.Count == 1 &&
            packet.Updates[0].Type == type &&
            packet.Updates[0].Value == value;
    }

    private static bool HasLegacyOverwhelmRuntimeStatusVector(LegacyMsgUpdatePacket packet)
    {
        return packet.Uid == 1_293_600 &&
            packet.Updates.Count == 1 &&
            packet.Updates[0].Type == LegacyMsgUpdateDataType.StatusFlag &&
            packet.Updates[0].Values is { } values &&
            HasLegacyStatusFlag(values, LegacyRuntimeUpdateTicker.OverwhelmFlag);
    }

    private static byte[] BuildLegacyNpcDialogReply(
        byte optionId,
        byte interactType,
        byte action = 0,
        uint npcId = 0,
        string input = "")
    {
        var inputBytes = Encoding.UTF8.GetBytes(input);
        var writer = new PacketWriter(WorldPacketOpcodes.LegacyNpcReply, payloadLength: 11 + inputBytes.Length);
        writer.WriteUInt32(0, npcId);
        writer.WriteUInt16(4, 0);
        writer.Payload[6] = optionId;
        writer.Payload[7] = interactType;
        writer.Payload[8] = action;
        writer.WriteUInt16(9, checked((ushort)inputBytes.Length));
        inputBytes.CopyTo(writer.Payload[11..]);
        return writer.ToArray();
    }

