    private static void AssertSingleUpdate(
        byte[] bytes,
        uint uid,
        LegacyMsgUpdateDataType dataType,
        ulong value)
    {
        Assert.True(LegacyMsgUpdatePacket.TryParse(ReadFrame(bytes), out var packet));
        Assert.Equal(uid, packet.Uid);
        Assert.Equal([new LegacyMsgUpdateEntry(dataType, value)], packet.Updates);
    }

    private static int FindSingleUpdateIndex(
        IReadOnlyList<byte[]> sent,
        uint uid,
        LegacyMsgUpdateDataType dataType,
        ulong value)
    {
        for (var index = 0; index < sent.Count; index++)
        {
            if (!LegacyMsgUpdatePacket.TryParse(ReadFrame(sent[index]), out var packet) ||
                packet.Uid != uid ||
                packet.Updates.Count != 1)
            {
                continue;
            }

            var update = packet.Updates[0];
            if (update.Type == dataType && update.Value == value)
            {
                return index;
            }
        }

        throw new InvalidOperationException(
            $"Could not find single {dataType} update for uid {uid} value {value}.");
    }

