            WriteSnapshot(1293600, uid: 1293600);
            File.WriteAllBytes(
                Path.Combine(itemsRoot, "1293600.bin"),
                PlayerItemSnapshotLoaderTests.BuildPlayerItems(
                    [
                        PlayerItemSnapshotLoaderTests.DbItem(uid: 2001, itemId: itemId, position: 0),
                    ],
                    []));
            using var log = new StringWriter();
            var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
            var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
            var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot, itemsRoot), handoff, log);
            var sent = new List<byte[]>();
            var connection = CreateSendingConnection(sent);

            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));

            Assert.Equal(basePosition, ItemType.GetLegacyEquipmentPosition(itemId));

            var countBeforeRequest = sent.Count;
            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new MsgItemUsagePacket(
                    Id: 2001,
                    DwParam: requestedPosition,
                    Action: MsgItemUsageAction.Equip,
                    Timestamp: 1234,
                    DwParam2: 0,
                    DwParam3: 0,
                    DwParam4: 0).ToFrameBytes()));

            Assert.Equal(countBeforeRequest + 6, sent.Count);
            LegacySelectedEquipmentQueryAssertions.InactiveAlternate(sent, countBeforeRequest + 4, 2001U, expectedPosition);
            AssertItemUsage(
                sent[countBeforeRequest],
                new MsgItemUsagePacket(
                    Id: 2001,
                    DwParam: 0,
                    Action: MsgItemUsageAction.RemoveInventory,
                    Timestamp: 0,
                    DwParam2: 0,
                    DwParam3: 0,
                    DwParam4: 0));
            AssertItemUsage(
                sent[countBeforeRequest + 1],
                new MsgItemUsagePacket(
                    Id: 2001,
                    DwParam: expectedPosition,
                    Action: MsgItemUsageAction.Unequip,
                    Timestamp: 0,
                    DwParam2: 0,
                    DwParam3: 0,
                    DwParam4: 0));

            var addedItem = ParseLegacyGameItem(sent[countBeforeRequest + 2]);
            Assert.Equal(2001U, addedItem.Uid);
            Assert.Equal(itemId, addedItem.ItemId);
            Assert.Equal(LegacyGameItemPacket.AddItemMode, addedItem.Mode);
            Assert.Equal((byte)expectedPosition, addedItem.Position);

            var updatedItem = ParseLegacyGameItem(sent[countBeforeRequest + 3]);
            Assert.Equal(2001U, updatedItem.Uid);
            Assert.Equal(itemId, updatedItem.ItemId);
            Assert.Equal(LegacyGameItemPacket.UpdateItemMode, updatedItem.Mode);
            Assert.Equal((byte)expectedPosition, updatedItem.Position);
            Assert.Contains($"slot={logSlot} alternate=True", log.ToString());
        }
        finally
        {
            if (Directory.Exists(itemsRoot))
            {
                Directory.Delete(itemsRoot, recursive: true);
            }
        }
    }

    private static LegacyGameItemPacket ParseLegacyGameItem(byte[] bytes)
    {
        Assert.True(LegacyGameItemPacket.TryParse(ReadFrame(bytes), out var packet));
        return packet;
    }

    private static int FindLegacyGameItemIndex(IReadOnlyList<byte[]> sent, uint uid)
    {
        for (var index = 0; index < sent.Count; index++)
        {
            if (LegacyGameItemPacket.TryParse(ReadFrame(sent[index]), out var packet) &&
                packet.Uid == uid)
            {
                return index;
            }
        }

        throw new InvalidOperationException($"Could not find legacy game item UID {uid}.");
    }

    private static int FindOpcodeIndex(IReadOnlyList<byte[]> sent, ushort opcode, int startIndex = 0)
    {
        for (var index = startIndex; index < sent.Count; index++)
        {
            if (ReadFrame(sent[index]).Header.Opcode == opcode)
            {
                return index;
            }
        }

        throw new InvalidOperationException($"Could not find opcode {opcode}.");
    }

    private static int FindSingleUpdateIndex(
        IReadOnlyList<byte[]> sent,
        LegacyMsgUpdateDataType dataType,
        int startIndex = 0)
    {
        for (var index = startIndex; index < sent.Count; index++)
        {
            if (LegacyMsgUpdatePacket.TryParse(ReadFrame(sent[index]), out var packet) &&
                packet.Updates.Count == 1 &&
                packet.Updates[0].Type == dataType)
            {
                return index;
            }
        }

        throw new InvalidOperationException($"Could not find legacy MsgUpdate data type {dataType}.");
    }

    private static LegacyFloorItemPacket ParseLegacyFloorItem(byte[] bytes)
