    private static byte[] BuildLegacyFloorItemPickupFrame(uint floorUid)
    {
        var writer = new PacketWriter(LegacyFloorItemPacket.Opcode, payloadLength: sizeof(uint));
        writer.WriteUInt32(0, floorUid);
        return writer.ToArray();
    }

    private static void AssertResponse(
        byte[] bytes,
        WorldSnapshotWireStatus status,
        long accountId,
        long uid = 0,
        long mapId = 0,
        long x = 0,
        long y = 0,
        long level = 0,
        long @class = 0)
    {
        Assert.True(PacketReader.TryRead(bytes, out var reader));
        Assert.Equal(WorldPacketOpcodes.InternalSnapshotResponse, reader.Header.Opcode);
        Assert.Equal(WorldSnapshotResponsePacket.PayloadLength, reader.Payload.Length);
        Assert.Equal(status, WorldSnapshotResponsePacket.ReadStatus(reader));
        Assert.Equal(accountId, WorldSnapshotResponsePacket.ReadAccountId(reader));
        Assert.Equal(uid, WorldSnapshotResponsePacket.ReadUid(reader));
        Assert.Equal(mapId, WorldSnapshotResponsePacket.ReadMapId(reader));
        Assert.Equal(x, WorldSnapshotResponsePacket.ReadX(reader));
        Assert.Equal(y, WorldSnapshotResponsePacket.ReadY(reader));
        Assert.Equal(level, WorldSnapshotResponsePacket.ReadLevel(reader));
        Assert.Equal(@class, WorldSnapshotResponsePacket.ReadClass(reader));
    }

    private static void AssertLegacyWorldEntryStartupFrames(
        IReadOnlyList<byte[]> sent,
        int startIndex,
        bool includesAutoHunt = true,
        bool includesCollectionStorage = false)
    {
        Assert.True(PacketFrameDecoder.TryRead(new ReadOnlySequence<byte>(sent[startIndex]), out var versionFrame, out _, out _));
        Assert.True(LegacyServerVersionPacket.TryParse(versionFrame, out _));

        Assert.True(PacketFrameDecoder.TryRead(new ReadOnlySequence<byte>(sent[startIndex + 1]), out var timerFrame, out _, out _));
        Assert.True(LegacyServerTimerPacket.TryParse(timerFrame, out _));

        Assert.True(PacketFrameDecoder.TryRead(new ReadOnlySequence<byte>(sent[startIndex + 2]), out var configFrame, out _, out _));
        Assert.True(LegacyServerConfigPacket.TryParse(configFrame, out _));

        var loaderIndex = startIndex + 3;
        if (includesCollectionStorage)
        {
            AssertLegacyCollectionStorageFrame(sent[loaderIndex]);
            loaderIndex++;
        }

        Assert.True(PacketFrameDecoder.TryRead(new ReadOnlySequence<byte>(sent[loaderIndex]), out var loaderFrame, out _, out _));
        Assert.True(LegacyLoaderHeroInfoPacket.TryParse(loaderFrame, out _));

        Assert.True(PacketFrameDecoder.TryRead(new ReadOnlySequence<byte>(sent[loaderIndex + 1]), out var protoHeroFrame, out _, out _));
        Assert.True(LegacyProtoHeroInfoPacket.TryParse(protoHeroFrame, out _));

        AssertLegacyChiRankingFrames(sent, loaderIndex + 2);

        AssertLegacyChiInfoFrame(sent[loaderIndex + 6]);

        AssertLegacyAchievementFrame(sent[loaderIndex + 7]);

        Assert.True(PacketFrameDecoder.TryRead(new ReadOnlySequence<byte>(sent[loaderIndex + 8]), out var nobilityFrame, out _, out _));
        Assert.True(LegacyNobilityIconPacket.TryParse(nobilityFrame, out _));

        if (includesAutoHunt)
        {
            // Native Equipment.Show always queries, including an empty equipped set.
            LegacySelectedEquipmentQueryAssertions.NeutralQuery(sent, loaderIndex + 9, 1_293_600U);
            AssertLegacyAutoHuntFrame(sent[loaderIndex + 19]);
            AssertLegacyActivenessFrames(sent, loaderIndex + 20);
            var lateIndex = loaderIndex + 23;
            Assert.True(LegacyJiangHuInfoPacket.TryParse(ReadFrame(sent[lateIndex]), out _));
            Assert.True(LegacyMsgUpdatePacket.TryParse(ReadFrame(sent[lateIndex + 1]), out _));
            Assert.True(LegacyMsgUpdatePacket.TryParse(ReadFrame(sent[lateIndex + 2]), out _));
            Assert.True(LegacyVipStatusPacket.TryParse(ReadFrame(sent[lateIndex + 3]), out _));
            Assert.True(LegacyMsgUpdatePacket.TryParse(ReadFrame(sent[lateIndex + 4]), out _));
            Assert.True(MsgActionPacket.TryParse(ReadFrame(sent[lateIndex + 5]), out _));
            Assert.True(LegacyCoatStoragePacket.TryParse(ReadFrame(sent[lateIndex + 6]), out _));
            Assert.True(LegacyCoatStoragePacket.TryParse(ReadFrame(sent[lateIndex + 7]), out _));
            Assert.True(LegacyMsgMessagePacket.TryParse(ReadFrame(sent[lateIndex + 8]), out var welcomeTalk));
            Assert.Equal("Welcome to WolfConquer.", welcomeTalk.Content[3]);
            Assert.True(LegacyNpcReplyPacket.TryParse(ReadFrame(sent[lateIndex + 14]), out var staticGui));
            Assert.Equal(LegacyNpcReplyInteractType.StaticGui, staticGui.InteractType);
            AssertSingleUpdate(sent[lateIndex + 19], 1_293_600, LegacyMsgUpdateDataType.InventorySashMax, 300);
            AssertSingleUpdate(sent[lateIndex + 20], 1_293_600, LegacyMsgUpdateDataType.InventorySash, 0);
            Assert.True(LegacyMsgMessagePacket.TryParse(ReadFrame(sent[lateIndex + 21]), out var runeRankMessage));
            Assert.Equal("My ranking: Unranked; Current rune pack score: 0", runeRankMessage.Content[3]);
            AssertLegacyRuneStorageFrame(sent[lateIndex + 22]);
        }
    }

