            Assert.True(PacketFrameDecoder.TryRead(new ReadOnlySequence<byte>(sent[startIndex + index]), out var rankingFrame, out _, out _));
            Assert.True(LegacyGenericRankingPacket.TryParse(rankingFrame, out var ranking));
