    private async Task AssertItemUsageAlternanteSkippedAsync(
        IReadOnlyList<PlayerItemSnapshotLoaderTests.TestDbItem> blockedItems,
        long specialGarment,
        string reason,
        string? statusFlags = null)
    {
        var itemsRoot = Path.Combine(Path.GetTempPath(), "wolf-world-alternate-blocked-items-" + Guid.NewGuid());
        try
        {
            Directory.CreateDirectory(_usersRoot);
            Directory.CreateDirectory(itemsRoot);
            WriteSnapshot(1293600, uid: 1293600, mapId: 1015, x: 830, y: 584);
            WriteSnapshot(
                1293601,
                uid: 1293601,
                mapId: 1015,
                x: 840,
                y: 590,
                specialGarment: specialGarment,
                statusFlags: statusFlags);
            File.WriteAllBytes(
                Path.Combine(itemsRoot, "1293601.bin"),
                PlayerItemSnapshotLoaderTests.BuildPlayerItems(blockedItems, []));
            using var log = new StringWriter();
            var handoff = new AccountHandoffService(new InMemoryAccountHandoffTicketStore());
            var ticket = handoff.Issue(1293600, "user02", ConquerRuntimeDefaults.WorldServer);
            var otherTicket = handoff.Issue(1293601, "demon3", ConquerRuntimeDefaults.WorldServer);
            var handler = new WorldServerFrameHandler(new CharacterSnapshotLoader(_usersRoot, itemsRoot), handoff, log);
            var sent = new List<byte[]>();
            var otherSent = new List<byte[]>();
            var connection = CreateSendingConnection(sent);
            var otherConnection = CreateSendingConnection(otherSent);

            await handler.HandleFrameAsync(
                connection,
                ReadFrame(new InternalWorldEnterRequestPacket(ticket.Token).ToFrameBytes()));
            await handler.HandleFrameAsync(
                otherConnection,
                ReadFrame(new InternalWorldEnterRequestPacket(otherTicket.Token).ToFrameBytes()));

            var visiblePeerBefore = sent.Count;
            var ownerBefore = otherSent.Count;
            await handler.HandleFrameAsync(
                otherConnection,
                ReadFrame(new MsgItemUsagePacket(
                    Id: 0,
                    DwParam: 0,
                    Action: MsgItemUsageAction.Alternante,
                    Timestamp: 1234,
                    DwParam2: 0,
                    DwParam3: 0,
                    DwParam4: 0).ToFrameBytes()));

            Assert.Equal(visiblePeerBefore, sent.Count);
            Assert.Equal(ownerBefore, otherSent.Count);
            Assert.Contains("WorldServer handled MsgItemUsage", log.ToString());
            Assert.Contains("WorldServer skipped alternate equipment toggle", log.ToString());
            Assert.Contains($"reason={reason}", log.ToString());
            Assert.DoesNotContain("WorldServer toggled alternate equipment", log.ToString());
        }
        finally
        {
            if (Directory.Exists(itemsRoot))
            {
                Directory.Delete(itemsRoot, recursive: true);
            }
        }
    }

