    private void WriteAccountManagerPaidNobilitySnapshot(
        int paidRank,
        string paidRankName,
        ulong previousDonation,
        DateTime periodTime)
    {
        var paidPosition = paidRank switch
        {
            LegacyNobilityRanking.RankKing => 0,
            LegacyNobilityRanking.RankPrince => 4,
            LegacyNobilityRanking.RankDuke => 15,
            _ => LegacyNobilityRanking.DefaultPosition,
        };
        WriteSnapshot(
            1293600,
            uid: 1293600,
            nobilityDonation: 0,
            extraCharacterLines: string.Format(
                CultureInfo.InvariantCulture,
                "LastNobilityDonation=0\r\nNobilityRank={0}\r\nNobilityPosition={1}",
                paidRank,
                paidPosition));
        File.AppendAllText(
            Path.Combine(_usersRoot, "1293600.ini"),
            string.Format(
                CultureInfo.InvariantCulture,
                "\r\nPaidRank={0}\r\nLastNobilityDonation={1}\r\nPeriodTime={2}\r\nIsActive=True\r\nRank={3}\r\nPosition={4}\r\n",
                paidRank,
                previousDonation,
                periodTime.ToBinary(),
                paidRankName,
                paidPosition));
    }

