    private static string FindRepositoryRoot([CallerFilePath] string sourceFilePath = "")
    {
        var startPaths = new[]
        {
            AppContext.BaseDirectory,
            Directory.GetCurrentDirectory(),
            Path.GetDirectoryName(sourceFilePath) ?? string.Empty,
        };
        foreach (var startPath in startPaths.Where(path => path.Length > 0).Distinct())
        {
            var directory = new DirectoryInfo(startPath);
            while (directory is not null)
            {
                if (File.Exists(Path.Combine(directory.FullName, "WolfConquer.sln")))
                {
                    return directory.FullName;
                }

                directory = directory.Parent;
            }
        }

        throw new InvalidOperationException("Could not locate WolfConquer.sln from the test output, working, or source directory.");
    }

    private static byte[] BuildPlayerItemsFile(
        uint itemUid,
        uint itemId,
        ushort durability = 1,
        ushort maximumDurability = 1,
        ushort position = 0,
        byte locked = 0,
        int unlockTimer = 0,
        uint purificationItemId = 0)
    {
        var bytes = new byte[sizeof(int) + PlayerItemSnapshotLoader.LegacyDbItemSize + sizeof(int)];
        BinaryPrimitives.WriteInt32LittleEndian(bytes.AsSpan(0, sizeof(int)), 1);
        var item = bytes.AsSpan(sizeof(int), PlayerItemSnapshotLoader.LegacyDbItemSize);
        BinaryPrimitives.WriteUInt32LittleEndian(item.Slice(0, sizeof(uint)), itemUid);
        BinaryPrimitives.WriteUInt32LittleEndian(item.Slice(4, sizeof(uint)), itemId);
        BinaryPrimitives.WriteUInt16LittleEndian(item.Slice(8, sizeof(ushort)), durability);
        BinaryPrimitives.WriteUInt16LittleEndian(item.Slice(10, sizeof(ushort)), maximumDurability);
        BinaryPrimitives.WriteUInt16LittleEndian(item.Slice(12, sizeof(ushort)), position);
        item[33] = locked;
        BinaryPrimitives.WriteUInt16LittleEndian(item.Slice(52, sizeof(ushort)), 1);
        BinaryPrimitives.WriteUInt32LittleEndian(item.Slice(60, sizeof(uint)), 6);
        BinaryPrimitives.WriteInt32LittleEndian(item.Slice(64, sizeof(int)), unlockTimer);
        BinaryPrimitives.WriteUInt32LittleEndian(item.Slice(84, sizeof(uint)), purificationItemId);
        BinaryPrimitives.WriteInt32LittleEndian(
            bytes.AsSpan(sizeof(int) + PlayerItemSnapshotLoader.LegacyDbItemSize, sizeof(int)),
            0);
        return bytes;
    }

    private static byte[] BuildRunePlayerItemsFile(params ushort[] positions)
    {
        var bytes = new byte[sizeof(int) + (positions.Length * PlayerItemSnapshotLoader.LegacyDbItemSize) + sizeof(int)];
        BinaryPrimitives.WriteInt32LittleEndian(bytes.AsSpan(0, sizeof(int)), positions.Length);
        var offset = sizeof(int);

        for (var index = 0; index < positions.Length; index++)
        {
            var item = bytes.AsSpan(offset, PlayerItemSnapshotLoader.LegacyDbItemSize);
            BinaryPrimitives.WriteUInt32LittleEndian(item.Slice(0, sizeof(uint)), (uint)(5_000_000 + index));
            BinaryPrimitives.WriteUInt32LittleEndian(item.Slice(4, sizeof(uint)), (uint)(4010501 + index));
            BinaryPrimitives.WriteUInt16LittleEndian(item.Slice(8, sizeof(ushort)), 1);
            BinaryPrimitives.WriteUInt16LittleEndian(item.Slice(10, sizeof(ushort)), 1);
            BinaryPrimitives.WriteUInt16LittleEndian(item.Slice(12, sizeof(ushort)), positions[index]);
            BinaryPrimitives.WriteUInt16LittleEndian(item.Slice(52, sizeof(ushort)), 1);
            offset += PlayerItemSnapshotLoader.LegacyDbItemSize;
        }

        BinaryPrimitives.WriteInt32LittleEndian(bytes.AsSpan(offset, sizeof(int)), 0);
        return bytes;
    }

    private static ArenaRecord ArenaRecord(
        int playerId,
        string name,
        int points,
        int currentHonor = 0,
        int historyHonor = 0,
        int todayBattles = 0,
        int todayWin = 0,
        int totalLose = 0,
        int totalWin = 0)
    {
        return new ArenaRecord(
            playerId,
            name,
            [140, 7051, 1008, points, currentHonor, historyHonor, todayBattles, todayWin, totalLose, totalWin, 4000, 0, 0, 999],
            "Arena.ini",
            playerId,
            $"{playerId}/{name}/140/7051/1008/{points}/{currentHonor}/{historyHonor}/{todayBattles}/{todayWin}/{totalLose}/{totalWin}/4000/0/0/999/",
            [$"{playerId}", name, "140", "7051", "1008", $"{points}", $"{currentHonor}", $"{historyHonor}", $"{todayBattles}", $"{todayWin}", $"{totalLose}", $"{totalWin}", "4000", "0", "0", "999", ""]);
    }

